--
-- TOC entry 407 (class 1255 OID 24116)
-- Name: fcardprofilemappingcrud(character varying, character varying, character varying, character varying, character varying, date, date, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fcardprofilemappingcrud(p_action character varying, p_card_profile_id character varying DEFAULT NULL::character varying, p_cardid character varying DEFAULT NULL::character varying, p_profileid character varying DEFAULT NULL::character varying, p_status character varying DEFAULT NULL::character varying, p_effective_date date DEFAULT NULL::date, p_expiry_date date DEFAULT NULL::date, p_assigned_by character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result JSON;
    v_count INTEGER;
    v_new_id VARCHAR(12);
    v_affected_rows INTEGER;
BEGIN
    -- Input validation
    IF p_action IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Action parameter is required');
    END IF;
    RAISE NOTICE 'befor insert cardid:%',p_cardid;
    -- INSERT action
    IF UPPER(p_action) = 'INSERT' THEN
        -- Check for required parameters
        IF p_cardid IS NULL OR p_profileid IS NULL OR p_effective_date IS NULL THEN
            RETURN json_build_object('success', false, 'message', 'cardid, profileid, and effective_date are required for INSERT');
        END IF;
        
        -- Check for duplicate active mapping
        SELECT COUNT(*) INTO v_count 
        FROM public.cardprofilemapping 
        WHERE cardid = p_cardid 
          AND profileid = p_profileid 
          AND status = 'ACTIVE';
        
        IF v_count > 0 THEN
            RETURN json_build_object('success', false, 'message', 'Active mapping already exists for this card and profile');
        END IF;
        
        -- Insert new record
        INSERT INTO public.cardprofilemapping (
            cardid,
            profileid,
            status,
            effective_date,
            expiry_date,
            assigned_by
        ) VALUES (
            p_cardid,
            p_profileid,
            COALESCE(p_status, 'ACTIVE'),
            p_effective_date,
            p_expiry_date,
            p_assigned_by
        ) RETURNING card_profile_id INTO v_new_id;
        
        RETURN json_build_object(
            'success', true,
            'message', 'Record inserted successfully',
            'card_profile_id', v_new_id
        );
    
    -- UPDATE action - Updates all fields EXCEPT cardid for given cardid
    ELSIF UPPER(p_action) = 'UPDATE' THEN
        -- UPDATE based on cardid
        IF p_cardid IS NULL THEN
            RETURN json_build_object('success', false, 'message', 'cardid is required for UPDATE');
        END IF;
        
        -- Check if any records exist for this cardid
        SELECT COUNT(*) INTO v_count 
        FROM public.cardprofilemapping 
        WHERE cardid = p_cardid;
        RAISE NOTICE 'select cardid:%',p_cardid;
        IF v_count = 0 THEN
            RETURN json_build_object('success', false, 'message', 'No records found for given cardid: ' || p_cardid);
        END IF;
        
        -- Update ALL records for this cardid (EXCLUDING cardid itself)
        UPDATE public.cardprofilemapping
        SET 
            -- DO NOT update: cardid (keep original)
            profileid = COALESCE(p_profileid, profileid),  -- Can update profileid if provided
            status = COALESCE(p_status, status),
            effective_date = COALESCE(p_effective_date, effective_date),
            expiry_date = p_expiry_date,  -- Can be set to NULL if provided
            assigned_by = COALESCE(p_assigned_by, assigned_by)
        WHERE cardid = p_cardid;
        
        GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
        
        RETURN json_build_object(
            'success', true,
            'message', v_affected_rows || ' record(s) updated successfully for cardid: ' || p_cardid,
            'affected_rows', v_affected_rows,
            'cardid', p_cardid,
            'updated_fields', json_build_object(
                'profileid_updated', p_profileid IS NOT NULL,
                'status_updated', p_status IS NOT NULL,
                'effective_date_updated', p_effective_date IS NOT NULL,
                'expiry_date_updated', TRUE,  -- Always considered (can be NULL)
                'assigned_by_updated', p_assigned_by IS NOT NULL
            )
        );
    
    -- DELETE action (HARD DELETE) - Uses cardid only
    ELSIF UPPER(p_action) = 'DELETE' THEN
        IF p_cardid IS NULL THEN
            RETURN json_build_object('success', false, 'message', 'cardid is required for DELETE');
        END IF;
        
        -- Check if any records exist for this cardid
        SELECT COUNT(*) INTO v_count 
        FROM public.cardprofilemapping 
        WHERE cardid = p_cardid;
        
        IF v_count = 0 THEN
            RETURN json_build_object('success', false, 'message', 'No records found for this cardid: ' || p_cardid);
        END IF;
        
        -- HARD DELETE (permanent removal)
        DELETE FROM public.cardprofilemapping
        WHERE cardid = p_cardid;
          
        GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
        
        RETURN json_build_object(
            'success', true,
            'message', v_affected_rows || ' record(s) permanently removed for cardid: ' || p_cardid,
            'affected_rows', v_affected_rows,
            'cardid', p_cardid,
            'delete_type', 'HARD_DELETE'
        );
    
    -- GET action - Uses cardid only
    ELSIF UPPER(p_action) = 'GET' THEN
        IF p_cardid IS NULL THEN
            RETURN json_build_object('success', false, 'message', 'cardid is required for GET');
        END IF;
        
        -- Get ALL mappings for the cardid
        SELECT json_build_object(
            'success', true,
            'data', COALESCE(json_agg(row_to_json(t)), '[]'::json),
            'count', COUNT(*),
            'cardid', p_cardid
        ) INTO v_result
        FROM (
            SELECT 
                card_profile_id,
                cardid,
                profileid,
                status,
                effective_date,
                expiry_date,
                assigned_by,
                assigned_at
            FROM public.cardprofilemapping
            WHERE cardid = p_cardid
            ORDER BY assigned_at DESC
        ) t;
        
        IF v_result IS NULL OR (v_result->>'count')::INTEGER = 0 THEN
            RETURN json_build_object('success', false, 'message', 'No records found for this cardid: ' || p_cardid, 'cardid', p_cardid);
        END IF;
        
        RETURN v_result;
    
    -- LIST action (multiple records with filters)
    ELSIF UPPER(p_action) = 'LIST' THEN
        SELECT json_build_object(
            'success', true,
            'data', COALESCE(json_agg(row_to_json(t)), '[]'::json),
            'count', COUNT(*),
            'filters', json_build_object(
                'cardid', p_cardid,
                'profileid', p_profileid,
                'status', p_status,
                'effective_date', p_effective_date
            )
        ) INTO v_result
        FROM (
            SELECT 
                card_profile_id,
                cardid,
                profileid,
                status,
                effective_date,
                expiry_date,
                assigned_by,
                assigned_at
            FROM public.cardprofilemapping
            WHERE 
                (p_cardid IS NULL OR cardid = p_cardid)
                AND (p_profileid IS NULL OR profileid = p_profileid)
                AND (p_status IS NULL OR status = p_status)
                AND (p_effective_date IS NULL OR effective_date = p_effective_date)
            ORDER BY assigned_at DESC
        ) t;
        
        RETURN v_result;
    
    ELSE
        RETURN json_build_object('success', false, 'message', 'Invalid action. Use INSERT, UPDATE, DELETE, GET, or LIST');
    END IF;
    
EXCEPTION
    WHEN unique_violation THEN
        RETURN json_build_object('success', false, 'message', 'Duplicate card-profile mapping');
    WHEN foreign_key_violation THEN
        RETURN json_build_object('success', false, 'message', 'Invalid profileid - does not exist in profilemaster');
    WHEN OTHERS THEN
        RETURN json_build_object('success', false, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION public.fcardprofilemappingcrud(p_action character varying, p_card_profile_id character varying, p_cardid character varying, p_profileid character varying, p_status character varying, p_effective_date date, p_expiry_date date, p_assigned_by character varying) OWNER TO postgres;

--
-- TOC entry 462 (class 1255 OID 24284)
-- Name: fchargeconfigcrud(character varying, character varying, character varying, character varying, character varying, double precision, numeric, character varying, character varying, character varying, integer, character varying, text, boolean, boolean, date, date, character varying, inet, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fchargeconfigcrud(p_action character varying, p_chargeid character varying DEFAULT NULL::character varying, p_chargename character varying DEFAULT NULL::character varying, p_charge_type character varying DEFAULT NULL::character varying, p_productid character varying DEFAULT NULL::character varying, p_percentage double precision DEFAULT NULL::double precision, p_amount numeric DEFAULT NULL::numeric, p_currency character varying DEFAULT 'NPR'::character varying, p_status character varying DEFAULT NULL::character varying, p_paymentmethod character varying DEFAULT NULL::character varying, p_graceperiod integer DEFAULT NULL::integer, p_applies_to character varying DEFAULT NULL::character varying, p_calculation_rule text DEFAULT NULL::text, p_istaxable boolean DEFAULT NULL::boolean, p_isactive boolean DEFAULT NULL::boolean, p_effectivedate date DEFAULT NULL::date, p_expirydate date DEFAULT NULL::date, p_user_id character varying DEFAULT NULL::character varying, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_old_record JSONB;
    v_new_record JSONB;
    v_audit_description TEXT;
    v_error_message TEXT;
    v_error_detail TEXT;
    v_error_hint TEXT;
    v_existing_chargeid VARCHAR(5);
    v_charge_count INTEGER;
    v_product_count INTEGER;
    v_return_message TEXT;
    v_validation_error TEXT;
BEGIN
    -- Initialize result
    v_result := '{"success": false, "message": "Unknown error", "data": null}'::JSONB;
    
    -- Trim and validate inputs
    p_action := UPPER(TRIM(p_action));
    p_chargeid := TRIM(p_chargeid);
    p_chargename := TRIM(p_chargename);
    p_charge_type := UPPER(TRIM(p_charge_type));
    p_productid := TRIM(p_productid);
    p_currency := UPPER(TRIM(p_currency));
    p_status := UPPER(TRIM(p_status));
    p_paymentmethod := TRIM(p_paymentmethod);
    p_applies_to := TRIM(p_applies_to);
    p_calculation_rule := TRIM(p_calculation_rule);
    
    -- Log function call for debugging
    INSERT INTO public.audit_trail (
        entity_type, 
        action_type, 
        description, 
        data, 
        user_id, 
        ip_address, 
        user_agent
    ) VALUES (
        'FUNCTION_CALL',
        'EXECUTE',
        'fchargeconfigCRUD called with action: ' || p_action,
        jsonb_build_object(
            'chargeid', p_chargeid,
            'chargename', p_chargename,
            'action', p_action
        ),
        p_user_id,
        p_ip_address,
        p_user_agent
    );
    
    -- Validate action parameter
    IF p_action NOT IN ('INSERT', 'UPDATE', 'DELETE', 'LIST', 'SELECT', 'LIST_BY_PRODUCT', 'LIST_ACTIVE') THEN
        RAISE EXCEPTION 'Invalid action. Must be INSERT, UPDATE, DELETE, LIST, SELECT, LIST_BY_PRODUCT, or LIST_ACTIVE';
    END IF;
    
    -- Validate required parameters based on action
    CASE p_action
        WHEN 'INSERT' THEN
            -- Validate mandatory fields for INSERT
            IF p_chargename IS NULL OR p_chargename = '' THEN
                RAISE EXCEPTION 'chargename is required for INSERT';
            END IF;
            
            IF p_charge_type IS NULL OR p_charge_type = '' THEN
                RAISE EXCEPTION 'charge_type is required for INSERT';
            END IF;
            
            -- Check if parent product exists (if provided)
            IF p_productid IS NOT NULL AND p_productid != '' THEN
                SELECT COUNT(*) INTO v_product_count
                FROM public.products
                WHERE productid = p_productid;
                
                IF v_product_count = 0 THEN
                    RAISE EXCEPTION 'Parent product with productid "%" does not exist', p_productid;
                END IF;
            END IF;
            
            -- Validate charge_type against allowed values
            IF p_charge_type NOT IN ('PER', 'FLAT', 'BOTH') THEN
                RAISE EXCEPTION 'Invalid charge_type. Must be PER, FLAT, or BOTH';
            END IF;
            
            -- Validate status if provided
            IF p_status IS NOT NULL AND p_status != '' THEN
                IF p_status NOT IN ('A', 'I') THEN
                    RAISE EXCEPTION 'Invalid status. Must be A (Active) or I (Inactive)';
                END IF;
            ELSE
                p_status := 'A'; -- Default to Active
            END IF;
            
            -- Validate business rules
            IF p_charge_type = 'PER' AND p_percentage IS NULL THEN
                RAISE EXCEPTION 'percentage is required for charge_type = PER';
            END IF;
            
            IF p_charge_type = 'FLAT' AND p_amount IS NULL THEN
                RAISE EXCEPTION 'amount is required for charge_type = FLAT';
            END IF;
            
            IF p_charge_type = 'BOTH' AND (p_percentage IS NULL OR p_amount IS NULL) THEN
                RAISE EXCEPTION 'Both percentage and amount are required for charge_type = BOTH';
            END IF;
            
            -- Validate dates
            IF p_effectivedate IS NOT NULL AND p_expirydate IS NOT NULL THEN
                IF p_effectivedate > p_expirydate THEN
                    RAISE EXCEPTION 'effectivedate cannot be after expirydate';
                END IF;
            END IF;
            
        WHEN 'UPDATE' THEN
            -- Validate UPDATE parameters
            IF p_chargeid IS NULL OR p_chargeid = '' THEN
                RAISE EXCEPTION 'chargeid is required for UPDATE';
            END IF;
            
            -- Check if record exists
            SELECT COUNT(*) INTO v_charge_count
            FROM public.chargeconfig
            WHERE chargeid = p_chargeid;
            
            IF v_charge_count = 0 THEN
                RAISE EXCEPTION 'chargeid "%" not found', p_chargeid;
            END IF;
            
            -- Get old record for audit
            SELECT row_to_json(cc) INTO v_old_record
            FROM public.chargeconfig cc
            WHERE chargeid = p_chargeid;
            
            -- Check if new product exists (if provided)
            IF p_productid IS NOT NULL AND p_productid != '' THEN
                SELECT COUNT(*) INTO v_product_count
                FROM public.products
                WHERE productid = p_productid;
                
                IF v_product_count = 0 THEN
                    RAISE EXCEPTION 'Parent product with productid "%" does not exist', p_productid;
                END IF;
            END IF;
            
            -- Validate charge_type if provided
            IF p_charge_type IS NOT NULL AND p_charge_type != '' THEN
                IF p_charge_type NOT IN ('PER', 'FLAT', 'BOTH') THEN
                    RAISE EXCEPTION 'Invalid charge_type. Must be PER, FLAT, or BOTH';
                END IF;
            END IF;
            
            -- Validate status if provided
            IF p_status IS NOT NULL AND p_status != '' THEN
                IF p_status NOT IN ('A', 'I') THEN
                    RAISE EXCEPTION 'Invalid status. Must be A (Active) or I (Inactive)';
                END IF;
            END IF;
            
        WHEN 'DELETE' THEN
            -- Validate DELETE parameters
            IF p_chargeid IS NULL OR p_chargeid = '' THEN
                RAISE EXCEPTION 'chargeid is required for DELETE';
            END IF;
            
            -- Check if record exists
            SELECT COUNT(*) INTO v_charge_count
            FROM public.chargeconfig
            WHERE chargeid = p_chargeid;
            
            IF v_charge_count = 0 THEN
                RAISE EXCEPTION 'chargeid "%" not found', p_chargeid;
            END IF;
            
            -- Get record for audit
            SELECT row_to_json(cc) INTO v_old_record
            FROM public.chargeconfig cc
            WHERE chargeid = p_chargeid;
            
        WHEN 'SELECT' THEN
            -- Validate SELECT parameters
            IF p_chargeid IS NULL OR p_chargeid = '' THEN
                RAISE EXCEPTION 'chargeid is required for SELECT';
            END IF;
            
        WHEN 'LIST_BY_PRODUCT' THEN
            -- Validate LIST_BY_PRODUCT parameters
            IF p_productid IS NULL OR p_productid = '' THEN
                RAISE EXCEPTION 'productid is required for LIST_BY_PRODUCT';
            END IF;
            
            -- Check if product exists
            SELECT COUNT(*) INTO v_product_count
            FROM public.products
            WHERE productid = p_productid;
            
            IF v_product_count = 0 THEN
                RAISE EXCEPTION 'Product with productid "%" does not exist', p_productid;
            END IF;
            
        WHEN 'LIST_ACTIVE' THEN
            -- No specific validation needed
            NULL;
            
    END CASE;
    
    -- Execute the requested action
    CASE p_action
        WHEN 'INSERT' THEN
            -- Insert new charge config (DO NOT include chargeid - it will be auto-generated)
            INSERT INTO public.chargeconfig (
                chargename,
                charge_type,
                productid,
                percentage,
                amount,
                currency,
                status,
                paymentmethod,
                graceperiod,
                applies_to,
                calculation_rule,
                istaxable,
                isactive,
                effectivedate,
                expirydate
            ) VALUES (
                p_chargename,
                p_charge_type,
                NULLIF(p_productid, ''),
                p_percentage,
                p_amount,
                p_currency,
                p_status,
                NULLIF(p_paymentmethod, ''),
                p_graceperiod,
                NULLIF(p_applies_to, ''),
                NULLIF(p_calculation_rule, ''),
                COALESCE(p_istaxable, false),
                COALESCE(p_isactive, true),
                p_effectivedate,
                p_expirydate
            )
            RETURNING chargeid INTO v_existing_chargeid;
            
            -- Get the newly inserted record
            SELECT jsonb_build_object(
                'chargeid', cc.chargeid,
                'chargename', cc.chargename,
                'charge_type', cc.charge_type,
                'productid', cc.productid,
                'percentage', cc.percentage,
                'amount', cc.amount,
                'currency', cc.currency,
                'status', cc.status,
                'paymentmethod', cc.paymentmethod,
                'graceperiod', cc.graceperiod,
                'applies_to', cc.applies_to,
                'calculation_rule', cc.calculation_rule,
                'istaxable', cc.istaxable,
                'isactive', cc.isactive,
                'effectivedate', cc.effectivedate,
                'expirydate', cc.expirydate,
                'created_date', cc.created_date,
                'updated_date', cc.updated_date
            ) INTO v_new_record
            FROM public.chargeconfig cc
            WHERE chargeid = v_existing_chargeid;
            
            v_return_message := 'Charge configuration created successfully';
            v_audit_description := 'Created new charge: ' || p_chargename;
            
        WHEN 'UPDATE' THEN
            -- Update existing charge config
            UPDATE public.chargeconfig
            SET 
                chargename = COALESCE(NULLIF(p_chargename, ''), chargename),
                charge_type = COALESCE(NULLIF(p_charge_type, ''), charge_type),
                productid = COALESCE(NULLIF(p_productid, ''), productid),
                percentage = COALESCE(p_percentage, percentage),
                amount = COALESCE(p_amount, amount),
                currency = COALESCE(NULLIF(p_currency, ''), currency),
                status = COALESCE(NULLIF(p_status, ''), status),
                paymentmethod = COALESCE(NULLIF(p_paymentmethod, ''), paymentmethod),
                graceperiod = COALESCE(p_graceperiod, graceperiod),
                applies_to = COALESCE(NULLIF(p_applies_to, ''), applies_to),
                calculation_rule = COALESCE(NULLIF(p_calculation_rule, ''), calculation_rule),
                istaxable = COALESCE(p_istaxable, istaxable),
                isactive = COALESCE(p_isactive, isactive),
                effectivedate = COALESCE(p_effectivedate, effectivedate),
                expirydate = COALESCE(p_expirydate, expirydate),
                updated_date = CURRENT_TIMESTAMP
            WHERE chargeid = p_chargeid
            RETURNING chargeid INTO v_existing_chargeid;
            
            -- Get the updated record
            SELECT jsonb_build_object(
                'chargeid', cc.chargeid,
                'chargename', cc.chargename,
                'charge_type', cc.charge_type,
                'productid', cc.productid,
                'percentage', cc.percentage,
                'amount', cc.amount,
                'currency', cc.currency,
                'status', cc.status,
                'paymentmethod', cc.paymentmethod,
                'graceperiod', cc.graceperiod,
                'applies_to', cc.applies_to,
                'calculation_rule', cc.calculation_rule,
                'istaxable', cc.istaxable,
                'isactive', cc.isactive,
                'effectivedate', cc.effectivedate,
                'expirydate', cc.expirydate,
                'created_date', cc.created_date,
                'updated_date', cc.updated_date
            ) INTO v_new_record
            FROM public.chargeconfig cc
            WHERE chargeid = p_chargeid;
            
            v_return_message := 'Charge configuration updated successfully';
            v_audit_description := 'Updated charge: ' || p_chargeid || ' - ' || p_chargename;
            
        WHEN 'DELETE' THEN
            -- Delete charge config
            DELETE FROM public.chargeconfig
            WHERE chargeid = p_chargeid;
            
            v_return_message := 'Charge configuration deleted successfully';
            v_audit_description := 'Deleted charge: ' || p_chargeid;
            v_new_record := NULL;
            
        WHEN 'SELECT' THEN
            -- Select specific charge config
            SELECT jsonb_build_object(
                'chargeid', cc.chargeid,
                'chargename', cc.chargename,
                'charge_type', cc.charge_type,
                'productid', cc.productid,
                'percentage', cc.percentage,
                'amount', cc.amount,
                'currency', cc.currency,
                'status', cc.status,
                'paymentmethod', cc.paymentmethod,
                'graceperiod', cc.graceperiod,
                'applies_to', cc.applies_to,
                'calculation_rule', cc.calculation_rule,
                'istaxable', cc.istaxable,
                'isactive', cc.isactive,
                'effectivedate', cc.effectivedate,
                'expirydate', cc.expirydate,
                'created_date', cc.created_date,
                'updated_date', cc.updated_date
            ) INTO v_new_record
            FROM public.chargeconfig cc
            WHERE chargeid = p_chargeid;
            
            IF v_new_record IS NULL THEN
                RAISE EXCEPTION 'Charge configuration with ID "%" not found', p_chargeid;
            END IF;
            
            v_return_message := 'Charge configuration retrieved successfully';
            v_audit_description := 'Retrieved charge: ' || p_chargeid;
            v_old_record := NULL;
            
        WHEN 'LIST' THEN
            -- Get all charge configs
            SELECT jsonb_agg(
                jsonb_build_object(
                    'chargeid', cc.chargeid,
                    'chargename', cc.chargename,
                    'charge_type', cc.charge_type,
                    'productid', cc.productid,
                    'percentage', cc.percentage,
                    'amount', cc.amount,
                    'currency', cc.currency,
                    'status', cc.status,
                    'paymentmethod', cc.paymentmethod,
                    'graceperiod', cc.graceperiod,
                    'applies_to', cc.applies_to,
                    'calculation_rule', cc.calculation_rule,
                    'istaxable', cc.istaxable,
                    'isactive', cc.isactive,
                    'effectivedate', cc.effectivedate,
                    'expirydate', cc.expirydate,
                    'created_date', cc.created_date,
                    'updated_date', cc.updated_date
                )
            ) INTO v_new_record
            FROM public.chargeconfig cc
            WHERE (p_isactive IS NULL OR cc.isactive = p_isactive)
            ORDER BY cc.chargename, cc.created_date DESC;
            
            IF v_new_record IS NULL THEN
                v_new_record := '[]'::JSONB;
            END IF;
            
            v_return_message := 'Charge configurations listed successfully';
            v_audit_description := 'Listed all charge configurations';
            v_old_record := NULL;
            
        WHEN 'LIST_BY_PRODUCT' THEN
            -- Get all charges for a specific product
            SELECT jsonb_agg(
                jsonb_build_object(
                    'chargeid', cc.chargeid,
                    'chargename', cc.chargename,
                    'charge_type', cc.charge_type,
                    'productid', cc.productid,
                    'percentage', cc.percentage,
                    'amount', cc.amount,
                    'currency', cc.currency,
                    'status', cc.status,
                    'paymentmethod', cc.paymentmethod,
                    'graceperiod', cc.graceperiod,
                    'applies_to', cc.applies_to,
                    'calculation_rule', cc.calculation_rule,
                    'istaxable', cc.istaxable,
                    'isactive', cc.isactive,
                    'effectivedate', cc.effectivedate,
                    'expirydate', cc.expirydate,
                    'created_date', cc.created_date,
                    'updated_date', cc.updated_date
                )
            ) INTO v_new_record
            FROM public.chargeconfig cc
            WHERE cc.productid = p_productid
            AND (p_isactive IS NULL OR cc.isactive = p_isactive)
            ORDER BY cc.charge_type, cc.chargename;
            
            IF v_new_record IS NULL THEN
                v_new_record := '[]'::JSONB;
            END IF;
            
            v_return_message := 'Charge configurations listed for product: ' || p_productid;
            v_audit_description := 'Listed charges for product: ' || p_productid;
            v_old_record := NULL;
            
        WHEN 'LIST_ACTIVE' THEN
            -- Get all active charge configs
            SELECT jsonb_agg(
                jsonb_build_object(
                    'chargeid', cc.chargeid,
                    'chargename', cc.chargename,
                    'charge_type', cc.charge_type,
                    'productid', cc.productid,
                    'percentage', cc.percentage,
                    'amount', cc.amount,
                    'currency', cc.currency,
                    'status', cc.status,
                    'paymentmethod', cc.paymentmethod,
                    'graceperiod', cc.graceperiod,
                    'applies_to', cc.applies_to,
                    'calculation_rule', cc.calculation_rule,
                    'istaxable', cc.istaxable,
                    'isactive', cc.isactive,
                    'effectivedate', cc.effectivedate,
                    'expirydate', cc.expirydate,
                    'created_date', cc.created_date,
                    'updated_date', cc.updated_date
                )
            ) INTO v_new_record
            FROM public.chargeconfig cc
            WHERE cc.isactive = true
            AND (cc.status IS NULL OR cc.status = 'A')
            AND (cc.effectivedate IS NULL OR cc.effectivedate <= CURRENT_DATE)
            AND (cc.expirydate IS NULL OR cc.expirydate >= CURRENT_DATE)
            ORDER BY cc.chargename;
            
            IF v_new_record IS NULL THEN
                v_new_record := '[]'::JSONB;
            END IF;
            
            v_return_message := 'Active charge configurations listed successfully';
            v_audit_description := 'Listed active charges';
            v_old_record := NULL;
            
    END CASE;
    
    -- Log the action to audit trail (except for LIST operations)
    IF p_action NOT IN ('LIST', 'LIST_BY_PRODUCT', 'LIST_ACTIVE') THEN
        INSERT INTO public.audit_trail (
            entity_type, 
            action_type, 
            description, 
            data, 
            user_id, 
            ip_address, 
            user_agent
        ) VALUES (
            'CHARGECONFIG',
            p_action,
            v_audit_description,
            jsonb_build_object(
                'old_record', v_old_record,
                'new_record', v_new_record,
                'chargeid', COALESCE(p_chargeid, v_existing_chargeid),
                'chargename', p_chargename
            ),
            p_user_id,
            p_ip_address,
            p_user_agent
        );
    END IF;
    
    -- Build success response
    v_result := jsonb_build_object(
        'success', true,
        'message', v_return_message,
        'data', CASE 
            WHEN p_action IN ('LIST', 'LIST_BY_PRODUCT', 'LIST_ACTIVE') THEN v_new_record
            ELSE jsonb_build_object('charge', v_new_record)
        END,
        'chargeid', COALESCE(p_chargeid, v_existing_chargeid)
    );
    
    RETURN v_result;
    
EXCEPTION
    WHEN foreign_key_violation THEN
        v_error_message := 'Foreign key violation. The referenced product does not exist.';
        v_error_detail := SQLERRM;
        v_error_hint := 'Ensure the productid exists in products table.';
        
    WHEN check_violation THEN
        v_error_message := 'Check constraint violation. Invalid charge_type or status.';
        v_error_detail := SQLERRM;
        v_error_hint := 'Check allowed values for charge_type (PER, FLAT, BOTH) and status (A, I).';
        
    WHEN OTHERS THEN
        -- Get error details
        GET STACKED DIAGNOSTICS 
            v_error_message = MESSAGE_TEXT,
            v_error_detail = PG_EXCEPTION_DETAIL,
            v_error_hint = PG_EXCEPTION_HINT;
        
    -- Log error to audit trail
    INSERT INTO public.audit_trail (
        entity_type, 
        action_type, 
        description, 
        data, 
        user_id, 
        ip_address, 
        user_agent
    ) VALUES (
        'CHARGECONFIG',
        'ERROR',
        'Error in fchargeconfigCRUD: ' || v_error_message,
        jsonb_build_object(
            'action', p_action,
            'error_detail', v_error_detail,
            'error_hint', v_error_hint,
            'chargeid', p_chargeid,
            'chargename', p_chargename
        ),
        p_user_id,
        p_ip_address,
        p_user_agent
    );
    
    -- Build error response
    v_result := jsonb_build_object(
        'success', false,
        'message', 'Operation failed: ' || v_error_message,
        'error_detail', v_error_detail,
        'error_hint', v_error_hint,
        'data', null
    );
    
    RETURN v_result;
END;
$$;


