CREATE FUNCTION public.fcreateproductid() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    next_seq INT;
    new_id TEXT;
BEGIN
    IF NEW.productid IS NOT NULL THEN
        RETURN NEW;
    END IF;

    SELECT COALESCE(MAX(CAST(SUBSTRING(productid FROM 3) AS INT)), 0) + 1 INTO next_seq FROM products;
    new_id := 'P' || LPAD(next_seq::TEXT, 4, '0');

    NEW.productid := new_id;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fcreateproductid() OWNER TO postgres;

--
-- TOC entry 469 (class 1255 OID 25541)
-- Name: fcreateprofilecardmappingid(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fcreateprofilecardmappingid() RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    next_val BIGINT;
    padded_val VARCHAR(12);
BEGIN
    -- Get the next value from the sequence
    next_val := nextval('s_cardprofile_id_seq');

    -- Pad the numeric value to 9 digits with leading zeros and prefix with 'PCM'
    -- Format: PCM + 9 digits = 12 characters total
    padded_val := 'PCM' || LPAD(next_val::TEXT, 9, '0');
    
    -- Ensure it's exactly 12 characters
    IF LENGTH(padded_val) > 12 THEN
        padded_val := SUBSTRING(padded_val FROM 1 FOR 12);
    END IF;
    
    RETURN padded_val;
END;
$$;


ALTER FUNCTION public.fcreateprofilecardmappingid() OWNER TO postgres;

