CREATE FUNCTION public.fdiag_comprehensivefunctionaltestv1_0_0() RETURNS TABLE(test_id text, test_phase text, test_result text, details text, debug_info text, recommendation text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_test_result RECORD;
    v_success_count INTEGER := 0;
    v_total_tests INTEGER := 10;
    v_function_oid OID;
    v_return_type TEXT;
    v_param_count INTEGER;
    v_success_rate NUMERIC(5,2);
    v_skipped_tests INTEGER := 0;
    v_has_performance_metrics BOOLEAN := FALSE;
    v_has_operation_status BOOLEAN := FALSE;
    v_param_list TEXT := '';
    v_func_name TEXT := 'fdaemonapply_dynamic_charges';
    v_test_start_time TIMESTAMP;
    v_test_end_time TIMESTAMP;
    v_execution_time INTERVAL;
BEGIN
    -- Initialize result table
    CREATE TEMP TABLE IF NOT EXISTS test_results (
        test_id TEXT,
        test_phase TEXT,
        test_result TEXT,
        details TEXT,
        debug_info TEXT,
        recommendation TEXT
    );
    
    -- Clear any existing results
    DELETE FROM test_results;
    
    v_test_start_time := clock_timestamp();
    
    -- =========================================================================
    -- TEST 8.1: Function Existence Check
    -- =========================================================================
    BEGIN
        SELECT p.oid INTO v_function_oid
        FROM pg_proc p 
        JOIN pg_namespace n ON p.pronamespace = n.oid 
        WHERE p.proname = v_func_name
        AND n.nspname NOT LIKE 'pg_%' 
        AND n.nspname != 'information_schema';
        
        IF v_function_oid IS NOT NULL THEN
            v_success_count := v_success_count + 1;
            INSERT INTO test_results VALUES (
                '8.1',
                'Function Existence Check',
                'PASS',
                'Function ' || v_func_name || ' exists in database',
                'OID: ' || v_function_oid || ', Schema: public',
                'Function is properly registered in system catalog'
            );
        ELSE
            INSERT INTO test_results VALUES (
                '8.1',
                'Function Existence Check',
                'FAIL',
                'Function ' || v_func_name || ' not found',
                'Searched in user schemas excluding system schemas',
                'Check if function was created in correct schema or verify function name spelling'
            );
        END IF;
        
    EXCEPTION WHEN others THEN
        INSERT INTO test_results VALUES (
            '8.1',
            'Function Existence Check',
            'ERROR',
            'Database query failed: ' || SQLERRM,
            'Error during pg_proc catalog query',
            'Check database connectivity and user permissions'
        );
    END;
    
    -- =========================================================================
    -- TEST 8.2: Function Signature Analysis
    -- =========================================================================
    IF v_function_oid IS NOT NULL THEN
        BEGIN
            SELECT format_type(p.prorettype, NULL), p.pronargs 
            INTO v_return_type, v_param_count
            FROM pg_proc p 
            WHERE p.oid = v_function_oid;
            
            -- Get parameter information
            SELECT string_agg(
                COALESCE(pa.param_name, 'param' || pa.param_index) || ' ' || 
                format_type(pa.param_type, NULL), ', ' ORDER BY pa.param_index
            ) INTO v_param_list
            FROM (
                SELECT row_number() OVER () as param_index,
                       unnest(COALESCE(p.proargnames, ARRAY[]::text[])) as param_name,
                       unnest(p.proargtypes) as param_type
                FROM pg_proc p WHERE p.oid = v_function_oid
            ) pa;
            
            IF v_param_list IS NULL THEN
                v_param_list := 'No parameters or unable to determine';
            END IF;
            
            v_success_count := v_success_count + 1;
            INSERT INTO test_results VALUES (
                '8.2',
                'Function Signature Analysis',
                'PASS',
                'Function signature validated',
                'Return Type: ' || COALESCE(v_return_type, 'unknown') || 
                ' | Parameters: ' || v_param_list || 
                ' | Parameter Count: ' || v_param_count,
                'Function interface matches expected signature'
            );
                         
        EXCEPTION WHEN others THEN
            INSERT INTO test_results VALUES (
                '8.2',
                'Function Signature Analysis',
                'FAIL',
                'Cannot analyze function signature',
                'Error: ' || SQLERRM || ' | OID: ' || v_function_oid,
                'Check function definition in pg_proc system catalog'
            );
        END;
    ELSE
        v_skipped_tests := v_skipped_tests + 1;
        INSERT INTO test_results VALUES (
            '8.2',
            'Function Signature Analysis',
            'SKIPPED',
            'Function not available for signature check',
            'v_function_oid is NULL from previous test',
            'Resolve function existence issue first'
        );
    END IF;
    
    -- =========================================================================
    -- TEST 8.3: Function Privileges Check
    -- =========================================================================
    IF v_function_oid IS NOT NULL THEN
        BEGIN
            PERFORM 1 FROM pg_proc p
            JOIN pg_namespace n ON p.pronamespace = n.oid
            WHERE p.oid = v_function_oid
            AND has_function_privilege(p.oid, 'execute');
            
            v_success_count := v_success_count + 1;
            INSERT INTO test_results VALUES (
                '8.3',
                'Function Privileges Check',
                'PASS',
                'Current user has EXECUTE privilege on function',
                'Function OID: ' || v_function_oid || ' | Privilege: EXECUTE',
                'Function permissions are properly configured'
            );
            
        EXCEPTION WHEN others THEN
            INSERT INTO test_results VALUES (
                '8.3',
                'Function Privileges Check',
                'FAIL',
                'Privilege check failed',
                'Error: ' || SQLERRM || ' | Function: ' || v_func_name,
                'Grant EXECUTE privilege: GRANT EXECUTE ON FUNCTION ' || v_func_name || ' TO current_user'
            );
        END;
    ELSE
        v_skipped_tests := v_skipped_tests + 1;
        INSERT INTO test_results VALUES (
            '8.3',
            'Function Privileges Check',
            'SKIPPED',
            'Cannot check privileges - function not found',
            'v_function_oid is NULL',
            'Resolve function existence issue first'
        );
    END IF;
    
    -- =========================================================================
    -- TEST 8.4: Basic Function Execution
    -- =========================================================================
    IF v_function_oid IS NOT NULL THEN
        BEGIN
            SELECT * INTO v_test_result 
