                END;
                
                BEGIN
                    IF v_test_result.performance_metrics IS NOT NULL THEN
                        v_has_performance_metrics := TRUE;
                    END IF;
                EXCEPTION WHEN others THEN
                    v_has_performance_metrics := FALSE;
                END;
                
                INSERT INTO test_results VALUES (
                    '8.4',
                    'Basic Function Execution',
