                    ' | operation_status: ' || v_has_operation_status || 
                    ' | performance_metrics: ' || v_has_performance_metrics,
                    'Function is operational and returning expected data structure'
                );
            EXCEPTION WHEN others THEN
                INSERT INTO test_results VALUES (
                    '8.4',
                    'Basic Function Execution',
                    'PASS',
                    'Function executed but return structure analysis failed',
                    'Execution successful | Structure analysis error: ' || SQLERRM,
                    'Verify function return type matches expected structure'
                );
            END;
                         
        EXCEPTION
            WHEN others THEN
                INSERT INTO test_results VALUES (
                    '8.4',
                    'Basic Function Execution',
                    'FAIL',
                    'Function execution failed',
                    'Error: ' || SQLERRM || ' | Parameters: p_dry_run=true',
                    'Check function implementation, parameter types, and dependencies'
                );
        END;
    ELSE
        v_skipped_tests := v_skipped_tests + 1;
        INSERT INTO test_results VALUES (
            '8.4',
            'Basic Function Execution',
            'SKIPPED',
            'Cannot execute - function not found',
            'v_function_oid is NULL',
            'Resolve function existence issue first'
        );
    END IF;
    
    -- =========================================================================
    -- TEST 8.5: Operation Logging Verification
    -- =========================================================================
    BEGIN
        IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'operation_logs') THEN
            PERFORM 1 FROM operation_logs 
