            LIMIT 1;
            
            v_success_count := v_success_count + 1;
            INSERT INTO test_results VALUES (
                '8.5',
                'Operation Logging Verification',
                'PASS',
                'Operation logging is active and contains function records',
                'Found records in operation_logs for function: ' || v_func_name,
                'Logging system is properly capturing function executions'
            );
        ELSE
            v_skipped_tests := v_skipped_tests + 1;
            INSERT INTO test_results VALUES (
                '8.5',
                'Operation Logging Verification',
                'SKIPPED',
                'operation_logs table does not exist',
                'Table operation_logs not found in current schema',
                'Create operation_logs table or check schema permissions'
            );
        END IF;
    EXCEPTION
        WHEN others THEN
            INSERT INTO test_results VALUES (
                '8.5',
                'Operation Logging Verification',
                'FAIL',
                'Operation logging check failed',
                'Error: ' || SQLERRM || ' | Table: operation_logs',
                'Check table permissions and structure'
            );
    END;
    
    -- =========================================================================
    -- TESTS 8.6-8.10: Additional Functional Tests
    -- =========================================================================
    
    -- Test 8.6: Return Structure Validation
    IF v_function_oid IS NOT NULL AND v_has_operation_status THEN
        BEGIN
            SELECT * INTO v_test_result 
            FROM fdaemonapply_dynamic_charges(p_dry_run => true);       
            
            IF v_test_result.operation_status IS NOT NULL THEN
                v_success_count := v_success_count + 1;
                INSERT INTO test_results VALUES (
                    '8.6',
                    'Return Structure Validation',
                    'PASS',
                    'Return structure contains valid operation_status',
                    'operation_status: ' || v_test_result.operation_status,
                    'Function return structure meets expectations'
                );
            ELSE
                INSERT INTO test_results VALUES (
                    '8.6',
                    'Return Structure Validation',
                    'FAIL',
                    'operation_status field is null',
                    'Expected non-null operation_status in return data',
                    'Check function logic for operation_status assignment'
                );
            END IF;
        EXCEPTION
            WHEN others THEN
                INSERT INTO test_results VALUES (
                    '8.6',
                    'Return Structure Validation',
                    'FAIL',
                    'Structure validation failed',
                    'Error: ' || SQLERRM,
                    'Verify function return type consistency'
                );
        END;
    ELSE
        v_skipped_tests := v_skipped_tests + 1;
        INSERT INTO test_results VALUES (
            '8.6',
            'Return Structure Validation',
            'SKIPPED',
            'Cannot validate structure - function or field not available',
            'Function available: ' || (v_function_oid IS NOT NULL) || 
            ' | operation_status field: ' || v_has_operation_status,
            'Ensure function exists and returns operation_status field'
        );
    END IF;
    
    -- Test 8.7: Performance Metrics Check
    IF v_function_oid IS NOT NULL THEN
        BEGIN
            SELECT * INTO v_test_result 
