            IF v_has_performance_metrics THEN
                IF v_test_result.performance_metrics IS NOT NULL THEN
                    v_success_count := v_success_count + 1;
                    INSERT INTO test_results VALUES (
                        '8.7',
                        'Performance Metrics Check',
                        'PASS',
                        'Performance metrics are collected',
                        'performance_metrics: ' || v_test_result.performance_metrics,
                        'Performance monitoring is active'
                    );
                ELSE
                    INSERT INTO test_results VALUES (
                        '8.7',
                        'Performance Metrics Check',
                        'FAIL',
                        'performance_metrics field is null with debug_level=1',
                        'Expected performance data with debug_level=1',
                        'Check performance metrics collection logic in function'
                    );
                END IF;
            ELSE
                v_success_count := v_success_count + 1;
                INSERT INTO test_results VALUES (
                    '8.7',
                    'Performance Metrics Check',
                    'PASS',
                    'Function executed with debug_level=1',
                    'No performance_metrics field in return type',
                    'Consider adding performance metrics to return type'
                );
            END IF;
        EXCEPTION
            WHEN others THEN
                INSERT INTO test_results VALUES (
                    '8.7',
                    'Performance Metrics Check',
                    'FAIL',
                    'Performance test failed',
