    END IF;
    
    CASE p_action
        WHEN 'insert' THEN
            -- Validate required fields
            IF NOT (p_data ? 'variable_key' AND p_data ? 'display_name') THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'Missing required fields: variable_key, display_name'
                );
            END IF;
            
            -- Insert new variable
            INSERT INTO email_variables (
                variable_key,
                display_name,
                description,
                data_source,
                sample_value,
                category
            ) VALUES (
                p_data->>'variable_key',
                p_data->>'display_name',
                p_data->>'description',
                p_data->>'data_source',
                p_data->>'sample_value',
                COALESCE(p_data->>'category', 'general')
            ) RETURNING id, variable_key INTO v_record;
            
            -- Log audit trail
            PERFORM flog_audit_trail(
                'EMAIL_VARIABLES',
                'INSERT',
                'Created email variable: ' || v_record.variable_key,
                jsonb_build_object(
                    'variable_id', v_record.id,
                    'variable_key', v_record.variable_key,
                    'action', 'INSERT'
                )
            );
            
            v_result := jsonb_build_object(
                'success', true,
                'message', 'Variable created successfully',
                'data', jsonb_build_object('id', v_record.id, 'variable_key', v_record.variable_key)
            );
            
        WHEN 'update' THEN
            IF p_id IS NULL THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'ID is required for update'
                );
            END IF;
            
            -- Get current variable key
            SELECT variable_key INTO v_variable_key 
            FROM email_variables 
            WHERE id = p_id;
            
            IF NOT FOUND THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'Variable not found'
                );
            END IF;
            
            -- Build update statement
            v_sql := 'UPDATE email_variables SET';
            
            IF p_data ? 'display_name' THEN
                v_sql := v_sql || ' display_name = ' || quote_literal(p_data->>'display_name');
            END IF;
            IF p_data ? 'description' THEN
                v_sql := v_sql || ', description = ' || quote_literal(p_data->>'description');
            END IF;
            IF p_data ? 'data_source' THEN
                v_sql := v_sql || ', data_source = ' || quote_literal(p_data->>'data_source');
            END IF;
            IF p_data ? 'sample_value' THEN
                v_sql := v_sql || ', sample_value = ' || quote_literal(p_data->>'sample_value');
            END IF;
            IF p_data ? 'category' THEN
                v_sql := v_sql || ', category = ' || quote_literal(p_data->>'category');
            END IF;
            
            v_sql := v_sql || ' WHERE id = ' || quote_literal(p_id::text);
            
            EXECUTE v_sql;
            GET DIAGNOSTICS v_count = ROW_COUNT;
            
            -- Log audit trail
            PERFORM flog_audit_trail(
                'EMAIL_VARIABLES',
                'UPDATE',
                'Updated email variable: ' || v_variable_key,
                jsonb_build_object(
                    'variable_id', p_id,
                    'variable_key', v_variable_key,
                    'new_data', p_data
                )
            );
            
            v_result := jsonb_build_object(
                'success', true,
                'message', 'Variable updated successfully',
                'rows_affected', v_count
            );
            
        WHEN 'delete' THEN
            IF p_id IS NULL THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'ID is required for delete'
                );
            END IF;
            
            -- Get variable key
            SELECT variable_key INTO v_variable_key 
            FROM email_variables 
            WHERE id = p_id;
            
            IF NOT FOUND THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'Variable not found'
                );
            END IF;
            
            -- Delete variable
            DELETE FROM email_variables WHERE id = p_id;
            GET DIAGNOSTICS v_count = ROW_COUNT;
            
            -- Log audit trail
            PERFORM flog_audit_trail(
                'EMAIL_VARIABLES',
                'DELETE',
                'Deleted email variable: ' || v_variable_key,
                jsonb_build_object(
                    'variable_id', p_id,
                    'variable_key', v_variable_key
                )
            );
            
            v_result := jsonb_build_object(
                'success', true,
                'message', 'Variable deleted successfully',
                'rows_deleted', v_count
            );
            
        WHEN 'search' THEN
            -- Build search query
            v_sql := 'SELECT * FROM email_variables WHERE 1=1';
            
            IF p_data ? 'variable_key' THEN
                v_sql := v_sql || ' AND variable_key ILIKE ' || quote_literal('%' || (p_data->>'variable_key') || '%');
            END IF;
            IF p_data ? 'category' THEN
                v_sql := v_sql || ' AND category = ' || quote_literal(p_data->>'category');
            END IF;
            IF p_data ? 'data_source' THEN
                v_sql := v_sql || ' AND data_source = ' || quote_literal(p_data->>'data_source');
            END IF;
            
            -- Order by category then display name
            v_sql := v_sql || ' ORDER BY category, display_name';
            
            -- Execute query and return as JSON
            EXECUTE 'SELECT COALESCE(jsonb_agg(t), ''[]''::jsonb) FROM (' || v_sql || ') t' 
            INTO v_result;
            
            -- Count results
            v_sql := 'SELECT COUNT(*) FROM email_variables WHERE 1=1';
            IF p_data ? 'category' THEN
                v_sql := v_sql || ' AND category = ' || quote_literal(p_data->>'category');
            END IF;
            
            EXECUTE v_sql INTO v_count;
            
            RETURN jsonb_build_object(
                'success', true,
                'data', v_result,
                'total_count', v_count
            );
            
    END CASE;
    
    -- Add debug info if requested
    IF p_debug_level >= 1 THEN
        v_result := v_result || jsonb_build_object('debug', v_debug_info);
    END IF;
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        PERFORM flog_audit_trail(
            'EMAIL_VARIABLES_FUNCTION',
            'ERROR',
            'Error in f_manage_email_variables: ' || SQLERRM,
            jsonb_build_object(
                'error_message', SQLERRM,
                'action', p_action
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Database error: ' || SQLERRM
        );
END;
$$;


ALTER FUNCTION public.femail_variables(p_action character varying, p_data jsonb, p_debug_level integer, p_id uuid) OWNER TO postgres;

--
-- TOC entry 458 (class 1255 OID 27796)
-- Name: fgenerate_instant_cardsrequest_from_cycle(text[], text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fgenerate_instant_cardsrequest_from_cycle(p_requestids text[] DEFAULT NULL::text[], p_status text DEFAULT 'VERIFIED'::text, p_debug_flag boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_batch_id VARCHAR(20);
    v_start_time TIMESTAMP;
    v_end_time TIMESTAMP;
    v_total_processed INTEGER := 0;
    v_total_errors INTEGER := 0;
    v_error_message TEXT;
    v_sql_state TEXT;
	v_pintype VARCHAR(15)=NULL;
	v_maxloopcount INTEGER :=0;--ADDED BY ST FEB-11-2026
    
    -- Cursor for fetching records based on request IDs array and status
    cur_requests CURSOR (p_req_ids text[], p_stat text) FOR 
        SELECT 
            requestid,
            totalnumberofcard,
            currency,
            requestedbranchname,
            scheme,
            cardtype,
            requestedby,
            requestbranchcode,
            pintype,
            flags,
			approved_cards
        FROM instantcardcycle
        WHERE 
            -- If request IDs array is provided, filter by those IDs
            (p_req_ids IS NULL OR requestid = ANY(p_req_ids))
            -- Always filter by status
            AND status = p_stat;
     
    v_record RECORD;
    v_card_counter INTEGER;
    v_dap_iden VARCHAR(20);
    v_customer_id VARCHAR(20);
    v_account_number VARCHAR(20);
    v_request_processed_count INTEGER;
    v_request_error_count INTEGER;
    v_total_requests_found INTEGER := 0;
    
    -- Variables for storing generated records
    v_generated_records JSONB := '[]'::JSONB;
    v_current_record JSONB;
    v_generated_data JSONB;
    
    -- Variables for batch insertion
    v_batch_timestamp TIMESTAMP;
    
    -- Variables for aggregated batch data
    v_request_ids_array JSONB := '[]'::JSONB;
    v_schemes_array JSONB := '[]'::JSONB;
    v_card_types_array JSONB := '[]'::JSONB;
    v_flags_array JSONB := '[]'::JSONB;
    
    -- NEW: Variables for bulk insert
    v_bulk_insert_start TIMESTAMP;
    v_bulk_insert_end TIMESTAMP;
    v_temp_cards_data TEXT;
    v_insert_sql TEXT;
    
BEGIN
    -- Initialize
    v_start_time := CURRENT_TIMESTAMP;
    v_batch_id := 'BATCH' || TO_CHAR(CURRENT_TIMESTAMP, 'YYMMDDHHMISS');
    v_batch_timestamp := CURRENT_TIMESTAMP;
    
    RAISE NOTICE 'Starting function with batch: %, request_ids: %, status: %', 
        v_batch_id, 
        p_requestids, 
        p_status;
    
    -- Start audit log if debug enabled
    BEGIN
        IF p_debug_flag THEN
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD_GEN',
                'START',
                'Starting bulk card generation',
                jsonb_build_object(
                    'batch_id', v_batch_id,
                    'start_time', v_start_time::TEXT,
                    'request_ids', p_requestids,
                    'status_filter', p_status,
                    'process_type', 
                        CASE 
                            WHEN p_requestids IS NOT NULL THEN 'SPECIFIC_REQUESTS'
                            ELSE 'ALL_' || p_status
                        END
                )
            );
        END IF;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Audit log error (ignored): %', SQLERRM;
    END;
    
    -- Count total requests that will be processed
    SELECT COUNT(*) INTO v_total_requests_found
    FROM instantcardcycle
    WHERE 
        (p_requestids IS NULL OR requestid = ANY(p_requestids))
        AND status = p_status;
    
    RAISE NOTICE 'Found % request(s) with status %', v_total_requests_found, p_status;
    
    -- If no records found, return early
    IF v_total_requests_found = 0 THEN
        v_result := jsonb_build_object(
            'success', TRUE,
            'message', 'No records found with the specified criteria',
            'batch_id', v_batch_id,
            'status_filter', p_status,
            'request_ids_provided', p_requestids,
            'total_requests_found', 0,
            'total_processed', 0,
            'total_errors', 0,
            'start_time', v_start_time::TEXT,
            'end_time', CURRENT_TIMESTAMP::TEXT,
            'duration_seconds', 0,
            'generated_records', '[]'::JSONB
        );
        
        -- Log the empty result
        IF p_debug_flag THEN
            BEGIN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_GEN',
                    'NO_RECORDS',
                    'No records found for processing',
                    jsonb_build_object(
                        'batch_id', v_batch_id,
                        'status_filter', p_status,
                        'request_ids', p_requestids
                    )
                );
            EXCEPTION WHEN OTHERS THEN
                RAISE NOTICE 'Audit log error: %', SQLERRM;
            END;
        END IF;
        
        RETURN v_result;
    END IF;
    
    -- ========== BULK INSERT OPTIMIZATION ==========
    -- Generate and insert ALL cards in a single operation
    v_bulk_insert_start := CURRENT_TIMESTAMP;
    
    RAISE NOTICE 'Starting bulk card generation...';
    
    WITH all_cards AS (
        -- Generate card series for each request
        SELECT 
            icc.requestid,
            icc.totalnumberofcard,
            icc.currency,
            icc.requestedbranchname,
            icc.scheme,
            icc.cardtype,
            icc.requestedby,
            icc.requestbranchcode,
            icc.pintype,
            icc.flags,
            gs.card_sequence,
            -- Generate unique IDs using your original logic
            icc.requestid || '_' || LPAD(gs.card_sequence::TEXT, 4, '0') as dap_iden,
            '9000' || LPAD((34456 + gs.card_sequence - 1)::TEXT, 5, '0') as customer_id,
            '900100000' || LPAD((34456 + gs.card_sequence - 1)::TEXT, 5, '0') as account_number
        FROM instantcardcycle icc
        CROSS JOIN LATERAL generate_series(1, icc.approved_cards) as gs(card_sequence)
        WHERE 
            (p_requestids IS NULL OR icc.requestid = ANY(p_requestids))
            AND icc.status = p_status
    )
    -- Bulk insert using your original column values
    INSERT INTO instant_card_applications (
        dap_iden, dap_ban_code, dap_bra_code, dap_user, dap_bat_code,
        dap_cus_type, dap_cus_old_new, dap_cus_iden, dap_date, dap_ast_code,
        dap_firs_nam1, dap_last_nam1, dap_midd_nam1, dap_tit1,
        dap_firs_ide1, dap_firs_iden_typ1, dap_gend1, dap_mst_cod1, dap_cou_cod1,
        dap_requ_acc_numb, dap_requ_acc_curr_code, dap_requ_cpr_code,
        dap_pan_gene_manu_auto, dap_requ_dpr_code,
        dap_chld_titl, dap_chld_firs_name, dap_chld_last_name, dap_chld_name,
        dap_prim_seco_card,
        dap_phon_number, dap_gree_pin_flag,
        firstaddresstype, firstaddressline1, firstadressphone1, firstcity,
        batchid, statusflag, formatid
    )
    SELECT 
        ac.dap_iden,
        '402122', '999', 'CCMSUSER', '10',
        'I', 'N', ac.customer_id, CURRENT_DATE, '1',
        'INSTANT' || ac.card_sequence, 'CARD', NULL, '1',
        '1', '1', '1', '1', COALESCE(ac.currency, '524'),
        ac.account_number, COALESCE(ac.currency, '524'), '731',
        'A', '730',
        '2', 'INSTANT' || ac.card_sequence, 'CARD', 'INSTANT CARD ' || ac.card_sequence,
        'P',
        '1111111111', 'N',
        '08', COALESCE(ac.requestedbranchname, 'Kathmandu'), '1111111111', '30608',
        v_batch_id, 'PENDING', 'AUTO_GENERATED'
    FROM all_cards ac
    ON CONFLICT (dap_iden, batchid) DO NOTHING;
    
    -- Get the total number of cards inserted
    GET DIAGNOSTICS v_total_processed = ROW_COUNT;
    v_bulk_insert_end := CURRENT_TIMESTAMP;
    
    RAISE NOTICE 'Bulk insert completed: % cards generated in % seconds', 
        v_total_processed, 
        EXTRACT(EPOCH FROM (v_bulk_insert_end - v_bulk_insert_start));
    
    -- ========== PROCESS INDIVIDUAL REQUESTS (KEEP YOUR ORIGINAL LOGIC) ==========
    -- Open cursor and process records for status updates, logging, and JSON building
    OPEN cur_requests(p_requestids, p_status);
    
    LOOP
        FETCH cur_requests INTO v_record;
        EXIT WHEN NOT FOUND;
        
        RAISE NOTICE 'Processing request metadata: %', v_record.requestid;
        
        -- Reset per-request counters (for tracking only)
        v_request_processed_count := 0;
        v_request_error_count := 0;
        v_generated_data := '[]'::JSONB;
        
        -- Add request ID to aggregated array
        v_request_ids_array := v_request_ids_array || to_jsonb(v_record.requestid);
        
        -- Add scheme to aggregated array (if not null and not already present)
        IF v_record.scheme IS NOT NULL THEN
            v_schemes_array := v_schemes_array || to_jsonb(v_record.scheme);
        END IF;
        
        -- Add card type to aggregated array (if not null and not already present)
        IF v_record.cardtype IS NOT NULL THEN
            v_card_types_array := v_card_types_array || to_jsonb(v_record.cardtype);
        END IF;
        
        -- Add flags to aggregated array (if not null)
        IF v_record.flags IS NOT NULL THEN
            v_flags_array := v_flags_array || to_jsonb(v_record.flags);
        END IF;
        
        -- Count cards generated for this specific request
        SELECT COUNT(*) INTO v_request_processed_count
        FROM instant_card_applications
        WHERE batchid = v_batch_id 
          AND dap_iden LIKE v_record.requestid || '_%';
		   RAISE NOTICE 'Total Count approved_cards:%',v_record.approved_cards;
           IF v_record.approved_cards>0 then
		  	   		v_maxloopcount=v_record.approved_cards;
		  ELSE
		  			v_maxloopcount=v_record.totalnumberofcard;
		  END IF;
		  RAISE NOTICE 'Value set to v_maxloopcount:%',v_maxloopcount;
        -- Build generated data for this request
        FOR v_card_counter IN 1..v_maxloopcount LOOP
            BEGIN
                -- Generate IDs using your original logic
                v_dap_iden := v_record.requestid || '_' || LPAD(v_card_counter::TEXT, 4, '0');
                v_customer_id := '9000' || LPAD((34456 + v_card_counter - 1)::TEXT, 5, '0');
                v_account_number := '900100000' || LPAD((34456 + v_card_counter - 1)::TEXT, 5, '0');
                
                -- Check if card was actually inserted
                PERFORM 1 FROM instant_card_applications 
                WHERE dap_iden = v_dap_iden AND batchid = v_batch_id;
                
                IF FOUND THEN
                    -- Create JSON object for this generated card (your original logic)
                    v_current_record := jsonb_strip_nulls(jsonb_build_object(
                        'dap_iden', v_dap_iden,
                        'dap_cus_iden', v_customer_id,
                        'dap_requ_acc_numb', v_account_number,
                        'dap_firs_nam1', 'INSTANT' || v_card_counter,
                        'dap_last_nam1', 'CARD',
                        'dap_requ_acc_curr_code', COALESCE(v_record.currency, '524'),
                        'firstaddressline1', COALESCE(v_record.requestedbranchname, 'Kathmandu'),
                        'batchid', v_batch_id,
                        'statusflag', 'PENDING',
                        'formatid', 'AUTO_GENERATED',
                        'requestid', v_record.requestid,
                        'scheme', v_record.scheme,
                        'cardtype', v_record.cardtype,
                        'pintype', v_record.pintype,
                        'flags', v_record.flags,
                        'card_sequence', v_card_counter,
                        'total_cards_for_request', v_record.totalnumberofcard,
                        'generated_at', CURRENT_TIMESTAMP::TEXT
                    ));
                    
                    -- Add to generated data array for this request
                    v_generated_data := v_generated_data || v_current_record;
                ELSE
                    -- Card insertion failed
                    v_request_error_count := v_request_error_count + 1;
                    v_total_errors := v_total_errors + 1;
                    
                    v_current_record := jsonb_build_object(
                        'error', true,
                        'requestid', v_record.requestid,
                        'card_sequence', v_card_counter,
                        'error_message', 'Card not inserted in bulk operation',
                        'error_time', CURRENT_TIMESTAMP::TEXT
                    );
                    
                    v_generated_data := v_generated_data || v_current_record;
                END IF;
                
            EXCEPTION
                WHEN OTHERS THEN
                    GET STACKED DIAGNOSTICS 
                        v_error_message = MESSAGE_TEXT,
                        v_sql_state = RETURNED_SQLSTATE;
                    
                    v_request_error_count := v_request_error_count + 1;
                    v_total_errors := v_total_errors + 1;
                    
                    v_current_record := jsonb_build_object(
                        'error', true,
                        'requestid', v_record.requestid,
                        'card_sequence', v_card_counter,
                        'error_message', v_error_message,
                        'sql_state', v_sql_state,
                        'error_time', CURRENT_TIMESTAMP::TEXT
                    );
                    
                    v_generated_data := v_generated_data || v_current_record;
            END;
        END LOOP;
        
        RAISE NOTICE 'Updating status for request % to PROCESSING', v_record.requestid;
        
        -- ✅ UPDATE STATUS FOR THIS SINGLE REQUESTID (your original logic)
        BEGIN
            UPDATE instantcardcycle
            SET status = 'PROCESSING'
            WHERE requestid = v_record.requestid;
            
            RAISE NOTICE 'Updated request % to PROCESSING (cards: %, errors: %)', 
                v_record.requestid, v_request_processed_count, v_request_error_count;
            
            -- Add request summary to generated records (your original logic)
            IF jsonb_array_length(v_generated_data) > 0 THEN
                v_current_record := jsonb_strip_nulls(jsonb_build_object(
                    'request_summary', jsonb_build_object(
                        'requestid', v_record.requestid,
                        'total_cards_requested', v_record.totalnumberofcard,
                        'cards_successfully_generated', v_request_processed_count,
                        'cards_failed', v_request_error_count,
                        'scheme', v_record.scheme,
                        'cardtype', v_record.cardtype,
                        'currency', v_record.currency,
                        'pintype', v_record.pintype,
                        'status_before', p_status,
                        'status_after', 'PROCESSING',
                        'batch_id', v_batch_id,
                        'processed_at', CURRENT_TIMESTAMP::TEXT
                    ),
                    'generated_cards', v_generated_data
                ));
                
                v_generated_records := v_generated_records || v_current_record;
            END IF;
            
            -- ✅ SEND AUDIT TRAIL FOR THIS REQUESTID (your original logic)
            IF p_debug_flag THEN
                BEGIN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_GEN',
                        'REQUEST_PROCESSED',
                        'Request processed: ' || v_record.requestid,
                        jsonb_build_object(
                            'requestid', v_record.requestid,
                            'batch_id', v_batch_id,
                            'cards_generated', v_request_processed_count,
                            'cards_failed', v_request_error_count,
                            'total_cards', v_record.totalnumberofcard,
                            'original_status', p_status,
                            'new_status', 'PROCESSING',
                            'processing_time', CURRENT_TIMESTAMP::TEXT
                        )
                    );
                    RAISE NOTICE 'Audit log sent for request %', v_record.requestid;
                EXCEPTION WHEN OTHERS THEN
                    RAISE NOTICE 'Audit log error for request %: %', v_record.requestid, SQLERRM;
                END;
            END IF;
            
        EXCEPTION
            WHEN OTHERS THEN
                GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;
                RAISE NOTICE 'Failed to update request %: %', v_record.requestid, v_error_message;
        END;
        
    END LOOP;
    
    CLOSE cur_requests;
    
    -- ✅ INSERT AGGREGATED BATCH RECORD (your original logic)
    BEGIN
        -- Remove duplicates from arrays using DISTINCT
        v_request_ids_array := (
            SELECT jsonb_agg(DISTINCT value)
            FROM jsonb_array_elements(v_request_ids_array)
        );
        
        v_schemes_array := (
            SELECT jsonb_agg(DISTINCT value)
            FROM jsonb_array_elements(v_schemes_array)
        );
        
        v_card_types_array := (
            SELECT jsonb_agg(DISTINCT value)
            FROM jsonb_array_elements(v_card_types_array)
        );
        
        v_flags_array := (
            SELECT jsonb_agg(DISTINCT value)
            FROM jsonb_array_elements(v_flags_array)
        );
        
        -- Insert into instant_card_generation_batches table
		SELECT DISTINCT pintype INTO v_pintype FROM instantcardcycle
    	WHERE requestid = ANY(p_requestids)AND pintype IS NOT NULL LIMIT 1;
        INSERT INTO instant_card_generation_batches (
            batch_id,
            request_ids,
            status,
            cards_generated,
            cards_failed,
            schemes,
            card_types,
            duration,
            timestamp,
            flags,
			pintype
        ) VALUES (
            v_batch_id,
            COALESCE(v_request_ids_array, '[]'::JSONB),
            'PROCESSING',
            v_total_processed,
            v_total_errors,
            COALESCE(v_schemes_array, '[]'::JSONB),
            COALESCE(v_card_types_array, '[]'::JSONB),
            NULL,
            v_batch_timestamp,
            COALESCE(v_flags_array, '[]'::JSONB),
			v_pintype
        );
        
        RAISE NOTICE 'Successfully inserted batch record % into instant_card_generation_batches', 
            v_batch_id;
        
    EXCEPTION
        WHEN OTHERS THEN
            GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;
            RAISE NOTICE 'Failed to insert into instant_card_generation_batches: %', v_error_message;
    END;
    
    -- Build final result with performance metrics
    v_end_time := CURRENT_TIMESTAMP;
    v_result := jsonb_build_object(
        'success', TRUE,
        'message', 'Bulk generation completed',
        'batch_id', v_batch_id,
        'status_filter', p_status,
        'request_ids_provided', p_requestids,
        'total_requests_found', v_total_requests_found,
        'total_processed', v_total_processed,
        'total_errors', v_total_errors,
        'start_time', v_start_time::TEXT,
        'end_time', v_end_time::TEXT,
        'duration_seconds', EXTRACT(EPOCH FROM (v_end_time - v_start_time)),
        'performance', jsonb_strip_nulls(jsonb_build_object(
            'bulk_insert_duration', EXTRACT(EPOCH FROM (v_bulk_insert_end - v_bulk_insert_start)),
            'requests_per_second', 
                CASE 
                    WHEN EXTRACT(EPOCH FROM (v_end_time - v_start_time)) > 0 
                    THEN v_total_requests_found / EXTRACT(EPOCH FROM (v_end_time - v_start_time))
                END,
            'cards_per_second',
                CASE 
                    WHEN EXTRACT(EPOCH FROM (v_end_time - v_start_time)) > 0 
                    THEN v_total_processed / EXTRACT(EPOCH FROM (v_end_time - v_start_time))
                END
        )),
        'generated_records', v_generated_records,
        'batch_records_inserted', 1,
        'request_ids_in_batch', v_request_ids_array
    );
    
    -- ✅ Update duration for the batch record (your original logic)
    BEGIN
        UPDATE instant_card_generation_batches 
        SET duration = EXTRACT(EPOCH FROM (v_end_time - v_start_time)) || ' seconds'
        WHERE batch_id = v_batch_id;
        
        RAISE NOTICE 'Updated duration for batch %', v_batch_id;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Failed to update duration: %', SQLERRM;
    END;
    
    -- Final audit log if debug enabled (your original logic)
    BEGIN
        IF p_debug_flag THEN
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD_GEN',
                'COMPLETE',
                'Bulk card generation completed',
                jsonb_build_object(
                    'batch_id', v_batch_id,
                    'total_requests', v_total_requests_found,
                    'total_cards_generated', v_total_processed,
                    'total_errors', v_total_errors,
                    'status_filter', p_status,
                    'request_ids_count', 
                        CASE 
                            WHEN p_requestids IS NULL THEN 0
                            ELSE array_length(p_requestids, 1)
                        END,
                    'duration_seconds', EXTRACT(EPOCH FROM (v_end_time - v_start_time)),
                    'start_time', v_start_time::TEXT,
                    'end_time', v_end_time::TEXT,
                    'batch_table_inserted', true,
                    'batch_request_count', jsonb_array_length(v_request_ids_array),
                    'bulk_insert_performance', EXTRACT(EPOCH FROM (v_bulk_insert_end - v_bulk_insert_start))
                )
            );
        END IF;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Final audit error: %', SQLERRM;
    END;
    
    RAISE NOTICE 'Function completed: total processed=%, total errors=%, batch record created for % request(s)', 
        v_total_processed, v_total_errors, v_total_requests_found;
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS 
            v_error_message = MESSAGE_TEXT,
            v_sql_state = RETURNED_SQLSTATE;
        
        RAISE NOTICE 'CRITICAL FUNCTION ERROR: %', v_error_message;
        RAISE NOTICE 'SQL State: %', v_sql_state;
        
        -- Try to insert batch record even on error (with current state)
        BEGIN
            INSERT INTO instant_card_generation_batches (
                batch_id,
                request_ids,
                status,
                cards_generated,
                cards_failed,
                schemes,
                card_types,
                duration,
                timestamp,
                flags
            ) VALUES (
                v_batch_id,
                COALESCE(v_request_ids_array, '[]'::JSONB),
                'FAILED',
                v_total_processed,
                v_total_errors,
                COALESCE(v_schemes_array, '[]'::JSONB),
                COALESCE(v_card_types_array, '[]'::JSONB),
                EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP - v_start_time)) || ' seconds',
                v_batch_timestamp,
                COALESCE(v_flags_array, '[]'::JSONB)
            );
            
            RAISE NOTICE 'Inserted FAILED batch record %', v_batch_id;
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE 'Could not insert failed batch record: %', SQLERRM;
        END;
        
        -- Build error result (still include any generated records so far)
        v_result := jsonb_build_object(
            'success', FALSE,
            'message', 'Critical error: ' || v_error_message,
            'batch_id', v_batch_id,
            'status_filter', p_status,
            'request_ids_provided', p_requestids,
            'total_processed', v_total_processed,
            'total_errors', v_total_errors,
            'sql_state', v_sql_state,
            'generated_records', COALESCE(v_generated_records, '[]'::JSONB),
            'error_time', CURRENT_TIMESTAMP::TEXT
        );
        
        RETURN v_result;
END;
$$;


ALTER FUNCTION public.fgenerate_instant_cardsrequest_from_cycle(p_requestids text[], p_status text, p_debug_flag boolean) OWNER TO postgres;

--
-- TOC entry 443 (class 1255 OID 26655)
-- Name: fget_batch_data_by_status(text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fget_batch_data_by_status(p_statusflag text DEFAULT 'PENDING'::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_total_count INTEGER := 0;
    v_batches JSONB;
    v_error_message TEXT;
    v_batch_record RECORD;
BEGIN
    -- Get total count of batches (not individual cards)
    SELECT COUNT(DISTINCT batchid) INTO v_total_count
    FROM instant_card_applications
    WHERE statusflag = p_statusflag;
    
    -- Initialize batches array
    v_batches := '[]'::jsonb;
    
    -- Get batch data with aggregated information
    FOR v_batch_record IN (
        SELECT 
            batchid,
            -- Extract distinct request IDs from dap_iden (format: REQUESTID_XXXX)
            jsonb_agg(DISTINCT SUBSTRING(dap_iden FROM 1 FOR 12)) as request_ids,
            -- Get status flag
            MIN(statusflag) as status,  -- All should have same status
            -- Count cards in this batch
            COUNT(*) as cards_generated,
            -- Count failed cards (if we had a failure flag)
            COUNT(*) FILTER (WHERE statusflag = 'FAILED') as cards_failed,
            -- Get distinct schemes (if available in data)
            COALESCE(jsonb_agg(DISTINCT 'MASTERCARD'::text), '[]'::jsonb) as schemes, -- Placeholder
            -- Get distinct card types (if available in data)
            COALESCE(jsonb_agg(DISTINCT 'INSTANT'::text), '[]'::jsonb) as card_types, -- Placeholder
            -- Placeholder for duration
            '0.000000 seconds' as duration,
            -- Get batch creation timestamp
            MIN(created_at) as timestamp,
            -- Get distinct flags (if available in data)
            COALESCE(jsonb_agg(DISTINCT 'A'::text), '[]'::jsonb) as flags, -- Placeholder
            -- Calculate success rate
            CASE 
                WHEN COUNT(*) > 0 THEN 
                    ROUND((COUNT(*) FILTER (WHERE statusflag != 'FAILED')::DECIMAL * 100.0 / COUNT(*)), 2)
                ELSE 0 
            END as success_rate,
            -- Count distinct requests
            COUNT(DISTINCT SUBSTRING(dap_iden FROM 1 FOR 12)) as request_count
        FROM instant_card_applications
        WHERE statusflag = p_statusflag
        GROUP BY batchid
        ORDER BY MIN(created_at) DESC
        LIMIT p_limit
        OFFSET p_offset
    ) LOOP
        -- Add each batch to the JSON array in your format
        v_batches := v_batches || jsonb_build_object(
            'batch_id', v_batch_record.batchid,
            'request_ids', v_batch_record.request_ids,
            'status', v_batch_record.status,
            'cards_generated', v_batch_record.cards_generated,
            'cards_failed', v_batch_record.cards_failed,
            'schemes', v_batch_record.schemes,
            'card_types', v_batch_record.card_types,
            'duration', v_batch_record.duration,
            'timestamp', v_batch_record.timestamp,
            'flags', v_batch_record.flags,
            'total_cards', v_batch_record.cards_generated + v_batch_record.cards_failed,
            'success_rate', v_batch_record.success_rate,
            'request_count', v_batch_record.request_count
        );
    END LOOP;
    
    -- Build result
    v_result := jsonb_build_object(
        'success', TRUE,
        'status_filter', p_statusflag,
        'total_batches', v_total_count,
        'returned_batches', COALESCE(jsonb_array_length(v_batches), 0),
        'limit', p_limit,
        'offset', p_offset,
        'batches', COALESCE(v_batches, '[]'::jsonb)
    );
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;
        
        v_result := jsonb_build_object(
            'success', FALSE,
            'error', v_error_message,
            'status_filter', p_statusflag
        );
        
        RETURN v_result;
END;
$$;


ALTER FUNCTION public.fget_batch_data_by_status(p_statusflag text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- TOC entry 440 (class 1255 OID 26656)
-- Name: fget_batch_summary_by_status(text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fget_batch_summary_by_status(p_status text DEFAULT 'PROCESSING'::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_total_count INTEGER := 0;
    v_batches JSONB;
    v_error_message TEXT;
BEGIN
    -- Get total count from instant_card_generation_batches
    SELECT COUNT(*) INTO v_total_count
    FROM instant_card_generation_batches
    WHERE status = p_status;
    
    -- Get batch data directly from the batch table
    SELECT jsonb_agg(
        jsonb_build_object(
            's_no', s_no,
            'batch_id', batch_id,
            'request_ids', request_ids,
            'status', status,
            'cards_generated', cards_generated,
            'cards_failed', cards_failed,
            'schemes', schemes,
            'card_types', card_types,
            'duration', duration,
            'timestamp', timestamp,
            'flags', flags,
            'total_cards', total_cards,
            'success_rate', success_rate,
            'request_count', request_count
        ) ORDER BY timestamp DESC
    ) INTO v_batches
    FROM instant_card_generation_batches
    WHERE status = p_status
    ORDER BY timestamp DESC
    LIMIT p_limit
    OFFSET p_offset;
    
    -- Build result
    v_result := jsonb_build_object(
        'success', TRUE,
        'status_filter', p_status,
        'total_batches', v_total_count,
        'returned_batches', COALESCE(jsonb_array_length(v_batches), 0),
        'limit', p_limit,
        'offset', p_offset,
        'batches', COALESCE(v_batches, '[]'::jsonb)
    );
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;
        
        v_result := jsonb_build_object(
            'success', FALSE,
            'error', v_error_message,
            'status_filter', p_status
        );
        
        RETURN v_result;
END;
$$;


