--
-- TOC entry 427 (class 1255 OID 30931)
-- Name: fget_creditbatchid(character varying, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fget_creditbatchid(p_username character varying DEFAULT NULL::character varying, p_debug_level integer DEFAULT 1) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    result_json JSON;
    v_total_batches INTEGER;
    v_total_records INTEGER;
    v_start_time TIMESTAMP;
    v_end_time TIMESTAMP;
    v_execution_time NUMERIC(10,3);
    
    -- Debug level constants
    c_debug_none CONSTANT INTEGER := 0;
    c_debug_basic CONSTANT INTEGER := 1;
    c_debug_detailed CONSTANT INTEGER := 2;
    c_debug_verbose CONSTANT INTEGER := 3;
BEGIN
    -- Validate debug level
    IF p_debug_level NOT IN (0, 1, 2, 3) THEN
        p_debug_level := c_debug_basic;
    END IF;
    
    v_start_time := clock_timestamp();
    
    -- Basic logging
    IF p_debug_level >= c_debug_basic THEN
        RAISE NOTICE '========================================================================';
        RAISE NOTICE 'Starting batch statistics function';
        RAISE NOTICE 'Username: %', COALESCE(p_username, 'SYSTEM');
        RAISE NOTICE 'Debug level: %', p_debug_level;
        RAISE NOTICE 'Start time: %', v_start_time;
        RAISE NOTICE '========================================================================';
    END IF;
    
    -- Check if table has data
    IF NOT EXISTS (SELECT 1 FROM public.credit_card_application LIMIT 1) THEN
        IF p_debug_level >= c_debug_basic THEN
            RAISE NOTICE 'Table credit_card_application is empty';
        END IF;
        
        v_end_time := clock_timestamp();
        v_execution_time := EXTRACT(EPOCH FROM (v_end_time - v_start_time));
        
        IF p_debug_level >= c_debug_basic THEN
            RAISE NOTICE 'Completed in % seconds', ROUND(v_execution_time::NUMERIC, 3);
            RAISE NOTICE 'Returning empty array';
        END IF;
        
        RETURN '[]'::JSON;
    END IF;
    
    -- Get batch statistics
    IF p_debug_level >= c_debug_detailed THEN
        RAISE NOTICE 'Executing aggregation query...';
    END IF;
    
    SELECT json_agg(
        json_build_object(
            'batch_id', batch_id,
            'total_records', total_records,
            'greenpin_request_count', greenpin_count,
            'paperpin_request_count', paperpin_count
        )
    ) INTO result_json
    FROM (
        SELECT 
            batch_id,
            COUNT(*) as total_records,
            COUNT(CASE WHEN dap_gree_pin_flag = 'Y' THEN 1 END) as greenpin_count,
            COUNT(CASE WHEN dap_gree_pin_flag = 'N' OR dap_gree_pin_flag IS NULL THEN 1 END) as paperpin_count
        FROM 
            public.credit_card_application
        WHERE 
            batch_id IS NOT NULL 
            AND batch_id != ''
        GROUP BY 
            batch_id
        ORDER BY 
            batch_id
    ) as batch_stats;
    
    -- Get summary stats
    SELECT COUNT(DISTINCT batch_id), COUNT(*)
    INTO v_total_batches, v_total_records
    FROM public.credit_card_application
    WHERE batch_id IS NOT NULL AND batch_id != '';
    
    v_end_time := clock_timestamp();
    v_execution_time := EXTRACT(EPOCH FROM (v_end_time - v_start_time));
    
    -- Completion logging
    IF p_debug_level >= c_debug_basic THEN
        RAISE NOTICE '========================================================================';
        RAISE NOTICE 'Batch statistics function completed';
        RAISE NOTICE 'Username: %', COALESCE(p_username, 'SYSTEM');
        RAISE NOTICE 'Total batches: %', v_total_batches;
        RAISE NOTICE 'Total records: %', v_total_records;
        RAISE NOTICE 'Execution time: % seconds', ROUND(v_execution_time, 3);
        RAISE NOTICE '========================================================================';
    END IF;
    
    -- Verbose logging
    IF p_debug_level >= c_debug_verbose AND result_json IS NOT NULL THEN
        RAISE NOTICE 'Result sample: %', substring(result_json::TEXT from 1 for 200);
    END IF;
    
    RETURN COALESCE(result_json, '[]'::JSON);
END;
$$;


