    dap_firs_ide1 = COALESCE(v_documentid, dap_firs_ide1),
    dap_firs_iden_typ1 = COALESCE(v_documenttype, dap_firs_iden_typ1),
    dap_gend1 = CASE 
        WHEN v_gender = 'Male' OR v_gender = 'M' THEN '1'
        WHEN v_gender = 'Female' OR v_gender = 'F' THEN '2'
        ELSE COALESCE(dap_gend1, '1')
    END,
    dap_mst_cod1 = CASE 
        WHEN v_maritalstatus = 'M' THEN '1'
        WHEN v_maritalstatus = 'S' THEN '2'
        WHEN v_maritalstatus = 'D' THEN '3'
        WHEN v_maritalstatus = 'W' THEN '4'
        ELSE COALESCE(dap_mst_cod1, '1')
    END,
    dap_cou_cod1 = CASE 
        WHEN v_nationality = 'Nepali' OR v_nationality ILIKE '%nepal%' THEN '524'
        ELSE COALESCE(dap_cou_cod1, '524')
    END,
    dap_requ_acc_numb = COALESCE(v_accountnumber, dap_requ_acc_numb),
