    dap_phon_number = COALESCE(v_mobileno, v_mobile, dap_phon_number),
    dap_email_adr = COALESCE(v_emailid, dap_email_adr),
    firstaddressline1 = COALESCE(v_address, firstaddressline1),
    firstcity = COALESCE(v_customer_branchcode, firstcity, '30608'),
    batch_id = v_batch_id,  -- ONLY batch_id
    updated_at = CURRENT_TIMESTAMP
WHERE dap_cus_iden = v_customercode;
				
                
                
                IF p_debug_level >= c_debug_verbose THEN
                    RAISE NOTICE '  ✓ Updated existing application (DAP_IDEN: %)', v_dap_iden;
                END IF;
                
                v_success_details := v_success_details || jsonb_build_object(
                    'dap_iden', v_dap_iden,
                    'request_id', v_request_id,
                    'customercode', v_customercode,
                    'account_number', v_accountnumber,
                    'customer_name', v_fname || ' ' || v_lname,
                    'action', 'UPDATED',
                    'reason', 'Duplicate customer',
                    'request_index', v_request_index,
                    'timestamp', CURRENT_TIMESTAMP::TEXT
                );
                
            ELSE
                -- ========== STEP 6: Insert New Record ==========
                DECLARE
                    v_dap_gend CHAR(1);
                    v_dap_tit CHAR(1);
                    v_dap_mst_cod CHAR(1);
                    v_country_code VARCHAR(10);
                    v_net_income NUMERIC(15,2);
                    v_customer_age INTEGER;
                BEGIN
                    -- Map gender
                    v_dap_gend := CASE 
                        WHEN v_gender = 'Male' OR v_gender = 'M' OR v_gender ILIKE '%male%' THEN '1'
                        WHEN v_gender = 'Female' OR v_gender = 'F' OR v_gender ILIKE '%female%' THEN '2'
                        ELSE '1'
                    END;
                    
                    -- Map title
                    v_dap_tit := CASE 
                        WHEN v_salutation = 'Mr.' THEN '1'
                        WHEN v_salutation = 'Mrs.' THEN '2'
                        WHEN v_salutation = 'Ms.' THEN '3'
                        WHEN v_salutation = 'Dr.' THEN '4'
                        ELSE '1'
                    END;
                    
                    -- Map marital status
                    v_dap_mst_cod := CASE 
                        WHEN v_maritalstatus = 'M' THEN '1'
                        WHEN v_maritalstatus = 'S' THEN '2'
                        WHEN v_maritalstatus = 'D' THEN '3'
                        WHEN v_maritalstatus = 'W' THEN '4'
                        ELSE '1'
                    END;
                    
                    -- Map country code
                    v_country_code := CASE 
                        WHEN v_nationality = 'Nepali' OR v_nationality ILIKE '%nepal%' THEN '524'
                        ELSE '524'
                    END;
                    
                    -- Calculate net income
                    v_net_income := COALESCE(v_annualincome, 0) * 0.8;
                    
                    -- Calculate age
                    IF v_dob IS NOT NULL THEN
                        v_customer_age := EXTRACT(YEAR FROM AGE(CURRENT_DATE, v_dob))::INTEGER;
                    ELSE
                        v_customer_age := 0;
                    END IF;
             --------------------------DEBUGING ST-----------------------------------
									 IF p_debug_level >= c_debug_verbose THEN
						    RAISE NOTICE 'Checking ALL VARCHAR(10) columns before INSERT:';
						    RAISE NOTICE '1. dap_bra_code: Value="%", Length=%', 
						        COALESCE(v_customer_branchcode, v_branchcode, '999'), 
						        length(COALESCE(v_customer_branchcode, v_branchcode, '999'));
						    
						    RAISE NOTICE '2. dap_firs_iden_typ1: Value="%", Length=%', 
						        v_documenttype, length(v_documenttype);
						    
						    RAISE NOTICE '3. dap_seco_iden_typ1: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '4. dap_mst_cod1: Value="%", Length=%', 
						        v_dap_mst_cod, length(v_dap_mst_cod);
						    
						    RAISE NOTICE '5. dap_cou_cod1: Value="%", Length=%', 
						        v_country_code, length(v_country_code);
						    
						    RAISE NOTICE '6. dap_firs_iden_typ2: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '7. dap_seco_iden_typ2: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '8. dap_mst_cod2: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '9. dap_cou_cod2: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '10. dap_requ_acc_curr_code: Value="%", Length=%', 
						        COALESCE(v_currency_type, '524'), length(COALESCE(v_currency_type, '524'));
						    
						    RAISE NOTICE '11. dap_requ_cpr_code: Value="%", Length=%', 
						        '731', length('731');
						    
						    RAISE NOTICE '12. dap_requ_dpr_code: Value="%", Length=%', 
						        '730', length('730');
						    
						    RAISE NOTICE '13. dap_chld_titl: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '14. dap_pers_fee_code: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '15. dap_memb_fee_code: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '16. dap_vca_code: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '17. dap_pro_code: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '18. dap_cust_pare: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '19. firstaddresstype: Value="%", Length=%', 
						        '08', length('08');
						END IF;

			 --------------------------DEBUGGING END ST----------------------------
                    -- Insert new record
                    INSERT INTO debit_card_application (
                        dap_iden, dap_ban_code, dap_bra_code, dap_user, dap_bat_code,
                        dap_cus_type, dap_cus_old_new, dap_cus_iden, dap_date, dap_ast_code,
                        dap_firs_nam1, dap_last_nam1, dap_midd_nam1, dap_tit1,
                        dap_birt_dat1, dap_birt_loc1, dap_firs_ide1, dap_firs_iden_typ1,
                        dap_seco_ide1, dap_seco_iden_typ1, dap_gend1, dap_mst_cod1, dap_cou_cod1,
                        dap_empl_cod1, dap_empl_nam1, dap_gros_sal1, dap_net_sal1, dap_empl_age1,
                        dap_requ_acc_numb, dap_requ_acc_curr_code, dap_requ_cpr_code,
                        dap_pan_gene_manu_auto, dap_requ_dpr_code,
                        dap_requ_effe_date, dap_requ_expi_date,
                        dap_phon_number, dap_email_adr, dap_gree_pin_flag,
                        firstaddresstype, firstaddressline1, firstaddressline2, 
                        firstaddressline3, firstaddresszipcode, firstadressphone1,
                        firstadressphone2, firstcity, emailaddress,
                        created_at, updated_at, batch_id
                    ) VALUES (
                        v_dap_iden, 
                        COALESCE(v_bankcode, '402122'),
                        COALESCE(v_customer_branchcode, v_branchcode, '999'),
                        'CCMSUSER',
                        '10',
                        'I',
                        'N',
                        v_customercode,
                        CURRENT_DATE,
                        '730',
                        v_fname,
                        v_lname,
                        v_middlename,
                        v_dap_tit,
                        v_dob,
                        v_address,
                        v_documentid,
                        v_documenttype,
                        '', '',
                        v_dap_gend,
                        v_dap_mst_cod,
                        v_country_code,
                        v_employment_type,
                        v_occupation,
                        v_annualincome,
                        v_net_income,
                        v_customer_age,
                        v_accountnumber,
                        COALESCE(v_currency_type, '524'),
                        '731',
                        'A',
                        '730',
                        CURRENT_DATE,
                        CURRENT_DATE + INTERVAL '5 years',
                        COALESCE(v_mobileno, v_mobile),
                        v_emailid,
                        'Y',
                        '08',
                        v_address,
                        '', '', '',
                        COALESCE(v_mobileno, v_mobile),
                        '',
                        COALESCE(v_customer_branchcode, '30608'),
                        v_emailid,
                        CURRENT_TIMESTAMP,
                        CURRENT_TIMESTAMP,
                        v_batch_id
                    );
                    
                    v_total_inserted := v_total_inserted + 1;
                    
                    IF p_debug_level >= c_debug_verbose THEN
                        RAISE NOTICE '  ✓ Inserted new application (DAP_IDEN: %)', v_dap_iden;
                    END IF;
                    
                    v_success_details := v_success_details || jsonb_build_object(
                        'dap_iden', v_dap_iden,
                        'request_id', v_request_id,
                        'customercode', v_customercode,
                        'account_number', v_accountnumber,
                        'customer_name', v_fname || ' ' || v_lname,
                        'card_type', v_card_type,
                        'card_scheme', v_card_scheme,
                        'action', 'INSERTED',
                        'request_index', v_request_index,
                        'timestamp', CURRENT_TIMESTAMP::TEXT
                    );
                    
                END;
            END IF;
            
            -- ========== STEP 7: Update Request Status ==========
            UPDATE card_request_cycle 
            SET status = 'PROCESSING', 
                updated_at = CURRENT_TIMESTAMP
            WHERE request_id = v_request_id;
            
            IF p_debug_level >= c_debug_verbose THEN
                RAISE NOTICE 'STEP 7: Updated card_request_cycle status to PROCESSING';
                RAISE NOTICE '✓ Successfully processed request %', v_request_id;
            ELSIF p_debug_level >= c_debug_basic THEN
                RAISE NOTICE '✓ Processed request %', v_request_id;
            END IF;
            
        EXCEPTION
            WHEN OTHERS THEN
                GET STACKED DIAGNOSTICS 
                    v_error_message = MESSAGE_TEXT,
                    v_sql_state = RETURNED_SQLSTATE;
                
                v_total_errors := v_total_errors + 1;
                v_error_types := array_append(v_error_types, split_part(v_sql_state, ':', 1));
                
                v_error_details := v_error_details || jsonb_build_object(
                    'request_id', v_request_id,
                    'request_index', v_request_index,
                    'error_type', 'PROCESSING_ERROR',
                    'error_message', v_error_message,
                    'sql_state', v_sql_state,
                    'timestamp', CURRENT_TIMESTAMP::TEXT,
                    'debug_level', p_debug_level
                );
                
                IF p_debug_level >= c_debug_basic THEN
                    RAISE NOTICE '✗ Error processing request %: %', v_request_id, v_error_message;
                END IF;
        END;
        
        -- Log progress
        IF p_debug_level >= c_debug_basic AND v_request_index % 5 = 0 THEN
            RAISE NOTICE 'Progress: %/% requests (%✓ %✗ %⚠ %↻)',
                v_request_index, v_total_requests, 
                v_total_inserted, v_total_errors, v_total_skipped, v_total_duplicates;
        END IF;
        
    END LOOP;
    
    -- ========== BUILD FINAL RESULT ==========
    v_end_time := CURRENT_TIMESTAMP;
    v_total_duration := EXTRACT(EPOCH FROM (v_end_time - v_start_time));
    
    -- Calculate success rate
    IF v_total_requests > 0 THEN
        v_success_rate := ((v_total_inserted + v_total_duplicates)::FLOAT / v_total_requests * 100)::NUMERIC(5,2);
    ELSE
        v_success_rate := 0;
    END IF;
    
    -- Build error summary
    IF array_length(v_error_types, 1) > 0 THEN
        DECLARE
            v_error_type TEXT;
            v_temp_errors TEXT[];
            v_error_count INTEGER;
        BEGIN
            FOR v_error_type IN 
                SELECT DISTINCT unnest(v_error_types)
            LOOP
                v_temp_errors := ARRAY[]::TEXT[];
                FOR i IN 1..array_length(v_error_types, 1) LOOP
                    IF v_error_types[i] = v_error_type THEN
                        v_temp_errors := array_append(v_temp_errors, v_error_types[i]);
                    END IF;
                END LOOP;
                
                v_error_count := array_length(v_temp_errors, 1);
                v_error_summary := v_error_summary || jsonb_build_object(
                    'error_type', v_error_type,
                    'count', v_error_count,
                    'percentage', ROUND((v_error_count::FLOAT / v_total_requests * 100)::NUMERIC, 2)
                );
            END LOOP;
        END;
    END IF;
    
    -- Build final result JSON
    v_result := jsonb_build_object(
        'success', v_total_inserted > 0 OR v_total_duplicates > 0,
        'message', CASE 
                    WHEN v_total_inserted > 0 OR v_total_duplicates > 0
                        THEN 'Processing completed successfully'
                    WHEN v_total_skipped > 0 
                        THEN 'Some requests were skipped (not in allowed statuses)'
                    WHEN v_total_errors = v_total_requests 
                        THEN 'All requests failed - check error details'
                    ELSE 'Processing completed with issues'
                   END,
        'batch_id', v_batch_id,
        'debug_level', p_debug_level,
        
        -- Statistics
        'statistics', jsonb_build_object(
            'total_requests', v_total_requests,
            'inserted', v_total_inserted,
            'duplicates', v_total_duplicates,
            'errors', v_total_errors,
            'skipped', v_total_skipped,
            'success_rate', v_success_rate
        ),
        
        -- Timing
        'timing', jsonb_build_object(
            'start_time', v_start_time::TEXT,
            'end_time', v_end_time::TEXT,
            'duration_seconds', ROUND(v_total_duration, 3)
        ),
        
        -- Configuration
        'config', jsonb_build_object(
            'allowed_request_statuses', c_allowed_request_statuses,
            'allowed_account_statuses', c_allowed_account_statuses
        ),
        
        -- Details
        'duplicate_customers', v_duplicate_ids,
        'error_summary', v_error_summary
    );
    
    -- Add detailed info based on debug level
    IF p_debug_level >= c_debug_detailed THEN
        v_result := v_result || jsonb_build_object(
            'success_details', v_success_details,
            'skipped_details', v_skipped_details
        );
    END IF;
    
    IF p_debug_level >= c_debug_verbose THEN
        v_result := v_result || jsonb_build_object(
            'error_details', v_error_details
        );
    END IF;
    
    -- ========== FINAL LOGGING ==========
    IF p_debug_level >= c_debug_basic THEN
        RAISE NOTICE '========================================================================';
        RAISE NOTICE 'Batch % completed in % seconds', v_batch_id, ROUND(v_total_duration, 2);
        RAISE NOTICE 'Summary: % inserted, % duplicates, % errors, % skipped', 
            v_total_inserted, v_total_duplicates, v_total_errors, v_total_skipped;
        
        IF v_total_requests > 0 THEN
            RAISE NOTICE 'Success rate: %%%', v_success_rate;
        END IF;
        
        RAISE NOTICE 'Config: Request statuses=%, Account statuses=%', 
            c_allowed_request_statuses, c_allowed_account_statuses;
        
        RAISE NOTICE '========================================================================';
    END IF;
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS 
            v_error_message = MESSAGE_TEXT,
            v_sql_state = RETURNED_SQLSTATE;
        
        v_end_time := CURRENT_TIMESTAMP;
        v_total_duration := EXTRACT(EPOCH FROM (v_end_time - v_start_time));
        
        IF p_debug_level >= c_debug_basic THEN
            RAISE NOTICE '========================================================================';
            RAISE NOTICE 'CRITICAL ERROR: %', v_error_message;
            RAISE NOTICE 'SQL State: %', v_sql_state;
            RAISE NOTICE '========================================================================';
        END IF;
        
        v_result := jsonb_build_object(
            'success', false,
            'message', 'Critical error: ' || v_error_message,
            'batch_id', v_batch_id,
            'debug_level', p_debug_level,
            'sql_state', v_sql_state,
            'config', jsonb_build_object(
                'allowed_request_statuses', c_allowed_request_statuses,
                'allowed_account_statuses', c_allowed_account_statuses
            ),
            'statistics', jsonb_build_object(
                'total_requests_attempted', v_total_requests,
                'total_inserted', v_total_inserted,
                'total_errors', v_total_errors,
                'total_duplicates', v_total_duplicates,
                'total_skipped', v_total_skipped
            ),
            'timing', jsonb_build_object(
                'start_time', v_start_time::TEXT,
                'end_time', v_end_time::TEXT,
                'duration_seconds', ROUND(v_total_duration, 3)
            ),
            'error_time', CURRENT_TIMESTAMP::TEXT
        );
        
        RETURN v_result;
END;
$$;


