CREATE FUNCTION public.finstant_getrequestdetailsbybatchidforswitch(p_action character varying, p_batch_ids character varying[], p_user character varying, p_new_status character varying DEFAULT NULL::character varying, p_search_criteria json DEFAULT NULL::json, p_debug_level integer DEFAULT 0, p_page_number integer DEFAULT 1, p_page_size integer DEFAULT 100, p_include_data boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_batch_id VARCHAR(20);
    v_timestamp VARCHAR(50);
    v_record RECORD;
    v_counter INTEGER;
    v_total_records INTEGER;
    v_query TEXT;
    v_count_query TEXT;
    v_where_conditions TEXT;
    v_criteria JSON;
    v_column_name VARCHAR(100);
    v_column_value TEXT;
    v_audit_data JSONB;
    v_start_time TIMESTAMP;
    v_end_time TIMESTAMP;
    v_result JSONB;
    v_batch_results JSONB[];
    v_batch_result JSONB;
    v_offset INTEGER;
    v_data JSONB[];
    v_row JSONB;
    v_error_context TEXT;
    v_error_message TEXT;
    v_error_detail TEXT;
    v_error_hint TEXT;
    v_execution_time_ms NUMERIC;
    v_function_name TEXT := 'finstant_getRequestDetailsByBatchidforSwitch';
    v_json_record JSONB;
    v_row_json TEXT;
BEGIN
    -- Initialize result
    v_result := jsonb_build_object(
        'success', false,
        'timestamp', CURRENT_TIMESTAMP,
        'function_name', v_function_name,
        'action', p_action,
        'user', p_user,
        'debug_level', p_debug_level,
        'total_batches_processed', 0,
        'total_records_affected', 0,
        'execution_time_ms', 0,
        'error', NULL,
        'batches', '[]'::jsonb
    );
    
    -- Start timing
    v_start_time := clock_timestamp();
    
    -- Create timestamp for audit
    v_timestamp := TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDD_HH24MISS');
    
    -- Log function start at debug level 1
    IF p_debug_level >= 1 THEN
        BEGIN
            INSERT INTO public.audit_trail (
                entity_type, 
                action_type, 
                description, 
                data, 
                user_id, 
                created_at
            ) VALUES (
                'INSTANT_CARD_APPLICATIONS',
                'FUNCTION_START',
                v_function_name || ' started',
                jsonb_build_object(
                    'action', p_action,
                    'batch_ids', p_batch_ids,
                    'user', p_user,
                    'debug_level', p_debug_level,
                    'search_criteria', p_search_criteria,
                    'new_status', p_new_status,
                    'page_number', p_page_number,
                    'page_size', p_page_size,
                    'include_data', p_include_data
                ),
                p_user,
                CURRENT_TIMESTAMP
            );
        EXCEPTION WHEN OTHERS THEN
            -- Continue execution even if audit fails
            NULL;
        END;
    END IF;
    
    -- Calculate offset for pagination
    v_offset := (p_page_number - 1) * p_page_size;
    
    -- Initialize batch results array
    v_batch_results := ARRAY[]::JSONB[];
    
    -- Validate input parameters with error handling
    BEGIN
        IF p_action NOT IN ('SEARCH', 'UPDATE', 'DELETE') THEN
            RAISE EXCEPTION 'Invalid action: %. Use SEARCH, UPDATE, or DELETE', p_action
            USING ERRCODE = '22000';
        END IF;
        
        IF p_batch_ids IS NULL OR array_length(p_batch_ids, 1) = 0 THEN
            RAISE EXCEPTION 'No batch IDs provided'
            USING ERRCODE = '22001';
        END IF;
        
        IF p_action = 'UPDATE' AND (p_new_status IS NULL OR p_new_status = '') THEN
            RAISE EXCEPTION 'New status is required for UPDATE action'
            USING ERRCODE = '22002';
        END IF;
        
    EXCEPTION WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS 
            v_error_message = MESSAGE_TEXT,
            v_error_detail = PG_EXCEPTION_DETAIL,
            v_error_hint = PG_EXCEPTION_HINT;
        
        -- Log error at debug level 0 (always log errors)
        BEGIN
            INSERT INTO public.audit_trail (
                entity_type, 
                action_type, 
                description, 
                data, 
                user_id, 
                created_at
            ) VALUES (
                'INSTANT_CARD_APPLICATIONS',
                'VALIDATION_ERROR',
                'Input validation failed',
                jsonb_build_object(
                    'function', v_function_name,
                    'error_message', v_error_message,
                    'error_detail', v_error_detail,
                    'error_hint', v_error_hint,
                    'sql_state', SQLSTATE
                ),
                p_user,
                CURRENT_TIMESTAMP
            );
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
        
        -- Calculate execution time
        v_end_time := clock_timestamp();
        v_execution_time_ms := EXTRACT(EPOCH FROM (v_end_time - v_start_time)) * 1000;
        
        -- Return error result
        v_result := v_result || jsonb_build_object(
            'success', false,
            'execution_time_ms', v_execution_time_ms,
            'error', jsonb_build_object(
                'message', v_error_message,
                'detail', v_error_detail,
                'hint', v_error_hint,
                'sql_state', SQLSTATE
            )
        );
        
        RETURN v_result;
    END;
    
    -- Process each batch ID
    FOR i IN 1..array_length(p_batch_ids, 1)
    LOOP
        v_batch_id := p_batch_ids[i];
        v_counter := 0;
        v_total_records := 0;
        v_data := ARRAY[]::JSONB[];
        v_where_conditions := 'WHERE batchid = ' || quote_literal(v_batch_id);
        
        -- Initialize batch result
        v_batch_result := jsonb_build_object(
            'batch_id', v_batch_id,
            'success', false,
            'records_affected', 0,
            'error', NULL
        );
        
        -- Log batch processing start
        IF p_debug_level >= 2 THEN
            BEGIN
                INSERT INTO public.audit_trail (
                    entity_type, 
                    action_type, 
                    description, 
                    data, 
                    user_id, 
                    created_at
                ) VALUES (
                    'INSTANT_CARD_APPLICATIONS',
                    'BATCH_START',
                    'Processing batch: ' || v_batch_id,
                    jsonb_build_object(
                        'batch_id', v_batch_id,
                        'action', p_action,
                        'sequence', i
                    ),
                    p_user,
                    CURRENT_TIMESTAMP
                );
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
        END IF;
        
        -- Process based on action
        BEGIN
            IF p_action = 'SEARCH' THEN
                -- Build WHERE conditions for search
                IF p_search_criteria IS NOT NULL THEN
                    v_criteria := p_search_criteria;
                    
                    FOR v_column_name, v_column_value IN 
                        SELECT * FROM json_each_text(v_criteria)
                    LOOP
                        IF v_column_name IN ('dap_gros_sal1', 'dap_net_sal1', 'dap_gros_sal2', 'dap_net_sal2') THEN
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' = ' || v_column_value;
                        ELSIF v_column_name IN ('dap_date', 'dap_birt_dat1', 'dap_birt_dat2', 'dap_deci_date', 'dap_requ_effe_date', 'dap_requ_expi_date') THEN
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' = ' || quote_literal(v_column_value);
                        ELSIF v_column_name IN ('statusflag', 'dap_cus_type', 'dap_cus_old_new', 'dap_gend1', 'dap_gend2') THEN
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' = ' || quote_literal(v_column_value);
                        ELSIF v_column_name IN ('dap_cus_iden', 'dap_iden', 'dap_requ_acc_numb', 'dap_requ_card_numb') THEN
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' = ' || quote_literal(v_column_value);
                        ELSE
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' ILIKE ' || quote_literal('%' || v_column_value || '%');
                        END IF;
                    END LOOP;
                END IF;
                
                -- Get total count for pagination
                v_count_query := 'SELECT COUNT(*) FROM public.instant_card_applications ' || v_where_conditions;
                EXECUTE v_count_query INTO v_total_records;
                
                -- Build search query with pagination - using row_to_json to avoid parameter limit
                v_query := 'SELECT row_to_json(t) as row_data 
                            FROM (
                                SELECT * FROM public.instant_card_applications ' || 
                                v_where_conditions || 
                                ' ORDER BY created_at DESC ' ||
                                ' LIMIT ' || p_page_size || 
                                ' OFFSET ' || v_offset || 
                            ') t';
                
                -- Execute query and collect data
                FOR v_record IN EXECUTE v_query
                LOOP
                    v_counter := v_counter + 1;
                    
                    -- Extract the JSON from row_data column
                    v_json_record := v_record.row_data::jsonb;
                    
                    -- Add to data array
                    v_data := array_append(v_data, v_json_record);
                END LOOP;
                
                -- Update batch result for SEARCH
                v_batch_result := v_batch_result || jsonb_build_object(
                    'success', true,
                    'action', 'SEARCH',
                    'records_found', v_counter,
                    'total_records', v_total_records,
                    'pagination', jsonb_build_object(
                        'page_number', p_page_number,
                        'page_size', p_page_size,
                        'total_pages', CASE WHEN p_page_size > 0 THEN CEIL(v_total_records::NUMERIC / p_page_size) ELSE 1 END
                    )
                );
                
                IF p_include_data AND v_counter > 0 THEN
                    v_batch_result := v_batch_result || jsonb_build_object(
                        'data', v_data
                    );
                END IF;
                
                -- Log successful search
                IF p_debug_level >= 1 AND v_counter > 0 THEN
                    BEGIN
                        INSERT INTO public.audit_trail (
                            entity_type, 
                            action_type, 
                            description, 
                            data, 
                            user_id, 
                            created_at
                        ) VALUES (
                            'INSTANT_CARD_APPLICATIONS',
                            'SEARCH_COMPLETED',
                            'Search completed for batch: ' || v_batch_id,
                            jsonb_build_object(
                                'batch_id', v_batch_id,
                                'records_found', v_counter,
                                'total_records', v_total_records
                            ),
                            p_user,
                            CURRENT_TIMESTAMP
                        );
                    EXCEPTION WHEN OTHERS THEN
                        NULL;
                    END;
                END IF;
                
            ELSIF p_action = 'UPDATE' THEN
                -- Build WHERE conditions for update
                IF p_search_criteria IS NOT NULL THEN
                    v_criteria := p_search_criteria;
                    
                    FOR v_column_name, v_column_value IN 
                        SELECT * FROM json_each_text(v_criteria)
                    LOOP
                        IF v_column_name = 'statusflag' THEN
                            v_where_conditions := v_where_conditions || ' AND statusflag = ' || quote_literal(v_column_value);
                        ELSIF v_column_name = 'dap_cus_iden' THEN
                            v_where_conditions := v_where_conditions || ' AND dap_cus_iden = ' || quote_literal(v_column_value);
                        ELSIF v_column_name = 'dap_iden' THEN
                            v_where_conditions := v_where_conditions || ' AND dap_iden = ' || quote_literal(v_column_value);
                        END IF;
                    END LOOP;
                END IF;
                
                -- Execute update with RETURNING clause - using row_to_json
                v_query := 'UPDATE public.instant_card_applications 
                            SET statusflag = ' || quote_literal(p_new_status) || 
                           ', updated_at = CURRENT_TIMESTAMP' ||
                           ', dap_deci_auth = ' || quote_literal(p_user) ||
                           ', dap_deci_date = CURRENT_DATE ' ||
                           v_where_conditions || 
                           ' RETURNING row_to_json(instant_card_applications.*) as row_data';
                
                -- Execute update and count affected rows
                FOR v_record IN EXECUTE v_query
                LOOP
                    v_counter := v_counter + 1;
                    
                    -- Extract the JSON from row_data column
                    v_json_record := v_record.row_data::jsonb;
                    
                    -- Add minimal info to data array
                    v_row := jsonb_build_object(
                        'dap_iden', v_json_record->>'dap_iden',
                        'dap_cus_iden', v_json_record->>'dap_cus_iden',
                        'old_status', v_json_record->>'statusflag',
                        'new_status', p_new_status
                    );
                    
                    v_data := array_append(v_data, v_row);
                END LOOP;
                
                -- Update batch result for UPDATE
                v_batch_result := v_batch_result || jsonb_build_object(
                    'success', true,
                    'action', 'UPDATE',
                    'records_affected', v_counter,
                    'new_status', p_new_status,
                    'updated_by', p_user
                );
                
                IF p_include_data AND v_counter > 0 THEN
                    v_batch_result := v_batch_result || jsonb_build_object(
                        'updated_records', v_data
                    );
                END IF;
                
                -- Log successful update
                IF p_debug_level >= 1 THEN
                    BEGIN
                        INSERT INTO public.audit_trail (
                            entity_type, 
                            action_type, 
                            description, 
                            data, 
                            user_id, 
                            created_at
                        ) VALUES (
                            'INSTANT_CARD_APPLICATIONS',
                            'UPDATE_COMPLETED',
                            'Status update completed for batch: ' || v_batch_id,
                            jsonb_build_object(
                                'batch_id', v_batch_id,
                                'records_updated', v_counter,
                                'new_status', p_new_status
                            ),
                            p_user,
                            CURRENT_TIMESTAMP
                        );
                    EXCEPTION WHEN OTHERS THEN
                        NULL;
                    END;
                END IF;
                
            ELSIF p_action = 'DELETE' THEN
                -- Additional conditions for deletion
                IF p_search_criteria IS NOT NULL THEN
                    v_criteria := p_search_criteria;
                    
                    FOR v_column_name, v_column_value IN 
                        SELECT * FROM json_each_text(v_criteria)
                    LOOP
                        IF v_column_name = 'statusflag' THEN
                            v_where_conditions := v_where_conditions || ' AND statusflag = ' || quote_literal(v_column_value);
                        END IF;
                    END LOOP;
                END IF;
                
                -- First, select records to be deleted using row_to_json
                v_query := 'SELECT row_to_json(t) as row_data 
                            FROM (
                                SELECT dap_iden, dap_cus_iden, statusflag 
                                FROM public.instant_card_applications ' || 
                                v_where_conditions || 
                            ') t';
                
                FOR v_record IN EXECUTE v_query
                LOOP
                    -- Extract the JSON from row_data column
                    v_json_record := v_record.row_data::jsonb;
                    
                    -- Store record info before deletion
                    v_row := jsonb_build_object(
                        'dap_iden', v_json_record->>'dap_iden',
                        'dap_cus_iden', v_json_record->>'dap_cus_iden',
                        'status', v_json_record->>'statusflag'
                    );
                    
                    v_data := array_append(v_data, v_row);
                END LOOP;
                
                -- Execute deletion
                v_query := 'DELETE FROM public.instant_card_applications ' || v_where_conditions;
                EXECUTE v_query;
                GET DIAGNOSTICS v_counter = ROW_COUNT;
                
                -- Update batch result for DELETE
                v_batch_result := v_batch_result || jsonb_build_object(
                    'success', true,
                    'action', 'DELETE',
                    'records_deleted', v_counter
                );
                
                IF p_include_data AND v_counter > 0 THEN
                    v_batch_result := v_batch_result || jsonb_build_object(
                        'deleted_records', v_data
                    );
                END IF;
                
                -- Log successful deletion
                IF p_debug_level >= 1 THEN
                    BEGIN
                        INSERT INTO public.audit_trail (
                            entity_type, 
                            action_type, 
                            description, 
                            data, 
                            user_id, 
                            created_at
                        ) VALUES (
                            'INSTANT_CARD_APPLICATIONS',
                            'DELETE_COMPLETED',
                            'Deletion completed for batch: ' || v_batch_id,
                            jsonb_build_object(
                                'batch_id', v_batch_id,
                                'records_deleted', v_counter
                            ),
                            p_user,
                            CURRENT_TIMESTAMP
                        );
                    EXCEPTION WHEN OTHERS THEN
                        NULL;
                    END;
                END IF;
            END IF;
            
            -- Update batch result with success
            v_batch_result := v_batch_result || jsonb_build_object(
                'records_affected', v_counter,
                'processed_at', CURRENT_TIMESTAMP
            );
            
            -- Add to batch results array
            v_batch_results := array_append(v_batch_results, v_batch_result);
            
            -- Update total records
            v_result := v_result || jsonb_build_object(
                'total_records_affected', (v_result->>'total_records_affected')::INTEGER + v_counter
            );
            
        EXCEPTION WHEN OTHERS THEN
            GET STACKED DIAGNOSTICS 
                v_error_message = MESSAGE_TEXT,
                v_error_detail = PG_EXCEPTION_DETAIL,
                v_error_hint = PG_EXCEPTION_HINT,
                v_error_context = PG_EXCEPTION_CONTEXT;
            
            -- Log batch error
            BEGIN
                INSERT INTO public.audit_trail (
                    entity_type, 
                    action_type, 
                    description, 
                    data, 
                    user_id, 
                    created_at
                ) VALUES (
                    'INSTANT_CARD_APPLICATIONS',
                    'BATCH_ERROR',
                    'Error processing batch: ' || v_batch_id,
                    jsonb_build_object(
                        'batch_id', v_batch_id,
                        'action', p_action,
                        'error_message', v_error_message,
                        'error_detail', v_error_detail,
                        'error_hint', v_error_hint,
                        'error_context', v_error_context,
                        'sql_state', SQLSTATE
                    ),
                    p_user,
                    CURRENT_TIMESTAMP
                );
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
            
            -- Update batch result with error
            v_batch_result := v_batch_result || jsonb_build_object(
                'success', false,
                'error', jsonb_build_object(
                    'message', v_error_message,
                    'detail', v_error_detail,
                    'hint', v_error_hint,
                    'sql_state', SQLSTATE
                )
            );
            
            v_batch_results := array_append(v_batch_results, v_batch_result);
        END;
        
        -- Log batch completion
        IF p_debug_level >= 2 THEN
            BEGIN
                INSERT INTO public.audit_trail (
                    entity_type, 
                    action_type, 
                    description, 
                    data, 
                    user_id, 
                    created_at
                ) VALUES (
                    'INSTANT_CARD_APPLICATIONS',
                    'BATCH_COMPLETE',
                    'Completed processing batch: ' || v_batch_id,
                    jsonb_build_object(
                        'batch_id', v_batch_id,
                        'records_affected', v_counter,
                        'success', v_batch_result->>'success'
                    ),
                    p_user,
                    CURRENT_TIMESTAMP
                );
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
        END IF;
    END LOOP;
    
    -- Calculate execution time
    v_end_time := clock_timestamp();
    v_execution_time_ms := EXTRACT(EPOCH FROM (v_end_time - v_start_time)) * 1000;
    
    -- Prepare final result
    v_result := v_result || jsonb_build_object(
        'success', true,
        'execution_time_ms', v_execution_time_ms,
        'total_batches_processed', array_length(p_batch_ids, 1),
        'batches', to_jsonb(v_batch_results)
    );
    
    -- Log function completion
    IF p_debug_level >= 1 THEN
        BEGIN
            INSERT INTO public.audit_trail (
                entity_type, 
                action_type, 
                description, 
                data, 
                user_id, 
                created_at
            ) VALUES (
                'INSTANT_CARD_APPLICATIONS',
                'FUNCTION_COMPLETE',
                v_function_name || ' completed successfully',
                jsonb_build_object(
                    'execution_time_ms', v_execution_time_ms,
                    'total_batches', array_length(p_batch_ids, 1),
                    'total_records', v_result->>'total_records_affected'
                ),
                p_user,
                CURRENT_TIMESTAMP
            );
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
    END IF;
    
    RETURN v_result;
    
EXCEPTION WHEN OTHERS THEN
    -- Global exception handler
    GET STACKED DIAGNOSTICS 
        v_error_message = MESSAGE_TEXT,
        v_error_detail = PG_EXCEPTION_DETAIL,
        v_error_hint = PG_EXCEPTION_HINT,
        v_error_context = PG_EXCEPTION_CONTEXT;
    
    -- Calculate execution time
    v_end_time := clock_timestamp();
    v_execution_time_ms := EXTRACT(EPOCH FROM (v_end_time - v_start_time)) * 1000;
    
    -- Log global error
    BEGIN
        INSERT INTO public.audit_trail (
            entity_type, 
            action_type, 
            description, 
            data, 
            user_id, 
            created_at
        ) VALUES (
            'INSTANT_CARD_APPLICATIONS',
            'FUNCTION_ERROR',
            v_function_name || ' failed',
            jsonb_build_object(
                'error_message', v_error_message,
                'error_detail', v_error_detail,
                'error_hint', v_error_hint,
                'error_context', v_error_context,
                'sql_state', SQLSTATE,
                'execution_time_ms', v_execution_time_ms
            ),
            p_user,
            CURRENT_TIMESTAMP
        );
    EXCEPTION WHEN OTHERS THEN
        NULL;
    END;
    
    -- Return error result
    v_result := v_result || jsonb_build_object(
        'success', false,
        'execution_time_ms', v_execution_time_ms,
        'error', jsonb_build_object(
            'message', v_error_message,
            'detail', v_error_detail,
            'hint', v_error_hint,
            'context', v_error_context,
            'sql_state', SQLSTATE
        )
    );
    
    RETURN v_result;
END;
$$;


