--
-- TOC entry 434 (class 1255 OID 32004)
-- Name: finstant_statusupdatebothflagtrue(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstant_statusupdatebothflagtrue() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Case 1: Both booked_cards and approved_cards have records (> 0)
    -- Then we need both flags to be true
    IF NEW.booked_cards > 0 AND NEW.approved_cards > 0 THEN
        -- Check if both allocation flags are true
        IF NEW.bookedcardallocated = true AND NEW.approvedcardsallocated = true THEN
            -- Both flags are true, update status if it's 'VERIFIED' or 'PROCESSING'
            IF NEW.status IN ('VERIFIED', 'PROCESSING') THEN
                NEW.status := 'ALLOCATED';
                
                -- Log this change
                RAISE NOTICE 'Request %: Both cards present (booked: %, approved: %) - status updated to ALLOCATED', 
                    NEW.requestid, NEW.booked_cards, NEW.approved_cards;
            END IF;
        END IF;
    
    -- Case 2: Only booked_cards have records (> 0) and approved_cards are zero
    ELSIF NEW.booked_cards > 0 AND (NEW.approved_cards = 0 OR NEW.approved_cards IS NULL) THEN
        -- Check only bookedcardallocated flag
        IF NEW.bookedcardallocated = true THEN
            IF NEW.status IN ('VERIFIED', 'PROCESSING') THEN
                NEW.status := 'ALLOCATED';
                
                RAISE NOTICE 'Request %: Only booked cards present (count: %) - status updated to ALLOCATED', 
                    NEW.requestid, NEW.booked_cards;
            END IF;
        END IF;
    
    -- Case 3: Only approved_cards have records (> 0) and booked_cards are zero
    ELSIF NEW.approved_cards > 0 AND (NEW.booked_cards = 0 OR NEW.booked_cards IS NULL) THEN
        -- Check only approvedcardsallocated flag
        IF NEW.approvedcardsallocated = true THEN
            IF NEW.status IN ('VERIFIED', 'PROCESSING') THEN
                NEW.status := 'ALLOCATED';
                
                RAISE NOTICE 'Request %: Only approved cards present (count: %) - status updated to ALLOCATED', 
                    NEW.requestid, NEW.approved_cards;
            END IF;
        END IF;
    
    -- Case 4: Both are zero or NULL - no allocation needed
    ELSE
        RAISE NOTICE 'Request %: No cards to allocate (booked: %, approved: %)', 
            NEW.requestid, NEW.booked_cards, NEW.approved_cards;
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.finstant_statusupdatebothflagtrue() OWNER TO postgres;

--
-- TOC entry 482 (class 1255 OID 31902)
-- Name: finstant_update_card_flags(character varying, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstant_update_card_flags(p_requestid character varying, p_booked_flag boolean, p_approved_flag boolean) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_booked_updated boolean := false;
    v_approved_updated boolean := false;
BEGIN
    -- Check if request exists
    IF NOT EXISTS (SELECT 1 FROM instantcardcycle WHERE requestid = p_requestid) THEN
        RETURN 'Error: Request ID not found';
    END IF;

    -- Update booked flag ONLY if parameter is TRUE
    IF p_booked_flag = true THEN
        UPDATE instantcardcycle 
        SET bookedcardallocated = true
        WHERE requestid = p_requestid;
        v_booked_updated := true;
    END IF;
    
    -- Update approved flag ONLY if parameter is TRUE
    IF p_approved_flag = true THEN
        UPDATE instantcardcycle 
        SET approvedcardsallocated = true
        WHERE requestid = p_requestid;
        v_approved_updated := true;
    END IF;
    
    -- Return appropriate message
    IF v_booked_updated AND v_approved_updated THEN
        RETURN 'Both flags updated to TRUE for request: ' || p_requestid;
    ELSIF v_booked_updated THEN
        RETURN 'Booked flag updated to TRUE for request: ' || p_requestid;
    ELSIF v_approved_updated THEN
        RETURN 'Approved flag updated to TRUE for request: ' || p_requestid;
    ELSE
        RETURN 'No flags were updated (parameters were not TRUE) for request: ' || p_requestid;
    END IF;
END;
$$;


ALTER FUNCTION public.finstant_update_card_flags(p_requestid character varying, p_booked_flag boolean, p_approved_flag boolean) OWNER TO postgres;

--
-- TOC entry 363 (class 1255 OID 27990)
-- Name: finstantbatchidmanagement(text, text, timestamp without time zone, timestamp without time zone, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstantbatchidmanagement(p_action text DEFAULT 'LOADING ALL'::text, p_batch_id text DEFAULT NULL::text, p_from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, p_to_date timestamp without time zone DEFAULT NULL::timestamp without time zone, p_status text DEFAULT NULL::text, p_debug_level integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
    -- Debug level definitions (INTERNAL - no external parameters needed)
    DEBUG_ERROR_ONLY CONSTANT integer := 0;  -- Log only errors
    DEBUG_INFO CONSTANT integer := 1;       -- Log info + errors
    DEBUG_VERBOSE CONSTANT integer := 2;    -- Log everything
    
    v_result JSONB;
    v_start_time TIMESTAMP := CURRENT_TIMESTAMP;
    v_end_time TIMESTAMP;
    v_affected_rows INTEGER := 0;
    v_error_message TEXT;
    v_sql_state TEXT;
    v_count_total INTEGER := 0;
    v_log_category TEXT := 'BATCH_MGMT';
    v_current_debug_level integer;
    
    -- Dynamic SQL variables
    v_where_clause TEXT := '';
    v_sql TEXT;
    
    -- Results
    v_batch_data JSONB;
    
BEGIN
    -- Set current debug level
    v_current_debug_level := COALESCE(p_debug_level, DEBUG_ERROR_ONLY);
    
    -- Debug log: Function start
    IF v_current_debug_level >= DEBUG_INFO THEN
        PERFORM public.flog_audit_trail(
            v_log_category,
            'FUNCTION_START',
            'Starting batch management function',
            jsonb_build_object(
                'action', p_action,
                'batch_id', p_batch_id,
                'from_date', p_from_date::TEXT,
                'to_date', p_to_date::TEXT,
                'status', p_status,
                'debug_level', v_current_debug_level,
                'start_time', v_start_time::TEXT
            )
        );
    END IF;
    
    -- ========== VALIDATE INPUTS ==========
    BEGIN
        -- Validate action parameter
        IF p_action NOT IN ('LOADING ALL', 'SEARCH', 'UPDATE') THEN
            RAISE EXCEPTION 'Invalid action: %. Must be LOADING ALL, SEARCH, or UPDATE', p_action;
        END IF;
        
        -- Validate required parameters for UPDATE
        IF p_action = 'UPDATE' THEN
            IF p_batch_id IS NULL THEN
                RAISE EXCEPTION 'batch_id is required for UPDATE action';
            END IF;
            IF p_status IS NULL THEN
                RAISE EXCEPTION 'status is required for UPDATE action';
            END IF;
            -- Validate status value
            IF p_status NOT IN ('PROCESSING', 'COMPLETED', 'FAILED', 'ARCHIVED', 'CANCELLED') THEN
                RAISE EXCEPTION 'Invalid status: %. Must be PROCESSING, COMPLETED, FAILED, ARCHIVED, or CANCELLED', p_status;
            END IF;
        END IF;
        
        -- Validate date range
        IF p_from_date IS NOT NULL AND p_to_date IS NOT NULL AND p_from_date > p_to_date THEN
            RAISE EXCEPTION 'from_date cannot be after to_date';
        END IF;
        
    EXCEPTION WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;
        
        IF v_current_debug_level >= DEBUG_ERROR_ONLY THEN
            PERFORM public.flog_audit_trail(
                v_log_category,
                'VALIDATION_ERROR',
                v_error_message,
                jsonb_build_object(
                    'action', p_action,
                    'batch_id', p_batch_id,
                    'error', SQLERRM
                )
            );
        END IF;
        
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', 'Validation error: ' || v_error_message,
            'action', p_action,
            'error_time', CURRENT_TIMESTAMP::TEXT
        );
    END;
    
    -- ========== ACTION: LOADING ALL ==========
    IF p_action = 'LOADING ALL' THEN
        BEGIN
            IF v_current_debug_level >= DEBUG_VERBOSE THEN
                RAISE NOTICE 'Executing LOADING ALL action';
            END IF;
            
            -- Build WHERE clause with available filters
            IF p_from_date IS NOT NULL THEN
                v_where_clause := v_where_clause || 
                    CASE WHEN v_where_clause = '' THEN ' WHERE ' ELSE ' AND ' END ||
                    '"timestamp" >= $1';
            END IF;
            
            IF p_to_date IS NOT NULL THEN
                v_where_clause := v_where_clause || 
                    CASE WHEN v_where_clause = '' THEN ' WHERE ' ELSE ' AND ' END ||
                    '"timestamp" <= $2';
            END IF;
            
            IF p_status IS NOT NULL THEN
                v_where_clause := v_where_clause || 
                    CASE WHEN v_where_clause = '' THEN ' WHERE ' ELSE ' AND ' END ||
                    'status = $3';
            END IF;
            
            -- Build SQL query
            v_sql := 'SELECT jsonb_agg(row_to_json(t)) FROM (' ||
                    'SELECT batch_id, request_ids, status,pintype, cards_generated, cards_failed, ' ||
                    'schemes, card_types, duration, timestamp, flags, total_cards, ' ||
                    'success_rate, request_count, report_id ' ||
                    'FROM instant_card_generation_batches' ||
                    v_where_clause || ' ORDER BY "timestamp" DESC' ||
                    ') t';
            
            -- Execute query with parameters
            IF p_from_date IS NOT NULL AND p_to_date IS NOT NULL AND p_status IS NOT NULL THEN
                EXECUTE v_sql INTO v_batch_data 
                USING p_from_date, p_to_date, p_status;
            ELSIF p_from_date IS NOT NULL AND p_to_date IS NOT NULL THEN
                EXECUTE v_sql INTO v_batch_data 
                USING p_from_date, p_to_date;
            ELSIF p_from_date IS NOT NULL AND p_status IS NOT NULL THEN
                EXECUTE v_sql INTO v_batch_data 
                USING p_from_date, p_status;
            ELSIF p_to_date IS NOT NULL AND p_status IS NOT NULL THEN
                EXECUTE v_sql INTO v_batch_data 
                USING p_to_date, p_status;
            ELSIF p_from_date IS NOT NULL THEN
                EXECUTE v_sql INTO v_batch_data 
                USING p_from_date;
            ELSIF p_to_date IS NOT NULL THEN
                EXECUTE v_sql INTO v_batch_data 
                USING p_to_date;
            ELSIF p_status IS NOT NULL THEN
                EXECUTE v_sql INTO v_batch_data 
                USING p_status;
            ELSE
                EXECUTE v_sql INTO v_batch_data;
            END IF;
            
            -- Get total count
            v_sql := 'SELECT COUNT(*) FROM instant_card_generation_batches' || v_where_clause;
            
            IF p_from_date IS NOT NULL AND p_to_date IS NOT NULL AND p_status IS NOT NULL THEN
                EXECUTE v_sql INTO v_count_total 
                USING p_from_date, p_to_date, p_status;
            ELSIF p_from_date IS NOT NULL AND p_to_date IS NOT NULL THEN
                EXECUTE v_sql INTO v_count_total 
                USING p_from_date, p_to_date;
            ELSIF p_from_date IS NOT NULL AND p_status IS NOT NULL THEN
                EXECUTE v_sql INTO v_count_total 
                USING p_from_date, p_status;
            ELSIF p_to_date IS NOT NULL AND p_status IS NOT NULL THEN
                EXECUTE v_sql INTO v_count_total 
                USING p_to_date, p_status;
            ELSIF p_from_date IS NOT NULL THEN
                EXECUTE v_sql INTO v_count_total 
                USING p_from_date;
            ELSIF p_to_date IS NOT NULL THEN
                EXECUTE v_sql INTO v_count_total 
                USING p_to_date;
            ELSIF p_status IS NOT NULL THEN
                EXECUTE v_sql INTO v_count_total 
                USING p_status;
            ELSE
                EXECUTE v_sql INTO v_count_total;
            END IF;
            
            -- Build result
            v_result := jsonb_build_object(
                'success', TRUE,
                'action', p_action,
                'data', COALESCE(v_batch_data, '[]'::JSONB),
                'metadata', jsonb_build_object(
                    'total_records', v_count_total,
                    'filters_applied', jsonb_build_object(
                        'from_date', p_from_date::TEXT,
                        'to_date', p_to_date::TEXT,
                        'status', p_status
                    ),
                    'query_time', v_start_time::TEXT
                )
            );
            
            -- Debug log
            IF v_current_debug_level >= DEBUG_INFO THEN
                PERFORM public.flog_audit_trail(
                    v_log_category,
                    'LOAD_SUCCESS',
                    'Successfully loaded batch data',
                    jsonb_build_object(
                        'action', p_action,
                        'records_returned', v_count_total,
                        'debug_level', v_current_debug_level
                    )
                );
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;
            
            IF v_current_debug_level >= DEBUG_ERROR_ONLY THEN
                PERFORM public.flog_audit_trail(
                    v_log_category,
                    'LOAD_ERROR',
                    'Error loading batch data',
                    jsonb_build_object(
                        'action', p_action,
                        'error', v_error_message,
                        'sql_state', SQLSTATE
                    )
                );
            END IF;
            
            v_result := jsonb_build_object(
                'success', FALSE,
                'message', 'Error loading data: ' || v_error_message,
                'action', p_action,
                'error_time', CURRENT_TIMESTAMP::TEXT
            );
        END;
    
    -- ========== ACTION: SEARCH ==========
    ELSIF p_action = 'SEARCH' THEN
        BEGIN
            IF v_current_debug_level >= DEBUG_VERBOSE THEN
                RAISE NOTICE 'Executing SEARCH action for batch_id: %', p_batch_id;
            END IF;
            
            IF p_batch_id IS NULL THEN
                v_result := jsonb_build_object(
                    'success', FALSE,
                    'message', 'batch_id is required for SEARCH action',
                    'action', p_action
                );
                RETURN v_result;
            END IF;
            
            -- Search for specific batch
            SELECT jsonb_build_object(
                'batch_id', batch_id,
                'request_ids', request_ids,
                'status', status,
                'cards_generated', cards_generated,
                'cards_failed', cards_failed,
                'schemes', schemes,
                'card_types', card_types,
                'duration', duration,
                'timestamp', "timestamp",
                'flags', flags,
                'total_cards', total_cards,
                'success_rate', success_rate,
                'request_count', request_count,
                'report_id', report_id
            ) INTO v_batch_data
            FROM instant_card_generation_batches
            WHERE batch_id = p_batch_id;
            
            IF v_batch_data IS NULL THEN
                v_result := jsonb_build_object(
                    'success', FALSE,
                    'message', 'Batch not found: ' || p_batch_id,
                    'action', p_action
                );
                
                IF v_current_debug_level >= DEBUG_INFO THEN
                    PERFORM public.flog_audit_trail(
                        v_log_category,
                        'SEARCH_NOT_FOUND',
                        'Batch not found',
                        jsonb_build_object(
                            'batch_id', p_batch_id,
                            'action', p_action
                        )
                    );
                END IF;
            ELSE
                v_result := jsonb_build_object(
                    'success', TRUE,
                    'action', p_action,
                    'data', v_batch_data,
                    'message', 'Batch found successfully'
                );
                
                IF v_current_debug_level >= DEBUG_INFO THEN
                    PERFORM public.flog_audit_trail(
                        v_log_category,
                        'SEARCH_SUCCESS',
                        'Batch found successfully',
                        jsonb_build_object(
                            'batch_id', p_batch_id,
                            'action', p_action
                        )
                    );
                END IF;
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;
            
            IF v_current_debug_level >= DEBUG_ERROR_ONLY THEN
                PERFORM public.flog_audit_trail(
                    v_log_category,
                    'SEARCH_ERROR',
                    'Error searching for batch',
                    jsonb_build_object(
                        'batch_id', p_batch_id,
                        'error', v_error_message,
                        'sql_state', SQLSTATE
                    )
                );
            END IF;
            
            v_result := jsonb_build_object(
                'success', FALSE,
                'message', 'Error searching data: ' || v_error_message,
                'action', p_action,
                'error_time', CURRENT_TIMESTAMP::TEXT
            );
        END;
    
    -- ========== ACTION: UPDATE ==========
    ELSIF p_action = 'UPDATE' THEN
        BEGIN
            IF v_current_debug_level >= DEBUG_VERBOSE THEN
                RAISE NOTICE 'Executing UPDATE action for batch_id: % with status: %', p_batch_id, p_status;
            END IF;
            
            -- UPDATE ONLY STATUS (no other fields can be modified)
            UPDATE instant_card_generation_batches
            SET status = p_status
            WHERE batch_id = p_batch_id
            RETURNING 1 INTO v_affected_rows;
            
            IF v_affected_rows = 0 THEN
                v_result := jsonb_build_object(
                    'success', FALSE,
                    'message', 'Batch not found or no changes made: ' || p_batch_id,
                    'action', p_action
                );
                
                IF v_current_debug_level >= DEBUG_INFO THEN
                    PERFORM public.flog_audit_trail(
                        v_log_category,
                        'UPDATE_NOT_FOUND',
                        'Batch not found for update',
                        jsonb_build_object(
                            'batch_id', p_batch_id,
                            'action', p_action
                        )
                    );
                END IF;
            ELSE
                v_result := jsonb_build_object(
                    'success', TRUE,
                    'action', p_action,
                    'message', 'Batch status updated successfully',
                    'updated_fields', jsonb_build_object('status', p_status),
                    'batch_id', p_batch_id
                );
                
                IF v_current_debug_level >= DEBUG_INFO THEN
                    PERFORM public.flog_audit_trail(
                        v_log_category,
                        'UPDATE_SUCCESS',
                        'Batch status updated successfully',
                        jsonb_build_object(
                            'batch_id', p_batch_id,
                            'old_status', NULL, -- You might want to capture old status
                            'new_status', p_status,
                            'action', p_action,
                            'affected_rows', v_affected_rows
                        )
                    );
                END IF;
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;
            
            IF v_current_debug_level >= DEBUG_ERROR_ONLY THEN
                PERFORM public.flog_audit_trail(
                    v_log_category,
                    'UPDATE_ERROR',
                    'Error updating batch status',
                    jsonb_build_object(
                        'batch_id', p_batch_id,
                        'status', p_status,
                        'error', v_error_message,
                        'sql_state', SQLSTATE
                    )
                );
            END IF;
            
            v_result := jsonb_build_object(
                'success', FALSE,
                'message', 'Error updating batch: ' || v_error_message,
                'action', p_action,
                'error_time', CURRENT_TIMESTAMP::TEXT
            );
        END;
    
    ELSE
        v_result := jsonb_build_object(
            'success', FALSE,
            'message', 'Unsupported action: ' || p_action,
            'action', p_action
        );
    END IF;
    
    -- Final debug log
    v_end_time := CURRENT_TIMESTAMP;
    
    IF v_current_debug_level >= DEBUG_INFO THEN
        PERFORM public.flog_audit_trail(
            v_log_category,
            'FUNCTION_END',
            'Batch management function completed',
            jsonb_build_object(
                'action', p_action,
                'success', v_result->>'success',
                'duration_seconds', EXTRACT(EPOCH FROM (v_end_time - v_start_time)),
                'start_time', v_start_time::TEXT,
                'end_time', v_end_time::TEXT,
                'debug_level', v_current_debug_level
            )
        );
    END IF;
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS 
            v_error_message = MESSAGE_TEXT,
            v_sql_state = RETURNED_SQLSTATE;
        
        IF v_current_debug_level >= DEBUG_ERROR_ONLY THEN
            PERFORM public.flog_audit_trail(
                v_log_category,
                'FUNCTION_CRITICAL_ERROR',
                'Critical error in batch management function',
                jsonb_build_object(
                    'action', p_action,
                    'error', v_error_message,
                    'sql_state', v_sql_state,
                    'error_time', CURRENT_TIMESTAMP::TEXT
                )
            );
        END IF;
        
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', 'Critical function error: ' || v_error_message,
            'action', p_action,
            'sql_state', v_sql_state,
            'error_time', CURRENT_TIMESTAMP::TEXT
        );
END;
$_$;


ALTER FUNCTION public.finstantbatchidmanagement(p_action text, p_batch_id text, p_from_date timestamp without time zone, p_to_date timestamp without time zone, p_status text, p_debug_level integer) OWNER TO postgres;

--
-- TOC entry 375 (class 1255 OID 31996)
-- Name: finstantcardbranchallocation(character varying, jsonb, integer, character varying, integer, character varying, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstantcardbranchallocation(p_action character varying, p_cardnumbers jsonb, p_userid integer, p_branchcodetoallocate character varying DEFAULT NULL::character varying, p_debuglevel integer DEFAULT 0, p_status character varying DEFAULT 'AVAILABLE'::character varying, p_requestid character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_start_time TIMESTAMP := clock_timestamp();
    v_execution_time INTERVAL;
    v_result JSONB;
    v_final_result JSONB;
    v_audit_data JSONB;
    
    v_card_record JSONB;
    v_cardnumber VARCHAR(19);
    v_masked_cardnumber VARCHAR(19);
    v_old_branch VARCHAR(4);
    v_uploadid VARCHAR(12);
    v_accountnumber VARCHAR(20);
    v_current_status VARCHAR(25);
    v_embossedname VARCHAR(30);
    v_expirydate DATE;
    v_isgreenpin BOOLEAN;
    v_row_count INTEGER;
    v_previous_values JSONB;
    
    v_total_cards INTEGER;
    v_processed_count INTEGER := 0;
    v_success_count INTEGER := 0;
    v_failed_count INTEGER := 0;
    v_results_array JSONB := '[]'::JSONB;
    v_action_message TEXT;
    v_card_results JSONB := '[]'::JSONB;
    
    v_search_result JSONB;
    v_card_count INTEGER;
    v_card_data JSONB;
    
    v_status_to_use VARCHAR(25);
    v_action_detail VARCHAR(50);
    
    -- Variables for status composition
    v_new_status VARCHAR(25);
    v_status_parts VARCHAR(25)[];
    v_current_card_part VARCHAR(25);
    v_current_pin_part VARCHAR(25);
    
    -- Cross-branch access variables
    v_user_branchcode VARCHAR(10);
    v_user_instcode VARCHAR(4);
    v_user_crossbranch BOOLEAN := FALSE;
    v_user_branchname VARCHAR(100);
    v_username VARCHAR(30);
    v_user_branch_id INTEGER;
    v_user_access_message TEXT;
    
    -- Variables for flag update based on card status and type
    v_current_booked_cards INTEGER;
    v_current_approved_cards INTEGER;
    v_current_booked_allocated BOOLEAN;
    v_current_approved_allocated BOOLEAN;
    v_flag_update_message TEXT := '';
    v_flag_updated BOOLEAN := FALSE;
    
    -- Track allocations by status, not by pin type
    v_booked_status_cards_allocated_count INTEGER := 0;
    v_approved_status_cards_allocated_count INTEGER := 0;
    v_total_booked_cards_in_request INTEGER := 0;
    v_total_approved_cards_in_request INTEGER := 0;
    
    -- Track if allocation is happening
    v_any_card_allocated BOOLEAN := FALSE;
    v_request_found BOOLEAN := FALSE;
BEGIN
    -- Debug level check for function start
    IF p_debuglevel > 3 THEN
        RAISE NOTICE '========================================';
        RAISE NOTICE 'FUNCTION STARTED at %', clock_timestamp();
        RAISE NOTICE 'Parameters:';
        RAISE NOTICE '  p_action: %', p_action;
        RAISE NOTICE '  p_cardnumbers: %', p_cardnumbers;
        RAISE NOTICE '  p_userid: %', p_userid;
        RAISE NOTICE '  p_branchcodetoallocate: %', p_branchcodetoallocate;
        RAISE NOTICE '  p_debuglevel: %', p_debuglevel;
        RAISE NOTICE '  p_status: %', p_status;
        RAISE NOTICE '  p_requestid: %', p_requestid;
        RAISE NOTICE '========================================';
    END IF;
    
    PERFORM set_config('app.debuglevel', p_debuglevel::text, false);
    PERFORM set_config('app.session_id', 
        COALESCE(current_setting('app.session_id', true), 
                'card_' || p_action || '_' || extract(epoch from now())::text), 
        false);
    PERFORM set_config('app.user_agent', 
        COALESCE(current_setting('app.user_agent', true), 'card_system'), 
        false);
    
    -- Get user branch info for access control
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 1: Getting user branch info for user_id: %', p_userid;
    END IF;
    
    IF p_userid IS NOT NULL AND p_userid > 0 THEN
        -- Get user info with explicit handling - JOIN with branch table to get branch_no
        SELECT u.branchid,
               LEFT(u.institutionid::TEXT, 4),
               u.crossbranch,
               b.branch_no,
               b.branch_name,
               al.username
          INTO v_user_branch_id, v_user_instcode, v_user_crossbranch, 
               v_user_branchcode, v_user_branchname, v_username
        FROM users u
        LEFT JOIN branch b ON b.id = u.branchid
        LEFT JOIN authlogin al ON al.userid = u.id
        WHERE u.id = p_userid;
        
        -- If user not found, use defaults
        IF NOT FOUND THEN
            v_user_crossbranch := FALSE;
            v_user_branchcode := NULL;
            v_user_instcode := NULL;
            v_user_branchname := NULL;
            v_username := NULL;
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'User ID % not found in users table, using limited access', p_userid;
            END IF;
        ELSE
            -- Clean branch code (remove any whitespace)
            v_user_branchcode := TRIM(v_user_branchcode);
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'User found:';
                RAISE NOTICE '  username: %', v_username;
                RAISE NOTICE '  branchcode: %', v_user_branchcode;
                RAISE NOTICE '  branchname: %', v_user_branchname;
                RAISE NOTICE '  crossbranch: %', v_user_crossbranch;
            END IF;
            
            -- Validate branch code
            IF v_user_branchcode IS NULL OR v_user_branchcode = '' THEN
                RAISE EXCEPTION 'User % has NULL or empty branch code. Please update user branch information.', p_userid;
            END IF;
        END IF;
        
        -- Set access message for audit logging
        IF v_user_crossbranch = TRUE THEN
            v_user_access_message := 'Cross-branch access enabled';
        ELSE
            v_user_access_message := 'Limited to branch: ' || v_user_branchcode;
        END IF;
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'Access message: %', v_user_access_message;
        END IF;
        
    ELSE
        -- No user ID provided, use limited access
        v_user_crossbranch := FALSE;
        v_user_branchcode := NULL;
        v_username := NULL;
        v_user_access_message := 'No valid user ID provided - limited access';
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'No valid user ID provided, using limited access';
        END IF;
    END IF;
    
    -- Set status to use
    IF p_status IS NULL THEN
        v_status_to_use := 'AVAILABLE';
    ELSE
        v_status_to_use := p_status;
    END IF;
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Status to use: %', v_status_to_use;
    END IF;
    
    -- Validate JSON input
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 2: Validating JSON input';
    END IF;
    
    IF jsonb_typeof(p_cardnumbers) != 'array' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: cardnumbers is not a JSON array, it is: %', jsonb_typeof(p_cardnumbers);
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'cardnumbers parameter must be a JSON array',
            jsonb_build_object(
                'error_message', 'cardnumbers parameter must be a JSON array',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'received_type', jsonb_typeof(p_cardnumbers),
                'debuglevel', p_debuglevel,
                'status', v_status_to_use
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'cardnumbers parameter must be a JSON array',
            'error_code', 'INVALID_INPUT',
            'user_access', v_user_access_message
        );
    END IF;
    
    v_total_cards := jsonb_array_length(p_cardnumbers);
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Total cards in array: %', v_total_cards;
    END IF;
    
    -- Validate empty array for UPDATE/DELETE
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 3: Checking for empty array (action: %)', p_action;
    END IF;
    
    IF p_action IN ('UPDATE', 'DELETE') AND v_total_cards = 0 THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: Empty card numbers array for UPDATE/DELETE action';
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'Empty card numbers array provided',
            jsonb_build_object(
                'error_message', 'Empty card numbers array provided',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'total_cards', v_total_cards,
                'debuglevel', p_debuglevel,
                'status', v_status_to_use
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'No card numbers provided',
            'error_code', 'EMPTY_ARRAY',
            'user_access', v_user_access_message
        );
    END IF;
    
    -- Validate status
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 4: Validating status: %', v_status_to_use;
    END IF;
    
    IF v_status_to_use NOT IN ('AVAILABLE', 'ALLOCATED', 'ASSIGNED', 'ACTIVE', 'BLOCKED', 'NEW', 'IN_STOCK', 'EXPIRED', 'CLOSED',
                               'CARD DISPATCH', 'PIN DISPATCH', 'CARD & PIN DISPATCH', 
                               'CARD ACK', 'PIN ACK', 'CARD ACK & PIN DISPATCH',
                               'CARD DISPATCH & PIN ACK', 'CARD ACK & PIN ACK','BOOKED') THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: Invalid status: %', v_status_to_use;
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'Invalid status value: ' || v_status_to_use,
            jsonb_build_object(
                'error_message', 'Invalid status value',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'provided_status', v_status_to_use,
                'valid_statuses', ARRAY['AVAILABLE', 'ALLOCATED', 'ASSIGNED', 'ACTIVE', 'BLOCKED', 'NEW', 'IN_STOCK', 'EXPIRED', 'CLOSED',
                                       'CARD DISPATCH', 'PIN DISPATCH', 'CARD & PIN DISPATCH', 
                                       'CARD ACK', 'PIN ACK', 'CARD ACK & PIN DISPATCH',
                                       'CARD DISPATCH & PIN ACK', 'CARD ACK & PIN ACK','BOOKED'],
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid status.',
            'error_code', 'INVALID_STATUS',
            'user_access', v_user_access_message
        );
    END IF;
    
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Status validation passed';
    END IF;
    
    -- Debug logging if debuglevel >= 1
    IF p_debuglevel >= 1 THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'Step 5: Debug logging (debuglevel >= 1)';
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            p_action || '_START',
            'Starting ' || p_action || ' action for ' || v_total_cards || ' cards with status: ' || v_status_to_use,
            jsonb_build_object(
                'action', p_action,
                'total_cards', v_total_cards,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'user_access_level', v_user_access_message,
                'branch_to_allocate', p_branchcodetoallocate,
                'status_to_set', v_status_to_use,
                'debuglevel', p_debuglevel,
                'start_time', v_start_time,
                'client_ip', inet_client_addr()
            )
        );
    END IF;
    
    -- Validate action
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 6: Validating action: %', p_action;
    END IF;
    
    IF p_action NOT IN ('UPDATE', 'DELETE', 'SEARCH') THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: Invalid action: %', p_action;
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'INVALID_ACTION',
            'Invalid action requested: ' || p_action,
            jsonb_build_object(
                'error_message', 'Invalid action requested',
                'requested_action', p_action,
                'valid_actions', ARRAY['UPDATE', 'DELETE', 'SEARCH'],
                'total_cards', v_total_cards,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status', v_status_to_use,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid action. Must be UPDATE, DELETE, or SEARCH',
            'error_code', 'INVALID_ACTION',
            'user_access', v_user_access_message
        );
    END IF;
    
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Action validation passed';
    END IF;
    
    -- Validate branch access for UPDATE
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 7: Validating branch access for UPDATE action';
    END IF;
    
    IF p_action = 'UPDATE' AND p_branchcodetoallocate IS NOT NULL 
       AND v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
       AND p_branchcodetoallocate != v_user_branchcode THEN
        
		        IF p_debuglevel > 3 THEN
		            RAISE NOTICE 'ACCESS DENIED: User cannot allocate to branch % (user branch: %)', 
		                p_branchcodetoallocate, v_user_branchcode;
		        END IF;    
		        PERFORM public.flog_audit_trail(
		            'INSTANT_CARD',
		            'BRANCH_ACCESS_DENIED',
		            'User cannot allocate to branch: ' || p_branchcodetoallocate,
		            jsonb_build_object(
		                'error_message', 'User does not have permission to allocate to this branch',
		                'action', p_action,
		                'user_id', p_userid,
		                'username', v_username,
		                'user_branch', v_user_branchcode,
		                'target_branch', p_branchcodetoallocate,
		                'crossbranch_access', v_user_crossbranch,
		                'total_cards', v_total_cards,
		                'debuglevel', p_debuglevel
		            )
		        );
        
		        RETURN jsonb_build_object(
		            'success', false,
		            'message', 'You do not have permission to allocate cards to branch: ' || p_branchcodetoallocate,
		            'error_code', 'BRANCH_ACCESS_DENIED',
		            'user_access', v_user_access_message,
		            'user_branch', v_user_branchcode,
		            'target_branch', p_branchcodetoallocate
		        );
    END IF;
    
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Branch access validation passed';
    END IF;
    
    -- If this is an UPDATE with requestid, pre-fetch the request details
    IF p_action = 'UPDATE' AND p_requestid IS NOT NULL THEN
        -- Get the request details from instantcardcycle
        SELECT 
            booked_cards,
            approved_cards,
            bookedcardallocated,
            approvedcardsallocated
        INTO 
            v_total_booked_cards_in_request,
            v_total_approved_cards_in_request,
            v_current_booked_allocated,
            v_current_approved_allocated
        FROM public.instantcardcycle
        WHERE requestid = p_requestid;
        
        IF FOUND THEN
            v_request_found := TRUE;
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Request details found for ID %:', p_requestid;
                RAISE NOTICE '  booked_cards: %', v_total_booked_cards_in_request;
                RAISE NOTICE '  approved_cards: %', v_total_approved_cards_in_request;
                RAISE NOTICE '  bookedcardallocated: %', v_current_booked_allocated;
                RAISE NOTICE '  approvedcardsallocated: %', v_current_approved_allocated;
            END IF;
        ELSE
            RAISE NOTICE 'Warning: Request ID % not found in instantcardcycle table', p_requestid;
        END IF;
    END IF;
    
    -- Main action handling
    IF p_action = 'UPDATE' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'PROCESSING UPDATE ACTION';
            RAISE NOTICE '========================================';
        END IF;
        
        -- Validate parameters for UPDATE
        IF p_branchcodetoallocate IS NULL AND v_status_to_use IS NULL THEN
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'ERROR: Neither branch nor status provided for UPDATE';
            END IF;
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD',
                'UPDATE_ERROR',
                'Either branch or status must be provided for UPDATE action',
                jsonb_build_object(
                    'error_message', 'Either branch or status must be provided for UPDATE action',
                    'action', p_action,
                    'total_cards', v_total_cards,
                    'user_id', p_userid,
                    'username', v_username,
                    'user_branch', v_user_branchcode,
                    'crossbranch_access', v_user_crossbranch,
                    'debuglevel', p_debuglevel
                )
            );
            
            RETURN jsonb_build_object(
                'success', false,
                'message', 'Either branch code or status must be provided for UPDATE action',
                'error_code', 'MISSING_PARAMETER',
                'user_access', v_user_access_message
            );
        END IF;
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'UPDATE parameters valid. Processing % cards', v_total_cards;
        END IF;
        
        -- Initialize counters
        v_booked_status_cards_allocated_count := 0;
        v_approved_status_cards_allocated_count := 0;
        
        -- Loop through each card
        FOR i IN 0..v_total_cards - 1 LOOP
            v_processed_count := v_processed_count + 1;
            v_cardnumber := p_cardnumbers->>i;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE '----------------------------------------';
                RAISE NOTICE 'Processing card % of % (Index: %)', i+1, v_total_cards, i;
                RAISE NOTICE 'Card number: %', v_cardnumber;
            END IF;
            
            IF v_cardnumber IS NULL OR v_cardnumber = '' THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Empty card number at index %', i;
                END IF;
                v_failed_count := v_failed_count + 1;
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'Empty card number',
                    'error_code', 'EMPTY_CARD_NUMBER',
                    'user_access', v_user_access_message
                );
                CONTINUE;
            END IF;
            
            -- Create masked version for audit trail only
            v_masked_cardnumber := 'XXXX-XXXX-XXXX-' || RIGHT(v_cardnumber, 4);
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Masked card number: %', v_masked_cardnumber;
            END IF;
            
            BEGIN
                -- Get card details from database including isgreenpin (for info only)
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Fetching card details from instantcardstock';
                END IF;
                
                SELECT 
                    allocatedbranch, 
                    uploadid, 
                    accountnumber, 
                    status,
                    embossedname,
                    expirydate,
                    isgreenpin
                INTO 
                    v_old_branch, 
                    v_uploadid, 
                    v_accountnumber, 
                    v_current_status,
                    v_embossedname,
                    v_expirydate,
                    v_isgreenpin
                FROM public.instantcardstock 
                WHERE cardnumber = v_cardnumber;
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Card details found:';
                    RAISE NOTICE '  allocatedbranch: %', v_old_branch;
                    RAISE NOTICE '  uploadid: %', v_uploadid;
                    RAISE NOTICE '  accountnumber: %', v_accountnumber;
                    RAISE NOTICE '  current status: %', v_current_status;
                    RAISE NOTICE '  embossedname: %', v_embossedname;
                    RAISE NOTICE '  isgreenpin: %', v_isgreenpin;
                END IF;
                
                IF v_uploadid IS NULL THEN
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'ERROR: Card not found in database';
                    END IF;
                    v_failed_count := v_failed_count + 1;
                    v_card_results := v_card_results || jsonb_build_object(
                        'cardnumber', v_cardnumber,
                        'success', false,
                        'message', 'Card not found',
                        'error_code', 'CARD_NOT_FOUND',
                        'user_access', v_user_access_message
                    );
                    CONTINUE;
                END IF;
                
                -- Check user access to modify this card
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Checking user access to modify card';
                END IF;
                
                IF v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
                   AND v_old_branch IS NOT NULL AND v_old_branch != v_user_branchcode THEN
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'ACCESS DENIED: Card belongs to branch %, user is from branch %', 
                            v_old_branch, v_user_branchcode;
                    END IF;
                        
                    v_failed_count := v_failed_count + 1;
                    v_card_results := v_card_results || jsonb_build_object(
                        'cardnumber', v_cardnumber,
                        'success', false,
                        'message', 'You do not have permission to modify this card. Card belongs to branch: ' || v_old_branch,
                        'error_code', 'CARD_ACCESS_DENIED',
                        'user_access', v_user_access_message,
                        'card_branch', v_old_branch,
                        'user_branch', v_user_branchcode
                    );
                    CONTINUE;
                END IF;
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Access granted';
                END IF;
                
                -- Initialize v_new_status with the requested status
                v_new_status := v_status_to_use;
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Requested new status: %', v_new_status;
                END IF;
                
                -- STATUS COMPOSITION LOGIC
                -- Only apply composition logic for card/PIN related statuses
                IF v_status_to_use IN ('CARD DISPATCH', 'PIN DISPATCH', 'CARD ACK', 'PIN ACK') THEN
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Applying status composition logic';
                        RAISE NOTICE 'Current status: %', v_current_status;
                    END IF;
                    
                    -- Check if current status is a combined status
                    IF v_current_status LIKE '%&%' THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Current status is combined status';
                        END IF;
                        -- Parse the current combined status
                        v_status_parts := string_to_array(v_current_status, ' & ');
                        
                        IF array_length(v_status_parts, 1) >= 1 THEN
                            v_current_card_part := TRIM(v_status_parts[1]);
                        END IF;
                        IF array_length(v_status_parts, 1) >= 2 THEN
                            v_current_pin_part := TRIM(v_status_parts[2]);
                        END IF;
                        
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Current card part: %, current pin part: %', 
                                v_current_card_part, v_current_pin_part;
                        END IF;
                        
                        -- Apply composition logic based on requested status
                        IF v_status_to_use = 'CARD DISPATCH' THEN
                            -- Update card part to CARD DISPATCH, keep existing pin part
                            IF v_current_pin_part IS NOT NULL THEN
                                v_new_status := 'CARD DISPATCH & ' || v_current_pin_part;
                            ELSE
                                v_new_status := 'CARD DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN DISPATCH' THEN
                            -- Update pin part to PIN DISPATCH, keep existing card part
                            IF v_current_card_part IS NOT NULL THEN
                                v_new_status := v_current_card_part || ' & PIN DISPATCH';
                            ELSE
                                v_new_status := 'PIN DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'CARD ACK' THEN
                            -- Update card part to CARD ACK, keep existing pin part
                            IF v_current_pin_part IS NOT NULL THEN
                                v_new_status := 'CARD ACK & ' || v_current_pin_part;
                            ELSE
                                v_new_status := 'CARD ACK';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN ACK' THEN
                            -- Update pin part to PIN ACK, keep existing card part
                            IF v_current_card_part IS NOT NULL THEN
                                v_new_status := v_current_card_part || ' & PIN ACK';
                            ELSE
                                v_new_status := 'PIN ACK';
                            END IF;
                        END IF;
                        
                    ELSE
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Current status is simple status';
                        END IF;
                        -- Current status is not combined, need to create combination if needed
                        IF v_status_to_use = 'CARD DISPATCH' THEN
                            IF v_current_status = 'PIN DISPATCH' THEN
                                -- PIN was dispatched first, now card dispatched
                                v_new_status := 'CARD & PIN DISPATCH';
                            ELSIF v_current_status = 'PIN ACK' THEN
                                -- PIN was acknowledged, now card dispatched
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSE
                                -- Starting fresh with card dispatch
                                v_new_status := 'CARD DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN DISPATCH' THEN
                            IF v_current_status = 'CARD DISPATCH' THEN
                                -- Card was dispatched first, now PIN dispatched
                                v_new_status := 'CARD & PIN DISPATCH';
                            ELSIF v_current_status = 'CARD ACK' THEN
                                -- Card was acknowledged, now PIN dispatched
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSE
                                -- Starting fresh with PIN dispatch
                                v_new_status := 'PIN DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'CARD ACK' THEN
                            IF v_current_status = 'CARD DISPATCH' THEN
                                -- Card was dispatched, now acknowledged
                                v_new_status := 'CARD ACK';
                            ELSIF v_current_status = 'CARD DISPATCH & PIN ACK' THEN
                                -- Card dispatched & PIN acked, now card acknowledged
                                v_new_status := 'CARD ACK & PIN ACK';
                            ELSIF v_current_status = 'CARD & PIN DISPATCH' THEN
                                -- Both dispatched, now card acknowledged
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSIF v_current_status = 'PIN DISPATCH' THEN
                                -- Only PIN dispatched, now card acknowledged (unusual)
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSE
                                -- Direct card acknowledgment
                                v_new_status := 'CARD ACK';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN ACK' THEN
                            IF v_current_status = 'PIN DISPATCH' THEN
                                -- PIN was dispatched, now acknowledged
                                v_new_status := 'PIN ACK';
                            ELSIF v_current_status = 'CARD ACK & PIN DISPATCH' THEN
                                -- Card acked & PIN dispatched, now PIN acknowledged
                                v_new_status := 'CARD ACK & PIN ACK';
                            ELSIF v_current_status = 'CARD & PIN DISPATCH' THEN
                                -- Both dispatched, now PIN acknowledged
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSIF v_current_status = 'CARD DISPATCH' THEN
                                -- Only card dispatched, now PIN acknowledged (unusual)
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSE
                                -- Direct PIN acknowledgment
                                v_new_status := 'PIN ACK';
                            END IF;
                        END IF;
                    END IF;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Composed new status: %', v_new_status;
                    END IF;
                END IF;
                -- END STATUS COMPOSITION LOGIC
                
                -- Track if we're setting status to ALLOCATED (for flag updates)
                IF v_new_status = 'ALLOCATED' THEN
                    v_any_card_allocated := TRUE;
                END IF;
                
                -- Now use v_new_status for the update   
                IF p_branchcodetoallocate IS NOT NULL THEN
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Branch allocation requested to: %', p_branchcodetoallocate;
                    END IF;
                    
                    -- Check if card can be allocated
                    IF v_current_status NOT IN ('AVAILABLE', 'NEW', 'IN_STOCK', 'ALLOCATED','BOOKED') THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'ERROR: Card status % does not allow allocation', v_current_status;
                        END IF;
                        v_failed_count := v_failed_count + 1;
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Card status does not allow branch allocation. Current: ' || v_current_status,
                            'error_code', 'INVALID_STATUS_FOR_BRANCH',
                            'current_status', v_current_status,
                            'user_access', v_user_access_message
                        );
                        CONTINUE;
                    END IF;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Current branch: %, Target branch: %', v_old_branch, p_branchcodetoallocate;
                    END IF;
                    
                    IF v_old_branch = p_branchcodetoallocate THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Branch already matches target branch';
                        END IF;
                        
                        IF v_current_status != v_new_status THEN
                            IF p_debuglevel > 3 THEN
                                RAISE NOTICE 'Updating status only (branch same)';
                            END IF;
                            
                            UPDATE public.instantcardstock
                            SET 
                                status = v_new_status,
                                lastupdateddate = CURRENT_TIMESTAMP,
                                lastupdatedby = v_username
                            WHERE cardnumber = v_cardnumber
                            RETURNING uploadid INTO v_uploadid;
                            
                            GET DIAGNOSTICS v_row_count = ROW_COUNT;
                            
                            IF v_row_count = 1 AND v_new_status = 'ALLOCATED' THEN
                                v_success_count := v_success_count + 1;
                                
                                -- Count this card for flag updates based on its ORIGINAL STATUS, not pin type
                                -- This is the key fix: use v_current_status (original status) to determine which counter to increment
                                IF v_current_status = 'BOOKED' THEN
                                    -- Cards that were BOOKED should update booked_cards count
                                    v_booked_status_cards_allocated_count := v_booked_status_cards_allocated_count + 1;
                                    IF p_debuglevel > 3 THEN
                                        RAISE NOTICE 'BOOKED status card allocated (was %), booked count: %', v_current_status, v_booked_status_cards_allocated_count;
                                    END IF;
                                ELSIF v_current_status = 'AVAILABLE' THEN
                                    -- Cards that were AVAILABLE should update approved_cards count
                                    v_approved_status_cards_allocated_count := v_approved_status_cards_allocated_count + 1;
                                    IF p_debuglevel > 3 THEN
                                        RAISE NOTICE 'AVAILABLE status card allocated (was %), approved count: %', v_current_status, v_approved_status_cards_allocated_count;
                                    END IF;
                                ELSE
                                    -- Other statuses - for informational purposes
                                    IF p_debuglevel > 3 THEN
                                        RAISE NOTICE 'Card with status % allocated - not counted for flags', v_current_status;
                                    END IF;
                                END IF;
                            END IF;
                            
                            -- LOGGING: Status change when branch already same (removed isgreenpin)
                            INSERT INTO LOG_instant_card_allocation (
                                cardnumber, operation_type,
                                from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                            ) VALUES (
                                v_cardnumber, 'STATUS_CHANGE',
                                v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                            );
                            
                            v_card_results := v_card_results || jsonb_build_object(
                                'cardnumber', v_cardnumber,
                                'success', true,
                                'message', 'Status updated to ' || v_new_status || ' (branch already ' || v_old_branch || ')',
                                'uploadid', v_uploadid,
                                'branch', v_old_branch,
                                'old_status', v_current_status,
                                'new_status', v_new_status,
                                'accountnumber', v_accountnumber,
                                'isgreenpin', v_isgreenpin,
                                'user_access', v_user_access_message
                            );
                            
                            IF p_debuglevel > 3 THEN
                                RAISE NOTICE 'Status update successful';
                            END IF;
                        ELSE
                            IF p_debuglevel > 3 THEN
                                RAISE NOTICE 'No changes required (branch and status same)';
                            END IF;
                            
                            v_success_count := v_success_count + 1;
                            
                            -- LOGGING: No change when branch same and status same (removed isgreenpin)
                            INSERT INTO LOG_instant_card_allocation (
                                cardnumber, operation_type,
                                from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                            ) VALUES (
                                v_cardnumber, 'UPDATE',
                                v_old_branch, p_branchcodetoallocate, v_current_status, v_current_status, v_username, p_userid
                            );
                            
                            v_card_results := v_card_results || jsonb_build_object(
                                'cardnumber', v_cardnumber,
                                'success', true,
                                'message', 'No changes required',
                                'no_change', true,
                                'current_branch', v_old_branch,
                                'current_status', v_current_status,
                                'isgreenpin', v_isgreenpin,
                                'user_access', v_user_access_message
                            );
                        END IF;
                        CONTINUE;
                    END IF;
                    
                    -- Perform the actual allocation
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Allocating card to new branch: %', p_branchcodetoallocate;
                    END IF;
                    
                    UPDATE public.instantcardstock
                    SET 
                        allocatedbranch = p_branchcodetoallocate,
                        status = v_new_status,
                        lastupdateddate = CURRENT_TIMESTAMP,
                        lastupdatedby = v_username
                    WHERE cardnumber = v_cardnumber
                    RETURNING uploadid INTO v_uploadid;
                    
                    GET DIAGNOSTICS v_row_count = ROW_COUNT;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Rows affected: %', v_row_count;
                    END IF;
                    
                    IF v_row_count = 1 THEN
                        v_success_count := v_success_count + 1;
                        
                        -- Count this card for flag updates based on its ORIGINAL STATUS, not pin type
                        IF v_new_status = 'ALLOCATED' THEN
                            IF v_current_status = 'BOOKED' THEN
                                -- Cards that were BOOKED should update booked_cards count
                                v_booked_status_cards_allocated_count := v_booked_status_cards_allocated_count + 1;
                                IF p_debuglevel > 3 THEN
                                    RAISE NOTICE 'BOOKED status card allocated (was %), booked count: %', v_current_status, v_booked_status_cards_allocated_count;
                                END IF;
                            ELSIF v_current_status = 'AVAILABLE' THEN
                                -- Cards that were AVAILABLE should update approved_cards count
                                v_approved_status_cards_allocated_count := v_approved_status_cards_allocated_count + 1;
                                IF p_debuglevel > 3 THEN
                                    RAISE NOTICE 'AVAILABLE status card allocated (was %), approved count: %', v_current_status, v_approved_status_cards_allocated_count;
                                END IF;
                            ELSE
                                -- Other statuses - for informational purposes
                                IF p_debuglevel > 3 THEN
                                    RAISE NOTICE 'Card with status % allocated - not counted for flags', v_current_status;
                                END IF;
                            END IF;
                        END IF;
                        
                        -- LOGGING: Branch allocation with status change (removed isgreenpin)
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'ALLOCATE',
                            v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Branch allocated to ' || p_branchcodetoallocate || ' with status ' || v_new_status,
                            'uploadid', v_uploadid,
                            'old_branch', v_old_branch,
                            'new_branch', p_branchcodetoallocate,
                            'old_status', v_current_status,
                            'new_status', v_new_status,
                            'accountnumber', v_accountnumber,
                            'isgreenpin', v_isgreenpin,
                            'user_access', v_user_access_message
                        );
                        
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Allocation successful';
                        END IF;
                        
                        IF p_debuglevel >= 2 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD',
                                'BRANCH_ALLOCATED',
                                'Card allocated to branch ' || p_branchcodetoallocate || ' with status ' || v_new_status || ': ' || v_masked_cardnumber,
                                jsonb_build_object(
                                    'cardnumber', v_masked_cardnumber,
                                    'uploadid', v_uploadid,
                                    'old_branch', v_old_branch,
                                    'new_branch', p_branchcodetoallocate,
                                    'old_status', v_current_status,
                                    'new_status', v_new_status,
                                    'accountnumber', v_accountnumber,
                                    'isgreenpin', v_isgreenpin,
                                    'user_id', p_userid,
                                    'username', v_username,
                                    'user_branch', v_user_branchcode,
                                    'crossbranch_access', v_user_crossbranch,
                                    'debuglevel', p_debuglevel
                                )
                            );
                        END IF;
                        
                    ELSE
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'ERROR: Allocation failed - no rows affected';
                        END IF;
                        
                        v_failed_count := v_failed_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'ALLOCATE',
                            v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Branch allocation failed - no rows affected',
                            'error_code', 'ALLOCATION_FAILED',
                            'user_access', v_user_access_message
                        );
                    END IF;
                    
                ELSE
                    -- No branch allocation, just status update
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'No branch allocation - just status update to: %', v_new_status;
                    END IF;
                    
                    IF v_current_status = v_new_status THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Status already set to % - no change needed', v_new_status;
                        END IF;
                        
                        v_success_count := v_success_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'UPDATE',
                            v_old_branch, v_old_branch, v_current_status, v_current_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Status already ' || v_new_status,
                            'no_change', true,
                            'current_branch', v_old_branch,
                            'current_status', v_current_status,
                            'isgreenpin', v_isgreenpin,
                            'user_access', v_user_access_message
                        );
                        CONTINUE;
                    END IF;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Updating status from % to %', v_current_status, v_new_status;
                    END IF;
                    
                    UPDATE public.instantcardstock
                    SET 
                        status = v_new_status,
                        lastupdateddate = CURRENT_TIMESTAMP,
                        lastupdatedby = v_username
                    WHERE cardnumber = v_cardnumber
                    RETURNING uploadid INTO v_uploadid;
                    
                    GET DIAGNOSTICS v_row_count = ROW_COUNT;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Rows affected: %', v_row_count;
                    END IF;
                    
                    IF v_row_count = 1 THEN
                        v_success_count := v_success_count + 1;
                        
                        -- Count this card for flag updates based on its ORIGINAL STATUS, not pin type
                        IF v_new_status = 'ALLOCATED' THEN
                            IF v_current_status = 'BOOKED' THEN
                                -- Cards that were BOOKED should update booked_cards count
                                v_booked_status_cards_allocated_count := v_booked_status_cards_allocated_count + 1;
                                IF p_debuglevel > 3 THEN
                                    RAISE NOTICE 'BOOKED status card allocated (was %), booked count: %', v_current_status, v_booked_status_cards_allocated_count;
                                END IF;
                            ELSIF v_current_status = 'AVAILABLE' THEN
                                -- Cards that were AVAILABLE should update approved_cards count
                                v_approved_status_cards_allocated_count := v_approved_status_cards_allocated_count + 1;
                                IF p_debuglevel > 3 THEN
                                    RAISE NOTICE 'AVAILABLE status card allocated (was %), approved count: %', v_current_status, v_approved_status_cards_allocated_count;
                                END IF;
                            ELSE
                                -- Other statuses - for informational purposes
                                IF p_debuglevel > 3 THEN
                                    RAISE NOTICE 'Card with status % allocated - not counted for flags', v_current_status;
                                END IF;
                            END IF;
                        END IF;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'STATUS_CHANGE',
                            v_old_branch, v_old_branch, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Status updated to ' || v_new_status,
                            'uploadid', v_uploadid,
                            'branch', v_old_branch,
                            'old_status', v_current_status,
                            'new_status', v_new_status,
                            'accountnumber', v_accountnumber,
                            'isgreenpin', v_isgreenpin,
                            'user_access', v_user_access_message
                        );
                        
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Status update successful';
                        END IF;
                        
                        IF p_debuglevel >= 2 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD',
                                'STATUS_UPDATED',
                                'Card status updated to ' || v_new_status || ': ' || v_masked_cardnumber,
                                jsonb_build_object(
                                    'cardnumber', v_masked_cardnumber,
                                    'uploadid', v_uploadid,
                                    'branch', v_old_branch,
                                    'old_status', v_current_status,
                                    'new_status', v_new_status,
                                    'accountnumber', v_accountnumber,
                                    'isgreenpin', v_isgreenpin,
                                    'user_id', p_userid,
                                    'username', v_username,
                                    'user_branch', v_user_branchcode,
                                    'crossbranch_access', v_user_crossbranch,
                                    'debuglevel', p_debuglevel
                                )
                            );
                        END IF;
                    ELSE
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'ERROR: Status update failed - no rows affected';
                        END IF;
                        
                        v_failed_count := v_failed_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'STATUS_CHANGE',
                            v_old_branch, v_old_branch, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Status update failed - no rows affected',
                            'error_code', 'STATUS_UPDATE_FAILED',
                            'user_access', v_user_access_message
                        );
                    END IF;
                END IF;
                  
            EXCEPTION WHEN OTHERS THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'EXCEPTION CAUGHT: %', SQLERRM;
                    RAISE NOTICE 'SQLSTATE: %', SQLSTATE;
                END IF;
                
                v_failed_count := v_failed_count + 1;
                
                INSERT INTO LOG_instant_card_allocation (
                    cardnumber, operation_type,
                    from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                ) VALUES (
                    v_cardnumber, 
                    CASE 
                        WHEN p_branchcodetoallocate IS NOT NULL AND v_old_branch != p_branchcodetoallocate THEN 'ALLOCATE'
                        ELSE 'STATUS_CHANGE'
                    END,
                    v_old_branch, 
                    p_branchcodetoallocate, 
                    v_current_status, 
                    v_new_status, 
                    v_username, 
                    p_userid
                );
                
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'Error: ' || SQLERRM,
                    'error_code', SQLSTATE,
                    'user_access', v_user_access_message
                );
            END;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Card processing complete. Success: %, Failed: %', v_success_count, v_failed_count;
            END IF;
        END LOOP;
        
        -- =====================================================
        -- FLAG UPDATE LOGIC - Based on original card status, not pin type
        -- =====================================================

		-- =====================================================
-- FLAG UPDATE LOGIC - Based on original card status
-- =====================================================
			IF v_any_card_allocated AND p_requestid IS NOT NULL AND v_request_found THEN
			    BEGIN
			        RAISE NOTICE '=== FLAG UPDATE DEBUG for Request: % ===', p_requestid;
			        RAISE NOTICE 'Cards with BOOKED status allocated in this batch: %', v_booked_status_cards_allocated_count;
			        RAISE NOTICE 'Cards with AVAILABLE status allocated in this batch: %', v_approved_status_cards_allocated_count;
			        RAISE NOTICE 'Total booked cards in request: %', v_total_booked_cards_in_request;
			        RAISE NOTICE 'Total approved cards in request: %', v_total_approved_cards_in_request;
			        RAISE NOTICE 'Current booked_allocated: %, approved_allocated: %', 
			            v_current_booked_allocated, v_current_approved_allocated;
			        
			        -- =========================================
			        -- BOOKED FLAG HANDLING
			        -- =========================================
			        
			        -- Only update booked flag if there are booked cards to allocate
			        IF v_total_booked_cards_in_request > 0 THEN
			            -- Case 1: All BOOKED cards have been allocated
			            IF v_booked_status_cards_allocated_count >= v_total_booked_cards_in_request 
			               AND v_current_booked_allocated = false THEN
			                
			                UPDATE public.instantcardcycle
			                SET bookedcardallocated = true
			                WHERE requestid = p_requestid;
			                
			                v_flag_update_message := 'Booked flag updated - all BOOKED cards allocated';
			                v_flag_updated := TRUE;
			                RAISE NOTICE '✓ Updated bookedcardallocated to TRUE (all % BOOKED cards allocated)', 
			                    v_total_booked_cards_in_request;
			                
			            -- Case 2: Partial allocation of BOOKED cards
			            ELSIF v_booked_status_cards_allocated_count > 0 
			                  AND v_current_booked_allocated = false THEN
			                RAISE NOTICE 'Partial allocation of BOOKED cards: % of % allocated - flag not updated yet', 
			                    v_booked_status_cards_allocated_count, v_total_booked_cards_in_request;
			            END IF;
			        ELSE
			            -- No booked cards in request - flag should remain FALSE
			            RAISE NOTICE 'No booked cards in request - booked flag remains false';
			        END IF;
			        
			        -- =========================================
			        -- APPROVED FLAG HANDLING
			        -- =========================================
			        
			        -- Only update approved flag if there are approved cards to allocate
			        IF v_total_approved_cards_in_request > 0 THEN
			            -- Case 1: All APPROVED cards have been allocated
			            IF v_approved_status_cards_allocated_count >= v_total_approved_cards_in_request 
			               AND v_current_approved_allocated = false THEN
			                
			                UPDATE public.instantcardcycle
			                SET approvedcardsallocated = true
			                WHERE requestid = p_requestid;
			                
			                v_flag_update_message := v_flag_update_message || ' Approved flag updated - all APPROVED cards allocated';
			                v_flag_updated := TRUE;
			                RAISE NOTICE '✓ Updated approvedcardsallocated to TRUE (all % APPROVED cards allocated)', 
			                    v_total_approved_cards_in_request;
			                
			            -- Case 2: Partial allocation of APPROVED cards
			            ELSIF v_approved_status_cards_allocated_count > 0 
			                  AND v_current_approved_allocated = false THEN
			                RAISE NOTICE 'Partial allocation of APPROVED cards: % of % allocated - flag not updated yet', 
			                    v_approved_status_cards_allocated_count, v_total_approved_cards_in_request;
			            END IF;
			        ELSE
			            -- No approved cards in request - flag should remain FALSE
			            RAISE NOTICE 'No approved cards in request - approved flag remains false';
			        END IF;
			        
			        RAISE NOTICE '=== END FLAG UPDATE DEBUG ===';
			        
			    EXCEPTION WHEN OTHERS THEN
			        RAISE NOTICE 'ERROR in flag update: %', SQLERRM;
			        PERFORM public.flog_audit_trail(
			            'INSTANT_CARD_CYCLE',
			            'FLAG_UPDATE_ERROR',
			            'Error: ' || SQLERRM,
			            jsonb_build_object(
			                'requestid', p_requestid,
			                'error', SQLERRM,
			                'booked_allocated_count', v_booked_status_cards_allocated_count,
			                'approved_allocated_count', v_approved_status_cards_allocated_count,
			                'total_booked', v_total_booked_cards_in_request,
			                'total_approved', v_total_approved_cards_in_request
			            )
			        );
			    END;
			    
			ELSIF v_any_card_allocated AND p_requestid IS NULL THEN
			    RAISE NOTICE 'Warning: Cards allocated but no requestid provided - flags not updated';
			    
			ELSIF v_any_card_allocated AND NOT v_request_found THEN
			    RAISE NOTICE 'Warning: Cards allocated but request ID % not found - flags not updated', p_requestid;
			    
			END IF;
        
        v_execution_time := clock_timestamp() - v_start_time;
        v_action_message := format('UPDATE completed: %s successful, %s failed out of %s total', 
                                 v_success_count, v_failed_count, v_total_cards);
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'UPDATE SUMMARY:';
            RAISE NOTICE '  Total cards: %', v_total_cards;
            RAISE NOTICE '  Processed: %', v_processed_count;
            RAISE NOTICE '  Successful: %', v_success_count;
            RAISE NOTICE '  Failed: %', v_failed_count;
            RAISE NOTICE '  BOOKED status cards allocated: %', v_booked_status_cards_allocated_count;
            RAISE NOTICE '  AVAILABLE status cards allocated: %', v_approved_status_cards_allocated_count;
            RAISE NOTICE '  Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '  Flag updated: %', v_flag_updated;
            RAISE NOTICE '  Flag message: %', v_flag_update_message;
            RAISE NOTICE '========================================';
        END IF;
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'UPDATE_COMPLETED',
            v_action_message,
            jsonb_build_object(
                'action', 'UPDATE',
                'total_cards', v_total_cards,
                'successful', v_success_count,
                'failed', v_failed_count,
                'branch_allocated', p_branchcodetoallocate,
                'status_set', v_new_status,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'summary_message', v_action_message,
                'debuglevel', p_debuglevel,
                'flag_updated', v_flag_updated,
                'flag_message', v_flag_update_message,
                'booked_status_cards_allocated', v_booked_status_cards_allocated_count,
                'available_status_cards_allocated', v_approved_status_cards_allocated_count
            )
        );
        
        RETURN jsonb_build_object(
            'success', v_success_count > 0,
            'message', v_action_message,
            'action', 'UPDATE',
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'branch', p_branchcodetoallocate,
                'status', v_new_status,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'flag_updated', v_flag_updated,
                'flag_message', v_flag_update_message,
                'booked_status_cards_allocated', v_booked_status_cards_allocated_count,
                'available_status_cards_allocated', v_approved_status_cards_allocated_count
            ),
            'card_results', v_card_results
        );
    
    ELSIF p_action = 'DELETE' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'PROCESSING DELETE ACTION';
            RAISE NOTICE '========================================';
        END IF;
        
        -- DELETE section (with debug notices)
        FOR i IN 0..v_total_cards - 1 LOOP
            v_processed_count := v_processed_count + 1;
            v_cardnumber := p_cardnumbers->>i;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Processing card % of % for DELETE', i+1, v_total_cards;
                RAISE NOTICE 'Card number: %', v_cardnumber;
            END IF;
            
            IF v_cardnumber IS NULL OR v_cardnumber = '' THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Empty card number';
                END IF;
                v_failed_count := v_failed_count + 1;
                CONTINUE;
            END IF;
            
            -- Get card branch info first
            SELECT allocatedbranch INTO v_old_branch 
            FROM public.instantcardstock 
            WHERE cardnumber = v_cardnumber;
            
            IF NOT FOUND THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Card not found';
                END IF;
                v_failed_count := v_failed_count + 1;
                CONTINUE;
            END IF;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Card found in branch: %', v_old_branch;
            END IF;
            
            -- Check if user has access to delete this card
            IF v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
               AND v_old_branch IS NOT NULL AND v_old_branch != v_user_branchcode THEN
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ACCESS DENIED: Card belongs to branch %, user is from branch %', 
                        v_old_branch, v_user_branchcode;
                END IF;
                    
                v_failed_count := v_failed_count + 1;
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'You do not have permission to delete this card. Card belongs to branch: ' || v_old_branch,
                    'error_code', 'CARD_ACCESS_DENIED',
                    'user_access', v_user_access_message,
                    'card_branch', v_old_branch,
                    'user_branch', v_user_branchcode
                );
                CONTINUE;
            END IF;
            
            -- Proceed with DELETE if user has access
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Deleting card';
            END IF;
            
            DELETE FROM public.instantcardstock 
            WHERE cardnumber = v_cardnumber;
            
            GET DIAGNOSTICS v_row_count = ROW_COUNT;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Rows affected: %', v_row_count;
            END IF;
            
            IF v_row_count = 1 THEN
                v_success_count := v_success_count + 1;
                
                INSERT INTO LOG_instant_card_allocation (
                    cardnumber, operation_type,
                    from_branch, to_branch, performed_by, performed_by_userid
                ) VALUES (
                    v_cardnumber, 'DELETE',
                    v_old_branch, NULL, v_username, p_userid
                );
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Delete successful';
                END IF;
            ELSE
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Delete failed';
                END IF;
                v_failed_count := v_failed_count + 1;
            END IF;
        END LOOP;
        
        v_execution_time := clock_timestamp() - v_start_time;
        v_action_message := format('DELETE completed: %s successful, %s failed out of %s total', 
                                 v_success_count, v_failed_count, v_total_cards);
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'DELETE SUMMARY:';
            RAISE NOTICE '  Total cards: %', v_total_cards;
            RAISE NOTICE '  Processed: %', v_processed_count;
            RAISE NOTICE '  Successful: %', v_success_count;
            RAISE NOTICE '  Failed: %', v_failed_count;
            RAISE NOTICE '  Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '========================================';
        END IF;
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'DELETE_COMPLETED',
            v_action_message,
            jsonb_build_object(
                'action', 'DELETE',
                'total_cards', v_total_cards,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'summary_message', v_action_message,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', v_success_count > 0,
            'message', v_action_message,
            'action', 'DELETE',
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            ),
            'card_results', v_card_results
        );
        
    ELSIF p_action = 'SEARCH' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'PROCESSING SEARCH ACTION';
            RAISE NOTICE '========================================';
        END IF;
        
        v_search_result := '[]'::JSONB;
        
        -- If no card numbers provided, return cards with the specified status
        IF v_total_cards = 0 THEN
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Searching for all cards with status: %', v_status_to_use;
                RAISE NOTICE 'Branch filter: user_branch=%, crossbranch=%', 
                    v_user_branchcode, v_user_crossbranch;
            END IF;
            
            SELECT COALESCE(jsonb_agg(
                jsonb_build_object(
                    'cardnumber', cardnumber,
                    'uploadid', uploadid,
                    'bankcode', bankcode,
                    'allocatedbranch', allocatedbranch,
                    'requestbranch', requestbranch,
                    'status', status,
                    'embossedname', embossedname,
                    'accountnumber', accountnumber,
                    'expirydate', expirydate,
                    'opendingdate', opendingdate,
                    'createddate', createddate,
                    'lastupdateddate', lastupdateddate,
                    'isgreenpin', isgreenpin
                )
                ORDER BY cardnumber asc
            ), '[]'::JSONB)
            INTO v_search_result
            FROM public.instantcardstock 
            WHERE CASE 
                -- When searching for PIN DISPATCH status, include multiple statuses
                WHEN v_status_to_use = 'PIN DISPATCH' THEN 
                    status IN ('ALLOCATED', 'CARD DISPATCH', 'CARD ACK')
                WHEN v_status_to_use = 'CARD DISPATCH' THEN 
                    status IN ('ALLOCATED', 'PIN DISPATCH', 'PIN ACK')
                WHEN v_status_to_use = 'PIN ACK' THEN 
                    status IN ('PIN DISPATCH', 'CARD ACK & PIN DISPATCH', 'CARD ACK','CARD & PIN DISPATCH')
                WHEN v_status_to_use = 'CARD ACK' THEN 
                    status IN ( 'CARD DISPATCH','CARD & PIN DISPATCH','CARD DISPATCH & PIN ACK')
                -- Otherwise use exact status match
                ELSE status = v_status_to_use
            END
            -- Branch access filtering for SEARCH
            AND (
                v_user_crossbranch = TRUE
                OR allocatedbranch = v_user_branchcode
                OR (v_user_branchcode IS NULL AND allocatedbranch IS NULL)
            );
            
            v_success_count := COALESCE(jsonb_array_length(v_search_result), 0);
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Found % cards matching criteria', v_success_count;
            END IF;
            
        ELSE
            -- Process specific card numbers with branch access check
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Searching for % specific card numbers', v_total_cards;
            END IF;
            
            FOR i IN 0..v_total_cards - 1 LOOP
                v_cardnumber := p_cardnumbers->>i;
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Searching for card: %', v_cardnumber;
                END IF;
                
                IF v_cardnumber IS NOT NULL AND v_cardnumber != '' THEN
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'cardnumber', cardnumber,
                            'uploadid', uploadid,
                            'bankcode', bankcode,
                            'allocatedbranch', allocatedbranch,
                            'requestbranch', requestbranch,
                            'status', status,
                            'embossedname', embossedname,
                            'accountnumber', accountnumber,
                            'expirydate', expirydate,
                            'opendingdate', opendingdate,
                            'createddate', createddate,
                            'lastupdateddate', lastupdateddate,
                            'isgreenpin', isgreenpin
                        )
                    )
                    INTO v_card_data
                    FROM public.instantcardstock 
                    WHERE cardnumber = v_cardnumber
                    AND (
                        v_user_crossbranch = TRUE
                        OR allocatedbranch = v_user_branchcode
                        OR (v_user_branchcode IS NULL AND allocatedbranch IS NULL)
                    );
                    
                    IF v_card_data IS NOT NULL THEN
                        v_search_result := v_search_result || v_card_data;
                        v_success_count := v_success_count + 1;
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Card found';
                        END IF;
                    ELSE
                        v_failed_count := v_failed_count + 1;
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Card not found or access denied';
                        END IF;
                    END IF;
                END IF;
            END LOOP;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Search complete. Found: %, Not found: %', 
                    v_success_count, v_failed_count;
            END IF;
        END IF;
        
        IF p_debuglevel >= 1 THEN
            v_execution_time := clock_timestamp() - v_start_time;
            v_action_message := format('SEARCH completed: Found %s cards, %s not found', 
                                     v_success_count, v_failed_count);
            
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD',
                'SEARCH_COMPLETED',
                v_action_message,
                jsonb_build_object(
                    'action', 'SEARCH',
                    'total_cards', v_total_cards,
                    'found', v_success_count,
                    'not_found', v_failed_count,
                    'user_id', p_userid,
                    'username', v_username,
                    'user_branch', v_user_branchcode,
                    'crossbranch_access', v_user_crossbranch,
                    'status_filter', v_status_to_use,
                    'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                    'summary_message', v_action_message,
                    'debuglevel', p_debuglevel,
                    'search_criteria', CASE 
                        WHEN v_total_cards = 0 THEN format('ALL_CARDS_WITH_STATUS_%s', v_status_to_use)
                        ELSE format('SPECIFIC_CARDS(%s)', v_total_cards)
                    END
                )
            );
        END IF;
        
        v_execution_time := clock_timestamp() - v_start_time;
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'SEARCH SUMMARY:';
            RAISE NOTICE '  Total requested: %', v_total_cards;
            RAISE NOTICE '  Found: %', v_success_count;
            RAISE NOTICE '  Not found: %', v_failed_count;
            RAISE NOTICE '  Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '========================================';
        END IF;
        
        RETURN jsonb_build_object(
            'success', true,
            'message', format('SEARCH completed: Found %s cards, %s not found', 
                            v_success_count, v_failed_count),
            'action', 'SEARCH',
            'summary', jsonb_build_object(
                'total_requested', v_total_cards,
                'found', v_success_count,
                'not_found', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status_filter', v_status_to_use,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            ),
            'cards', v_search_result
        );
    END IF;
    
EXCEPTION
    WHEN OTHERS THEN
        v_execution_time := clock_timestamp() - v_start_time;
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'FATAL ERROR IN FUNCTION';
            RAISE NOTICE 'Error message: %', SQLERRM;
            RAISE NOTICE 'SQLSTATE: %', SQLSTATE;
            RAISE NOTICE 'Action: %', p_action;
            RAISE NOTICE 'Total cards: %', v_total_cards;
            RAISE NOTICE 'Processed: %', v_processed_count;
            RAISE NOTICE 'Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '========================================';
        END IF;
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'FUNCTION_ERROR',
            'Function error: ' || SQLERRM,
            jsonb_build_object(
                'error_message', SQLERRM,
                'error_code', SQLSTATE,
                'action', p_action,
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status', v_status_to_use,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Function error: ' || SQLERRM,
            'error_code', SQLSTATE,
            'action', p_action,
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            )
        );
END;
$$;


ALTER FUNCTION public.finstantcardbranchallocation(p_action character varying, p_cardnumbers jsonb, p_userid integer, p_branchcodetoallocate character varying, p_debuglevel integer, p_status character varying, p_requestid character varying) OWNER TO postgres;

--
-- TOC entry 410 (class 1255 OID 31969)
-- Name: finstantcardbranchallocation_feb172026_v1(character varying, jsonb, integer, character varying, integer, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstantcardbranchallocation_feb172026_v1(p_action character varying, p_cardnumbers jsonb, p_userid integer, p_branchcodetoallocate character varying DEFAULT NULL::character varying, p_debuglevel integer DEFAULT 0, p_status character varying DEFAULT 'AVAILABLE'::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_start_time TIMESTAMP := clock_timestamp();
    v_execution_time INTERVAL;
    v_result JSONB;
    v_final_result JSONB;
    v_audit_data JSONB;
    
    v_card_record JSONB;
    v_cardnumber VARCHAR(19);
    v_masked_cardnumber VARCHAR(19);
    v_old_branch VARCHAR(4);
    v_uploadid VARCHAR(12);
    v_accountnumber VARCHAR(20);
    v_current_status VARCHAR(25);
    v_embossedname VARCHAR(30);
    v_expirydate DATE;
    v_row_count INTEGER;
    v_previous_values JSONB;
    
    v_total_cards INTEGER;
    v_processed_count INTEGER := 0;
    v_success_count INTEGER := 0;
    v_failed_count INTEGER := 0;
    v_results_array JSONB := '[]'::JSONB;
    v_action_message TEXT;
    v_card_results JSONB := '[]'::JSONB;
    
    v_search_result JSONB;
    v_card_count INTEGER;
    v_card_data JSONB;
    
    v_status_to_use VARCHAR(25);
    v_action_detail VARCHAR(50);
    
    -- Variables for status composition
    v_new_status VARCHAR(25);
    v_status_parts VARCHAR(25)[];
    v_current_card_part VARCHAR(25);
    v_current_pin_part VARCHAR(25);
    
    -- Cross-branch access variables
    v_user_branchcode VARCHAR(10);
    v_user_instcode VARCHAR(4);
    v_user_crossbranch BOOLEAN := FALSE;
    v_user_branchname VARCHAR(100);
    v_username VARCHAR(30);
    v_user_branch_id INTEGER;
    v_user_access_message TEXT;
	v_current_booked_cards INTEGER;
	v_current_approved_cards INTEGER;
	v_current_booked_allocated BOOLEAN;
	v_current_approved_allocated BOOLEAN;
	v_flag_update_message TEXT := '';
	v_flag_updated BOOLEAN := FALSE;
BEGIN
    PERFORM set_config('app.debuglevel', p_debuglevel::text, false);
    PERFORM set_config('app.session_id', 
        COALESCE(current_setting('app.session_id', true), 
                'card_' || p_action || '_' || extract(epoch from now())::text), 
        false);
    PERFORM set_config('app.user_agent', 
        COALESCE(current_setting('app.user_agent', true), 'card_system'), 
        false);
    
    -- Get user branch info for access control
    IF p_userid IS NOT NULL AND p_userid > 0 THEN
        -- Get user info with explicit handling - JOIN with branch table to get branch_no
        SELECT u.branchid,
               LEFT(u.institutionid::TEXT, 4),
               u.crossbranch,
               b.branch_no,
               b.branch_name,
               al.username
          INTO v_user_branch_id, v_user_instcode, v_user_crossbranch, 
               v_user_branchcode, v_user_branchname, v_username
        FROM users u
        LEFT JOIN branch b ON b.id = u.branchid
        LEFT JOIN authlogin al ON al.userid = u.id
        WHERE u.id = p_userid;
        
        -- If user not found, use defaults
        IF NOT FOUND THEN
            v_user_crossbranch := FALSE;
            v_user_branchcode := NULL;
            v_user_instcode := NULL;
            v_user_branchname := NULL;
            v_username := NULL;
            RAISE NOTICE 'User ID % not found in users table, using limited access', p_userid;
        ELSE
            -- Clean branch code (remove any whitespace)
            v_user_branchcode := TRIM(v_user_branchcode);
            
            -- Validate branch code
            IF v_user_branchcode IS NULL OR v_user_branchcode = '' THEN
                RAISE EXCEPTION 'User % has NULL or empty branch code. Please update user branch information.', p_userid;
            END IF;
        END IF;
        
        -- Set access message for audit logging
        IF v_user_crossbranch = TRUE THEN
            v_user_access_message := 'Cross-branch access enabled';
        ELSE
            v_user_access_message := 'Limited to branch: ' || v_user_branchcode;
        END IF;
        
    ELSE
        -- No user ID provided, use limited access
        v_user_crossbranch := FALSE;
        v_user_branchcode := NULL;
        v_username := NULL;
        v_user_access_message := 'No valid user ID provided - limited access';
        RAISE NOTICE 'No valid user ID provided, using limited access';
    END IF;
    
    IF p_status IS NULL THEN
        v_status_to_use := 'AVAILABLE';
    ELSE
        v_status_to_use := p_status;
    END IF;
    
    IF jsonb_typeof(p_cardnumbers) != 'array' THEN
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'cardnumbers parameter must be a JSON array',
            jsonb_build_object(
                'error_message', 'cardnumbers parameter must be a JSON array',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'received_type', jsonb_typeof(p_cardnumbers),
                'debuglevel', p_debuglevel,
                'status', v_status_to_use
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'cardnumbers parameter must be a JSON array',
            'error_code', 'INVALID_INPUT',
            'user_access', v_user_access_message
        );
    END IF;
    
    v_total_cards := jsonb_array_length(p_cardnumbers);
    
    -- Only validate empty array for UPDATE and DELETE actions, not for SEARCH
    IF p_action IN ('UPDATE', 'DELETE') AND v_total_cards = 0 THEN
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'Empty card numbers array provided',
            jsonb_build_object(
                'error_message', 'Empty card numbers array provided',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'total_cards', v_total_cards,
                'debuglevel', p_debuglevel,
                'status', v_status_to_use
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'No card numbers provided',
            'error_code', 'EMPTY_ARRAY',
            'user_access', v_user_access_message
        );
    END IF;
    
    -- Update status validation to include all card/PIN status combinations
    IF v_status_to_use NOT IN ('AVAILABLE', 'ALLOCATED', 'ASSIGNED', 'ACTIVE', 'BLOCKED', 'NEW', 'IN_STOCK', 'EXPIRED', 'CLOSED',
                               'CARD DISPATCH', 'PIN DISPATCH', 'CARD & PIN DISPATCH', 
                               'CARD ACK', 'PIN ACK', 'CARD ACK & PIN DISPATCH',
                               'CARD DISPATCH & PIN ACK', 'CARD ACK & PIN ACK','BOOKED') THEN
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'Invalid status value: ' || v_status_to_use,
            jsonb_build_object(
                'error_message', 'Invalid status value',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'provided_status', v_status_to_use,
                'valid_statuses', ARRAY['AVAILABLE', 'ALLOCATED', 'ASSIGNED', 'ACTIVE', 'BLOCKED', 'NEW', 'IN_STOCK', 'EXPIRED', 'CLOSED',
                                       'CARD DISPATCH', 'PIN DISPATCH', 'CARD & PIN DISPATCH', 
                                       'CARD ACK', 'PIN ACK', 'CARD ACK & PIN DISPATCH',
                                       'CARD DISPATCH & PIN ACK', 'CARD ACK & PIN ACK','BOOKED'],
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid status.',
            'error_code', 'INVALID_STATUS',
            'user_access', v_user_access_message
        );
    END IF;
    
    IF p_debuglevel >= 1 THEN
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            p_action || '_START',
            'Starting ' || p_action || ' action for ' || v_total_cards || ' cards with status: ' || v_status_to_use,
            jsonb_build_object(
                'action', p_action,
                'total_cards', v_total_cards,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'user_access_level', v_user_access_message,
                'branch_to_allocate', p_branchcodetoallocate,
                'status_to_set', v_status_to_use,
                'debuglevel', p_debuglevel,
                'start_time', v_start_time,
                'client_ip', inet_client_addr()
            )
        );
    END IF;
    
    IF p_action NOT IN ('UPDATE', 'DELETE', 'SEARCH') THEN
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'INVALID_ACTION',
            'Invalid action requested: ' || p_action,
            jsonb_build_object(
                'error_message', 'Invalid action requested',
                'requested_action', p_action,
                'valid_actions', ARRAY['UPDATE', 'DELETE', 'SEARCH'],
                'total_cards', v_total_cards,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status', v_status_to_use,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid action. Must be UPDATE, DELETE, or SEARCH',
            'error_code', 'INVALID_ACTION',
            'user_access', v_user_access_message
        );
    END IF;
    
    -- Validate if user can allocate to target branch for UPDATE action
	RAISE NOTICE 'GOINING INSIDE Validate if user can allocate to target branch for UPDATE action-LEVEL-1';
    IF p_action = 'UPDATE' AND p_branchcodetoallocate IS NOT NULL 
       AND v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
       AND p_branchcodetoallocate != v_user_branchcode THEN
        RAISE NOTICE 'INSIDE LEVEL-1';
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'BRANCH_ACCESS_DENIED',
            'User cannot allocate to branch: ' || p_branchcodetoallocate,
            jsonb_build_object(
                'error_message', 'User does not have permission to allocate to this branch',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'target_branch', p_branchcodetoallocate,
                'crossbranch_access', v_user_crossbranch,
                'total_cards', v_total_cards,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'You do not have permission to allocate cards to branch: ' || p_branchcodetoallocate,
            'error_code', 'BRANCH_ACCESS_DENIED',
            'user_access', v_user_access_message,
            'user_branch', v_user_branchcode,
            'target_branch', p_branchcodetoallocate
        );
    END IF;
    
    IF p_action = 'UPDATE' THEN
        IF p_branchcodetoallocate IS NULL AND v_status_to_use IS NULL THEN
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD',
                'UPDATE_ERROR',
                'Either branch or status must be provided for UPDATE action',
                jsonb_build_object(
                    'error_message', 'Either branch or status must be provided for UPDATE action',
                    'action', p_action,
                    'total_cards', v_total_cards,
                    'user_id', p_userid,
                    'username', v_username,
                    'user_branch', v_user_branchcode,
                    'crossbranch_access', v_user_crossbranch,
                    'debuglevel', p_debuglevel
                )
            );
            
            RETURN jsonb_build_object(
                'success', false,
                'message', 'Either branch code or status must be provided for UPDATE action',
                'error_code', 'MISSING_PARAMETER',
                'user_access', v_user_access_message
            );
        END IF;
        
        FOR i IN 0..v_total_cards - 1 LOOP
            v_processed_count := v_processed_count + 1;
            v_cardnumber := p_cardnumbers->>i;
            IF v_cardnumber IS NULL OR v_cardnumber = '' THEN
                v_failed_count := v_failed_count + 1;
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'Empty card number',
                    'error_code', 'EMPTY_CARD_NUMBER',
                    'user_access', v_user_access_message
                );
                CONTINUE;
            END IF;
            -- Create masked version for audit trail only
            v_masked_cardnumber := 'XXXX-XXXX-XXXX-' || RIGHT(v_cardnumber, 4);
            BEGIN
                SELECT 
                    allocatedbranch, 
                    uploadid, 
                    accountnumber, 
                    status,
                    embossedname,
                    expirydate
                INTO 
                    v_old_branch, 
                    v_uploadid, 
                    v_accountnumber, 
                    v_current_status,
                    v_embossedname,
                    v_expirydate
                FROM public.instantcardstock 
                WHERE cardnumber = v_cardnumber;
                
                IF v_uploadid IS NULL THEN
                    v_failed_count := v_failed_count + 1;
                    v_card_results := v_card_results || jsonb_build_object(
                        'cardnumber', v_cardnumber,
                        'success', false,
                        'message', 'Card not found',
                        'error_code', 'CARD_NOT_FOUND',
                        'user_access', v_user_access_message
                    );
                    CONTINUE;
                END IF;
                
                -- ADDED: Check if user has access to modify this card
                -- Users can only modify cards in their own branch unless they have cross-branch access
                IF v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
                   AND v_old_branch IS NOT NULL AND v_old_branch != v_user_branchcode THEN 
                    v_failed_count := v_failed_count + 1;
                    v_card_results := v_card_results || jsonb_build_object(
                        'cardnumber', v_cardnumber,
                        'success', false,
                        'message', 'You do not have permission to modify this card. Card belongs to branch: ' || v_old_branch,
                        'error_code', 'CARD_ACCESS_DENIED',
                        'user_access', v_user_access_message,
                        'card_branch', v_old_branch,
                        'user_branch', v_user_branchcode
                    );
                    CONTINUE;
                END IF;
                -- Initialize v_new_status with the requested status
                v_new_status := v_status_to_use;
                
                -- STATUS COMPOSITION LOGIC
                -- Only apply composition logic for card/PIN related statuses
                IF v_status_to_use IN ('CARD DISPATCH', 'PIN DISPATCH', 'CARD ACK', 'PIN ACK') THEN
                    -- Check if current status is a combined status
                    IF v_current_status LIKE '%&%' THEN
                        -- Parse the current combined status
                        v_status_parts := string_to_array(v_current_status, ' & ');
                        
                        IF array_length(v_status_parts, 1) >= 1 THEN
                            v_current_card_part := TRIM(v_status_parts[1]);
                        END IF;
                        IF array_length(v_status_parts, 1) >= 2 THEN
                            v_current_pin_part := TRIM(v_status_parts[2]);
                        END IF;
                        
                        -- Apply composition logic based on requested status
                        IF v_status_to_use = 'CARD DISPATCH' THEN
                            -- Update card part to CARD DISPATCH, keep existing pin part
                            IF v_current_pin_part IS NOT NULL THEN
                                v_new_status := 'CARD DISPATCH & ' || v_current_pin_part;
                            ELSE
                                v_new_status := 'CARD DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN DISPATCH' THEN
                            -- Update pin part to PIN DISPATCH, keep existing card part
                            IF v_current_card_part IS NOT NULL THEN
                                v_new_status := v_current_card_part || ' & PIN DISPATCH';
                            ELSE
                                v_new_status := 'PIN DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'CARD ACK' THEN
                            -- Update card part to CARD ACK, keep existing pin part
                            IF v_current_pin_part IS NOT NULL THEN
                                v_new_status := 'CARD ACK & ' || v_current_pin_part;
                            ELSE
                                v_new_status := 'CARD ACK';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN ACK' THEN
                            -- Update pin part to PIN ACK, keep existing card part
                            IF v_current_card_part IS NOT NULL THEN
                                v_new_status := v_current_card_part || ' & PIN ACK';
                            ELSE
                                v_new_status := 'PIN ACK';
                            END IF;
                        END IF;
                        
                    ELSE
                        -- Current status is not combined, need to create combination if needed
                        IF v_status_to_use = 'CARD DISPATCH' THEN
                            IF v_current_status = 'PIN DISPATCH' THEN
                                -- PIN was dispatched first, now card dispatched
                                v_new_status := 'CARD & PIN DISPATCH';
                            ELSIF v_current_status = 'PIN ACK' THEN
                                -- PIN was acknowledged, now card dispatched
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSE
                                -- Starting fresh with card dispatch
                                v_new_status := 'CARD DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN DISPATCH' THEN
                            IF v_current_status = 'CARD DISPATCH' THEN
                                -- Card was dispatched first, now PIN dispatched
                                v_new_status := 'CARD & PIN DISPATCH';
                            ELSIF v_current_status = 'CARD ACK' THEN
                                -- Card was acknowledged, now PIN dispatched
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSE
                                -- Starting fresh with PIN dispatch
                                v_new_status := 'PIN DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'CARD ACK' THEN
                            IF v_current_status = 'CARD DISPATCH' THEN
                                -- Card was dispatched, now acknowledged
                                v_new_status := 'CARD ACK';
                            ELSIF v_current_status = 'CARD DISPATCH & PIN ACK' THEN
                                -- Card dispatched & PIN acked, now card acknowledged
                                v_new_status := 'CARD ACK & PIN ACK';
                            ELSIF v_current_status = 'CARD & PIN DISPATCH' THEN
                                -- Both dispatched, now card acknowledged
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSIF v_current_status = 'PIN DISPATCH' THEN
                                -- Only PIN dispatched, now card acknowledged (unusual)
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSE
                                -- Direct card acknowledgment
                                v_new_status := 'CARD ACK';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN ACK' THEN
                            IF v_current_status = 'PIN DISPATCH' THEN
                                -- PIN was dispatched, now acknowledged
                                v_new_status := 'PIN ACK';
                            ELSIF v_current_status = 'CARD ACK & PIN DISPATCH' THEN
                                -- Card acked & PIN dispatched, now PIN acknowledged
                                v_new_status := 'CARD ACK & PIN ACK';
                            ELSIF v_current_status = 'CARD & PIN DISPATCH' THEN
                                -- Both dispatched, now PIN acknowledged
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSIF v_current_status = 'CARD DISPATCH' THEN
                                -- Only card dispatched, now PIN acknowledged (unusual)
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSE
                                -- Direct PIN acknowledgment
                                v_new_status := 'PIN ACK';
                            END IF;
                        END IF;
                    END IF;
                END IF;
                -- END STATUS COMPOSITION LOGIC
                -- Now use v_new_status (which may have been composed) for the update   
                IF p_branchcodetoallocate IS NOT NULL THEN
                    -- Check if card can be allocated - ALLOW ALLOCATED cards to be re-allocated
                    IF v_current_status NOT IN ('AVAILABLE', 'NEW', 'IN_STOCK', 'ALLOCATED','BOOKED') THEN
                        v_failed_count := v_failed_count + 1;
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Card status does not allow branch allocation. Current: ' || v_current_status,
                            'error_code', 'INVALID_STATUS_FOR_BRANCH',
                            'current_status', v_current_status,
                            'user_access', v_user_access_message
                        );
                        CONTINUE;
                    END IF;
                    
                    IF v_old_branch = p_branchcodetoallocate THEN
                        IF v_current_status != v_new_status THEN
                            UPDATE public.instantcardstock
                            SET 
                                status = v_new_status,
                                lastupdateddate = CURRENT_TIMESTAMP,
                                lastupdatedby = v_username  -- Use username instead of user ID
                            WHERE cardnumber = v_cardnumber;
                            
                            v_success_count := v_success_count + 1;
                            
                            -- LOGGING: Status change when branch already same
                            INSERT INTO LOG_instant_card_allocation (
                                cardnumber, operation_type,
                                from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                            ) VALUES (
                                v_cardnumber, 'STATUS_CHANGE',
                                v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                            );
                            
                            v_card_results := v_card_results || jsonb_build_object(
                                'cardnumber', v_cardnumber,
                                'success', true,
                                'message', 'Status updated to ' || v_new_status || ' (branch already ' || v_old_branch || ')',
                                'uploadid', v_uploadid,
                                'branch', v_old_branch,
                                'old_status', v_current_status,
                                'new_status', v_new_status,
                                'accountnumber', v_accountnumber,
                                'user_access', v_user_access_message
                            );
                        ELSE
                            v_success_count := v_success_count + 1;
                            
                            -- LOGGING: No change when branch same and status same
                            INSERT INTO LOG_instant_card_allocation (
                                cardnumber, operation_type,
                                from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                            ) VALUES (
                                v_cardnumber, 'UPDATE',
                                v_old_branch, p_branchcodetoallocate, v_current_status, v_current_status, v_username, p_userid
                            );
                            
                            v_card_results := v_card_results || jsonb_build_object(
                                'cardnumber', v_cardnumber,
                                'success', true,
                                'message', 'No changes required',
                                'no_change', true,
                                'current_branch', v_old_branch,
                                'current_status', v_current_status,
                                'user_access', v_user_access_message
                            );
                        END IF;
                        CONTINUE;
                    END IF;
                    
                    UPDATE public.instantcardstock
                    SET 
                        allocatedbranch = p_branchcodetoallocate,
                        status = v_new_status,
                        lastupdateddate = CURRENT_TIMESTAMP,
                        lastupdatedby = v_username  -- Use username instead of user ID
                    WHERE cardnumber = v_cardnumber
                    RETURNING uploadid INTO v_uploadid;
                    
                    GET DIAGNOSTICS v_row_count = ROW_COUNT;
                    
                    IF v_row_count = 1 THEN
                        v_success_count := v_success_count + 1;
                        
                        -- LOGGING: Branch allocation with status change
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'ALLOCATE',
                            v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Branch allocated to ' || p_branchcodetoallocate || ' with status ' || v_new_status,
                            'uploadid', v_uploadid,
                            'old_branch', v_old_branch,
                            'new_branch', p_branchcodetoallocate,
                            'old_status', v_current_status,
                            'new_status', v_new_status,
                            'accountnumber', v_accountnumber,
                            'user_access', v_user_access_message
                        );
                        
                        IF p_debuglevel >= 2 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD',
                                'BRANCH_ALLOCATED',
                                'Card allocated to branch ' || p_branchcodetoallocate || ' with status ' || v_new_status || ': ' || v_masked_cardnumber,
                                jsonb_build_object(
                                    'cardnumber', v_masked_cardnumber,
                                    'uploadid', v_uploadid,
                                    'old_branch', v_old_branch,
                                    'new_branch', p_branchcodetoallocate,
                                    'old_status', v_current_status,
                                    'new_status', v_new_status,
                                    'accountnumber', v_accountnumber,
                                    'user_id', p_userid,
                                    'username', v_username,
                                    'user_branch', v_user_branchcode,
                                    'crossbranch_access', v_user_crossbranch,
                                    'debuglevel', p_debuglevel
                                )
                            );
                        END IF;
							-- =====================================================
							-- Update instantcardcycle flags when status = 'ALLOCATED' Added by ST Feb-17-2026 for updating isallocated flag instantcardcycle
							-- =====================================================
							-- =====================================================
							IF v_new_status = 'ALLOCATED' AND v_uploadid IS NOT NULL THEN
							    BEGIN
							        -- Get the request details
							        SELECT 
							            booked_cards,
							            approved_cards,
							            bookedcardallocated,
							            approvedcardsallocated
							        INTO 
							            v_current_booked_cards,
							            v_current_approved_cards,
							            v_current_booked_allocated,
							            v_current_approved_allocated
							        FROM public.instantcardcycle
							        WHERE requestid = v_uploadid;
							        
							        -- DEBUG: Show the values retrieved
							        RAISE NOTICE '=== FLAG UPDATE DEBUG for Request: % ===', v_uploadid;
							        RAISE NOTICE 'booked_cards: %, approved_cards: %', v_current_booked_cards, v_current_approved_cards;
							        RAISE NOTICE 'bookedcardallocated: %, approvedcardsallocated: %', v_current_booked_allocated, v_current_approved_allocated;
							        RAISE NOTICE 'Total cards being allocated: %', v_total_cards;
							        
							        IF FOUND THEN
							            -- Check if the current allocation count matches booked_cards
							            IF v_current_booked_allocated = false 
							               AND v_current_booked_cards > 0 
							               AND v_total_cards = v_current_booked_cards THEN
							                
							                RAISE NOTICE 'CONDITION MET: Updating bookedcardallocated to TRUE for request %', v_uploadid;
							                
							                UPDATE public.instantcardcycle
							                SET bookedcardallocated = true
							                WHERE requestid = v_uploadid;
							                
							                v_flag_update_message := 'Booked flag updated for request ' || v_uploadid;
							                v_flag_updated := TRUE;
							                
							                RAISE NOTICE 'Booked flag updated successfully';
							            ELSE
							                RAISE NOTICE 'Booked flag condition NOT met:';
							                RAISE NOTICE '  - v_current_booked_allocated=false? %', (v_current_booked_allocated = false);
							                RAISE NOTICE '  - v_current_booked_cards>0? %', (v_current_booked_cards > 0);
							                RAISE NOTICE '  - v_total_cards=% = v_current_booked_cards=%? %', 
							                    v_total_cards, v_current_booked_cards, (v_total_cards = v_current_booked_cards);
							            END IF;
							            
							            -- Check if the current allocation count matches approved_cards
							            IF v_current_approved_allocated = false 
							               AND v_current_approved_cards > 0 
							               AND v_total_cards = v_current_approved_cards THEN
							                
							                RAISE NOTICE 'CONDITION MET: Updating approvedcardsallocated to TRUE for request %', v_uploadid;
							                
							                UPDATE public.instantcardcycle
							                SET approvedcardsallocated = true
							                WHERE requestid = v_uploadid;
							                
							                v_flag_update_message := v_flag_update_message || ' Approved flag updated for request ' || v_uploadid;
							                v_flag_updated := TRUE;
							                
							                RAISE NOTICE 'Approved flag updated successfully';
							            ELSE
							                RAISE NOTICE 'Approved flag condition NOT met:';
							                RAISE NOTICE '  - v_current_approved_allocated=false? %', (v_current_approved_allocated = false);
							                RAISE NOTICE '  - v_current_approved_cards>0? %', (v_current_approved_cards > 0);
							                RAISE NOTICE '  - v_total_cards=% = v_current_approved_cards=%? %', 
							                    v_total_cards, v_current_approved_cards, (v_total_cards = v_current_approved_cards);
							            END IF;
							        ELSE
							            RAISE NOTICE 'Request ID % not found in instantcardcycle table', v_uploadid;
							        END IF;
							        
							        RAISE NOTICE '=== END FLAG UPDATE DEBUG ===';
							        
							    EXCEPTION WHEN OTHERS THEN
							        RAISE NOTICE 'ERROR in flag update: %', SQLERRM;
							        PERFORM public.flog_audit_trail(
							            'INSTANT_CARD_CYCLE',
							            'FLAG_UPDATE_ERROR',
							            'Error: ' || SQLERRM,
							            jsonb_build_object('requestid', v_uploadid)
							        );
							    END;
							END IF;
                    ELSE
                        v_failed_count := v_failed_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'ALLOCATE',
                            v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Branch allocation failed - no rows affected',
                            'error_code', 'ALLOCATION_FAILED',
                            'user_access', v_user_access_message
                        );
                    END IF;
                    
                ELSE
                    -- No branch allocation, just status update
                    IF v_current_status = v_new_status THEN
                        v_success_count := v_success_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'UPDATE',
                            v_old_branch, v_old_branch, v_current_status, v_current_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Status already ' || v_new_status,
                            'no_change', true,
                            'current_branch', v_old_branch,
                            'current_status', v_current_status,
                            'user_access', v_user_access_message
                        );
                        CONTINUE;
                    END IF;
                    
                    UPDATE public.instantcardstock
                    SET 
                        status = v_new_status,
                        lastupdateddate = CURRENT_TIMESTAMP,
                        lastupdatedby = v_username  -- Use username instead of user ID
                    WHERE cardnumber = v_cardnumber
                    RETURNING uploadid INTO v_uploadid;
                    
                    GET DIAGNOSTICS v_row_count = ROW_COUNT;
                    
                    IF v_row_count = 1 THEN
                        v_success_count := v_success_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'STATUS_CHANGE',
                            v_old_branch, v_old_branch, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Status updated to ' || v_new_status,
                            'uploadid', v_uploadid,
                            'branch', v_old_branch,
                            'old_status', v_current_status,
                            'new_status', v_new_status,
                            'accountnumber', v_accountnumber,
                            'user_access', v_user_access_message
                        );
                        
                        IF p_debuglevel >= 2 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD',
                                'STATUS_UPDATED',
                                'Card status updated to ' || v_new_status || ': ' || v_masked_cardnumber,
                                jsonb_build_object(
                                    'cardnumber', v_masked_cardnumber,
                                    'uploadid', v_uploadid,
                                    'branch', v_old_branch,
                                    'old_status', v_current_status,
                                    'new_status', v_new_status,
                                    'accountnumber', v_accountnumber,
                                    'user_id', p_userid,
                                    'username', v_username,
                                    'user_branch', v_user_branchcode,
                                    'crossbranch_access', v_user_crossbranch,
                                    'debuglevel', p_debuglevel
                                )
                            );
                        END IF;
                    ELSE
                        v_failed_count := v_failed_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'STATUS_CHANGE',
                            v_old_branch, v_old_branch, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Status update failed - no rows affected',
                            'error_code', 'STATUS_UPDATE_FAILED',
                            'user_access', v_user_access_message
                        );
                    END IF;
                END IF;
                
            EXCEPTION WHEN OTHERS THEN
                v_failed_count := v_failed_count + 1;
                
                INSERT INTO LOG_instant_card_allocation (
                    cardnumber, operation_type,
                    from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                ) VALUES (
                    v_cardnumber, 
                    CASE 
                        WHEN p_branchcodetoallocate IS NOT NULL AND v_old_branch != p_branchcodetoallocate THEN 'ALLOCATE'
                        ELSE 'STATUS_CHANGE'
                    END,
                    v_old_branch, 
                    p_branchcodetoallocate, 
                    v_current_status, 
                    v_new_status, 
                    v_username, 
                    p_userid
                );
                
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'Error: ' || SQLERRM,
                    'error_code', SQLSTATE,
                    'user_access', v_user_access_message
                );
            END;
        END LOOP;
        
        v_execution_time := clock_timestamp() - v_start_time;
        v_action_message := format('UPDATE completed: %s successful, %s failed out of %s total', 
                                 v_success_count, v_failed_count, v_total_cards);
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'UPDATE_COMPLETED',
            v_action_message,
            jsonb_build_object(
                'action', 'UPDATE',
                'total_cards', v_total_cards,
                'successful', v_success_count,
                'failed', v_failed_count,
                'branch_allocated', p_branchcodetoallocate,
                'status_set', v_new_status,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'summary_message', v_action_message,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', v_success_count > 0,
            'message', v_action_message,
            'action', 'UPDATE',
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'branch', p_branchcodetoallocate,
                'status', v_new_status,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            ),
            'card_results', v_card_results
        );
    
    ELSIF p_action = 'DELETE' THEN
        -- DELETE section (simplified for brevity)
        -- Add similar branch access checks for DELETE
        FOR i IN 0..v_total_cards - 1 LOOP
            v_processed_count := v_processed_count + 1;
            v_cardnumber := p_cardnumbers->>i;
            
            IF v_cardnumber IS NULL OR v_cardnumber = '' THEN
                v_failed_count := v_failed_count + 1;
                CONTINUE;
            END IF;
            
            -- Get card branch info first
            SELECT allocatedbranch INTO v_old_branch 
            FROM public.instantcardstock 
            WHERE cardnumber = v_cardnumber;
            
            IF NOT FOUND THEN
                v_failed_count := v_failed_count + 1;
                CONTINUE;
            END IF;
            
            -- ADDED: Check if user has access to delete this card
            IF v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
               AND v_old_branch IS NOT NULL AND v_old_branch != v_user_branchcode THEN
                
                v_failed_count := v_failed_count + 1;
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'You do not have permission to delete this card. Card belongs to branch: ' || v_old_branch,
                    'error_code', 'CARD_ACCESS_DENIED',
                    'user_access', v_user_access_message,
                    'card_branch', v_old_branch,
                    'user_branch', v_user_branchcode
                );
                CONTINUE;
            END IF;
            
            -- Proceed with DELETE if user has access
            DELETE FROM public.instantcardstock 
            WHERE cardnumber = v_cardnumber;
            
            GET DIAGNOSTICS v_row_count = ROW_COUNT;
            
            IF v_row_count = 1 THEN
                v_success_count := v_success_count + 1;
                
                INSERT INTO LOG_instant_card_allocation (
                    cardnumber, operation_type,
                    from_branch, to_branch, performed_by, performed_by_userid
                ) VALUES (
                    v_cardnumber, 'DELETE',
                    v_old_branch, NULL, v_username, p_userid
                );
            ELSE
                v_failed_count := v_failed_count + 1;
            END IF;
        END LOOP;
        
        v_execution_time := clock_timestamp() - v_start_time;
        v_action_message := format('DELETE completed: %s successful, %s failed out of %s total', 
                                 v_success_count, v_failed_count, v_total_cards);
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'DELETE_COMPLETED',
            v_action_message,
            jsonb_build_object(
                'action', 'DELETE',
                'total_cards', v_total_cards,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'summary_message', v_action_message,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', v_success_count > 0,
            'message', v_action_message,
            'action', 'DELETE',
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            ),
            'card_results', v_card_results
        );
        
    ELSIF p_action = 'SEARCH' THEN
        v_search_result := '[]'::JSONB;
        
        -- If no card numbers provided, return cards with the specified status
        -- ADDED: Apply branch filtering based on user access
        IF v_total_cards = 0 THEN
            SELECT COALESCE(jsonb_agg(
                jsonb_build_object(
                    'cardnumber', cardnumber,
                    'uploadid', uploadid,
                    'bankcode', bankcode,
                    'allocatedbranch', allocatedbranch,
                    'requestbranch', requestbranch,
                    'status', status,
                    'embossedname', embossedname,
                    'accountnumber', accountnumber,
                    'expirydate', expirydate,
                    'opendingdate', opendingdate,
                    'createddate', createddate,
                    'lastupdateddate', lastupdateddate,
					'isgreenpin',isgreenpin
                )
                ORDER BY cardnumber asc
            ), '[]'::JSONB)
            INTO v_search_result
            FROM public.instantcardstock 
            WHERE CASE 
                -- When searching for PIN DISPATCH status, include multiple statuses
                WHEN v_status_to_use = 'PIN DISPATCH' THEN 
                    status IN ('ALLOCATED', 'CARD DISPATCH', 'CARD ACK')
                WHEN v_status_to_use = 'CARD DISPATCH' THEN 
                    status IN ('ALLOCATED', 'PIN DISPATCH', 'PIN ACK')
                WHEN v_status_to_use = 'PIN ACK' THEN 
                    status IN ('PIN DISPATCH', 'CARD ACK & PIN DISPATCH', 'CARD ACK')
                WHEN v_status_to_use = 'CARD ACK' THEN 
                    status IN ( 'CARD DISPATCH','CARD & PIN DISPATCH','CARD DISPATCH & PIN ACK')
                -- Otherwise use exact status match
                ELSE status = v_status_to_use
            END
            -- ADDED: Branch access filtering for SEARCH
            AND (
                v_user_crossbranch = TRUE  -- Users with cross-branch access see all
                OR allocatedbranch = v_user_branchcode  -- Others only see their branch
                OR (v_user_branchcode IS NULL AND allocatedbranch IS NULL)  -- Handle null cases
            );
            
            v_success_count := COALESCE(jsonb_array_length(v_search_result), 0);
            v_total_cards := v_success_count;
        ELSE
            -- Process specific card numbers with branch access check
            FOR i IN 0..v_total_cards - 1 LOOP
                v_cardnumber := p_cardnumbers->>i;
                
                IF v_cardnumber IS NOT NULL AND v_cardnumber != '' THEN
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'cardnumber', cardnumber,
                            'uploadid', uploadid,
                            'bankcode', bankcode,
                            'allocatedbranch', allocatedbranch,
                            'requestbranch', requestbranch,
                            'status', status,
                            'embossedname', embossedname,
                            'accountnumber', accountnumber,
                            'expirydate', expirydate,
                            'opendingdate', opendingdate,
                            'createddate', createddate,
                            'lastupdateddate', lastupdateddate
                        )
                    )
                    INTO v_card_data
                    FROM public.instantcardstock 
                    WHERE cardnumber = v_cardnumber
                    -- ADDED: Branch access filtering
                    AND (
                        v_user_crossbranch = TRUE
                        OR allocatedbranch = v_user_branchcode
                        OR (v_user_branchcode IS NULL AND allocatedbranch IS NULL)
                    );
                    
                    IF v_card_data IS NOT NULL THEN
                        v_search_result := v_search_result || v_card_data;
                        v_success_count := v_success_count + 1;
                    ELSE
                        v_failed_count := v_failed_count + 1;
                    END IF;
                END IF;
            END LOOP;
        END IF;
        
        IF p_debuglevel >= 1 THEN
            v_execution_time := clock_timestamp() - v_start_time;
            v_action_message := format('SEARCH completed: Found %s cards, %s not found', 
                                     v_success_count, v_failed_count);
            
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD',
                'SEARCH_COMPLETED',
                v_action_message,
                jsonb_build_object(
                    'action', 'SEARCH',
                    'total_cards', v_total_cards,
                    'found', v_success_count,
                    'not_found', v_failed_count,
                    'user_id', p_userid,
                    'username', v_username,
                    'user_branch', v_user_branchcode,
                    'crossbranch_access', v_user_crossbranch,
                    'status_filter', v_status_to_use,
                    'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                    'summary_message', v_action_message,
                    'debuglevel', p_debuglevel,
                    'search_criteria', CASE 
                        WHEN v_total_cards = 0 THEN format('ALL_CARDS_WITH_STATUS_%s', v_status_to_use)
                        ELSE format('SPECIFIC_CARDS(%s)', v_total_cards)
                    END
                )
            );
        END IF;
        
        v_execution_time := clock_timestamp() - v_start_time;
        RETURN jsonb_build_object(
            'success', true,
            'message', format('SEARCH completed: Found %s cards, %s not found', 
                            v_success_count, v_failed_count),
            'action', 'SEARCH',
            'summary', jsonb_build_object(
                'total_requested', v_total_cards,
                'found', v_success_count,
                'not_found', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status_filter', v_status_to_use,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            ),
            'cards', v_search_result
        );
    END IF;
    
EXCEPTION
    WHEN OTHERS THEN
        v_execution_time := clock_timestamp() - v_start_time;
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'FUNCTION_ERROR',
            'Function error: ' || SQLERRM,
            jsonb_build_object(
                'error_message', SQLERRM,
                'error_code', SQLSTATE,
                'action', p_action,
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status', v_status_to_use,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Function error: ' || SQLERRM,
            'error_code', SQLSTATE,
            'action', p_action,
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            )
        );
END;
$$;


ALTER FUNCTION public.finstantcardbranchallocation_feb172026_v1(p_action character varying, p_cardnumbers jsonb, p_userid integer, p_branchcodetoallocate character varying, p_debuglevel integer, p_status character varying) OWNER TO postgres;

--
-- TOC entry 432 (class 1255 OID 31992)
-- Name: finstantcardbranchallocation_feb172026v2(character varying, jsonb, integer, character varying, integer, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstantcardbranchallocation_feb172026v2(p_action character varying, p_cardnumbers jsonb, p_userid integer, p_branchcodetoallocate character varying DEFAULT NULL::character varying, p_debuglevel integer DEFAULT 0, p_status character varying DEFAULT 'AVAILABLE'::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_start_time TIMESTAMP := clock_timestamp();
    v_execution_time INTERVAL;
    v_result JSONB;
    v_final_result JSONB;
    v_audit_data JSONB;
    
    v_card_record JSONB;
    v_cardnumber VARCHAR(19);
    v_masked_cardnumber VARCHAR(19);
    v_old_branch VARCHAR(4);
    v_uploadid VARCHAR(12);
    v_accountnumber VARCHAR(20);
    v_current_status VARCHAR(25);
    v_embossedname VARCHAR(30);
    v_expirydate DATE;
    v_row_count INTEGER;
    v_previous_values JSONB;
    
    v_total_cards INTEGER;
    v_processed_count INTEGER := 0;
    v_success_count INTEGER := 0;
    v_failed_count INTEGER := 0;
    v_results_array JSONB := '[]'::JSONB;
    v_action_message TEXT;
    v_card_results JSONB := '[]'::JSONB;
    
    v_search_result JSONB;
    v_card_count INTEGER;
    v_card_data JSONB;
    
    v_status_to_use VARCHAR(25);
    v_action_detail VARCHAR(50);
    
    -- Variables for status composition
    v_new_status VARCHAR(25);
    v_status_parts VARCHAR(25)[];
    v_current_card_part VARCHAR(25);
    v_current_pin_part VARCHAR(25);
    
    -- Cross-branch access variables
    v_user_branchcode VARCHAR(10);
    v_user_instcode VARCHAR(4);
    v_user_crossbranch BOOLEAN := FALSE;
    v_user_branchname VARCHAR(100);
    v_username VARCHAR(30);
    v_user_branch_id INTEGER;
    v_user_access_message TEXT;
    v_current_booked_cards INTEGER;
    v_current_approved_cards INTEGER;
    v_current_booked_allocated BOOLEAN;
    v_current_approved_allocated BOOLEAN;
    v_flag_update_message TEXT := '';
    v_flag_updated BOOLEAN := FALSE;
BEGIN
    -- Debug level check for function start
    IF p_debuglevel > 3 THEN
        RAISE NOTICE '========================================';
        RAISE NOTICE 'FUNCTION STARTED at %', clock_timestamp();
        RAISE NOTICE 'Parameters:';
        RAISE NOTICE '  p_action: %', p_action;
        RAISE NOTICE '  p_cardnumbers: %', p_cardnumbers;
        RAISE NOTICE '  p_userid: %', p_userid;
        RAISE NOTICE '  p_branchcodetoallocate: %', p_branchcodetoallocate;
        RAISE NOTICE '  p_debuglevel: %', p_debuglevel;
        RAISE NOTICE '  p_status: %', p_status;
        RAISE NOTICE '========================================';
    END IF;
    
    PERFORM set_config('app.debuglevel', p_debuglevel::text, false);
    PERFORM set_config('app.session_id', 
        COALESCE(current_setting('app.session_id', true), 
                'card_' || p_action || '_' || extract(epoch from now())::text), 
        false);
    PERFORM set_config('app.user_agent', 
        COALESCE(current_setting('app.user_agent', true), 'card_system'), 
        false);
    
    -- Get user branch info for access control
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 1: Getting user branch info for user_id: %', p_userid;
    END IF;
    
    IF p_userid IS NOT NULL AND p_userid > 0 THEN
        -- Get user info with explicit handling - JOIN with branch table to get branch_no
        SELECT u.branchid,
               LEFT(u.institutionid::TEXT, 4),
               u.crossbranch,
               b.branch_no,
               b.branch_name,
               al.username
          INTO v_user_branch_id, v_user_instcode, v_user_crossbranch, 
               v_user_branchcode, v_user_branchname, v_username
        FROM users u
        LEFT JOIN branch b ON b.id = u.branchid
        LEFT JOIN authlogin al ON al.userid = u.id
        WHERE u.id = p_userid;
        
        -- If user not found, use defaults
        IF NOT FOUND THEN
            v_user_crossbranch := FALSE;
            v_user_branchcode := NULL;
            v_user_instcode := NULL;
            v_user_branchname := NULL;
            v_username := NULL;
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'User ID % not found in users table, using limited access', p_userid;
            END IF;
        ELSE
            -- Clean branch code (remove any whitespace)
            v_user_branchcode := TRIM(v_user_branchcode);
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'User found:';
                RAISE NOTICE '  username: %', v_username;
                RAISE NOTICE '  branchcode: %', v_user_branchcode;
                RAISE NOTICE '  branchname: %', v_user_branchname;
                RAISE NOTICE '  crossbranch: %', v_user_crossbranch;
            END IF;
            
            -- Validate branch code
            IF v_user_branchcode IS NULL OR v_user_branchcode = '' THEN
                RAISE EXCEPTION 'User % has NULL or empty branch code. Please update user branch information.', p_userid;
            END IF;
        END IF;
        
        -- Set access message for audit logging
        IF v_user_crossbranch = TRUE THEN
            v_user_access_message := 'Cross-branch access enabled';
        ELSE
            v_user_access_message := 'Limited to branch: ' || v_user_branchcode;
        END IF;
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'Access message: %', v_user_access_message;
        END IF;
        
    ELSE
        -- No user ID provided, use limited access
        v_user_crossbranch := FALSE;
        v_user_branchcode := NULL;
        v_username := NULL;
        v_user_access_message := 'No valid user ID provided - limited access';
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'No valid user ID provided, using limited access';
        END IF;
    END IF;
    
    -- Set status to use
    IF p_status IS NULL THEN
        v_status_to_use := 'AVAILABLE';
    ELSE
        v_status_to_use := p_status;
    END IF;
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Status to use: %', v_status_to_use;
    END IF;
    
    -- Validate JSON input
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 2: Validating JSON input';
    END IF;
    
    IF jsonb_typeof(p_cardnumbers) != 'array' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: cardnumbers is not a JSON array, it is: %', jsonb_typeof(p_cardnumbers);
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'cardnumbers parameter must be a JSON array',
            jsonb_build_object(
                'error_message', 'cardnumbers parameter must be a JSON array',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'received_type', jsonb_typeof(p_cardnumbers),
                'debuglevel', p_debuglevel,
                'status', v_status_to_use
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'cardnumbers parameter must be a JSON array',
            'error_code', 'INVALID_INPUT',
            'user_access', v_user_access_message
        );
    END IF;
    
    v_total_cards := jsonb_array_length(p_cardnumbers);
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Total cards in array: %', v_total_cards;
    END IF;
    
    -- Validate empty array for UPDATE/DELETE
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 3: Checking for empty array (action: %)', p_action;
    END IF;
    
    IF p_action IN ('UPDATE', 'DELETE') AND v_total_cards = 0 THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: Empty card numbers array for UPDATE/DELETE action';
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'Empty card numbers array provided',
            jsonb_build_object(
                'error_message', 'Empty card numbers array provided',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'total_cards', v_total_cards,
                'debuglevel', p_debuglevel,
                'status', v_status_to_use
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'No card numbers provided',
            'error_code', 'EMPTY_ARRAY',
            'user_access', v_user_access_message
        );
    END IF;
    
    -- Validate status
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 4: Validating status: %', v_status_to_use;
    END IF;
    
    IF v_status_to_use NOT IN ('AVAILABLE', 'ALLOCATED', 'ASSIGNED', 'ACTIVE', 'BLOCKED', 'NEW', 'IN_STOCK', 'EXPIRED', 'CLOSED',
                               'CARD DISPATCH', 'PIN DISPATCH', 'CARD & PIN DISPATCH', 
                               'CARD ACK', 'PIN ACK', 'CARD ACK & PIN DISPATCH',
                               'CARD DISPATCH & PIN ACK', 'CARD ACK & PIN ACK','BOOKED') THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: Invalid status: %', v_status_to_use;
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'Invalid status value: ' || v_status_to_use,
            jsonb_build_object(
                'error_message', 'Invalid status value',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'provided_status', v_status_to_use,
                'valid_statuses', ARRAY['AVAILABLE', 'ALLOCATED', 'ASSIGNED', 'ACTIVE', 'BLOCKED', 'NEW', 'IN_STOCK', 'EXPIRED', 'CLOSED',
                                       'CARD DISPATCH', 'PIN DISPATCH', 'CARD & PIN DISPATCH', 
                                       'CARD ACK', 'PIN ACK', 'CARD ACK & PIN DISPATCH',
                                       'CARD DISPATCH & PIN ACK', 'CARD ACK & PIN ACK','BOOKED'],
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid status.',
            'error_code', 'INVALID_STATUS',
            'user_access', v_user_access_message
        );
    END IF;
    
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Status validation passed';
    END IF;
    
    -- Debug logging if debuglevel >= 1
    IF p_debuglevel >= 1 THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'Step 5: Debug logging (debuglevel >= 1)';
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            p_action || '_START',
            'Starting ' || p_action || ' action for ' || v_total_cards || ' cards with status: ' || v_status_to_use,
            jsonb_build_object(
                'action', p_action,
                'total_cards', v_total_cards,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'user_access_level', v_user_access_message,
                'branch_to_allocate', p_branchcodetoallocate,
                'status_to_set', v_status_to_use,
                'debuglevel', p_debuglevel,
                'start_time', v_start_time,
                'client_ip', inet_client_addr()
            )
        );
    END IF;
    
    -- Validate action
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 6: Validating action: %', p_action;
    END IF;
    
    IF p_action NOT IN ('UPDATE', 'DELETE', 'SEARCH') THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: Invalid action: %', p_action;
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'INVALID_ACTION',
            'Invalid action requested: ' || p_action,
            jsonb_build_object(
                'error_message', 'Invalid action requested',
                'requested_action', p_action,
                'valid_actions', ARRAY['UPDATE', 'DELETE', 'SEARCH'],
                'total_cards', v_total_cards,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status', v_status_to_use,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid action. Must be UPDATE, DELETE, or SEARCH',
            'error_code', 'INVALID_ACTION',
            'user_access', v_user_access_message
        );
    END IF;
    
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Action validation passed';
    END IF;
    
    -- Validate branch access for UPDATE
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 7: Validating branch access for UPDATE action';
    END IF;
    
    IF p_action = 'UPDATE' AND p_branchcodetoallocate IS NOT NULL 
       AND v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
       AND p_branchcodetoallocate != v_user_branchcode THEN
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ACCESS DENIED: User cannot allocate to branch % (user branch: %)', 
                p_branchcodetoallocate, v_user_branchcode;
        END IF;
            
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'BRANCH_ACCESS_DENIED',
            'User cannot allocate to branch: ' || p_branchcodetoallocate,
            jsonb_build_object(
                'error_message', 'User does not have permission to allocate to this branch',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'target_branch', p_branchcodetoallocate,
                'crossbranch_access', v_user_crossbranch,
                'total_cards', v_total_cards,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'You do not have permission to allocate cards to branch: ' || p_branchcodetoallocate,
            'error_code', 'BRANCH_ACCESS_DENIED',
            'user_access', v_user_access_message,
            'user_branch', v_user_branchcode,
            'target_branch', p_branchcodetoallocate
        );
    END IF;
    
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Branch access validation passed';
    END IF;
    
    -- Main action handling
    IF p_action = 'UPDATE' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'PROCESSING UPDATE ACTION';
            RAISE NOTICE '========================================';
        END IF;
        
        -- Validate parameters for UPDATE
        IF p_branchcodetoallocate IS NULL AND v_status_to_use IS NULL THEN
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'ERROR: Neither branch nor status provided for UPDATE';
            END IF;
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD',
                'UPDATE_ERROR',
                'Either branch or status must be provided for UPDATE action',
                jsonb_build_object(
                    'error_message', 'Either branch or status must be provided for UPDATE action',
                    'action', p_action,
                    'total_cards', v_total_cards,
                    'user_id', p_userid,
                    'username', v_username,
                    'user_branch', v_user_branchcode,
                    'crossbranch_access', v_user_crossbranch,
                    'debuglevel', p_debuglevel
                )
            );
            
            RETURN jsonb_build_object(
                'success', false,
                'message', 'Either branch code or status must be provided for UPDATE action',
                'error_code', 'MISSING_PARAMETER',
                'user_access', v_user_access_message
            );
        END IF;
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'UPDATE parameters valid. Processing % cards', v_total_cards;
        END IF;
        
        -- Loop through each card
        FOR i IN 0..v_total_cards - 1 LOOP
            v_processed_count := v_processed_count + 1;
            v_cardnumber := p_cardnumbers->>i;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE '----------------------------------------';
                RAISE NOTICE 'Processing card % of % (Index: %)', i+1, v_total_cards, i;
                RAISE NOTICE 'Card number: %', v_cardnumber;
            END IF;
            
            IF v_cardnumber IS NULL OR v_cardnumber = '' THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Empty card number at index %', i;
                END IF;
                v_failed_count := v_failed_count + 1;
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'Empty card number',
                    'error_code', 'EMPTY_CARD_NUMBER',
                    'user_access', v_user_access_message
                );
                CONTINUE;
            END IF;
            
            -- Create masked version for audit trail only
            v_masked_cardnumber := 'XXXX-XXXX-XXXX-' || RIGHT(v_cardnumber, 4);
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Masked card number: %', v_masked_cardnumber;
            END IF;
            
            BEGIN
                -- Get card details from database
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Fetching card details from instantcardstock';
                END IF;
                
                SELECT 
                    allocatedbranch, 
                    uploadid, 
                    accountnumber, 
                    status,
                    embossedname,
                    expirydate
                INTO 
                    v_old_branch, 
                    v_uploadid, 
                    v_accountnumber, 
                    v_current_status,
                    v_embossedname,
                    v_expirydate
                FROM public.instantcardstock 
                WHERE cardnumber = v_cardnumber;
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Card details found:';
                    RAISE NOTICE '  allocatedbranch: %', v_old_branch;
                    RAISE NOTICE '  uploadid: %', v_uploadid;
                    RAISE NOTICE '  accountnumber: %', v_accountnumber;
                    RAISE NOTICE '  current status: %', v_current_status;
                    RAISE NOTICE '  embossedname: %', v_embossedname;
                END IF;
                
                IF v_uploadid IS NULL THEN
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'ERROR: Card not found in database';
                    END IF;
                    v_failed_count := v_failed_count + 1;
                    v_card_results := v_card_results || jsonb_build_object(
                        'cardnumber', v_cardnumber,
                        'success', false,
                        'message', 'Card not found',
                        'error_code', 'CARD_NOT_FOUND',
                        'user_access', v_user_access_message
                    );
                    CONTINUE;
                END IF;
                
                -- Check user access to modify this card
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Checking user access to modify card';
                END IF;
                
                IF v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
                   AND v_old_branch IS NOT NULL AND v_old_branch != v_user_branchcode THEN
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'ACCESS DENIED: Card belongs to branch %, user is from branch %', 
                            v_old_branch, v_user_branchcode;
                    END IF;
                        
                    v_failed_count := v_failed_count + 1;
                    v_card_results := v_card_results || jsonb_build_object(
                        'cardnumber', v_cardnumber,
                        'success', false,
                        'message', 'You do not have permission to modify this card. Card belongs to branch: ' || v_old_branch,
                        'error_code', 'CARD_ACCESS_DENIED',
                        'user_access', v_user_access_message,
                        'card_branch', v_old_branch,
                        'user_branch', v_user_branchcode
                    );
                    CONTINUE;
                END IF;
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Access granted';
                END IF;
                
                -- Initialize v_new_status with the requested status
                v_new_status := v_status_to_use;
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Requested new status: %', v_new_status;
                END IF;
                
                -- STATUS COMPOSITION LOGIC
                -- Only apply composition logic for card/PIN related statuses
                IF v_status_to_use IN ('CARD DISPATCH', 'PIN DISPATCH', 'CARD ACK', 'PIN ACK') THEN
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Applying status composition logic';
                        RAISE NOTICE 'Current status: %', v_current_status;
                    END IF;
                    
                    -- Check if current status is a combined status
                    IF v_current_status LIKE '%&%' THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Current status is combined status';
                        END IF;
                        -- Parse the current combined status
                        v_status_parts := string_to_array(v_current_status, ' & ');
                        
                        IF array_length(v_status_parts, 1) >= 1 THEN
                            v_current_card_part := TRIM(v_status_parts[1]);
                        END IF;
                        IF array_length(v_status_parts, 1) >= 2 THEN
                            v_current_pin_part := TRIM(v_status_parts[2]);
                        END IF;
                        
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Current card part: %, current pin part: %', 
                                v_current_card_part, v_current_pin_part;
                        END IF;
                        
                        -- Apply composition logic based on requested status
                        IF v_status_to_use = 'CARD DISPATCH' THEN
                            -- Update card part to CARD DISPATCH, keep existing pin part
                            IF v_current_pin_part IS NOT NULL THEN
                                v_new_status := 'CARD DISPATCH & ' || v_current_pin_part;
                            ELSE
                                v_new_status := 'CARD DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN DISPATCH' THEN
                            -- Update pin part to PIN DISPATCH, keep existing card part
                            IF v_current_card_part IS NOT NULL THEN
                                v_new_status := v_current_card_part || ' & PIN DISPATCH';
                            ELSE
                                v_new_status := 'PIN DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'CARD ACK' THEN
                            -- Update card part to CARD ACK, keep existing pin part
                            IF v_current_pin_part IS NOT NULL THEN
                                v_new_status := 'CARD ACK & ' || v_current_pin_part;
                            ELSE
                                v_new_status := 'CARD ACK';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN ACK' THEN
                            -- Update pin part to PIN ACK, keep existing card part
                            IF v_current_card_part IS NOT NULL THEN
                                v_new_status := v_current_card_part || ' & PIN ACK';
                            ELSE
                                v_new_status := 'PIN ACK';
                            END IF;
                        END IF;
                        
                    ELSE
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Current status is simple status';
                        END IF;
                        -- Current status is not combined, need to create combination if needed
                        IF v_status_to_use = 'CARD DISPATCH' THEN
                            IF v_current_status = 'PIN DISPATCH' THEN
                                -- PIN was dispatched first, now card dispatched
                                v_new_status := 'CARD & PIN DISPATCH';
                            ELSIF v_current_status = 'PIN ACK' THEN
                                -- PIN was acknowledged, now card dispatched
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSE
                                -- Starting fresh with card dispatch
                                v_new_status := 'CARD DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN DISPATCH' THEN
                            IF v_current_status = 'CARD DISPATCH' THEN
                                -- Card was dispatched first, now PIN dispatched
                                v_new_status := 'CARD & PIN DISPATCH';
                            ELSIF v_current_status = 'CARD ACK' THEN
                                -- Card was acknowledged, now PIN dispatched
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSE
                                -- Starting fresh with PIN dispatch
                                v_new_status := 'PIN DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'CARD ACK' THEN
                            IF v_current_status = 'CARD DISPATCH' THEN
                                -- Card was dispatched, now acknowledged
                                v_new_status := 'CARD ACK';
                            ELSIF v_current_status = 'CARD DISPATCH & PIN ACK' THEN
                                -- Card dispatched & PIN acked, now card acknowledged
                                v_new_status := 'CARD ACK & PIN ACK';
                            ELSIF v_current_status = 'CARD & PIN DISPATCH' THEN
                                -- Both dispatched, now card acknowledged
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSIF v_current_status = 'PIN DISPATCH' THEN
                                -- Only PIN dispatched, now card acknowledged (unusual)
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSE
                                -- Direct card acknowledgment
                                v_new_status := 'CARD ACK';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN ACK' THEN
                            IF v_current_status = 'PIN DISPATCH' THEN
                                -- PIN was dispatched, now acknowledged
                                v_new_status := 'PIN ACK';
                            ELSIF v_current_status = 'CARD ACK & PIN DISPATCH' THEN
                                -- Card acked & PIN dispatched, now PIN acknowledged
                                v_new_status := 'CARD ACK & PIN ACK';
                            ELSIF v_current_status = 'CARD & PIN DISPATCH' THEN
                                -- Both dispatched, now PIN acknowledged
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSIF v_current_status = 'CARD DISPATCH' THEN
                                -- Only card dispatched, now PIN acknowledged (unusual)
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSE
                                -- Direct PIN acknowledgment
                                v_new_status := 'PIN ACK';
                            END IF;
                        END IF;
                    END IF;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Composed new status: %', v_new_status;
                    END IF;
                END IF;
                -- END STATUS COMPOSITION LOGIC
                
                -- Now use v_new_status for the update   
                IF p_branchcodetoallocate IS NOT NULL THEN
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Branch allocation requested to: %', p_branchcodetoallocate;
                    END IF;
                    
                    -- Check if card can be allocated
                    IF v_current_status NOT IN ('AVAILABLE', 'NEW', 'IN_STOCK', 'ALLOCATED','BOOKED') THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'ERROR: Card status % does not allow allocation', v_current_status;
                        END IF;
                        v_failed_count := v_failed_count + 1;
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Card status does not allow branch allocation. Current: ' || v_current_status,
                            'error_code', 'INVALID_STATUS_FOR_BRANCH',
                            'current_status', v_current_status,
                            'user_access', v_user_access_message
                        );
                        CONTINUE;
                    END IF;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Current branch: %, Target branch: %', v_old_branch, p_branchcodetoallocate;
                    END IF;
                    
                    IF v_old_branch = p_branchcodetoallocate THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Branch already matches target branch';
                        END IF;
                        
                        IF v_current_status != v_new_status THEN
                            IF p_debuglevel > 3 THEN
                                RAISE NOTICE 'Updating status only (branch same)';
                            END IF;
                            
                            UPDATE public.instantcardstock
                            SET 
                                status = v_new_status,
                                lastupdateddate = CURRENT_TIMESTAMP,
                                lastupdatedby = v_username
                            WHERE cardnumber = v_cardnumber;
                            
                            GET DIAGNOSTICS v_row_count = ROW_COUNT;
                            v_success_count := v_success_count + 1;
                            
                            -- =====================================================
                            -- FLAG UPDATE - STATUS CHANGE WITH SAME BRANCH
                            -- =====================================================
                            IF v_new_status = 'ALLOCATED' AND v_uploadid IS NOT NULL AND v_row_count = 1 THEN
                                RAISE NOTICE 'Checking flag update condition: v_new_status=%, v_uploadid=%', v_new_status, v_uploadid;
                                
                                -- Get the request details
                                SELECT 
                                    booked_cards,
                                    approved_cards,
                                    bookedcardallocated,
                                    approvedcardsallocated
                                INTO 
                                    v_current_booked_cards,
                                    v_current_approved_cards,
                                    v_current_booked_allocated,
                                    v_current_approved_allocated
                                FROM public.instantcardcycle
                                WHERE requestid = v_uploadid;
                                RAISE NOTICE 'DEBUG - Request ID % found in instantcardcycle: %', v_uploadid, FOUND;
                                IF FOUND THEN
                                    -- Check if the current allocation count matches booked_cards
									 RAISE NOTICE 'DEBUG - booked_cards: %, approved_cards: %', v_current_booked_cards, v_current_approved_cards;
								    RAISE NOTICE 'DEBUG - v_total_cards: %, comparing to booked: %', v_total_cards, (v_total_cards = v_current_booked_cards);
								    RAISE NOTICE 'DEBUG - v_total_cards: %, comparing to approved: %', v_total_cards, (v_total_cards = v_current_approved_cards);
                                    IF v_current_booked_allocated = false 
                                       AND v_current_booked_cards > 0 
                                       AND v_total_cards = v_current_booked_cards THEN
                                        
                                        UPDATE public.instantcardcycle
                                        SET bookedcardallocated = true
                                        WHERE requestid = v_uploadid;
                                        
                                        v_flag_update_message := 'Booked flag updated for request ' || v_uploadid;
                                        v_flag_updated := TRUE;
                                    END IF;
                                    
                                    -- Check if the current allocation count matches approved_cards
                                    IF v_current_approved_allocated = false 
                                       AND v_current_approved_cards > 0 
                                       AND v_total_cards = v_current_approved_cards THEN
                                        
                                        UPDATE public.instantcardcycle
                                        SET approvedcardsallocated = true
                                        WHERE requestid = v_uploadid;
                                        
                                        v_flag_update_message := v_flag_update_message || ' Approved flag updated for request ' || v_uploadid;
                                        v_flag_updated := TRUE;
                                    END IF;
                                END IF;
                            END IF;
                            
                            -- LOGGING: Status change when branch already same
                            INSERT INTO LOG_instant_card_allocation (
                                cardnumber, operation_type,
                                from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                            ) VALUES (
                                v_cardnumber, 'STATUS_CHANGE',
                                v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                            );
                            
                            v_card_results := v_card_results || jsonb_build_object(
                                'cardnumber', v_cardnumber,
                                'success', true,
                                'message', 'Status updated to ' || v_new_status || ' (branch already ' || v_old_branch || ')',
                                'uploadid', v_uploadid,
                                'branch', v_old_branch,
                                'old_status', v_current_status,
                                'new_status', v_new_status,
                                'accountnumber', v_accountnumber,
                                'user_access', v_user_access_message,
                                'flag_updated', v_flag_updated,
                                'flag_message', v_flag_update_message
                            );
                            
                            IF p_debuglevel > 3 THEN
                                RAISE NOTICE 'Status update successful';
                            END IF;
                        ELSE
                            IF p_debuglevel > 3 THEN
                                RAISE NOTICE 'No changes required (branch and status same)';
                            END IF;
                            
                            v_success_count := v_success_count + 1;
                            
                            -- LOGGING: No change when branch same and status same
                            INSERT INTO LOG_instant_card_allocation (
                                cardnumber, operation_type,
                                from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                            ) VALUES (
                                v_cardnumber, 'UPDATE',
                                v_old_branch, p_branchcodetoallocate, v_current_status, v_current_status, v_username, p_userid
                            );
                            
                            v_card_results := v_card_results || jsonb_build_object(
                                'cardnumber', v_cardnumber,
                                'success', true,
                                'message', 'No changes required',
                                'no_change', true,
                                'current_branch', v_old_branch,
                                'current_status', v_current_status,
                                'user_access', v_user_access_message
                            );
                        END IF;
                        CONTINUE;
                    END IF;
                    
                    -- Perform the actual allocation
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Allocating card to new branch: %', p_branchcodetoallocate;
                    END IF;
                    
                    UPDATE public.instantcardstock
                    SET 
                        allocatedbranch = p_branchcodetoallocate,
                        status = v_new_status,
                        lastupdateddate = CURRENT_TIMESTAMP,
                        lastupdatedby = v_username
                    WHERE cardnumber = v_cardnumber
                    RETURNING uploadid INTO v_uploadid;
                    
                    GET DIAGNOSTICS v_row_count = ROW_COUNT;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Rows affected: %', v_row_count;
                    END IF;
                    
                    IF v_row_count = 1 THEN
                        v_success_count := v_success_count + 1;
                        
                        -- =====================================================
                        -- FLAG UPDATE - BRANCH ALLOCATION
                        -- =====================================================
                        IF v_new_status = 'ALLOCATED' AND v_uploadid IS NOT NULL THEN
                            RAISE NOTICE 'Checking flag update condition: v_new_status=%, v_uploadid=%', v_new_status, v_uploadid;
                            
                            -- Get the request details
                            SELECT 
                                booked_cards,
                                approved_cards,
                                bookedcardallocated,
                                approvedcardsallocated
                            INTO 
                                v_current_booked_cards,
                                v_current_approved_cards,
                                v_current_booked_allocated,
                                v_current_approved_allocated
                            FROM public.instantcardcycle
                            WHERE requestid = v_uploadid;
                            
                            IF FOUND THEN
                                -- Check if the current allocation count matches booked_cards
                                IF v_current_booked_allocated = false 
                                   AND v_current_booked_cards > 0 
                                   AND v_total_cards = v_current_booked_cards THEN
                                    
                                    UPDATE public.instantcardcycle
                                    SET bookedcardallocated = true
                                    WHERE requestid = v_uploadid;
                                    
                                    v_flag_update_message := 'Booked flag updated for request ' || v_uploadid;
                                    v_flag_updated := TRUE;
                                END IF;
                                
                                -- Check if the current allocation count matches approved_cards
                                IF v_current_approved_allocated = false 
                                   AND v_current_approved_cards > 0 
                                   AND v_total_cards = v_current_approved_cards THEN
                                    
                                    UPDATE public.instantcardcycle
                                    SET approvedcardsallocated = true
                                    WHERE requestid = v_uploadid;
                                    
                                    v_flag_update_message := v_flag_update_message || ' Approved flag updated for request ' || v_uploadid;
                                    v_flag_updated := TRUE;
                                END IF;
                            END IF;
                        END IF;
                        
                        -- LOGGING: Branch allocation with status change
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'ALLOCATE',
                            v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Branch allocated to ' || p_branchcodetoallocate || ' with status ' || v_new_status,
                            'uploadid', v_uploadid,
                            'old_branch', v_old_branch,
                            'new_branch', p_branchcodetoallocate,
                            'old_status', v_current_status,
                            'new_status', v_new_status,
                            'accountnumber', v_accountnumber,
                            'user_access', v_user_access_message,
                            'flag_updated', v_flag_updated,
                            'flag_message', v_flag_update_message
                        );
                        
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Allocation successful';
                        END IF;
                        
                        IF p_debuglevel >= 2 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD',
                                'BRANCH_ALLOCATED',
                                'Card allocated to branch ' || p_branchcodetoallocate || ' with status ' || v_new_status || ': ' || v_masked_cardnumber,
                                jsonb_build_object(
                                    'cardnumber', v_masked_cardnumber,
                                    'uploadid', v_uploadid,
                                    'old_branch', v_old_branch,
                                    'new_branch', p_branchcodetoallocate,
                                    'old_status', v_current_status,
                                    'new_status', v_new_status,
                                    'accountnumber', v_accountnumber,
                                    'user_id', p_userid,
                                    'username', v_username,
                                    'user_branch', v_user_branchcode,
                                    'crossbranch_access', v_user_crossbranch,
                                    'debuglevel', p_debuglevel
                                )
                            );
                        END IF;
                        
                    ELSE
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'ERROR: Allocation failed - no rows affected';
                        END IF;
                        
                        v_failed_count := v_failed_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'ALLOCATE',
                            v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Branch allocation failed - no rows affected',
                            'error_code', 'ALLOCATION_FAILED',
                            'user_access', v_user_access_message
                        );
                    END IF;
                    
                ELSE
                    -- No branch allocation, just status update
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'No branch allocation - just status update to: %', v_new_status;
                    END IF;
                    
                    IF v_current_status = v_new_status THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Status already set to % - no change needed', v_new_status;
                        END IF;
                        
                        v_success_count := v_success_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'UPDATE',
                            v_old_branch, v_old_branch, v_current_status, v_current_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Status already ' || v_new_status,
                            'no_change', true,
                            'current_branch', v_old_branch,
                            'current_status', v_current_status,
                            'user_access', v_user_access_message
                        );
                        CONTINUE;
                    END IF;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Updating status from % to %', v_current_status, v_new_status;
                    END IF;
                    
                    UPDATE public.instantcardstock
                    SET 
                        status = v_new_status,
                        lastupdateddate = CURRENT_TIMESTAMP,
                        lastupdatedby = v_username
                    WHERE cardnumber = v_cardnumber
                    RETURNING uploadid INTO v_uploadid;
                    
                    GET DIAGNOSTICS v_row_count = ROW_COUNT;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Rows affected: %', v_row_count;
                    END IF;
                    
                    IF v_row_count = 1 THEN
                        v_success_count := v_success_count + 1;
                        
                        -- =====================================================
                        -- FLAG UPDATE - STATUS ONLY CHANGE
                        -- =====================================================
                        IF v_new_status = 'ALLOCATED' AND v_uploadid IS NOT NULL THEN
                            RAISE NOTICE 'Checking flag update condition: v_new_status=%, v_uploadid=%', v_new_status, v_uploadid;
                            
                            -- Get the request details
                            SELECT 
                                booked_cards,
                                approved_cards,
                                bookedcardallocated,
                                approvedcardsallocated
                            INTO 
                                v_current_booked_cards,
                                v_current_approved_cards,
                                v_current_booked_allocated,
                                v_current_approved_allocated
                            FROM public.instantcardcycle
                            WHERE requestid = v_uploadid;
                            
                            IF FOUND THEN
                                -- Check if the current allocation count matches booked_cards
                                IF v_current_booked_allocated = false 
                                   AND v_current_booked_cards > 0 
                                   AND v_total_cards = v_current_booked_cards THEN
                                    
                                    UPDATE public.instantcardcycle
                                    SET bookedcardallocated = true
                                    WHERE requestid = v_uploadid;
                                    
                                    v_flag_update_message := 'Booked flag updated for request ' || v_uploadid;
                                    v_flag_updated := TRUE;
                                END IF;
                                
                                -- Check if the current allocation count matches approved_cards
                                IF v_current_approved_allocated = false 
                                   AND v_current_approved_cards > 0 
                                   AND v_total_cards = v_current_approved_cards THEN
                                    
                                    UPDATE public.instantcardcycle
                                    SET approvedcardsallocated = true
                                    WHERE requestid = v_uploadid;
                                    
                                    v_flag_update_message := v_flag_update_message || ' Approved flag updated for request ' || v_uploadid;
                                    v_flag_updated := TRUE;
                                END IF;
                            END IF;
                        END IF;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'STATUS_CHANGE',
                            v_old_branch, v_old_branch, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Status updated to ' || v_new_status,
                            'uploadid', v_uploadid,
                            'branch', v_old_branch,
                            'old_status', v_current_status,
                            'new_status', v_new_status,
                            'accountnumber', v_accountnumber,
                            'user_access', v_user_access_message,
                            'flag_updated', v_flag_updated,
                            'flag_message', v_flag_update_message
                        );
                        
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Status update successful';
                        END IF;
                        
                        IF p_debuglevel >= 2 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD',
                                'STATUS_UPDATED',
                                'Card status updated to ' || v_new_status || ': ' || v_masked_cardnumber,
                                jsonb_build_object(
                                    'cardnumber', v_masked_cardnumber,
                                    'uploadid', v_uploadid,
                                    'branch', v_old_branch,
                                    'old_status', v_current_status,
                                    'new_status', v_new_status,
                                    'accountnumber', v_accountnumber,
                                    'user_id', p_userid,
                                    'username', v_username,
                                    'user_branch', v_user_branchcode,
                                    'crossbranch_access', v_user_crossbranch,
                                    'debuglevel', p_debuglevel
                                )
                            );
                        END IF;
                    ELSE
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'ERROR: Status update failed - no rows affected';
                        END IF;
                        
                        v_failed_count := v_failed_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'STATUS_CHANGE',
                            v_old_branch, v_old_branch, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Status update failed - no rows affected',
                            'error_code', 'STATUS_UPDATE_FAILED',
                            'user_access', v_user_access_message
                        );
                    END IF;
                END IF;
                  
            EXCEPTION WHEN OTHERS THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'EXCEPTION CAUGHT: %', SQLERRM;
                    RAISE NOTICE 'SQLSTATE: %', SQLSTATE;
                END IF;
                
                v_failed_count := v_failed_count + 1;
                
                INSERT INTO LOG_instant_card_allocation (
                    cardnumber, operation_type,
                    from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                ) VALUES (
                    v_cardnumber, 
                    CASE 
                        WHEN p_branchcodetoallocate IS NOT NULL AND v_old_branch != p_branchcodetoallocate THEN 'ALLOCATE'
                        ELSE 'STATUS_CHANGE'
                    END,
                    v_old_branch, 
                    p_branchcodetoallocate, 
                    v_current_status, 
                    v_new_status, 
                    v_username, 
                    p_userid
                );
                
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'Error: ' || SQLERRM,
                    'error_code', SQLSTATE,
                    'user_access', v_user_access_message
                );
            END;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Card processing complete. Success: %, Failed: %', v_success_count, v_failed_count;
            END IF;
        END LOOP;
        
        v_execution_time := clock_timestamp() - v_start_time;
        v_action_message := format('UPDATE completed: %s successful, %s failed out of %s total', 
                                 v_success_count, v_failed_count, v_total_cards);
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'UPDATE SUMMARY:';
            RAISE NOTICE '  Total cards: %', v_total_cards;
            RAISE NOTICE '  Processed: %', v_processed_count;
            RAISE NOTICE '  Successful: %', v_success_count;
            RAISE NOTICE '  Failed: %', v_failed_count;
            RAISE NOTICE '  Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '  Flag updated: %', v_flag_updated;
            RAISE NOTICE '  Flag message: %', v_flag_update_message;
            RAISE NOTICE '========================================';
        END IF;
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'UPDATE_COMPLETED',
            v_action_message,
            jsonb_build_object(
                'action', 'UPDATE',
                'total_cards', v_total_cards,
                'successful', v_success_count,
                'failed', v_failed_count,
                'branch_allocated', p_branchcodetoallocate,
                'status_set', v_new_status,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'summary_message', v_action_message,
                'debuglevel', p_debuglevel,
                'flag_updated', v_flag_updated,
                'flag_message', v_flag_update_message
            )
        );
        
        RETURN jsonb_build_object(
            'success', v_success_count > 0,
            'message', v_action_message,
            'action', 'UPDATE',
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'branch', p_branchcodetoallocate,
                'status', v_new_status,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'flag_updated', v_flag_updated,
                'flag_message', v_flag_update_message
            ),
            'card_results', v_card_results
        );
    
    ELSIF p_action = 'DELETE' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'PROCESSING DELETE ACTION';
            RAISE NOTICE '========================================';
        END IF;
        
        -- DELETE section (with debug notices)
        FOR i IN 0..v_total_cards - 1 LOOP
            v_processed_count := v_processed_count + 1;
            v_cardnumber := p_cardnumbers->>i;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Processing card % of % for DELETE', i+1, v_total_cards;
                RAISE NOTICE 'Card number: %', v_cardnumber;
            END IF;
            
            IF v_cardnumber IS NULL OR v_cardnumber = '' THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Empty card number';
                END IF;
                v_failed_count := v_failed_count + 1;
                CONTINUE;
            END IF;
            
            -- Get card branch info first
            SELECT allocatedbranch INTO v_old_branch 
            FROM public.instantcardstock 
            WHERE cardnumber = v_cardnumber;
            
            IF NOT FOUND THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Card not found';
                END IF;
                v_failed_count := v_failed_count + 1;
                CONTINUE;
            END IF;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Card found in branch: %', v_old_branch;
            END IF;
            
            -- Check if user has access to delete this card
            IF v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
               AND v_old_branch IS NOT NULL AND v_old_branch != v_user_branchcode THEN
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ACCESS DENIED: Card belongs to branch %, user is from branch %', 
                        v_old_branch, v_user_branchcode;
                END IF;
                    
                v_failed_count := v_failed_count + 1;
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'You do not have permission to delete this card. Card belongs to branch: ' || v_old_branch,
                    'error_code', 'CARD_ACCESS_DENIED',
                    'user_access', v_user_access_message,
                    'card_branch', v_old_branch,
                    'user_branch', v_user_branchcode
                );
                CONTINUE;
            END IF;
            
            -- Proceed with DELETE if user has access
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Deleting card';
            END IF;
            
            DELETE FROM public.instantcardstock 
            WHERE cardnumber = v_cardnumber;
            
            GET DIAGNOSTICS v_row_count = ROW_COUNT;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Rows affected: %', v_row_count;
            END IF;
            
            IF v_row_count = 1 THEN
                v_success_count := v_success_count + 1;
                
                INSERT INTO LOG_instant_card_allocation (
                    cardnumber, operation_type,
                    from_branch, to_branch, performed_by, performed_by_userid
                ) VALUES (
                    v_cardnumber, 'DELETE',
                    v_old_branch, NULL, v_username, p_userid
                );
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Delete successful';
                END IF;
            ELSE
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Delete failed';
                END IF;
                v_failed_count := v_failed_count + 1;
            END IF;
        END LOOP;
        
        v_execution_time := clock_timestamp() - v_start_time;
        v_action_message := format('DELETE completed: %s successful, %s failed out of %s total', 
                                 v_success_count, v_failed_count, v_total_cards);
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'DELETE SUMMARY:';
            RAISE NOTICE '  Total cards: %', v_total_cards;
            RAISE NOTICE '  Processed: %', v_processed_count;
            RAISE NOTICE '  Successful: %', v_success_count;
            RAISE NOTICE '  Failed: %', v_failed_count;
            RAISE NOTICE '  Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '========================================';
        END IF;
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'DELETE_COMPLETED',
            v_action_message,
            jsonb_build_object(
                'action', 'DELETE',
                'total_cards', v_total_cards,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'summary_message', v_action_message,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', v_success_count > 0,
            'message', v_action_message,
            'action', 'DELETE',
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            ),
            'card_results', v_card_results
        );
        
    ELSIF p_action = 'SEARCH' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'PROCESSING SEARCH ACTION';
            RAISE NOTICE '========================================';
        END IF;
        
        v_search_result := '[]'::JSONB;
        
        -- If no card numbers provided, return cards with the specified status
        IF v_total_cards = 0 THEN
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Searching for all cards with status: %', v_status_to_use;
                RAISE NOTICE 'Branch filter: user_branch=%, crossbranch=%', 
                    v_user_branchcode, v_user_crossbranch;
            END IF;
            
            SELECT COALESCE(jsonb_agg(
                jsonb_build_object(
                    'cardnumber', cardnumber,
                    'uploadid', uploadid,
                    'bankcode', bankcode,
                    'allocatedbranch', allocatedbranch,
                    'requestbranch', requestbranch,
                    'status', status,
                    'embossedname', embossedname,
                    'accountnumber', accountnumber,
                    'expirydate', expirydate,
                    'opendingdate', opendingdate,
                    'createddate', createddate,
                    'lastupdateddate', lastupdateddate,
                    'isgreenpin',isgreenpin
                )
                ORDER BY cardnumber asc
            ), '[]'::JSONB)
            INTO v_search_result
            FROM public.instantcardstock 
            WHERE CASE 
                -- When searching for PIN DISPATCH status, include multiple statuses
                WHEN v_status_to_use = 'PIN DISPATCH' THEN 
                    status IN ('ALLOCATED', 'CARD DISPATCH', 'CARD ACK')
                WHEN v_status_to_use = 'CARD DISPATCH' THEN 
                    status IN ('ALLOCATED', 'PIN DISPATCH', 'PIN ACK')
                WHEN v_status_to_use = 'PIN ACK' THEN 
                    status IN ('PIN DISPATCH', 'CARD ACK & PIN DISPATCH', 'CARD ACK')
                WHEN v_status_to_use = 'CARD ACK' THEN 
                    status IN ( 'CARD DISPATCH','CARD & PIN DISPATCH','CARD DISPATCH & PIN ACK')
                -- Otherwise use exact status match
                ELSE status = v_status_to_use
            END
            -- Branch access filtering for SEARCH
            AND (
                v_user_crossbranch = TRUE
                OR allocatedbranch = v_user_branchcode
                OR (v_user_branchcode IS NULL AND allocatedbranch IS NULL)
            );
            
            v_success_count := COALESCE(jsonb_array_length(v_search_result), 0);
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Found % cards matching criteria', v_success_count;
            END IF;
            
        ELSE
            -- Process specific card numbers with branch access check
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Searching for % specific card numbers', v_total_cards;
            END IF;
            
            FOR i IN 0..v_total_cards - 1 LOOP
                v_cardnumber := p_cardnumbers->>i;
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Searching for card: %', v_cardnumber;
                END IF;
                
                IF v_cardnumber IS NOT NULL AND v_cardnumber != '' THEN
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'cardnumber', cardnumber,
                            'uploadid', uploadid,
                            'bankcode', bankcode,
                            'allocatedbranch', allocatedbranch,
                            'requestbranch', requestbranch,
                            'status', status,
                            'embossedname', embossedname,
                            'accountnumber', accountnumber,
                            'expirydate', expirydate,
                            'opendingdate', opendingdate,
                            'createddate', createddate,
                            'lastupdateddate', lastupdateddate
                        )
                    )
                    INTO v_card_data
                    FROM public.instantcardstock 
                    WHERE cardnumber = v_cardnumber
                    AND (
                        v_user_crossbranch = TRUE
                        OR allocatedbranch = v_user_branchcode
                        OR (v_user_branchcode IS NULL AND allocatedbranch IS NULL)
                    );
                    
                    IF v_card_data IS NOT NULL THEN
                        v_search_result := v_search_result || v_card_data;
                        v_success_count := v_success_count + 1;
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Card found';
                        END IF;
                    ELSE
                        v_failed_count := v_failed_count + 1;
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Card not found or access denied';
                        END IF;
                    END IF;
                END IF;
            END LOOP;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Search complete. Found: %, Not found: %', 
                    v_success_count, v_failed_count;
            END IF;
        END IF;
        
        IF p_debuglevel >= 1 THEN
            v_execution_time := clock_timestamp() - v_start_time;
            v_action_message := format('SEARCH completed: Found %s cards, %s not found', 
                                     v_success_count, v_failed_count);
            
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD',
                'SEARCH_COMPLETED',
                v_action_message,
                jsonb_build_object(
                    'action', 'SEARCH',
                    'total_cards', v_total_cards,
                    'found', v_success_count,
                    'not_found', v_failed_count,
                    'user_id', p_userid,
                    'username', v_username,
                    'user_branch', v_user_branchcode,
                    'crossbranch_access', v_user_crossbranch,
                    'status_filter', v_status_to_use,
                    'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                    'summary_message', v_action_message,
                    'debuglevel', p_debuglevel,
                    'search_criteria', CASE 
                        WHEN v_total_cards = 0 THEN format('ALL_CARDS_WITH_STATUS_%s', v_status_to_use)
                        ELSE format('SPECIFIC_CARDS(%s)', v_total_cards)
                    END
                )
            );
        END IF;
        
        v_execution_time := clock_timestamp() - v_start_time;
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'SEARCH SUMMARY:';
            RAISE NOTICE '  Total requested: %', v_total_cards;
            RAISE NOTICE '  Found: %', v_success_count;
            RAISE NOTICE '  Not found: %', v_failed_count;
            RAISE NOTICE '  Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '========================================';
        END IF;
        
        RETURN jsonb_build_object(
            'success', true,
            'message', format('SEARCH completed: Found %s cards, %s not found', 
                            v_success_count, v_failed_count),
            'action', 'SEARCH',
            'summary', jsonb_build_object(
                'total_requested', v_total_cards,
                'found', v_success_count,
                'not_found', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status_filter', v_status_to_use,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            ),
            'cards', v_search_result
        );
    END IF;
    
EXCEPTION
    WHEN OTHERS THEN
        v_execution_time := clock_timestamp() - v_start_time;
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'FATAL ERROR IN FUNCTION';
            RAISE NOTICE 'Error message: %', SQLERRM;
            RAISE NOTICE 'SQLSTATE: %', SQLSTATE;
            RAISE NOTICE 'Action: %', p_action;
            RAISE NOTICE 'Total cards: %', v_total_cards;
            RAISE NOTICE 'Processed: %', v_processed_count;
            RAISE NOTICE 'Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '========================================';
        END IF;
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'FUNCTION_ERROR',
            'Function error: ' || SQLERRM,
            jsonb_build_object(
                'error_message', SQLERRM,
                'error_code', SQLSTATE,
                'action', p_action,
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status', v_status_to_use,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Function error: ' || SQLERRM,
            'error_code', SQLSTATE,
            'action', p_action,
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            )
        );
END;
$$;


ALTER FUNCTION public.finstantcardbranchallocation_feb172026v2(p_action character varying, p_cardnumbers jsonb, p_userid integer, p_branchcodetoallocate character varying, p_debuglevel integer, p_status character varying) OWNER TO postgres;

--
-- TOC entry 361 (class 1255 OID 32199)
-- Name: finstantcardbranchallocation_feb242026v3(character varying, jsonb, integer, character varying, integer, character varying, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstantcardbranchallocation_feb242026v3(p_action character varying, p_cardnumbers jsonb, p_userid integer, p_branchcodetoallocate character varying DEFAULT NULL::character varying, p_debuglevel integer DEFAULT 0, p_status character varying DEFAULT 'AVAILABLE'::character varying, p_requestid character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_start_time TIMESTAMP := clock_timestamp();
    v_execution_time INTERVAL;
    v_result JSONB;
    v_final_result JSONB;
    v_audit_data JSONB;
    
    v_card_record JSONB;
    v_cardnumber VARCHAR(19);
    v_masked_cardnumber VARCHAR(19);
    v_old_branch VARCHAR(4);
    v_uploadid VARCHAR(12);
    v_accountnumber VARCHAR(20);
    v_current_status VARCHAR(25);
    v_embossedname VARCHAR(30);
    v_expirydate DATE;
    v_row_count INTEGER;
    v_previous_values JSONB;
    
    v_total_cards INTEGER;
    v_processed_count INTEGER := 0;
    v_success_count INTEGER := 0;
    v_failed_count INTEGER := 0;
    v_results_array JSONB := '[]'::JSONB;
    v_action_message TEXT;
    v_card_results JSONB := '[]'::JSONB;
    
    v_search_result JSONB;
    v_card_count INTEGER;
    v_card_data JSONB;
    
    v_status_to_use VARCHAR(25);
    v_action_detail VARCHAR(50);
    
    -- Variables for status composition
    v_new_status VARCHAR(25);
    v_status_parts VARCHAR(25)[];
    v_current_card_part VARCHAR(25);
    v_current_pin_part VARCHAR(25);
    
    -- Cross-branch access variables
    v_user_branchcode VARCHAR(10);
    v_user_instcode VARCHAR(4);
    v_user_crossbranch BOOLEAN := FALSE;
    v_user_branchname VARCHAR(100);
    v_username VARCHAR(30);
    v_user_branch_id INTEGER;
    v_user_access_message TEXT;
    v_current_booked_cards INTEGER;
    v_current_approved_cards INTEGER;
    v_current_booked_allocated BOOLEAN;
    v_current_approved_allocated BOOLEAN;
    v_flag_update_message TEXT := '';
    v_flag_updated BOOLEAN := FALSE;
BEGIN
    -- Debug level check for function start
    IF p_debuglevel > 3 THEN
        RAISE NOTICE '========================================';
        RAISE NOTICE 'FUNCTION STARTED at %', clock_timestamp();
        RAISE NOTICE 'Parameters:';
        RAISE NOTICE '  p_action: %', p_action;
        RAISE NOTICE '  p_cardnumbers: %', p_cardnumbers;
        RAISE NOTICE '  p_userid: %', p_userid;
        RAISE NOTICE '  p_branchcodetoallocate: %', p_branchcodetoallocate;
        RAISE NOTICE '  p_debuglevel: %', p_debuglevel;
        RAISE NOTICE '  p_status: %', p_status;
        RAISE NOTICE '  p_requestid: %', p_requestid;
        RAISE NOTICE '========================================';
    END IF;
    
    PERFORM set_config('app.debuglevel', p_debuglevel::text, false);
    PERFORM set_config('app.session_id', 
        COALESCE(current_setting('app.session_id', true), 
                'card_' || p_action || '_' || extract(epoch from now())::text), 
        false);
    PERFORM set_config('app.user_agent', 
        COALESCE(current_setting('app.user_agent', true), 'card_system'), 
        false);
    
    -- Get user branch info for access control
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 1: Getting user branch info for user_id: %', p_userid;
    END IF;
    
    IF p_userid IS NOT NULL AND p_userid > 0 THEN
        -- Get user info with explicit handling - JOIN with branch table to get branch_no
        SELECT u.branchid,
               LEFT(u.institutionid::TEXT, 4),
               u.crossbranch,
               b.branch_no,
               b.branch_name,
               al.username
          INTO v_user_branch_id, v_user_instcode, v_user_crossbranch, 
               v_user_branchcode, v_user_branchname, v_username
        FROM users u
        LEFT JOIN branch b ON b.id = u.branchid
        LEFT JOIN authlogin al ON al.userid = u.id
        WHERE u.id = p_userid;
        
        -- If user not found, use defaults
        IF NOT FOUND THEN
            v_user_crossbranch := FALSE;
            v_user_branchcode := NULL;
            v_user_instcode := NULL;
            v_user_branchname := NULL;
            v_username := NULL;
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'User ID % not found in users table, using limited access', p_userid;
            END IF;
        ELSE
            -- Clean branch code (remove any whitespace)
            v_user_branchcode := TRIM(v_user_branchcode);
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'User found:';
                RAISE NOTICE '  username: %', v_username;
                RAISE NOTICE '  branchcode: %', v_user_branchcode;
                RAISE NOTICE '  branchname: %', v_user_branchname;
                RAISE NOTICE '  crossbranch: %', v_user_crossbranch;
            END IF;
            
            -- Validate branch code
            IF v_user_branchcode IS NULL OR v_user_branchcode = '' THEN
                RAISE EXCEPTION 'User % has NULL or empty branch code. Please update user branch information.', p_userid;
            END IF;
        END IF;
        
        -- Set access message for audit logging
        IF v_user_crossbranch = TRUE THEN
            v_user_access_message := 'Cross-branch access enabled';
        ELSE
            v_user_access_message := 'Limited to branch: ' || v_user_branchcode;
        END IF;
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'Access message: %', v_user_access_message;
        END IF;
        
    ELSE
        -- No user ID provided, use limited access
        v_user_crossbranch := FALSE;
        v_user_branchcode := NULL;
        v_username := NULL;
        v_user_access_message := 'No valid user ID provided - limited access';
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'No valid user ID provided, using limited access';
        END IF;
    END IF;
    
    -- Set status to use
    IF p_status IS NULL THEN
        v_status_to_use := 'AVAILABLE';
    ELSE
        v_status_to_use := p_status;
    END IF;
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Status to use: %', v_status_to_use;
    END IF;
    
    -- Validate JSON input
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 2: Validating JSON input';
    END IF;
    
    IF jsonb_typeof(p_cardnumbers) != 'array' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: cardnumbers is not a JSON array, it is: %', jsonb_typeof(p_cardnumbers);
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'cardnumbers parameter must be a JSON array',
            jsonb_build_object(
                'error_message', 'cardnumbers parameter must be a JSON array',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'received_type', jsonb_typeof(p_cardnumbers),
                'debuglevel', p_debuglevel,
                'status', v_status_to_use
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'cardnumbers parameter must be a JSON array',
            'error_code', 'INVALID_INPUT',
            'user_access', v_user_access_message
        );
    END IF;
    
    v_total_cards := jsonb_array_length(p_cardnumbers);
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Total cards in array: %', v_total_cards;
    END IF;
    
    -- Validate empty array for UPDATE/DELETE
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 3: Checking for empty array (action: %)', p_action;
    END IF;
    
    IF p_action IN ('UPDATE', 'DELETE') AND v_total_cards = 0 THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: Empty card numbers array for UPDATE/DELETE action';
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'Empty card numbers array provided',
            jsonb_build_object(
                'error_message', 'Empty card numbers array provided',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'total_cards', v_total_cards,
                'debuglevel', p_debuglevel,
                'status', v_status_to_use
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'No card numbers provided',
            'error_code', 'EMPTY_ARRAY',
            'user_access', v_user_access_message
        );
    END IF;
    
    -- Validate status
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 4: Validating status: %', v_status_to_use;
    END IF;
    
    IF v_status_to_use NOT IN ('AVAILABLE', 'ALLOCATED', 'ASSIGNED', 'ACTIVE', 'BLOCKED', 'NEW', 'IN_STOCK', 'EXPIRED', 'CLOSED',
                               'CARD DISPATCH', 'PIN DISPATCH', 'CARD & PIN DISPATCH', 
                               'CARD ACK', 'PIN ACK', 'CARD ACK & PIN DISPATCH',
                               'CARD DISPATCH & PIN ACK', 'CARD ACK & PIN ACK','BOOKED') THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: Invalid status: %', v_status_to_use;
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'Invalid status value: ' || v_status_to_use,
            jsonb_build_object(
                'error_message', 'Invalid status value',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'provided_status', v_status_to_use,
                'valid_statuses', ARRAY['AVAILABLE', 'ALLOCATED', 'ASSIGNED', 'ACTIVE', 'BLOCKED', 'NEW', 'IN_STOCK', 'EXPIRED', 'CLOSED',
                                       'CARD DISPATCH', 'PIN DISPATCH', 'CARD & PIN DISPATCH', 
                                       'CARD ACK', 'PIN ACK', 'CARD ACK & PIN DISPATCH',
                                       'CARD DISPATCH & PIN ACK', 'CARD ACK & PIN ACK','BOOKED'],
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid status.',
            'error_code', 'INVALID_STATUS',
            'user_access', v_user_access_message
        );
    END IF;
    
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Status validation passed';
    END IF;
    
    -- Debug logging if debuglevel >= 1
    IF p_debuglevel >= 1 THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'Step 5: Debug logging (debuglevel >= 1)';
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            p_action || '_START',
            'Starting ' || p_action || ' action for ' || v_total_cards || ' cards with status: ' || v_status_to_use,
            jsonb_build_object(
                'action', p_action,
                'total_cards', v_total_cards,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'user_access_level', v_user_access_message,
                'branch_to_allocate', p_branchcodetoallocate,
                'status_to_set', v_status_to_use,
                'debuglevel', p_debuglevel,
                'start_time', v_start_time,
                'client_ip', inet_client_addr()
            )
        );
    END IF;
    
    -- Validate action
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 6: Validating action: %', p_action;
    END IF;
    
    IF p_action NOT IN ('UPDATE', 'DELETE', 'SEARCH') THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: Invalid action: %', p_action;
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'INVALID_ACTION',
            'Invalid action requested: ' || p_action,
            jsonb_build_object(
                'error_message', 'Invalid action requested',
                'requested_action', p_action,
                'valid_actions', ARRAY['UPDATE', 'DELETE', 'SEARCH'],
                'total_cards', v_total_cards,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status', v_status_to_use,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid action. Must be UPDATE, DELETE, or SEARCH',
            'error_code', 'INVALID_ACTION',
            'user_access', v_user_access_message
        );
    END IF;
    
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Action validation passed';
    END IF;
    
    -- Validate branch access for UPDATE
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 7: Validating branch access for UPDATE action';
    END IF;
    
    IF p_action = 'UPDATE' AND p_branchcodetoallocate IS NOT NULL 
       AND v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
       AND p_branchcodetoallocate != v_user_branchcode THEN
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ACCESS DENIED: User cannot allocate to branch % (user branch: %)', 
                p_branchcodetoallocate, v_user_branchcode;
        END IF;
            
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'BRANCH_ACCESS_DENIED',
            'User cannot allocate to branch: ' || p_branchcodetoallocate,
            jsonb_build_object(
                'error_message', 'User does not have permission to allocate to this branch',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'target_branch', p_branchcodetoallocate,
                'crossbranch_access', v_user_crossbranch,
                'total_cards', v_total_cards,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'You do not have permission to allocate cards to branch: ' || p_branchcodetoallocate,
            'error_code', 'BRANCH_ACCESS_DENIED',
            'user_access', v_user_access_message,
            'user_branch', v_user_branchcode,
            'target_branch', p_branchcodetoallocate
        );
    END IF;
    
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Branch access validation passed';
    END IF;
    
    -- Main action handling
    IF p_action = 'UPDATE' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'PROCESSING UPDATE ACTION';
            RAISE NOTICE '========================================';
        END IF;
        
        -- Validate parameters for UPDATE
        IF p_branchcodetoallocate IS NULL AND v_status_to_use IS NULL THEN
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'ERROR: Neither branch nor status provided for UPDATE';
            END IF;
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD',
                'UPDATE_ERROR',
                'Either branch or status must be provided for UPDATE action',
                jsonb_build_object(
                    'error_message', 'Either branch or status must be provided for UPDATE action',
                    'action', p_action,
                    'total_cards', v_total_cards,
                    'user_id', p_userid,
                    'username', v_username,
                    'user_branch', v_user_branchcode,
                    'crossbranch_access', v_user_crossbranch,
                    'debuglevel', p_debuglevel
                )
            );
            
            RETURN jsonb_build_object(
                'success', false,
                'message', 'Either branch code or status must be provided for UPDATE action',
                'error_code', 'MISSING_PARAMETER',
                'user_access', v_user_access_message
            );
        END IF;
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'UPDATE parameters valid. Processing % cards', v_total_cards;
        END IF;
        
        -- Loop through each card
        FOR i IN 0..v_total_cards - 1 LOOP
            v_processed_count := v_processed_count + 1;
            v_cardnumber := p_cardnumbers->>i;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE '----------------------------------------';
                RAISE NOTICE 'Processing card % of % (Index: %)', i+1, v_total_cards, i;
                RAISE NOTICE 'Card number: %', v_cardnumber;
            END IF;
            
            IF v_cardnumber IS NULL OR v_cardnumber = '' THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Empty card number at index %', i;
                END IF;
                v_failed_count := v_failed_count + 1;
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'Empty card number',
                    'error_code', 'EMPTY_CARD_NUMBER',
                    'user_access', v_user_access_message
                );
                CONTINUE;
            END IF;
            
            -- Create masked version for audit trail only
            v_masked_cardnumber := 'XXXX-XXXX-XXXX-' || RIGHT(v_cardnumber, 4);
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Masked card number: %', v_masked_cardnumber;
            END IF;
            
            BEGIN
                -- Get card details from database
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Fetching card details from instantcardstock';
                END IF;
                
                SELECT 
                    allocatedbranch, 
                    uploadid, 
                    accountnumber, 
                    status,
                    embossedname,
                    expirydate
                INTO 
                    v_old_branch, 
                    v_uploadid, 
                    v_accountnumber, 
                    v_current_status,
                    v_embossedname,
                    v_expirydate
                FROM public.instantcardstock 
                WHERE cardnumber = v_cardnumber;
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Card details found:';
                    RAISE NOTICE '  allocatedbranch: %', v_old_branch;
                    RAISE NOTICE '  uploadid: %', v_uploadid;
                    RAISE NOTICE '  accountnumber: %', v_accountnumber;
                    RAISE NOTICE '  current status: %', v_current_status;
                    RAISE NOTICE '  embossedname: %', v_embossedname;
                END IF;
                
                IF v_uploadid IS NULL THEN
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'ERROR: Card not found in database';
                    END IF;
                    v_failed_count := v_failed_count + 1;
                    v_card_results := v_card_results || jsonb_build_object(
                        'cardnumber', v_cardnumber,
                        'success', false,
                        'message', 'Card not found',
                        'error_code', 'CARD_NOT_FOUND',
                        'user_access', v_user_access_message
                    );
                    CONTINUE;
                END IF;
                
                -- Check user access to modify this card
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Checking user access to modify card';
                END IF;
                
                IF v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
                   AND v_old_branch IS NOT NULL AND v_old_branch != v_user_branchcode THEN
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'ACCESS DENIED: Card belongs to branch %, user is from branch %', 
                            v_old_branch, v_user_branchcode;
                    END IF;
                        
                    v_failed_count := v_failed_count + 1;
                    v_card_results := v_card_results || jsonb_build_object(
                        'cardnumber', v_cardnumber,
                        'success', false,
                        'message', 'You do not have permission to modify this card. Card belongs to branch: ' || v_old_branch,
                        'error_code', 'CARD_ACCESS_DENIED',
                        'user_access', v_user_access_message,
                        'card_branch', v_old_branch,
                        'user_branch', v_user_branchcode
                    );
                    CONTINUE;
                END IF;
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Access granted';
                END IF;
                
                -- Initialize v_new_status with the requested status
                v_new_status := v_status_to_use;
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Requested new status: %', v_new_status;
                END IF;
                
                -- STATUS COMPOSITION LOGIC
                -- Only apply composition logic for card/PIN related statuses
                IF v_status_to_use IN ('CARD DISPATCH', 'PIN DISPATCH', 'CARD ACK', 'PIN ACK') THEN
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Applying status composition logic';
                        RAISE NOTICE 'Current status: %', v_current_status;
                    END IF;
                    
                    -- Check if current status is a combined status
                    IF v_current_status LIKE '%&%' THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Current status is combined status';
                        END IF;
                        -- Parse the current combined status
                        v_status_parts := string_to_array(v_current_status, ' & ');
                        
                        IF array_length(v_status_parts, 1) >= 1 THEN
                            v_current_card_part := TRIM(v_status_parts[1]);
                        END IF;
                        IF array_length(v_status_parts, 1) >= 2 THEN
                            v_current_pin_part := TRIM(v_status_parts[2]);
                        END IF;
                        
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Current card part: %, current pin part: %', 
                                v_current_card_part, v_current_pin_part;
                        END IF;
                        
                        -- Apply composition logic based on requested status
                        IF v_status_to_use = 'CARD DISPATCH' THEN
                            -- Update card part to CARD DISPATCH, keep existing pin part
                            IF v_current_pin_part IS NOT NULL THEN
                                v_new_status := 'CARD DISPATCH & ' || v_current_pin_part;
                            ELSE
                                v_new_status := 'CARD DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN DISPATCH' THEN
                            -- Update pin part to PIN DISPATCH, keep existing card part
                            IF v_current_card_part IS NOT NULL THEN
                                v_new_status := v_current_card_part || ' & PIN DISPATCH';
                            ELSE
                                v_new_status := 'PIN DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'CARD ACK' THEN
                            -- Update card part to CARD ACK, keep existing pin part
                            IF v_current_pin_part IS NOT NULL THEN
                                v_new_status := 'CARD ACK & ' || v_current_pin_part;
                            ELSE
                                v_new_status := 'CARD ACK';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN ACK' THEN
                            -- Update pin part to PIN ACK, keep existing card part
                            IF v_current_card_part IS NOT NULL THEN
                                v_new_status := v_current_card_part || ' & PIN ACK';
                            ELSE
                                v_new_status := 'PIN ACK';
                            END IF;
                        END IF;
                        
                    ELSE
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Current status is simple status';
                        END IF;
                        -- Current status is not combined, need to create combination if needed
                        IF v_status_to_use = 'CARD DISPATCH' THEN
                            IF v_current_status = 'PIN DISPATCH' THEN
                                -- PIN was dispatched first, now card dispatched
                                v_new_status := 'CARD & PIN DISPATCH';
                            ELSIF v_current_status = 'PIN ACK' THEN
                                -- PIN was acknowledged, now card dispatched
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSE
                                -- Starting fresh with card dispatch
                                v_new_status := 'CARD DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN DISPATCH' THEN
                            IF v_current_status = 'CARD DISPATCH' THEN
                                -- Card was dispatched first, now PIN dispatched
                                v_new_status := 'CARD & PIN DISPATCH';
                            ELSIF v_current_status = 'CARD ACK' THEN
                                -- Card was acknowledged, now PIN dispatched
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSE
                                -- Starting fresh with PIN dispatch
                                v_new_status := 'PIN DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'CARD ACK' THEN
                            IF v_current_status = 'CARD DISPATCH' THEN
                                -- Card was dispatched, now acknowledged
                                v_new_status := 'CARD ACK';
                            ELSIF v_current_status = 'CARD DISPATCH & PIN ACK' THEN
                                -- Card dispatched & PIN acked, now card acknowledged
                                v_new_status := 'CARD ACK & PIN ACK';
                            ELSIF v_current_status = 'CARD & PIN DISPATCH' THEN
                                -- Both dispatched, now card acknowledged
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSIF v_current_status = 'PIN DISPATCH' THEN
                                -- Only PIN dispatched, now card acknowledged (unusual)
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSE
                                -- Direct card acknowledgment
                                v_new_status := 'CARD ACK';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN ACK' THEN
                            IF v_current_status = 'PIN DISPATCH' THEN
                                -- PIN was dispatched, now acknowledged
                                v_new_status := 'PIN ACK';
                            ELSIF v_current_status = 'CARD ACK & PIN DISPATCH' THEN
                                -- Card acked & PIN dispatched, now PIN acknowledged
                                v_new_status := 'CARD ACK & PIN ACK';
                            ELSIF v_current_status = 'CARD & PIN DISPATCH' THEN
                                -- Both dispatched, now PIN acknowledged
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSIF v_current_status = 'CARD DISPATCH' THEN
                                -- Only card dispatched, now PIN acknowledged (unusual)
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSE
                                -- Direct PIN acknowledgment
                                v_new_status := 'PIN ACK';
                            END IF;
                        END IF;
                    END IF;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Composed new status: %', v_new_status;
                    END IF;
                END IF;
                -- END STATUS COMPOSITION LOGIC
                
                -- Now use v_new_status for the update   
                IF p_branchcodetoallocate IS NOT NULL THEN
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Branch allocation requested to: %', p_branchcodetoallocate;
                    END IF;
                    
                    -- Check if card can be allocated
                    IF v_current_status NOT IN ('AVAILABLE', 'NEW', 'IN_STOCK', 'ALLOCATED','BOOKED') THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'ERROR: Card status % does not allow allocation', v_current_status;
                        END IF;
                        v_failed_count := v_failed_count + 1;
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Card status does not allow branch allocation. Current: ' || v_current_status,
                            'error_code', 'INVALID_STATUS_FOR_BRANCH',
                            'current_status', v_current_status,
                            'user_access', v_user_access_message
                        );
                        CONTINUE;
                    END IF;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Current branch: %, Target branch: %', v_old_branch, p_branchcodetoallocate;
                    END IF;
                    
                    IF v_old_branch = p_branchcodetoallocate THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Branch already matches target branch';
                        END IF;
                        
                        IF v_current_status != v_new_status THEN
                            IF p_debuglevel > 3 THEN
                                RAISE NOTICE 'Updating status only (branch same)';
                            END IF;
                            
                            UPDATE public.instantcardstock
                            SET 
                                status = v_new_status,
                                lastupdateddate = CURRENT_TIMESTAMP,
                                lastupdatedby = v_username
                            WHERE cardnumber = v_cardnumber;
                            
                            GET DIAGNOSTICS v_row_count = ROW_COUNT;
                            v_success_count := v_success_count + 1;
                            
                            -- =====================================================
                            -- FLAG UPDATE - STATUS CHANGE WITH SAME BRANCH
                            -- =====================================================
                            IF v_new_status = 'ALLOCATED' AND p_requestid IS NOT NULL AND v_row_count = 1 THEN
                                RAISE NOTICE 'Checking flag update condition: v_new_status=%, p_requestid=%', v_new_status, p_requestid;
                                
                                -- Get the request details
                                SELECT 
                                    booked_cards,
                                    approved_cards,
                                    bookedcardallocated,
                                    approvedcardsallocated
                                INTO 
                                    v_current_booked_cards,
                                    v_current_approved_cards,
                                    v_current_booked_allocated,
                                    v_current_approved_allocated
                                FROM public.instantcardcycle
                                WHERE requestid = p_requestid;
                                
                                IF FOUND THEN
                                    RAISE NOTICE 'DEBUG - booked_cards: %, approved_cards: %', v_current_booked_cards, v_current_approved_cards;
                                    RAISE NOTICE 'DEBUG - v_total_cards: %, comparing to booked: %', v_total_cards, (v_total_cards = v_current_booked_cards);
                                    RAISE NOTICE 'DEBUG - v_total_cards: %, comparing to approved: %', v_total_cards, (v_total_cards = v_current_approved_cards);
                                    
                                    -- Check if the current allocation count matches booked_cards
                                    IF v_current_booked_allocated = false 
                                       AND v_current_booked_cards > 0 
                                       AND v_total_cards = v_current_booked_cards THEN
                                        
                                        UPDATE public.instantcardcycle
                                        SET bookedcardallocated = true
                                        WHERE requestid = p_requestid;
                                        
                                        v_flag_update_message := 'Booked flag updated for request ' || p_requestid;
                                        v_flag_updated := TRUE;
                                    END IF;
                                    
                                    -- Check if the current allocation count matches approved_cards
                                    IF v_current_approved_allocated = false 
                                       AND v_current_approved_cards > 0 
                                       AND v_total_cards = v_current_approved_cards THEN
                                        
                                        UPDATE public.instantcardcycle
                                        SET approvedcardsallocated = true
                                        WHERE requestid = p_requestid;
                                        
                                        v_flag_update_message := v_flag_update_message || ' Approved flag updated for request ' || p_requestid;
                                        v_flag_updated := TRUE;
                                    END IF;
                                ELSE
                                    RAISE NOTICE 'DEBUG - Request ID % NOT found in instantcardcycle table', p_requestid;
                                END IF;
                            END IF;
                            
                            -- LOGGING: Status change when branch already same
                            INSERT INTO LOG_instant_card_allocation (
                                cardnumber, operation_type,
                                from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                            ) VALUES (
                                v_cardnumber, 'STATUS_CHANGE',
                                v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                            );
                            
                            v_card_results := v_card_results || jsonb_build_object(
                                'cardnumber', v_cardnumber,
                                'success', true,
                                'message', 'Status updated to ' || v_new_status || ' (branch already ' || v_old_branch || ')',
                                'uploadid', v_uploadid,
                                'branch', v_old_branch,
                                'old_status', v_current_status,
                                'new_status', v_new_status,
                                'accountnumber', v_accountnumber,
                                'user_access', v_user_access_message,
                                'flag_updated', v_flag_updated,
                                'flag_message', v_flag_update_message
                            );
                            
                            IF p_debuglevel > 3 THEN
                                RAISE NOTICE 'Status update successful';
                            END IF;
                        ELSE
                            IF p_debuglevel > 3 THEN
                                RAISE NOTICE 'No changes required (branch and status same)';
                            END IF;
                            
                            v_success_count := v_success_count + 1;
                            
                            -- LOGGING: No change when branch same and status same
                            INSERT INTO LOG_instant_card_allocation (
                                cardnumber, operation_type,
                                from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                            ) VALUES (
                                v_cardnumber, 'UPDATE',
                                v_old_branch, p_branchcodetoallocate, v_current_status, v_current_status, v_username, p_userid
                            );
                            
                            v_card_results := v_card_results || jsonb_build_object(
                                'cardnumber', v_cardnumber,
                                'success', true,
                                'message', 'No changes required',
                                'no_change', true,
                                'current_branch', v_old_branch,
                                'current_status', v_current_status,
                                'user_access', v_user_access_message
                            );
                        END IF;
                        CONTINUE;
                    END IF;
                    
                    -- Perform the actual allocation
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Allocating card to new branch: %', p_branchcodetoallocate;
                    END IF;
                    
                    UPDATE public.instantcardstock
                    SET 
                        allocatedbranch = p_branchcodetoallocate,
                        status = v_new_status,
                        lastupdateddate = CURRENT_TIMESTAMP,
                        lastupdatedby = v_username
                    WHERE cardnumber = v_cardnumber
                    RETURNING uploadid INTO v_uploadid;
                    
                    GET DIAGNOSTICS v_row_count = ROW_COUNT;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Rows affected: %', v_row_count;
                    END IF;
                    
                    IF v_row_count = 1 THEN
                        v_success_count := v_success_count + 1;
                        
                        -- =====================================================
                        -- FLAG UPDATE - BRANCH ALLOCATION
                        -- =====================================================
                        IF v_new_status = 'ALLOCATED' AND p_requestid IS NOT NULL THEN
                            RAISE NOTICE 'Checking flag update condition: v_new_status=%, p_requestid=%', v_new_status, p_requestid;
                            
                            -- Get the request details
                            SELECT 
                                booked_cards,
                                approved_cards,
                                bookedcardallocated,
                                approvedcardsallocated
                            INTO 
                                v_current_booked_cards,
                                v_current_approved_cards,
                                v_current_booked_allocated,
                                v_current_approved_allocated
                            FROM public.instantcardcycle
                            WHERE requestid = p_requestid;
                            
                            IF FOUND THEN
                                RAISE NOTICE 'DEBUG - booked_cards: %, approved_cards: %', v_current_booked_cards, v_current_approved_cards;
                                RAISE NOTICE 'DEBUG - v_total_cards: %, comparing to booked: %', v_total_cards, (v_total_cards = v_current_booked_cards);
                                RAISE NOTICE 'DEBUG - v_total_cards: %, comparing to approved: %', v_total_cards, (v_total_cards = v_current_approved_cards);
                                
                                -- Check if the current allocation count matches booked_cards
                                IF v_current_booked_allocated = false 
                                   AND v_current_booked_cards > 0 
                                   AND v_total_cards = v_current_booked_cards THEN
                                    
                                    UPDATE public.instantcardcycle
                                    SET bookedcardallocated = true
                                    WHERE requestid = p_requestid;
                                    
                                    v_flag_update_message := 'Booked flag updated for request ' || p_requestid;
                                    v_flag_updated := TRUE;
                                END IF;
                                
                                -- Check if the current allocation count matches approved_cards
                                IF v_current_approved_allocated = false 
                                   AND v_current_approved_cards > 0 
                                   AND v_total_cards = v_current_approved_cards THEN
                                    
                                    UPDATE public.instantcardcycle
                                    SET approvedcardsallocated = true
                                    WHERE requestid = p_requestid;
                                    
                                    v_flag_update_message := v_flag_update_message || ' Approved flag updated for request ' || p_requestid;
                                    v_flag_updated := TRUE;
                                END IF;
                            ELSE
                                RAISE NOTICE 'DEBUG - Request ID % NOT found in instantcardcycle table', p_requestid;
                            END IF;
                        END IF;
                        
                        -- LOGGING: Branch allocation with status change
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'ALLOCATE',
                            v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Branch allocated to ' || p_branchcodetoallocate || ' with status ' || v_new_status,
                            'uploadid', v_uploadid,
                            'old_branch', v_old_branch,
                            'new_branch', p_branchcodetoallocate,
                            'old_status', v_current_status,
                            'new_status', v_new_status,
                            'accountnumber', v_accountnumber,
                            'user_access', v_user_access_message,
                            'flag_updated', v_flag_updated,
                            'flag_message', v_flag_update_message
                        );
                        
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Allocation successful';
                        END IF;
                        
                        IF p_debuglevel >= 2 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD',
                                'BRANCH_ALLOCATED',
                                'Card allocated to branch ' || p_branchcodetoallocate || ' with status ' || v_new_status || ': ' || v_masked_cardnumber,
                                jsonb_build_object(
                                    'cardnumber', v_masked_cardnumber,
                                    'uploadid', v_uploadid,
                                    'old_branch', v_old_branch,
                                    'new_branch', p_branchcodetoallocate,
                                    'old_status', v_current_status,
                                    'new_status', v_new_status,
                                    'accountnumber', v_accountnumber,
                                    'user_id', p_userid,
                                    'username', v_username,
                                    'user_branch', v_user_branchcode,
                                    'crossbranch_access', v_user_crossbranch,
                                    'debuglevel', p_debuglevel
                                )
                            );
                        END IF;
                        
                    ELSE
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'ERROR: Allocation failed - no rows affected';
                        END IF;
                        
                        v_failed_count := v_failed_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'ALLOCATE',
                            v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Branch allocation failed - no rows affected',
                            'error_code', 'ALLOCATION_FAILED',
                            'user_access', v_user_access_message
                        );
                    END IF;
                    
                ELSE
                    -- No branch allocation, just status update
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'No branch allocation - just status update to: %', v_new_status;
                    END IF;
                    
                    IF v_current_status = v_new_status THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Status already set to % - no change needed', v_new_status;
                        END IF;
                        
                        v_success_count := v_success_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'UPDATE',
                            v_old_branch, v_old_branch, v_current_status, v_current_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Status already ' || v_new_status,
                            'no_change', true,
                            'current_branch', v_old_branch,
                            'current_status', v_current_status,
                            'user_access', v_user_access_message
                        );
                        CONTINUE;
                    END IF;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Updating status from % to %', v_current_status, v_new_status;
                    END IF;
                    
                    UPDATE public.instantcardstock
                    SET 
                        status = v_new_status,
                        lastupdateddate = CURRENT_TIMESTAMP,
                        lastupdatedby = v_username
                    WHERE cardnumber = v_cardnumber
                    RETURNING uploadid INTO v_uploadid;
                    
                    GET DIAGNOSTICS v_row_count = ROW_COUNT;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Rows affected: %', v_row_count;
                    END IF;
                    
                    IF v_row_count = 1 THEN
                        v_success_count := v_success_count + 1;
                        
                        -- =====================================================
                        -- FLAG UPDATE - STATUS ONLY CHANGE
                        -- =====================================================
                        IF v_new_status = 'ALLOCATED' AND p_requestid IS NOT NULL THEN
                            RAISE NOTICE 'Checking flag update condition: v_new_status=%, p_requestid=%', v_new_status, p_requestid;
                            
                            -- Get the request details
                            SELECT 
                                booked_cards,
                                approved_cards,
                                bookedcardallocated,
                                approvedcardsallocated
                            INTO 
                                v_current_booked_cards,
                                v_current_approved_cards,
                                v_current_booked_allocated,
                                v_current_approved_allocated
                            FROM public.instantcardcycle
                            WHERE requestid = p_requestid;
                            
                            IF FOUND THEN
                                RAISE NOTICE 'DEBUG - booked_cards: %, approved_cards: %', v_current_booked_cards, v_current_approved_cards;
                                RAISE NOTICE 'DEBUG - v_total_cards: %, comparing to booked: %', v_total_cards, (v_total_cards = v_current_booked_cards);
                                RAISE NOTICE 'DEBUG - v_total_cards: %, comparing to approved: %', v_total_cards, (v_total_cards = v_current_approved_cards);
                                
                                -- Check if the current allocation count matches booked_cards
                                IF v_current_booked_allocated = false 
                                   AND v_current_booked_cards > 0 
                                   AND v_total_cards = v_current_booked_cards THEN
                                    
                                    UPDATE public.instantcardcycle
                                    SET bookedcardallocated = true
                                    WHERE requestid = p_requestid;
                                    
                                    v_flag_update_message := 'Booked flag updated for request ' || p_requestid;
                                    v_flag_updated := TRUE;
                                END IF;
                                
                                -- Check if the current allocation count matches approved_cards
                                IF v_current_approved_allocated = false 
                                   AND v_current_approved_cards > 0 
                                   AND v_total_cards = v_current_approved_cards THEN
                                    
                                    UPDATE public.instantcardcycle
                                    SET approvedcardsallocated = true
                                    WHERE requestid = p_requestid;
                                    
                                    v_flag_update_message := v_flag_update_message || ' Approved flag updated for request ' || p_requestid;
                                    v_flag_updated := TRUE;
                                END IF;
                            ELSE
                                RAISE NOTICE 'DEBUG - Request ID % NOT found in instantcardcycle table', p_requestid;
                            END IF;
                        END IF;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'STATUS_CHANGE',
                            v_old_branch, v_old_branch, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Status updated to ' || v_new_status,
                            'uploadid', v_uploadid,
                            'branch', v_old_branch,
                            'old_status', v_current_status,
                            'new_status', v_new_status,
                            'accountnumber', v_accountnumber,
                            'user_access', v_user_access_message,
                            'flag_updated', v_flag_updated,
                            'flag_message', v_flag_update_message
                        );
                        
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Status update successful';
                        END IF;
                        
                        IF p_debuglevel >= 2 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD',
                                'STATUS_UPDATED',
                                'Card status updated to ' || v_new_status || ': ' || v_masked_cardnumber,
                                jsonb_build_object(
                                    'cardnumber', v_masked_cardnumber,
                                    'uploadid', v_uploadid,
                                    'branch', v_old_branch,
                                    'old_status', v_current_status,
                                    'new_status', v_new_status,
                                    'accountnumber', v_accountnumber,
                                    'user_id', p_userid,
                                    'username', v_username,
                                    'user_branch', v_user_branchcode,
                                    'crossbranch_access', v_user_crossbranch,
                                    'debuglevel', p_debuglevel
                                )
                            );
                        END IF;
                    ELSE
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'ERROR: Status update failed - no rows affected';
                        END IF;
                        
                        v_failed_count := v_failed_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'STATUS_CHANGE',
                            v_old_branch, v_old_branch, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Status update failed - no rows affected',
                            'error_code', 'STATUS_UPDATE_FAILED',
                            'user_access', v_user_access_message
                        );
                    END IF;
                END IF;
                  
            EXCEPTION WHEN OTHERS THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'EXCEPTION CAUGHT: %', SQLERRM;
                    RAISE NOTICE 'SQLSTATE: %', SQLSTATE;
                END IF;
                
                v_failed_count := v_failed_count + 1;
                
                INSERT INTO LOG_instant_card_allocation (
                    cardnumber, operation_type,
                    from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                ) VALUES (
                    v_cardnumber, 
                    CASE 
                        WHEN p_branchcodetoallocate IS NOT NULL AND v_old_branch != p_branchcodetoallocate THEN 'ALLOCATE'
                        ELSE 'STATUS_CHANGE'
                    END,
                    v_old_branch, 
                    p_branchcodetoallocate, 
                    v_current_status, 
                    v_new_status, 
                    v_username, 
                    p_userid
                );
                
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'Error: ' || SQLERRM,
                    'error_code', SQLSTATE,
                    'user_access', v_user_access_message
                );
            END;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Card processing complete. Success: %, Failed: %', v_success_count, v_failed_count;
            END IF;
        END LOOP;
        
        v_execution_time := clock_timestamp() - v_start_time;
        v_action_message := format('UPDATE completed: %s successful, %s failed out of %s total', 
                                 v_success_count, v_failed_count, v_total_cards);
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'UPDATE SUMMARY:';
            RAISE NOTICE '  Total cards: %', v_total_cards;
            RAISE NOTICE '  Processed: %', v_processed_count;
            RAISE NOTICE '  Successful: %', v_success_count;
            RAISE NOTICE '  Failed: %', v_failed_count;
            RAISE NOTICE '  Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '  Flag updated: %', v_flag_updated;
            RAISE NOTICE '  Flag message: %', v_flag_update_message;
            RAISE NOTICE '========================================';
        END IF;
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'UPDATE_COMPLETED',
            v_action_message,
            jsonb_build_object(
                'action', 'UPDATE',
                'total_cards', v_total_cards,
                'successful', v_success_count,
                'failed', v_failed_count,
                'branch_allocated', p_branchcodetoallocate,
                'status_set', v_new_status,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'summary_message', v_action_message,
                'debuglevel', p_debuglevel,
                'flag_updated', v_flag_updated,
                'flag_message', v_flag_update_message
            )
        );
        
        RETURN jsonb_build_object(
            'success', v_success_count > 0,
            'message', v_action_message,
            'action', 'UPDATE',
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'branch', p_branchcodetoallocate,
                'status', v_new_status,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'flag_updated', v_flag_updated,
                'flag_message', v_flag_update_message
            ),
            'card_results', v_card_results
        );
    
    ELSIF p_action = 'DELETE' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'PROCESSING DELETE ACTION';
            RAISE NOTICE '========================================';
        END IF;
        
        -- DELETE section (with debug notices)
        FOR i IN 0..v_total_cards - 1 LOOP
            v_processed_count := v_processed_count + 1;
            v_cardnumber := p_cardnumbers->>i;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Processing card % of % for DELETE', i+1, v_total_cards;
                RAISE NOTICE 'Card number: %', v_cardnumber;
            END IF;
            
            IF v_cardnumber IS NULL OR v_cardnumber = '' THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Empty card number';
                END IF;
                v_failed_count := v_failed_count + 1;
                CONTINUE;
            END IF;
            
            -- Get card branch info first
            SELECT allocatedbranch INTO v_old_branch 
            FROM public.instantcardstock 
            WHERE cardnumber = v_cardnumber;
            
            IF NOT FOUND THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Card not found';
                END IF;
                v_failed_count := v_failed_count + 1;
                CONTINUE;
            END IF;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Card found in branch: %', v_old_branch;
            END IF;
            
            -- Check if user has access to delete this card
            IF v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
               AND v_old_branch IS NOT NULL AND v_old_branch != v_user_branchcode THEN
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ACCESS DENIED: Card belongs to branch %, user is from branch %', 
                        v_old_branch, v_user_branchcode;
                END IF;
                    
                v_failed_count := v_failed_count + 1;
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'You do not have permission to delete this card. Card belongs to branch: ' || v_old_branch,
                    'error_code', 'CARD_ACCESS_DENIED',
                    'user_access', v_user_access_message,
                    'card_branch', v_old_branch,
                    'user_branch', v_user_branchcode
                );
                CONTINUE;
            END IF;
            
            -- Proceed with DELETE if user has access
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Deleting card';
            END IF;
            
            DELETE FROM public.instantcardstock 
            WHERE cardnumber = v_cardnumber;
            
            GET DIAGNOSTICS v_row_count = ROW_COUNT;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Rows affected: %', v_row_count;
            END IF;
            
            IF v_row_count = 1 THEN
                v_success_count := v_success_count + 1;
                
                INSERT INTO LOG_instant_card_allocation (
                    cardnumber, operation_type,
                    from_branch, to_branch, performed_by, performed_by_userid
                ) VALUES (
                    v_cardnumber, 'DELETE',
                    v_old_branch, NULL, v_username, p_userid
                );
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Delete successful';
                END IF;
            ELSE
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Delete failed';
                END IF;
                v_failed_count := v_failed_count + 1;
            END IF;
        END LOOP;
        
        v_execution_time := clock_timestamp() - v_start_time;
        v_action_message := format('DELETE completed: %s successful, %s failed out of %s total', 
                                 v_success_count, v_failed_count, v_total_cards);
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'DELETE SUMMARY:';
            RAISE NOTICE '  Total cards: %', v_total_cards;
            RAISE NOTICE '  Processed: %', v_processed_count;
            RAISE NOTICE '  Successful: %', v_success_count;
            RAISE NOTICE '  Failed: %', v_failed_count;
            RAISE NOTICE '  Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '========================================';
        END IF;
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'DELETE_COMPLETED',
            v_action_message,
            jsonb_build_object(
                'action', 'DELETE',
                'total_cards', v_total_cards,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'summary_message', v_action_message,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', v_success_count > 0,
            'message', v_action_message,
            'action', 'DELETE',
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            ),
            'card_results', v_card_results
        );
        
    ELSIF p_action = 'SEARCH' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'PROCESSING SEARCH ACTION';
            RAISE NOTICE '========================================';
        END IF;
        
        v_search_result := '[]'::JSONB;
        
        -- If no card numbers provided, return cards with the specified status
        IF v_total_cards = 0 THEN
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Searching for all cards with status: %', v_status_to_use;
                RAISE NOTICE 'Branch filter: user_branch=%, crossbranch=%', 
                    v_user_branchcode, v_user_crossbranch;
            END IF;
            
            SELECT COALESCE(jsonb_agg(
                jsonb_build_object(
                    'cardnumber', cardnumber,
                    'uploadid', uploadid,
                    'bankcode', bankcode,
                    'allocatedbranch', allocatedbranch,
                    'requestbranch', requestbranch,
                    'status', status,
                    'embossedname', embossedname,
                    'accountnumber', accountnumber,
                    'expirydate', expirydate,
                    'opendingdate', opendingdate,
                    'createddate', createddate,
                    'lastupdateddate', lastupdateddate,
                    'isgreenpin',isgreenpin
                )
                ORDER BY cardnumber asc
            ), '[]'::JSONB)
            INTO v_search_result
            FROM public.instantcardstock 
            WHERE CASE 
                -- When searching for PIN DISPATCH status, include multiple statuses
                WHEN v_status_to_use = 'PIN DISPATCH' THEN 
                    status IN ('ALLOCATED', 'CARD DISPATCH', 'CARD ACK')
                WHEN v_status_to_use = 'CARD DISPATCH' THEN 
                    status IN ('ALLOCATED', 'PIN DISPATCH', 'PIN ACK')
                WHEN v_status_to_use = 'PIN ACK' THEN 
                    status IN ('PIN DISPATCH', 'CARD ACK & PIN DISPATCH', 'CARD ACK')
                WHEN v_status_to_use = 'CARD ACK' THEN 
                    status IN ( 'CARD DISPATCH','CARD & PIN DISPATCH','CARD DISPATCH & PIN ACK')
                -- Otherwise use exact status match
                ELSE status = v_status_to_use
            END
            -- Branch access filtering for SEARCH
            AND (
                v_user_crossbranch = TRUE
                OR allocatedbranch = v_user_branchcode
                OR (v_user_branchcode IS NULL AND allocatedbranch IS NULL)
            );
            
            v_success_count := COALESCE(jsonb_array_length(v_search_result), 0);
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Found % cards matching criteria', v_success_count;
            END IF;
            
        ELSE
            -- Process specific card numbers with branch access check
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Searching for % specific card numbers', v_total_cards;
            END IF;
            
            FOR i IN 0..v_total_cards - 1 LOOP
                v_cardnumber := p_cardnumbers->>i;
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Searching for card: %', v_cardnumber;
                END IF;
                
                IF v_cardnumber IS NOT NULL AND v_cardnumber != '' THEN
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'cardnumber', cardnumber,
                            'uploadid', uploadid,
                            'bankcode', bankcode,
                            'allocatedbranch', allocatedbranch,
                            'requestbranch', requestbranch,
                            'status', status,
                            'embossedname', embossedname,
                            'accountnumber', accountnumber,
                            'expirydate', expirydate,
                            'opendingdate', opendingdate,
                            'createddate', createddate,
                            'lastupdateddate', lastupdateddate
                        )
                    )
                    INTO v_card_data
                    FROM public.instantcardstock 
                    WHERE cardnumber = v_cardnumber
                    AND (
                        v_user_crossbranch = TRUE
                        OR allocatedbranch = v_user_branchcode
                        OR (v_user_branchcode IS NULL AND allocatedbranch IS NULL)
                    );
                    
                    IF v_card_data IS NOT NULL THEN
                        v_search_result := v_search_result || v_card_data;
                        v_success_count := v_success_count + 1;
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Card found';
                        END IF;
                    ELSE
                        v_failed_count := v_failed_count + 1;
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Card not found or access denied';
                        END IF;
                    END IF;
                END IF;
            END LOOP;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Search complete. Found: %, Not found: %', 
                    v_success_count, v_failed_count;
            END IF;
        END IF;
        
        IF p_debuglevel >= 1 THEN
            v_execution_time := clock_timestamp() - v_start_time;
            v_action_message := format('SEARCH completed: Found %s cards, %s not found', 
                                     v_success_count, v_failed_count);
            
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD',
                'SEARCH_COMPLETED',
                v_action_message,
                jsonb_build_object(
                    'action', 'SEARCH',
                    'total_cards', v_total_cards,
                    'found', v_success_count,
                    'not_found', v_failed_count,
                    'user_id', p_userid,
                    'username', v_username,
                    'user_branch', v_user_branchcode,
                    'crossbranch_access', v_user_crossbranch,
                    'status_filter', v_status_to_use,
                    'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                    'summary_message', v_action_message,
                    'debuglevel', p_debuglevel,
                    'search_criteria', CASE 
                        WHEN v_total_cards = 0 THEN format('ALL_CARDS_WITH_STATUS_%s', v_status_to_use)
                        ELSE format('SPECIFIC_CARDS(%s)', v_total_cards)
                    END
                )
            );
        END IF;
        
        v_execution_time := clock_timestamp() - v_start_time;
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'SEARCH SUMMARY:';
            RAISE NOTICE '  Total requested: %', v_total_cards;
            RAISE NOTICE '  Found: %', v_success_count;
            RAISE NOTICE '  Not found: %', v_failed_count;
            RAISE NOTICE '  Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '========================================';
        END IF;
        
        RETURN jsonb_build_object(
            'success', true,
            'message', format('SEARCH completed: Found %s cards, %s not found', 
                            v_success_count, v_failed_count),
            'action', 'SEARCH',
            'summary', jsonb_build_object(
                'total_requested', v_total_cards,
                'found', v_success_count,
                'not_found', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status_filter', v_status_to_use,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            ),
            'cards', v_search_result
        );
    END IF;
    
EXCEPTION
    WHEN OTHERS THEN
        v_execution_time := clock_timestamp() - v_start_time;
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'FATAL ERROR IN FUNCTION';
            RAISE NOTICE 'Error message: %', SQLERRM;
            RAISE NOTICE 'SQLSTATE: %', SQLSTATE;
            RAISE NOTICE 'Action: %', p_action;
            RAISE NOTICE 'Total cards: %', v_total_cards;
            RAISE NOTICE 'Processed: %', v_processed_count;
            RAISE NOTICE 'Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '========================================';
        END IF;
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'FUNCTION_ERROR',
            'Function error: ' || SQLERRM,
            jsonb_build_object(
                'error_message', SQLERRM,
                'error_code', SQLSTATE,
                'action', p_action,
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status', v_status_to_use,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Function error: ' || SQLERRM,
            'error_code', SQLSTATE,
            'action', p_action,
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            )
        );
END;
$$;


ALTER FUNCTION public.finstantcardbranchallocation_feb242026v3(p_action character varying, p_cardnumbers jsonb, p_userid integer, p_branchcodetoallocate character varying, p_debuglevel integer, p_status character varying, p_requestid character varying) OWNER TO postgres;

--
-- TOC entry 441 (class 1255 OID 31245)
-- Name: finstantcardcycle(character varying, character varying, character varying, character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, date, date, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstantcardcycle(p_action character varying, p_requestid character varying DEFAULT NULL::character varying, p_scheme character varying DEFAULT NULL::character varying, p_cardtype character varying DEFAULT NULL::character varying, p_currency character varying DEFAULT NULL::character varying, p_totalnumberofcard integer DEFAULT NULL::integer, p_flags character varying DEFAULT NULL::character varying, p_pintype character varying DEFAULT NULL::character varying, p_requestedby character varying DEFAULT NULL::character varying, p_requestedbranchname character varying DEFAULT NULL::character varying, p_requestbranchcode character varying DEFAULT NULL::character varying, p_approvedby character varying DEFAULT NULL::character varying, p_approvedbranchcode character varying DEFAULT NULL::character varying, p_approvedbranchname character varying DEFAULT NULL::character varying, p_verifiedby character varying DEFAULT NULL::character varying, p_verifiedbranchname character varying DEFAULT NULL::character varying, p_verifiedbranchcode character varying DEFAULT NULL::character varying, p_status character varying DEFAULT NULL::character varying, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_userid integer DEFAULT 0, OUT p_result_message character varying, OUT p_result_data jsonb) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_new_requestid VARCHAR(12);
    v_current_record RECORD;
    v_update_type VARCHAR(20); -- 'ALL', 'APPROVAL', 'STATUS_ONLY'
    v_debug_flag INTEGER := 1; -- 1 = Enable audit logging for CRUD, 0 = Disable audit logging
    v_search_debug_flag INTEGER := 1; -- 1 = Enable audit logging for SEARCH, 0 = Disable (default off for production)
    v_audit_user VARCHAR(100);
    v_audit_data JSONB;
    v_audit_description TEXT;
    
    -- SEARCH variables
    v_search_records JSONB;
    v_total_count INTEGER;
    v_filtered_count INTEGER;
    v_search_criteria JSONB;
    
    -- Cross-branch access variables
    v_branchcode VARCHAR(10);
    v_instcode VARCHAR(4);
    v_crossbranch BOOLEAN := FALSE;
    v_branchname VARCHAR(100);
    v_username VARCHAR(30);
    v_user_branch_id INTEGER;
    
    -- NEW VARIABLES for stock management
    v_headoffice_branchcode VARCHAR(4) := '0000';
    v_available_stock INTEGER;
    v_booked_cards INTEGER := 0;
    v_card_numbers TEXT[]; -- To store booked card numbers if needed
    v_temp_card_number VARCHAR(19);
    v_booked_cards_cursor REFCURSOR;
    v_stock_check_result RECORD;
	v_booked_count INTEGER DEFAULT 0;
    v_approved_count INTEGER DEFAULT 0;
BEGIN
    -- Initialize outputs
    p_result_message := '';
    p_result_data := '{}'::JSONB;
    
    -- Determine audit user (priority: approvedby > requestedby > current user)
    v_audit_user := COALESCE(p_approvedby, p_requestedby, CURRENT_USER);
    
    -- Get user branch info for access control
    IF p_userid IS NOT NULL AND p_userid > 0 THEN
        RAISE NOTICE 'USER REQUESTING ID: %', p_userid;
        
        -- Get user info with explicit handling - JOIN with branch table to get branch_no
        SELECT u.branchid,
               LEFT(u.institutionid::TEXT, 4),
               u.crossbranch,
               b.branch_no,
               b.branch_name
          INTO v_user_branch_id, v_instcode, v_crossbranch, v_branchcode, v_branchname
        FROM users u
        LEFT JOIN branch b ON b.id = u.branchid
        WHERE u.id = p_userid;
        
        -- If user not found, use defaults
        IF NOT FOUND THEN
            v_crossbranch := FALSE;
            v_branchcode := NULL;
            v_instcode := NULL;
            v_branchname := NULL;
            RAISE NOTICE 'User ID % not found in users table, using limited access', p_userid;
        ELSE
            RAISE NOTICE 'User branch: % (code: %), Cross-branch: %', v_branchname, v_branchcode, v_crossbranch;
            
            -- Clean branch code (remove any whitespace)
            v_branchcode := TRIM(v_branchcode);
            
            -- Validate branch code
            IF v_branchcode IS NULL OR v_branchcode = '' THEN
                RAISE EXCEPTION 'User % has NULL or empty branch code. Please update user branch information.', p_userid;
            END IF;
        END IF;
        
        -- Get username for audit purposes
        SELECT username INTO v_username FROM authlogin WHERE userid = p_userid LIMIT 1;
        IF FOUND THEN
            v_audit_user := COALESCE(v_audit_user, v_username);
        END IF;
    ELSE
        -- No user ID provided, use limited access
        v_crossbranch := FALSE;
        v_branchcode := NULL;
        RAISE NOTICE 'No user ID provided, using limited access';
    END IF;
    
    -- Validate action (UPDATED to include SEARCH)
    IF p_action NOT IN ('INSERT', 'UPDATE', 'DELETE', 'SEARCH') THEN
        p_result_message := 'ERROR: Invalid action. Use INSERT, UPDATE, DELETE, or SEARCH';
        
        -- Audit log for invalid action if debug flag is 1
        IF v_debug_flag = 1 THEN
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD_CYCLE',
                'INVALID_ACTION',
                'Invalid action attempted: ' || p_action,
                jsonb_build_object(
                    'action', p_action,
                    'error', p_result_message,
                    'user', v_audit_user,
                    'user_id', p_userid
                )
            );
        END IF;
        RETURN;
    END IF;
    
    -- ACTION: SEARCH
    IF p_action = 'SEARCH' THEN
        BEGIN
            -- Build search criteria for audit logging (if enabled)
            v_search_criteria := jsonb_build_object(
                'requestid', p_requestid,
                'scheme', p_scheme,
                'cardtype', p_cardtype,
                'requestedby', p_requestedby,
                'approvedby', p_approvedby,
                'verifiedby', p_verifiedby,
                'requestbranchcode', p_requestbranchcode,
                'approvedbranchcode', p_approvedbranchcode,
                'verifiedbranchcode', p_verifiedbranchcode,
                'status', p_status,
                'start_date', p_start_date,
                'end_date', p_end_date,
                'user_id', p_userid,
                'user_branch', v_branchcode,
                'crossbranch_access', v_crossbranch
            );
            
            -- Get total count of all records
            SELECT COUNT(*) INTO v_total_count FROM instantcardcycle;
            
            -- Build dynamic query for search with branch access control
            IF p_requestid IS NOT NULL THEN
                -- EXCLUSIVE SEARCH: When requestid is provided, search ONLY by ID
                -- But check branch access if user doesn't have cross-branch privileges
                v_search_records := (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'requestid', icc.requestid,
                            'scheme', icc.scheme,
                            'cardtype', icc.cardtype,
                            'currency', icc.currency,
                            'totalnumberofcard', icc.totalnumberofcard,
							 'approved_cards', icc.approved_cards,        -- ADDED 13thfeb2026
            				'booked_cards', icc.booked_cards,            -- ADDED13thfeb2026
                            'flags', icc.flags,
                            'pintype', icc.pintype,
                            'requestedby', icc.requestedby,
                            'requestedbranchname', icc.requestedbranchname,
                            'requestbranchcode', icc.requestbranchcode,
                            'approvedby', icc.approvedby,
                            'approvedbranchcode', icc.approvedbranchcode,
                            'approvedbranchname', icc.approvedbranchname,
                            'verifiedby', icc.verifiedby,
                            'verifiedbranchname', icc.verifiedbranchname,
                            'verifiedbranchcode', icc.verifiedbranchcode,
                            'status', icc.status,
                            'requesteddate', icc.requesteddate,
                            'approvedate', icc.approvedate,
                            'verifieddate', icc.verifieddate,
							'bookedcardallocated', icc.bookedcardallocated,     -- ADDED 13thfeb2026
            				'approvedcardsallocated', icc.approvedcardsallocated -- ADDED 13thfeb2026
                        )
                    )
                    FROM instantcardcycle icc
                    WHERE icc.requestid = p_requestid
                    -- ADDED: Branch access check
                    AND (v_crossbranch = TRUE OR icc.requestbranchcode = v_branchcode 
                         OR (p_userid IS NULL OR p_userid = 0)) -- Allow if no user ID provided
                );
            ELSE
                -- NORMAL SEARCH: When no requestid provided, use all other filters
                -- ADDED: Apply branch filtering based on user privileges
                v_search_records := (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'requestid', icc.requestid,
                            'scheme', icc.scheme,
                            'cardtype', icc.cardtype,
                            'currency', icc.currency,
                           -- 'totalnumberofcard', icc.totalnumberofcard,
						     'totalnumberofcard', icc.totalnumberofcard, --st added feb-11-2026 to handle partial card request
                            'approved_cards', icc.approved_cards,        -- ADDED
            				'booked_cards', icc.booked_cards,            -- ADDED
							'flags', icc.flags,
                            'pintype', icc.pintype,
                            'requestedby', icc.requestedby,
                            'requestedbranchname', icc.requestedbranchname,
                            'requestbranchcode', icc.requestbranchcode,
                            'approvedby', icc.approvedby,
                            'approvedbranchcode', icc.approvedbranchcode,
                            'approvedbranchname', icc.approvedbranchname,
                            'verifiedby', icc.verifiedby,
                            'verifiedbranchname', icc.verifiedbranchname,
                            'verifiedbranchcode', icc.verifiedbranchcode,
                            'status', icc.status,
                            'requesteddate', icc.requesteddate,
                            'approvedate', icc.approvedate,
                            'verifieddate', icc.verifieddate,
							'bookedcardallocated', icc.bookedcardallocated,     -- ADDED
            				'approvedcardsallocated', icc.approvedcardsallocated -- ADDED
                        )
                        ORDER BY icc.requesteddate DESC
                    )
                    FROM instantcardcycle icc
                    WHERE 
                        (p_scheme IS NULL OR icc.scheme = p_scheme)
                        AND (p_cardtype IS NULL OR icc.cardtype = p_cardtype)
                        AND (p_requestedby IS NULL OR icc.requestedby = p_requestedby)
                        AND (p_approvedby IS NULL OR icc.approvedby = p_approvedby)
                        AND (p_verifiedby IS NULL OR icc.verifiedby = p_verifiedby)
                        AND (p_requestbranchcode IS NULL OR icc.requestbranchcode = p_requestbranchcode)
                        AND (p_approvedbranchcode IS NULL OR icc.approvedbranchcode = p_approvedbranchcode)
                        AND (p_verifiedbranchcode IS NULL OR icc.verifiedbranchcode = p_verifiedbranchcode)
                        AND (p_status IS NULL OR icc.status = p_status)
                        AND (p_start_date IS NULL OR DATE(icc.requesteddate) >= p_start_date)
                        AND (p_end_date IS NULL OR DATE(icc.requesteddate) <= p_end_date)
                        -- ADDED: Branch access control
                        AND (
                            v_crossbranch = TRUE 
                            OR icc.requestbranchcode = v_branchcode 
                            OR (p_userid IS NULL OR p_userid = 0) -- Allow if no user ID provided
                        )
                );
            END IF;
            
            -- Get filtered count
            IF v_search_records IS NULL THEN
                v_filtered_count := 0;
            ELSE
                v_filtered_count := jsonb_array_length(v_search_records);
            END IF;
            
            -- Prepare result data with access info
            p_result_data := jsonb_build_object(
                'search_criteria', v_search_criteria,
                'search_type', CASE WHEN p_requestid IS NOT NULL THEN 'ID_EXCLUSIVE' ELSE 'NORMAL' END,
                'total_records', v_total_count,
                'filtered_records', v_filtered_count,
                'user_access', jsonb_build_object(
                    'user_id', p_userid,
                    'branch_code', v_branchcode,
                    'crossbranch_access', v_crossbranch,
                    'branch_name', v_branchname
                ),
                'records', COALESCE(v_search_records, '[]'::jsonb)
            );
            
            IF p_requestid IS NOT NULL THEN
                p_result_message := 'SUCCESS: ID exclusive search completed. Found ' || v_filtered_count || ' record(s)';
            ELSE
                p_result_message := 'SUCCESS: Search completed. Found ' || v_filtered_count || ' records';
            END IF;
            
            -- Add access info to message if not cross-branch
            IF v_crossbranch = FALSE AND v_branchcode IS NOT NULL THEN
                p_result_message := p_result_message || ' (Filtered by branch: ' || v_branchcode || ')';
            ELSIF v_crossbranch = TRUE THEN
                p_result_message := p_result_message || ' (Cross-branch access enabled)';
            END IF;
            
            -- Audit log for SEARCH only if search debug flag is enabled
            IF v_search_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    CASE WHEN p_requestid IS NOT NULL THEN 'SEARCH_ID_EXCLUSIVE' ELSE 'SEARCH_SUCCESS' END,
                    'Search performed: ' || v_filtered_count || ' records found',
                    jsonb_build_object(
                        'search_criteria', v_search_criteria,
                        'total_records', v_total_count,
                        'filtered_records', v_filtered_count,
                        'search_type', CASE WHEN p_requestid IS NOT NULL THEN 'ID_EXCLUSIVE' ELSE 'NORMAL' END,
                        'user', v_audit_user,
                        'user_id', p_userid,
                        'branch_access', v_branchcode,
                        'crossbranch', v_crossbranch
                    )
                );
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            p_result_message := 'ERROR: Search failed - ' || SQLERRM;
            p_result_data := '{}'::JSONB;
            
            -- Audit log for SEARCH error only if search debug flag is enabled
            IF v_search_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    'SEARCH_ERROR',
                    'Search failed: ' || SQLERRM,
                    jsonb_build_object(
                        'error', SQLERRM,
                        'search_criteria', v_search_criteria,
                        'user', v_audit_user,
                        'user_id', p_userid
                    )
                );
            END IF;
        END;
        
        -- Return after SEARCH action
        RETURN;
    END IF;
    
    -- ACTION: INSERT (UPDATED with stock availability check)
    IF p_action = 'INSERT' THEN
        BEGIN
            -- Check for NULL required fields
            IF p_scheme IS NULL THEN
                p_result_message := 'ERROR: scheme is required';
                RETURN;
            END IF;
            IF p_cardtype IS NULL THEN
                p_result_message := 'ERROR: cardtype is required';
                RETURN;
            END IF;
            IF p_currency IS NULL THEN
                p_result_message := 'ERROR: currency is required';
                RETURN;
            END IF;
            IF p_totalnumberofcard IS NULL THEN
                p_result_message := 'ERROR: totalnumberofcard is required';
                RETURN;
            END IF;
            IF p_requestedby IS NULL THEN
                p_result_message := 'ERROR: requestedby is required';
                RETURN;
            END IF;
            
            -- ADDED: Use user's branch info if not provided
            IF p_requestedbranchname IS NULL AND v_branchname IS NOT NULL THEN
                p_requestedbranchname := v_branchname;
            END IF;
            
            IF p_requestbranchcode IS NULL THEN
                IF v_branchcode IS NOT NULL THEN
                    p_requestbranchcode := v_branchcode;
                ELSE
                    p_result_message := 'ERROR: requestbranchcode is required';
                    RETURN;
                END IF;
            END IF;
            
            -- ADDED: Validate user can create for this branch if branch code is provided
            IF p_requestbranchcode IS NOT NULL AND v_branchcode IS NOT NULL 
               AND p_requestbranchcode != v_branchcode AND v_crossbranch = FALSE THEN
                p_result_message := 'ERROR: You do not have permission to create records for branch: ' || 
                                   p_requestbranchcode || '. Your branch: ' || v_branchcode;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_ACCESS_DENIED',
                        'Branch access denied for INSERT',
                        jsonb_build_object(
                            'user_branch', v_branchcode,
                            'requested_branch', p_requestbranchcode,
                            'crossbranch', v_crossbranch,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Validate card count
            IF p_totalnumberofcard < 1 THEN
                p_result_message := 'ERROR: Minimum 10 cards required. Provided: ' || p_totalnumberofcard::text;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_VALIDATION_ERROR',
                        'Card count validation failed: ' || p_totalnumberofcard,
                        jsonb_build_object(
                            'provided_cards', p_totalnumberofcard,
                            'minimum_required', 10,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                RETURN;
            END IF;
            IF p_totalnumberofcard > 10000 THEN
                p_result_message := 'ERROR: Maximum 10000 cards allowed. Provided: ' || p_totalnumberofcard::text;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_VALIDATION_ERROR',
                        'Card count validation failed: ' || p_totalnumberofcard,
                        jsonb_build_object(
                            'provided_cards', p_totalnumberofcard,
                            'maximum_allowed', 10000,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
           
            
            -- Variable to store the status we'll insert with
            DECLARE
                v_insert_status VARCHAR(20) := COALESCE(p_status, 'PENDING');
            BEGIN
                INSERT INTO instantcardcycle (
                    scheme, cardtype, currency, totalnumberofcard, 
                    flags, pintype, requestedby, requestedbranchname, 
                    requestbranchcode, status
                ) VALUES (
                    p_scheme,
                    p_cardtype,
                    UPPER(p_currency),
                    p_totalnumberofcard,
                    p_flags,
                    p_pintype,
                    p_requestedby,
                    p_requestedbranchname,
                    p_requestbranchcode,
                    v_insert_status  -- Use the determined status
                )
                RETURNING requestid, jsonb_build_object(
                    'requestid', requestid,
                    'scheme', scheme,
                    'cardtype', cardtype,
                    'currency', currency,
                    'totalnumberofcard', totalnumberofcard,
                    'status', status,
                    'requesteddate', requesteddate,
                    'requestbranchcode', requestbranchcode,
                    'requestedbranchname', requestedbranchname,
                    'cards_available', v_available_stock,
                    'cards_requested', p_totalnumberofcard,
                    'cards_booked', v_booked_cards,
                    'stock_check_performed', CASE WHEN p_requestbranchcode != v_headoffice_branchcode THEN TRUE ELSE FALSE END,
                    'is_head_office', CASE WHEN p_requestbranchcode = v_headoffice_branchcode THEN TRUE ELSE FALSE END
                ) INTO v_new_requestid, p_result_data;
                
                p_result_message := 'SUCCESS: Record inserted for branch: ' || p_requestbranchcode || ' with status: ' || v_insert_status;
                
                -- Add stock info to message if applicable
                IF p_requestbranchcode != v_headoffice_branchcode THEN
                    IF v_insert_status = 'BOOKED' THEN
                        p_result_message := p_result_message || ' - Sufficient stock available';
                    ELSE
                        p_result_message := p_result_message || ' - Insufficient stock (Available: ' || v_available_stock || ' cards)';
                    END IF;
                END IF;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_SUCCESS',
                        'Instant card cycle created: ' || v_new_requestid || ' with status: ' || v_insert_status,
                        jsonb_build_object(
                            'requestid', v_new_requestid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'total_cards', p_totalnumberofcard,
                            'status', v_insert_status,
                            'branch', p_requestbranchcode,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'user_branch', v_branchcode,
                            'crossbranch', v_crossbranch,
                            'stock_available', v_available_stock,
                            'cards_requested', p_totalnumberofcard,
                            'is_head_office', CASE WHEN p_requestbranchcode = v_headoffice_branchcode THEN TRUE ELSE FALSE END
                        )
                    );
                END IF;
            END;
            
        EXCEPTION 
            WHEN not_null_violation THEN
                p_result_message := 'ERROR: Required field is missing';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_CONSTRAINT_ERROR',
                        'Not null constraint violation',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                
            WHEN check_violation THEN
                p_result_message := 'ERROR: Data validation failed';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_CONSTRAINT_ERROR',
                        'Check constraint violation',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                
            WHEN OTHERS THEN
                p_result_message := 'ERROR: ' || SQLERRM;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_ERROR',
                        'Insert failed: ' || SQLERRM,
                        jsonb_build_object(
                            'error', SQLERRM,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'total_cards', p_totalnumberofcard,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
        END;
        
    -- ACTION: UPDATE (UPDATED with branch access control)
    ELSIF p_action = 'UPDATE' THEN
        BEGIN
            IF p_requestid IS NULL THEN
                p_result_message := 'ERROR: requestid is required for UPDATE';
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_VALIDATION_ERROR',
                        'Missing requestid for UPDATE',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            -- Get current record
            SELECT * INTO v_current_record 
            FROM instantcardcycle 
            WHERE requestid = p_requestid;
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found with requestid: ' || p_requestid;
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_NOT_FOUND',
                        'Record not found: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            -- ADDED: Check if user has access to this record's branch
            IF v_branchcode IS NOT NULL AND v_crossbranch = FALSE 
               AND v_current_record.requestbranchcode != v_branchcode THEN
                p_result_message := 'ERROR: You do not have permission to update this record. ' ||
                                   'Record belongs to branch: ' || v_current_record.requestbranchcode || 
                                   ', Your branch: ' || v_branchcode;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_ACCESS_DENIED',
                        'Branch access denied for UPDATE',
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'record_branch', v_current_record.requestbranchcode,
                            'user_branch', v_branchcode,
                            'crossbranch', v_crossbranch,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            -- Prepare audit data for UPDATE if debug flag is 1
            IF v_debug_flag = 1 THEN
                v_audit_data := jsonb_build_object(
                    'requestid', p_requestid,
                    'old_status', v_current_record.status,
                    'new_status', p_status,
                    'user', v_audit_user,
                    'user_id', p_userid,
                    'user_branch', v_branchcode,
                    'record_branch', v_current_record.requestbranchcode,
                    'crossbranch', v_crossbranch,
                    'old_approvedby', v_current_record.approvedby,
                    'new_approvedby', p_approvedby,
                    'old_verifiedby', v_current_record.verifiedby,
                    'new_verifiedby', p_verifiedby,
                    'old_verifiedbranchcode', v_current_record.verifiedbranchcode,
                    'new_verifiedbranchcode', p_verifiedbranchcode,
                    'changes', jsonb_build_object()
                );
            END IF;
            
            -- Determine update type based on provided parameters
            IF p_scheme IS NOT NULL OR p_cardtype IS NOT NULL OR p_currency IS NOT NULL OR
               p_totalnumberofcard IS NOT NULL OR p_flags IS NOT NULL OR p_pintype IS NOT NULL OR
               p_requestedby IS NOT NULL OR p_requestedbranchname IS NOT NULL OR p_requestbranchcode IS NOT NULL THEN
                -- Type 1: Update all fields (if any non-approval field is provided)
                v_update_type := 'ALL';
                RAISE NOTICE 'Setting v_update_type as %',v_update_type;
                -- ADDED: Check if user can change branch if requestbranchcode is being updated
                IF p_requestbranchcode IS NOT NULL AND v_branchcode IS NOT NULL 
                   AND p_requestbranchcode != v_current_record.requestbranchcode 
                   AND v_crossbranch = FALSE THEN
                    p_result_message := 'ERROR: You do not have permission to change record branch. ' ||
                                       'Current branch: ' || v_current_record.requestbranchcode || 
                                       ', New branch: ' || p_requestbranchcode;
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_ACCESS_DENIED',
                            'Branch change denied for UPDATE',
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'old_branch', v_current_record.requestbranchcode,
                                'new_branch', p_requestbranchcode,
                                'user_branch', v_branchcode,
                                'crossbranch', v_crossbranch,
                                'user', v_audit_user,
                                'user_id', p_userid
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
                -- Validate card count if provided
                IF p_totalnumberofcard IS NOT NULL THEN
                    IF p_totalnumberofcard < 1 THEN
                        p_result_message := 'ERROR: Minimum 10 cards required. Provided: ' || p_totalnumberofcard::text;
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Card count validation failed: ' || p_totalnumberofcard,
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'provided_cards', p_totalnumberofcard,
                                    'minimum_required', 10,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_cards', v_current_record.totalnumberofcard
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                    
                    IF p_totalnumberofcard > 10000 THEN
                        p_result_message := 'ERROR: Maximum 10000 cards allowed. Provided: ' || p_totalnumberofcard::text;
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Card count validation failed: ' || p_totalnumberofcard,
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'provided_cards', p_totalnumberofcard,
                                    'maximum_allowed', 10000,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_cards', v_current_record.totalnumberofcard
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                END IF;
                
            ELSIF p_approvedby IS NOT NULL OR p_approvedbranchcode IS NOT NULL OR 
                  p_approvedbranchname IS NOT NULL OR p_verifiedby IS NOT NULL OR
                  p_verifiedbranchname IS NOT NULL OR p_verifiedbranchcode IS NOT NULL OR 
                  p_status IS NOT NULL THEN
                -- Type 2: Update approval/verification fields + status
                v_update_type := 'APPROVAL';
                 RAISE NOTICE 'Setting v_update_type as %',v_update_type;
                -- Validate status if provided
                IF p_status IS NOT NULL AND p_status NOT IN ('PENDING', 'APPROVED', 'REJECTED', 'PROCESSING', 'COMPLETED', 'VERIFIED') THEN
                    p_result_message := 'ERROR: Invalid status value: ' || p_status;
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_VALIDATION_ERROR',
                            'Invalid status value: ' || p_status,
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'invalid_status', p_status,
                                'user', v_audit_user,
                                'user_id', p_userid,
                                'current_status', v_current_record.status
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
            ELSE
                -- Type 3: No fields to update
                p_result_message := 'ERROR: No fields provided for update';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_VALIDATION_ERROR',
                        'No fields provided for update',
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Validate status transitions
            IF p_status IS NOT NULL THEN
                -- Cannot update COMPLETED records
                IF v_current_record.status = 'COMPLETED' THEN
                    p_result_message := 'ERROR: Cannot update completed cycle';
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
