                        'UPDATE_ERROR',
                        'Record not found during update: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
            ELSE
                -- ADDED: Include user access info in success message
                IF v_crossbranch = FALSE AND v_branchcode IS NOT NULL THEN
                    p_result_message := p_result_message || ' (User branch: ' || v_branchcode || ')';
                END IF;
                
                IF v_debug_flag = 1 AND v_audit_description IS NOT NULL THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_SUCCESS',
                        v_audit_description,
                        v_audit_data
                    );
                END IF;
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            p_result_message := 'ERROR: ' || SQLERRM;
            p_result_data := '{}'::JSONB;
            
            IF v_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    'UPDATE_ERROR',
                    'Update failed: ' || p_requestid || ' - ' || SQLERRM,
                    jsonb_build_object(
                        'requestid', p_requestid,
                        'error', SQLERRM,
                        'user', v_audit_user,
                        'user_id', p_userid
                    )
                );
            END IF;
        END;-- END OF UPDATE PART
        
    -- ACTION: DELETE (UPDATED with branch access control)
    ELSIF p_action = 'DELETE' THEN
        BEGIN
            IF p_requestid IS NULL THEN
                p_result_message := 'ERROR: requestid is required for DELETE';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_VALIDATION_ERROR',
                        'Missing requestid for DELETE',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Get record before deletion for audit logging
            SELECT * INTO v_current_record 
            FROM instantcardcycle 
            WHERE requestid = p_requestid;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_NOT_FOUND',
                        'Record not found for deletion: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- ADDED: Check if user has access to this record's branch
            IF v_branchcode IS NOT NULL AND v_crossbranch = FALSE 
               AND v_current_record.requestbranchcode != v_branchcode THEN
                p_result_message := 'ERROR: You do not have permission to delete this record. ' ||
                                   'Record belongs to branch: ' || v_current_record.requestbranchcode || 
                                   ', Your branch: ' || v_branchcode;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_ACCESS_DENIED',
                        'Branch access denied for DELETE',
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'record_branch', v_current_record.requestbranchcode,
                            'user_branch', v_branchcode,
                            'crossbranch', v_crossbranch,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Only allow deletion of PENDING or REJECTED records
            IF v_current_record.status NOT IN ('PENDING', 'REJECTED') THEN
                p_result_message := 'ERROR: Cannot delete record with status: ' || v_current_record.status;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_VALIDATION_ERROR',
                        'Delete failed - invalid status: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'status', v_current_record.status,
                            'allowed_statuses', 'PENDING, REJECTED',
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Prepare audit data for DELETE if debug flag is 1
            IF v_debug_flag = 1 THEN
                v_audit_data := jsonb_build_object(
                    'requestid', p_requestid,
                    'scheme', v_current_record.scheme,
                    'cardtype', v_current_record.cardtype,
                    'total_cards', v_current_record.totalnumberofcard,
                    'status', v_current_record.status,
                    'branch', v_current_record.requestbranchcode,
                    'requested_by', v_current_record.requestedby,
                    'approved_by', v_current_record.approvedby,
                    'verified_by', v_current_record.verifiedby,
                    'user', v_audit_user,
                    'user_id', p_userid,
                    'user_branch', v_branchcode,
                    'record_branch', v_current_record.requestbranchcode,
                    'crossbranch', v_crossbranch
                );
            END IF;
            
            -- Delete record
            DELETE FROM instantcardcycle 
            WHERE requestid = p_requestid;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_ERROR',
                        'Record not found during deletion: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
            ELSE
                p_result_message := 'SUCCESS: Record deleted from branch: ' || v_current_record.requestbranchcode;
                p_result_data := jsonb_build_object(
                    'deleted_requestid', p_requestid,
                    'deleted_branch', v_current_record.requestbranchcode,
                    'user_branch', v_branchcode
                );
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_SUCCESS',
                        'Instant card cycle deleted: ' || p_requestid,
                        v_audit_data
                    );
                END IF;
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            p_result_message := 'ERROR: ' || SQLERRM;
            
            IF v_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    'DELETE_ERROR',
                    'Delete failed: ' || p_requestid || ' - ' || SQLERRM,
                    jsonb_build_object(
                        'requestid', p_requestid,
                        'error', SQLERRM,
                        'user', v_audit_user,
                        'user_id', p_userid
                    )
                );
            END IF;
        END;
        
   			 	END IF;
    
END;
$$;


ALTER FUNCTION public.finstantcardcycle(p_action character varying, p_requestid character varying, p_scheme character varying, p_cardtype character varying, p_currency character varying, p_totalnumberofcard integer, p_flags character varying, p_pintype character varying, p_requestedby character varying, p_requestedbranchname character varying, p_requestbranchcode character varying, p_approvedby character varying, p_approvedbranchcode character varying, p_approvedbranchname character varying, p_verifiedby character varying, p_verifiedbranchname character varying, p_verifiedbranchcode character varying, p_status character varying, p_start_date date, p_end_date date, p_userid integer, OUT p_result_message character varying, OUT p_result_data jsonb) OWNER TO postgres;

--
-- TOC entry 476 (class 1255 OID 31247)
-- Name: finstantcardcycle_backup_mar26(character varying, character varying, character varying, character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, date, date, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstantcardcycle_backup_mar26(p_action character varying, p_requestid character varying DEFAULT NULL::character varying, p_scheme character varying DEFAULT NULL::character varying, p_cardtype character varying DEFAULT NULL::character varying, p_currency character varying DEFAULT NULL::character varying, p_totalnumberofcard integer DEFAULT NULL::integer, p_flags character varying DEFAULT NULL::character varying, p_pintype character varying DEFAULT NULL::character varying, p_requestedby character varying DEFAULT NULL::character varying, p_requestedbranchname character varying DEFAULT NULL::character varying, p_requestbranchcode character varying DEFAULT NULL::character varying, p_approvedby character varying DEFAULT NULL::character varying, p_approvedbranchcode character varying DEFAULT NULL::character varying, p_approvedbranchname character varying DEFAULT NULL::character varying, p_verifiedby character varying DEFAULT NULL::character varying, p_verifiedbranchname character varying DEFAULT NULL::character varying, p_verifiedbranchcode character varying DEFAULT NULL::character varying, p_status character varying DEFAULT NULL::character varying, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_userid integer DEFAULT 0, OUT p_result_message character varying, OUT p_result_data jsonb) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_new_requestid VARCHAR(12);
    v_current_record RECORD;
    v_update_type VARCHAR(20); -- 'ALL', 'APPROVAL', 'STATUS_ONLY'
    v_debug_flag INTEGER := 1; -- 1 = Enable audit logging for CRUD, 0 = Disable audit logging
    v_search_debug_flag INTEGER := 1; -- 1 = Enable audit logging for SEARCH, 0 = Disable (default off for production)
    v_audit_user VARCHAR(100);
    v_audit_data JSONB;
    v_audit_description TEXT;
    
    -- SEARCH variables
    v_search_records JSONB;
    v_total_count INTEGER;
    v_filtered_count INTEGER;
    v_search_criteria JSONB;
    
    -- Cross-branch access variables (ADDED)
    v_branchcode VARCHAR(10);
    v_instcode VARCHAR(4);
    v_crossbranch BOOLEAN := FALSE;
    v_branchname VARCHAR(100);
    v_username VARCHAR(30);
    v_user_branch_id INTEGER;
	v_headoffice_branchcode VARCHAR(4)='0000';
BEGIN
    -- Initialize outputs
    p_result_message := '';
    p_result_data := '{}'::JSONB;
    
    -- Determine audit user (priority: approvedby > requestedby > current user)
    v_audit_user := COALESCE(p_approvedby, p_requestedby, CURRENT_USER);
    
    -- Get user branch info for access control (ADDED - Similar to reference function)
    IF p_userid IS NOT NULL AND p_userid > 0 THEN
        RAISE NOTICE 'USER REQUESTING ID: %', p_userid;
        
        -- Get user info with explicit handling - JOIN with branch table to get branch_no
        SELECT u.branchid,
               LEFT(u.institutionid::TEXT, 4),
               u.crossbranch,
               b.branch_no,
               b.branch_name
          INTO v_user_branch_id, v_instcode, v_crossbranch, v_branchcode, v_branchname
        FROM users u
        LEFT JOIN branch b ON b.id = u.branchid
        WHERE u.id = p_userid;
        
        -- If user not found, use defaults
        IF NOT FOUND THEN
            v_crossbranch := FALSE;
            v_branchcode := NULL;
            v_instcode := NULL;
            v_branchname := NULL;
            RAISE NOTICE 'User ID % not found in users table, using limited access', p_userid;
        ELSE
            RAISE NOTICE 'User branch: % (code: %), Cross-branch: %', v_branchname, v_branchcode, v_crossbranch;
            
            -- Clean branch code (remove any whitespace)
            v_branchcode := TRIM(v_branchcode);
            
            -- Validate branch code
            IF v_branchcode IS NULL OR v_branchcode = '' THEN
                RAISE EXCEPTION 'User % has NULL or empty branch code. Please update user branch information.', p_userid;
            END IF;
        END IF;
        
        -- Get username for audit purposes
        SELECT username INTO v_username FROM authlogin WHERE userid = p_userid LIMIT 1;
        IF FOUND THEN
            v_audit_user := COALESCE(v_audit_user, v_username);
        END IF;
    ELSE
        -- No user ID provided, use limited access
        v_crossbranch := FALSE;
        v_branchcode := NULL;
        RAISE NOTICE 'No user ID provided, using limited access';
    END IF;
    
    -- Validate action (UPDATED to include SEARCH)
    IF p_action NOT IN ('INSERT', 'UPDATE', 'DELETE', 'SEARCH') THEN
        p_result_message := 'ERROR: Invalid action. Use INSERT, UPDATE, DELETE, or SEARCH';
        
        -- Audit log for invalid action if debug flag is 1
        IF v_debug_flag = 1 THEN
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD_CYCLE',
                'INVALID_ACTION',
                'Invalid action attempted: ' || p_action,
                jsonb_build_object(
                    'action', p_action,
                    'error', p_result_message,
                    'user', v_audit_user,
                    'user_id', p_userid
                )
            );
        END IF;
        RETURN;
    END IF;
    
    -- ACTION: SEARCH (UPDATED with cross-branch access control)
    IF p_action = 'SEARCH' THEN
        BEGIN
            -- Build search criteria for audit logging (if enabled)
            v_search_criteria := jsonb_build_object(
                'requestid', p_requestid,
                'scheme', p_scheme,
                'cardtype', p_cardtype,
                'requestedby', p_requestedby,
                'approvedby', p_approvedby,
                'verifiedby', p_verifiedby,
                'requestbranchcode', p_requestbranchcode,
                'approvedbranchcode', p_approvedbranchcode,
                'verifiedbranchcode', p_verifiedbranchcode,
                'status', p_status,
                'start_date', p_start_date,
                'end_date', p_end_date,
                'user_id', p_userid,
                'user_branch', v_branchcode,
                'crossbranch_access', v_crossbranch
            );
            
            -- Get total count of all records
            SELECT COUNT(*) INTO v_total_count FROM instantcardcycle;
            
            -- Build dynamic query for search with branch access control
            IF p_requestid IS NOT NULL THEN
                -- EXCLUSIVE SEARCH: When requestid is provided, search ONLY by ID
                -- But check branch access if user doesn't have cross-branch privileges
                v_search_records := (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'requestid', icc.requestid,
                            'scheme', icc.scheme,
                            'cardtype', icc.cardtype,
                            'currency', icc.currency,
                            'totalnumberofcard', icc.totalnumberofcard,
                            'flags', icc.flags,
                            'pintype', icc.pintype,
                            'requestedby', icc.requestedby,
                            'requestedbranchname', icc.requestedbranchname,
                            'requestbranchcode', icc.requestbranchcode,
                            'approvedby', icc.approvedby,
                            'approvedbranchcode', icc.approvedbranchcode,
                            'approvedbranchname', icc.approvedbranchname,
                            'verifiedby', icc.verifiedby,
                            'verifiedbranchname', icc.verifiedbranchname,
                            'verifiedbranchcode', icc.verifiedbranchcode,
                            'status', icc.status,
                            'requesteddate', icc.requesteddate,
                            'approvedate', icc.approvedate,
                            'verifieddate', icc.verifieddate
                        )
                    )
                    FROM instantcardcycle icc
                    WHERE icc.requestid = p_requestid
                    -- ADDED: Branch access check
                    AND (v_crossbranch = TRUE OR icc.requestbranchcode = v_branchcode 
                         OR (p_userid IS NULL OR p_userid = 0)) -- Allow if no user ID provided
                );
            ELSE
                -- NORMAL SEARCH: When no requestid provided, use all other filters
                -- ADDED: Apply branch filtering based on user privileges
                v_search_records := (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'requestid', icc.requestid,
                            'scheme', icc.scheme,
                            'cardtype', icc.cardtype,
                            'currency', icc.currency,
                            'totalnumberofcard', icc.totalnumberofcard,
                            'flags', icc.flags,
                            'pintype', icc.pintype,
                            'requestedby', icc.requestedby,
                            'requestedbranchname', icc.requestedbranchname,
                            'requestbranchcode', icc.requestbranchcode,
                            'approvedby', icc.approvedby,
                            'approvedbranchcode', icc.approvedbranchcode,
                            'approvedbranchname', icc.approvedbranchname,
                            'verifiedby', icc.verifiedby,
                            'verifiedbranchname', icc.verifiedbranchname,
                            'verifiedbranchcode', icc.verifiedbranchcode,
                            'status', icc.status,
                            'requesteddate', icc.requesteddate,
                            'approvedate', icc.approvedate,
                            'verifieddate', icc.verifieddate
                        )
                        ORDER BY icc.requesteddate DESC
                    )
                    FROM instantcardcycle icc
                    WHERE 
                        (p_scheme IS NULL OR icc.scheme = p_scheme)
                        AND (p_cardtype IS NULL OR icc.cardtype = p_cardtype)
                        AND (p_requestedby IS NULL OR icc.requestedby = p_requestedby)
                        AND (p_approvedby IS NULL OR icc.approvedby = p_approvedby)
                        AND (p_verifiedby IS NULL OR icc.verifiedby = p_verifiedby)
                        AND (p_requestbranchcode IS NULL OR icc.requestbranchcode = p_requestbranchcode)
                        AND (p_approvedbranchcode IS NULL OR icc.approvedbranchcode = p_approvedbranchcode)
                        AND (p_verifiedbranchcode IS NULL OR icc.verifiedbranchcode = p_verifiedbranchcode)
                        AND (p_status IS NULL OR icc.status = p_status)
                        AND (p_start_date IS NULL OR DATE(icc.requesteddate) >= p_start_date)
                        AND (p_end_date IS NULL OR DATE(icc.requesteddate) <= p_end_date)
                        -- ADDED: Branch access control
                        AND (
                            v_crossbranch = TRUE 
                            OR icc.requestbranchcode = v_branchcode 
                            OR (p_userid IS NULL OR p_userid = 0) -- Allow if no user ID provided
                        )
                );
            END IF;
            
            -- Get filtered count
            IF v_search_records IS NULL THEN
                v_filtered_count := 0;
            ELSE
                v_filtered_count := jsonb_array_length(v_search_records);
            END IF;
            
            -- Prepare result data with access info
            p_result_data := jsonb_build_object(
                'search_criteria', v_search_criteria,
                'search_type', CASE WHEN p_requestid IS NOT NULL THEN 'ID_EXCLUSIVE' ELSE 'NORMAL' END,
                'total_records', v_total_count,
                'filtered_records', v_filtered_count,
                'user_access', jsonb_build_object(
                    'user_id', p_userid,
                    'branch_code', v_branchcode,
                    'crossbranch_access', v_crossbranch,
                    'branch_name', v_branchname
                ),
                'records', COALESCE(v_search_records, '[]'::jsonb)
            );
            
            IF p_requestid IS NOT NULL THEN
                p_result_message := 'SUCCESS: ID exclusive search completed. Found ' || v_filtered_count || ' record(s)';
            ELSE
                p_result_message := 'SUCCESS: Search completed. Found ' || v_filtered_count || ' records';
            END IF;
            
            -- Add access info to message if not cross-branch
            IF v_crossbranch = FALSE AND v_branchcode IS NOT NULL THEN
                p_result_message := p_result_message || ' (Filtered by branch: ' || v_branchcode || ')';
            ELSIF v_crossbranch = TRUE THEN
                p_result_message := p_result_message || ' (Cross-branch access enabled)';
            END IF;
            
            -- Audit log for SEARCH only if search debug flag is enabled
            IF v_search_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    CASE WHEN p_requestid IS NOT NULL THEN 'SEARCH_ID_EXCLUSIVE' ELSE 'SEARCH_SUCCESS' END,
                    'Search performed: ' || v_filtered_count || ' records found',
                    jsonb_build_object(
                        'search_criteria', v_search_criteria,
                        'total_records', v_total_count,
                        'filtered_records', v_filtered_count,
                        'search_type', CASE WHEN p_requestid IS NOT NULL THEN 'ID_EXCLUSIVE' ELSE 'NORMAL' END,
                        'user', v_audit_user,
                        'user_id', p_userid,
                        'branch_access', v_branchcode,
                        'crossbranch', v_crossbranch
                    )
                );
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            p_result_message := 'ERROR: Search failed - ' || SQLERRM;
            p_result_data := '{}'::JSONB;
            
            -- Audit log for SEARCH error only if search debug flag is enabled
            IF v_search_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    'SEARCH_ERROR',
                    'Search failed: ' || SQLERRM,
                    jsonb_build_object(
                        'error', SQLERRM,
                        'search_criteria', v_search_criteria,
                        'user', v_audit_user,
                        'user_id', p_userid
                    )
                );
            END IF;
        END;
        
        -- Return after SEARCH action
        RETURN;
    END IF;
    
    -- ACTION: INSERT (UPDATED with branch validation)
    IF p_action = 'INSERT' THEN
        BEGIN
            -- Check for NULL required fields
            IF p_scheme IS NULL THEN
                p_result_message := 'ERROR: scheme is required';
                RETURN;
            END IF;
            IF p_cardtype IS NULL THEN
                p_result_message := 'ERROR: cardtype is required';
                RETURN;
            END IF;
            IF p_currency IS NULL THEN
                p_result_message := 'ERROR: currency is required';
                RETURN;
            END IF;
            IF p_totalnumberofcard IS NULL THEN
                p_result_message := 'ERROR: totalnumberofcard is required';
                RETURN;
            END IF;
            IF p_requestedby IS NULL THEN
                p_result_message := 'ERROR: requestedby is required';
                RETURN;
            END IF;
            
            -- ADDED: Use user's branch info if not provided
            IF p_requestedbranchname IS NULL AND v_branchname IS NOT NULL THEN
                p_requestedbranchname := v_branchname;
            END IF;
            
            IF p_requestbranchcode IS NULL THEN
                IF v_branchcode IS NOT NULL THEN
                    p_requestbranchcode := v_branchcode;
                ELSE
                    p_result_message := 'ERROR: requestbranchcode is required';
                    RETURN;
                END IF;
            END IF;
            
            -- ADDED: Validate user can create for this branch if branch code is provided
            IF p_requestbranchcode IS NOT NULL AND v_branchcode IS NOT NULL 
               AND p_requestbranchcode != v_branchcode AND v_crossbranch = FALSE THEN
                p_result_message := 'ERROR: You do not have permission to create records for branch: ' || 
                                   p_requestbranchcode || '. Your branch: ' || v_branchcode;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_ACCESS_DENIED',
                        'Branch access denied for INSERT',
                        jsonb_build_object(
                            'user_branch', v_branchcode,
                            'requested_branch', p_requestbranchcode,
                            'crossbranch', v_crossbranch,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Validate card count
            IF p_totalnumberofcard < 10 THEN
                p_result_message := 'ERROR: Minimum 10 cards required. Provided: ' || p_totalnumberofcard::text;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_VALIDATION_ERROR',
                        'Card count validation failed: ' || p_totalnumberofcard,
                        jsonb_build_object(
                            'provided_cards', p_totalnumberofcard,
                            'minimum_required', 10,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            IF p_totalnumberofcard > 10000 THEN
                p_result_message := 'ERROR: Maximum 10000 cards allowed. Provided: ' || p_totalnumberofcard::text;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_VALIDATION_ERROR',
                        'Card count validation failed: ' || p_totalnumberofcard,
                        jsonb_build_object(
                            'provided_cards', p_totalnumberofcard,
                            'maximum_allowed', 10000,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Insert record
            INSERT INTO instantcardcycle (
                scheme, cardtype, currency, totalnumberofcard, 
                flags, pintype, requestedby, requestedbranchname, 
                requestbranchcode, status
            ) VALUES (
                p_scheme,
                p_cardtype,
                UPPER(p_currency),
                p_totalnumberofcard,
                p_flags,
                p_pintype,
                p_requestedby,
                p_requestedbranchname,
                p_requestbranchcode,
                COALESCE(p_status, 'PENDING')
            )
            RETURNING requestid, jsonb_build_object(
                'requestid', requestid,
                'scheme', scheme,
                'cardtype', cardtype,
                'currency', currency,
                'totalnumberofcard', totalnumberofcard,
                'status', status,
                'requesteddate', requesteddate,
                'requestbranchcode', requestbranchcode,
                'requestedbranchname', requestedbranchname
            ) INTO v_new_requestid, p_result_data;
            
            p_result_message := 'SUCCESS: Record inserted for branch: ' || p_requestbranchcode;
            
            IF v_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    'INSERT_SUCCESS',
                    'Instant card cycle created: ' || v_new_requestid,
                    jsonb_build_object(
                        'requestid', v_new_requestid,
                        'scheme', p_scheme,
                        'cardtype', p_cardtype,
                        'total_cards', p_totalnumberofcard,
                        'status', COALESCE(p_status, 'PENDING'),
                        'branch', p_requestbranchcode,
                        'user', v_audit_user,
                        'user_id', p_userid,
                        'user_branch', v_branchcode,
                        'crossbranch', v_crossbranch
                    )
                );
            END IF;
            
        EXCEPTION 
            WHEN not_null_violation THEN
                p_result_message := 'ERROR: Required field is missing';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_CONSTRAINT_ERROR',
                        'Not null constraint violation',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                
            WHEN check_violation THEN
                p_result_message := 'ERROR: Data validation failed';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_CONSTRAINT_ERROR',
                        'Check constraint violation',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                
            WHEN OTHERS THEN
                p_result_message := 'ERROR: ' || SQLERRM;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_ERROR',
                        'Insert failed: ' || SQLERRM,
                        jsonb_build_object(
                            'error', SQLERRM,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'total_cards', p_totalnumberofcard,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
        END;
        
    -- ACTION: UPDATE (UPDATED with branch access control)
    ELSIF p_action = 'UPDATE' THEN
        BEGIN
            IF p_requestid IS NULL THEN
                p_result_message := 'ERROR: requestid is required for UPDATE';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_VALIDATION_ERROR',
                        'Missing requestid for UPDATE',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Get current record
            SELECT * INTO v_current_record 
            FROM instantcardcycle 
            WHERE requestid = p_requestid;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found with requestid: ' || p_requestid;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_NOT_FOUND',
                        'Record not found: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- ADDED: Check if user has access to this record's branch
            IF v_branchcode IS NOT NULL AND v_crossbranch = FALSE 
               AND v_current_record.requestbranchcode != v_branchcode THEN
                p_result_message := 'ERROR: You do not have permission to update this record. ' ||
                                   'Record belongs to branch: ' || v_current_record.requestbranchcode || 
                                   ', Your branch: ' || v_branchcode;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_ACCESS_DENIED',
                        'Branch access denied for UPDATE',
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'record_branch', v_current_record.requestbranchcode,
                            'user_branch', v_branchcode,
                            'crossbranch', v_crossbranch,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Prepare audit data for UPDATE if debug flag is 1
            IF v_debug_flag = 1 THEN
                v_audit_data := jsonb_build_object(
                    'requestid', p_requestid,
                    'old_status', v_current_record.status,
                    'new_status', p_status,
                    'user', v_audit_user,
                    'user_id', p_userid,
                    'user_branch', v_branchcode,
                    'record_branch', v_current_record.requestbranchcode,
                    'crossbranch', v_crossbranch,
                    'old_approvedby', v_current_record.approvedby,
                    'new_approvedby', p_approvedby,
                    'old_verifiedby', v_current_record.verifiedby,
                    'new_verifiedby', p_verifiedby,
                    'old_verifiedbranchcode', v_current_record.verifiedbranchcode,
                    'new_verifiedbranchcode', p_verifiedbranchcode,
                    'changes', jsonb_build_object()
                );
            END IF;
            
            -- Determine update type based on provided parameters
            IF p_scheme IS NOT NULL OR p_cardtype IS NOT NULL OR p_currency IS NOT NULL OR
               p_totalnumberofcard IS NOT NULL OR p_flags IS NOT NULL OR p_pintype IS NOT NULL OR
               p_requestedby IS NOT NULL OR p_requestedbranchname IS NOT NULL OR p_requestbranchcode IS NOT NULL THEN
                -- Type 1: Update all fields (if any non-approval field is provided)
                v_update_type := 'ALL';
                
                -- ADDED: Check if user can change branch if requestbranchcode is being updated
                IF p_requestbranchcode IS NOT NULL AND v_branchcode IS NOT NULL 
                   AND p_requestbranchcode != v_current_record.requestbranchcode 
                   AND v_crossbranch = FALSE THEN
                    p_result_message := 'ERROR: You do not have permission to change record branch. ' ||
                                       'Current branch: ' || v_current_record.requestbranchcode || 
                                       ', New branch: ' || p_requestbranchcode;
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_ACCESS_DENIED',
                            'Branch change denied for UPDATE',
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'old_branch', v_current_record.requestbranchcode,
                                'new_branch', p_requestbranchcode,
                                'user_branch', v_branchcode,
                                'crossbranch', v_crossbranch,
                                'user', v_audit_user,
                                'user_id', p_userid
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
                -- Validate card count if provided
                IF p_totalnumberofcard IS NOT NULL THEN
                    IF p_totalnumberofcard < 10 THEN
                        p_result_message := 'ERROR: Minimum 10 cards required. Provided: ' || p_totalnumberofcard::text;
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Card count validation failed: ' || p_totalnumberofcard,
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'provided_cards', p_totalnumberofcard,
                                    'minimum_required', 10,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_cards', v_current_record.totalnumberofcard
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                    
                    IF p_totalnumberofcard > 10000 THEN
                        p_result_message := 'ERROR: Maximum 10000 cards allowed. Provided: ' || p_totalnumberofcard::text;
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Card count validation failed: ' || p_totalnumberofcard,
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'provided_cards', p_totalnumberofcard,
                                    'maximum_allowed', 10000,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_cards', v_current_record.totalnumberofcard
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                END IF;
                
            ELSIF p_approvedby IS NOT NULL OR p_approvedbranchcode IS NOT NULL OR 
                  p_approvedbranchname IS NOT NULL OR p_verifiedby IS NOT NULL OR
                  p_verifiedbranchname IS NOT NULL OR p_verifiedbranchcode IS NOT NULL OR 
                  p_status IS NOT NULL THEN
                -- Type 2: Update approval/verification fields + status
                v_update_type := 'APPROVAL';
                
                -- Validate status if provided
                IF p_status IS NOT NULL AND p_status NOT IN ('PENDING', 'APPROVED', 'REJECTED', 'PROCESSING', 'COMPLETED', 'VERIFIED') THEN
                    p_result_message := 'ERROR: Invalid status value: ' || p_status;
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_VALIDATION_ERROR',
                            'Invalid status value: ' || p_status,
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'invalid_status', p_status,
                                'user', v_audit_user,
                                'user_id', p_userid,
                                'current_status', v_current_record.status
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
            ELSE
                -- Type 3: No fields to update
                p_result_message := 'ERROR: No fields provided for update';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_VALIDATION_ERROR',
                        'No fields provided for update',
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Validate status transitions
            IF p_status IS NOT NULL THEN
                -- Cannot update COMPLETED records
                IF v_current_record.status = 'COMPLETED' THEN
                    p_result_message := 'ERROR: Cannot update completed cycle';
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_VALIDATION_ERROR',
                            'Attempt to update completed cycle',
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'current_status', v_current_record.status,
                                'requested_status', p_status,
                                'user', v_audit_user,
                                'user_id', p_userid
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
                -- If approving, require approvedby if not already set
                IF p_status = 'APPROVED' AND p_approvedby IS NULL AND v_current_record.approvedby IS NULL THEN
                    p_result_message := 'ERROR: approvedby is required when approving a request';
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_VALIDATION_ERROR',
                            'Missing approver for approval',
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'error', p_result_message,
                                'user', v_audit_user,
                                'user_id', p_userid,
                                'current_status', v_current_record.status
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
                -- If verifying, require verifiedby AND verifiedbranchcode if not already set
                IF p_status = 'VERIFIED' THEN
                    IF p_verifiedby IS NULL AND v_current_record.verifiedby IS NULL THEN
                        p_result_message := 'ERROR: verifiedby is required when verifying a request';
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Missing verifier for verification',
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'error', p_result_message,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_status', v_current_record.status
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                    
                    IF p_verifiedbranchcode IS NULL AND v_current_record.verifiedbranchcode IS NULL THEN
                        p_result_message := 'ERROR: verifiedbranchcode is required when verifying a request';
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Missing verification branch for verification',
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'error', p_result_message,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_status', v_current_record.status
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                END IF;
            END IF;
            
            -- Perform update based on type
            IF v_update_type = 'ALL' THEN
                -- Update all fields
                UPDATE instantcardcycle
                SET 
                    scheme = COALESCE(p_scheme, scheme),
                    cardtype = COALESCE(p_cardtype, cardtype),
                    currency = CASE 
                        WHEN p_currency IS NOT NULL THEN UPPER(p_currency) 
                        ELSE currency 
                    END,
                    totalnumberofcard = COALESCE(p_totalnumberofcard, totalnumberofcard),
                    flags = COALESCE(p_flags, flags),
                    pintype = COALESCE(p_pintype, pintype),
                    requestedby = COALESCE(p_requestedby, requestedby),
                    requestedbranchname = COALESCE(p_requestedbranchname, requestedbranchname),
                    requestbranchcode = COALESCE(p_requestbranchcode, requestbranchcode),
                    approvedby = COALESCE(p_approvedby, approvedby),
                    approvedbranchcode = COALESCE(p_approvedbranchcode, approvedbranchcode),
                    approvedbranchname = COALESCE(p_approvedbranchname, approvedbranchname),
                    verifiedby = COALESCE(p_verifiedby, verifiedby),
                    verifiedbranchname = COALESCE(p_verifiedbranchname, verifiedbranchname),
                    verifiedbranchcode = COALESCE(p_verifiedbranchcode, verifiedbranchcode),
                    status = COALESCE(p_status, status),
                    approvedate = CASE 
                        WHEN p_status IN ('APPROVED', 'REJECTED') AND approvedate IS NULL THEN CURRENT_TIMESTAMP
                        WHEN p_status IN ('APPROVED', 'REJECTED') THEN approvedate
                        ELSE approvedate
                    END,
                    verifieddate = CASE 
                        WHEN p_status = 'VERIFIED' AND verifieddate IS NULL THEN CURRENT_TIMESTAMP
                        WHEN p_status = 'VERIFIED' THEN verifieddate
                        ELSE verifieddate
                    END
                WHERE requestid = p_requestid
                RETURNING jsonb_build_object(
                    'requestid', requestid,
                    'scheme', scheme,
                    'cardtype', cardtype,
                    'currency', currency,
                    'totalnumberofcard', totalnumberofcard,
                    'flags', flags,
                    'pintype', pintype,
                    'status', status,
                    'approvedby', approvedby,
                    'approvedbranchcode', approvedbranchcode,
                    'approvedbranchname', approvedbranchname,
                    'verifiedby', verifiedby,
                    'verifiedbranchname', verifiedbranchname,
                    'verifiedbranchcode', verifiedbranchcode,
                    'approvedate', approvedate,
                    'verifieddate', verifieddate,
                    'requestbranchcode', requestbranchcode,
                    'requestedbranchname', requestedbranchname
                ) INTO p_result_data;
                
                p_result_message := 'SUCCESS: All fields updated';
                
                -- Update audit data with changes for ALL fields update
                IF v_debug_flag = 1 THEN
                    IF p_scheme IS NOT NULL AND p_scheme != v_current_record.scheme THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,scheme}', 
                            jsonb_build_object('from', v_current_record.scheme, 'to', p_scheme));
                    END IF;
                    
                    IF p_totalnumberofcard IS NOT NULL AND p_totalnumberofcard != v_current_record.totalnumberofcard THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,totalnumberofcard}', 
                            jsonb_build_object('from', v_current_record.totalnumberofcard, 'to', p_totalnumberofcard));
                    END IF;
                    
                    IF p_status IS NOT NULL AND p_status != v_current_record.status THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,status}', 
                            jsonb_build_object('from', v_current_record.status, 'to', p_status));
                    END IF;
                    
                    IF p_verifiedby IS NOT NULL AND p_verifiedby != v_current_record.verifiedby THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,verifiedby}', 
                            jsonb_build_object('from', v_current_record.verifiedby, 'to', p_verifiedby));
                    END IF;
                    
                    IF p_verifiedbranchcode IS NOT NULL AND p_verifiedbranchcode != v_current_record.verifiedbranchcode THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,verifiedbranchcode}', 
                            jsonb_build_object('from', v_current_record.verifiedbranchcode, 'to', p_verifiedbranchcode));
                    END IF;
                    
                    IF p_requestbranchcode IS NOT NULL AND p_requestbranchcode != v_current_record.requestbranchcode THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,requestbranchcode}', 
                            jsonb_build_object('from', v_current_record.requestbranchcode, 'to', p_requestbranchcode));
                    END IF;
                    
                    v_audit_description := 'All fields updated for request: ' || p_requestid;
                END IF;
                
            ELSIF v_update_type = 'APPROVAL' THEN
                -- Update only approval/verification fields and status
                UPDATE instantcardcycle
                SET 
                    approvedby = COALESCE(p_approvedby, approvedby),
                    approvedbranchcode = COALESCE(p_approvedbranchcode, approvedbranchcode),
                    approvedbranchname = COALESCE(p_approvedbranchname, approvedbranchname),
                    verifiedby = COALESCE(p_verifiedby, verifiedby),
                    verifiedbranchname = COALESCE(p_verifiedbranchname, verifiedbranchname),
                    verifiedbranchcode = COALESCE(p_verifiedbranchcode, verifiedbranchcode),
                    status = COALESCE(p_status, status),
                    approvedate = CASE 
                        WHEN p_status IN ('APPROVED', 'REJECTED') AND approvedate IS NULL THEN CURRENT_TIMESTAMP
                        WHEN p_status IN ('APPROVED', 'REJECTED') THEN approvedate
                        ELSE approvedate
                    END,
                    verifieddate = CASE 
                        WHEN p_status = 'VERIFIED' AND verifieddate IS NULL THEN CURRENT_TIMESTAMP
                        WHEN p_status = 'VERIFIED' THEN verifieddate
                        ELSE verifieddate
                    END
                WHERE requestid = p_requestid
                RETURNING jsonb_build_object(
                    'requestid', requestid,
                    'status', status,
                    'approvedby', approvedby,
                    'approvedbranchcode', approvedbranchcode,
                    'approvedbranchname', approvedbranchname,
                    'verifiedby', verifiedby,
                    'verifiedbranchname', verifiedbranchname,
                    'verifiedbranchcode', verifiedbranchcode,
                    'approvedate', approvedate,
                    'verifieddate', verifieddate
                ) INTO p_result_data;
                
                p_result_message := 'SUCCESS: Approval/Verification fields updated';
                
                -- Update audit data for APPROVAL/VERIFICATION update
                IF v_debug_flag = 1 THEN
                    IF p_status IS NOT NULL AND p_status != v_current_record.status THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,status}', 
                            jsonb_build_object('from', v_current_record.status, 'to', p_status));
                    END IF;
                    
                    IF p_approvedby IS NOT NULL AND p_approvedby != v_current_record.approvedby THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,approvedby}', 
                            jsonb_build_object('from', v_current_record.approvedby, 'to', p_approvedby));
                    END IF;
                    
                    IF p_verifiedby IS NOT NULL AND p_verifiedby != v_current_record.verifiedby THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,verifiedby}', 
                            jsonb_build_object('from', v_current_record.verifiedby, 'to', p_verifiedby));
                    END IF;
                    
                    IF p_verifiedbranchcode IS NOT NULL AND p_verifiedbranchcode != v_current_record.verifiedbranchcode THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,verifiedbranchcode}', 
                            jsonb_build_object('from', v_current_record.verifiedbranchcode, 'to', p_verifiedbranchcode));
                    END IF;
                    
                    v_audit_description := 'Status updated to ' || COALESCE(p_status, v_current_record.status) || 
                                          ' for request: ' || p_requestid;
                END IF;
                
            END IF;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found';
                p_result_data := '{}'::JSONB;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_ERROR',
                        'Record not found during update: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
            ELSE
                -- ADDED: Include user access info in success message
                IF v_crossbranch = FALSE AND v_branchcode IS NOT NULL THEN
                    p_result_message := p_result_message || ' (User branch: ' || v_branchcode || ')';
                END IF;
                
                IF v_debug_flag = 1 AND v_audit_description IS NOT NULL THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_SUCCESS',
                        v_audit_description,
                        v_audit_data
                    );
                END IF;
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            p_result_message := 'ERROR: ' || SQLERRM;
            p_result_data := '{}'::JSONB;
            
            IF v_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    'UPDATE_ERROR',
                    'Update failed: ' || p_requestid || ' - ' || SQLERRM,
                    jsonb_build_object(
                        'requestid', p_requestid,
                        'error', SQLERRM,
                        'user', v_audit_user,
                        'user_id', p_userid
                    )
                );
            END IF;
        END;
        
    -- ACTION: DELETE (UPDATED with branch access control)
    ELSIF p_action = 'DELETE' THEN
        BEGIN
            IF p_requestid IS NULL THEN
                p_result_message := 'ERROR: requestid is required for DELETE';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_VALIDATION_ERROR',
                        'Missing requestid for DELETE',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Get record before deletion for audit logging
            SELECT * INTO v_current_record 
            FROM instantcardcycle 
            WHERE requestid = p_requestid;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_NOT_FOUND',
                        'Record not found for deletion: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- ADDED: Check if user has access to this record's branch
            IF v_branchcode IS NOT NULL AND v_crossbranch = FALSE 
               AND v_current_record.requestbranchcode != v_branchcode THEN
                p_result_message := 'ERROR: You do not have permission to delete this record. ' ||
                                   'Record belongs to branch: ' || v_current_record.requestbranchcode || 
                                   ', Your branch: ' || v_branchcode;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_ACCESS_DENIED',
                        'Branch access denied for DELETE',
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'record_branch', v_current_record.requestbranchcode,
                            'user_branch', v_branchcode,
                            'crossbranch', v_crossbranch,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Only allow deletion of PENDING or REJECTED records
            IF v_current_record.status NOT IN ('PENDING', 'REJECTED') THEN
                p_result_message := 'ERROR: Cannot delete record with status: ' || v_current_record.status;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_VALIDATION_ERROR',
                        'Delete failed - invalid status: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'status', v_current_record.status,
                            'allowed_statuses', 'PENDING, REJECTED',
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Prepare audit data for DELETE if debug flag is 1
            IF v_debug_flag = 1 THEN
                v_audit_data := jsonb_build_object(
                    'requestid', p_requestid,
                    'scheme', v_current_record.scheme,
                    'cardtype', v_current_record.cardtype,
                    'total_cards', v_current_record.totalnumberofcard,
                    'status', v_current_record.status,
                    'branch', v_current_record.requestbranchcode,
                    'requested_by', v_current_record.requestedby,
                    'approved_by', v_current_record.approvedby,
                    'verified_by', v_current_record.verifiedby,
                    'user', v_audit_user,
                    'user_id', p_userid,
                    'user_branch', v_branchcode,
                    'record_branch', v_current_record.requestbranchcode,
                    'crossbranch', v_crossbranch
                );
            END IF;
            
            -- Delete record
            DELETE FROM instantcardcycle 
            WHERE requestid = p_requestid;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_ERROR',
                        'Record not found during deletion: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
            ELSE
                p_result_message := 'SUCCESS: Record deleted from branch: ' || v_current_record.requestbranchcode;
                p_result_data := jsonb_build_object(
                    'deleted_requestid', p_requestid,
                    'deleted_branch', v_current_record.requestbranchcode,
                    'user_branch', v_branchcode
                );
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_SUCCESS',
                        'Instant card cycle deleted: ' || p_requestid,
                        v_audit_data
                    );
                END IF;
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            p_result_message := 'ERROR: ' || SQLERRM;
            
            IF v_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    'DELETE_ERROR',
                    'Delete failed: ' || p_requestid || ' - ' || SQLERRM,
                    jsonb_build_object(
                        'requestid', p_requestid,
                        'error', SQLERRM,
                        'user', v_audit_user,
                        'user_id', p_userid
                    )
                );
            END IF;
        END;
        
    END IF;
    
END;
$$;


ALTER FUNCTION public.finstantcardcycle_backup_mar26(p_action character varying, p_requestid character varying, p_scheme character varying, p_cardtype character varying, p_currency character varying, p_totalnumberofcard integer, p_flags character varying, p_pintype character varying, p_requestedby character varying, p_requestedbranchname character varying, p_requestbranchcode character varying, p_approvedby character varying, p_approvedbranchcode character varying, p_approvedbranchname character varying, p_verifiedby character varying, p_verifiedbranchname character varying, p_verifiedbranchcode character varying, p_status character varying, p_start_date date, p_end_date date, p_userid integer, OUT p_result_message character varying, OUT p_result_data jsonb) OWNER TO postgres;

--
-- TOC entry 392 (class 1255 OID 31272)
-- Name: finstantcardcycle_feb112026(character varying, character varying, character varying, character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, date, date, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstantcardcycle_feb112026(p_action character varying, p_requestid character varying DEFAULT NULL::character varying, p_scheme character varying DEFAULT NULL::character varying, p_cardtype character varying DEFAULT NULL::character varying, p_currency character varying DEFAULT NULL::character varying, p_totalnumberofcard integer DEFAULT NULL::integer, p_flags character varying DEFAULT NULL::character varying, p_pintype character varying DEFAULT NULL::character varying, p_requestedby character varying DEFAULT NULL::character varying, p_requestedbranchname character varying DEFAULT NULL::character varying, p_requestbranchcode character varying DEFAULT NULL::character varying, p_approvedby character varying DEFAULT NULL::character varying, p_approvedbranchcode character varying DEFAULT NULL::character varying, p_approvedbranchname character varying DEFAULT NULL::character varying, p_verifiedby character varying DEFAULT NULL::character varying, p_verifiedbranchname character varying DEFAULT NULL::character varying, p_verifiedbranchcode character varying DEFAULT NULL::character varying, p_status character varying DEFAULT NULL::character varying, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_userid integer DEFAULT 0, OUT p_result_message character varying, OUT p_result_data jsonb) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_new_requestid VARCHAR(12);
    v_current_record RECORD;
    v_update_type VARCHAR(20); -- 'ALL', 'APPROVAL', 'STATUS_ONLY'
    v_debug_flag INTEGER := 1; -- 1 = Enable audit logging for CRUD, 0 = Disable audit logging
    v_search_debug_flag INTEGER := 1; -- 1 = Enable audit logging for SEARCH, 0 = Disable (default off for production)
    v_audit_user VARCHAR(100);
    v_audit_data JSONB;
    v_audit_description TEXT;
    
    -- SEARCH variables
    v_search_records JSONB;
    v_total_count INTEGER;
    v_filtered_count INTEGER;
    v_search_criteria JSONB;
    
    -- Cross-branch access variables
    v_branchcode VARCHAR(10);
    v_instcode VARCHAR(4);
    v_crossbranch BOOLEAN := FALSE;
    v_branchname VARCHAR(100);
    v_username VARCHAR(30);
    v_user_branch_id INTEGER;
    
    -- NEW VARIABLES for stock management
    v_headoffice_branchcode VARCHAR(4) := '0000';
    v_available_stock INTEGER;
    v_booked_cards INTEGER := 0;
    v_card_numbers TEXT[]; -- To store booked card numbers if needed
    v_temp_card_number VARCHAR(19);
    v_booked_cards_cursor REFCURSOR;
    v_stock_check_result RECORD;
BEGIN
    -- Initialize outputs
    p_result_message := '';
    p_result_data := '{}'::JSONB;
    
    -- Determine audit user (priority: approvedby > requestedby > current user)
    v_audit_user := COALESCE(p_approvedby, p_requestedby, CURRENT_USER);
    
    -- Get user branch info for access control
    IF p_userid IS NOT NULL AND p_userid > 0 THEN
        RAISE NOTICE 'USER REQUESTING ID: %', p_userid;
        
        -- Get user info with explicit handling - JOIN with branch table to get branch_no
        SELECT u.branchid,
               LEFT(u.institutionid::TEXT, 4),
               u.crossbranch,
               b.branch_no,
               b.branch_name
          INTO v_user_branch_id, v_instcode, v_crossbranch, v_branchcode, v_branchname
        FROM users u
        LEFT JOIN branch b ON b.id = u.branchid
        WHERE u.id = p_userid;
        
        -- If user not found, use defaults
        IF NOT FOUND THEN
            v_crossbranch := FALSE;
            v_branchcode := NULL;
            v_instcode := NULL;
            v_branchname := NULL;
            RAISE NOTICE 'User ID % not found in users table, using limited access', p_userid;
        ELSE
            RAISE NOTICE 'User branch: % (code: %), Cross-branch: %', v_branchname, v_branchcode, v_crossbranch;
            
            -- Clean branch code (remove any whitespace)
            v_branchcode := TRIM(v_branchcode);
            
            -- Validate branch code
            IF v_branchcode IS NULL OR v_branchcode = '' THEN
                RAISE EXCEPTION 'User % has NULL or empty branch code. Please update user branch information.', p_userid;
            END IF;
        END IF;
        
        -- Get username for audit purposes
        SELECT username INTO v_username FROM authlogin WHERE userid = p_userid LIMIT 1;
        IF FOUND THEN
            v_audit_user := COALESCE(v_audit_user, v_username);
        END IF;
    ELSE
        -- No user ID provided, use limited access
        v_crossbranch := FALSE;
        v_branchcode := NULL;
        RAISE NOTICE 'No user ID provided, using limited access';
    END IF;
    
    -- Validate action (UPDATED to include SEARCH)
    IF p_action NOT IN ('INSERT', 'UPDATE', 'DELETE', 'SEARCH') THEN
        p_result_message := 'ERROR: Invalid action. Use INSERT, UPDATE, DELETE, or SEARCH';
        
        -- Audit log for invalid action if debug flag is 1
        IF v_debug_flag = 1 THEN
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD_CYCLE',
                'INVALID_ACTION',
                'Invalid action attempted: ' || p_action,
                jsonb_build_object(
                    'action', p_action,
                    'error', p_result_message,
                    'user', v_audit_user,
                    'user_id', p_userid
                )
            );
        END IF;
        RETURN;
    END IF;
    
    -- ACTION: SEARCH
    IF p_action = 'SEARCH' THEN
        BEGIN
            -- Build search criteria for audit logging (if enabled)
            v_search_criteria := jsonb_build_object(
                'requestid', p_requestid,
                'scheme', p_scheme,
                'cardtype', p_cardtype,
                'requestedby', p_requestedby,
                'approvedby', p_approvedby,
                'verifiedby', p_verifiedby,
                'requestbranchcode', p_requestbranchcode,
                'approvedbranchcode', p_approvedbranchcode,
                'verifiedbranchcode', p_verifiedbranchcode,
                'status', p_status,
                'start_date', p_start_date,
                'end_date', p_end_date,
                'user_id', p_userid,
                'user_branch', v_branchcode,
                'crossbranch_access', v_crossbranch
            );
            
            -- Get total count of all records
            SELECT COUNT(*) INTO v_total_count FROM instantcardcycle;
            
            -- Build dynamic query for search with branch access control
            IF p_requestid IS NOT NULL THEN
                -- EXCLUSIVE SEARCH: When requestid is provided, search ONLY by ID
                -- But check branch access if user doesn't have cross-branch privileges
                v_search_records := (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'requestid', icc.requestid,
                            'scheme', icc.scheme,
                            'cardtype', icc.cardtype,
                            'currency', icc.currency,
                            'totalnumberofcard', icc.totalnumberofcard,
                            'flags', icc.flags,
                            'pintype', icc.pintype,
                            'requestedby', icc.requestedby,
                            'requestedbranchname', icc.requestedbranchname,
                            'requestbranchcode', icc.requestbranchcode,
                            'approvedby', icc.approvedby,
                            'approvedbranchcode', icc.approvedbranchcode,
                            'approvedbranchname', icc.approvedbranchname,
                            'verifiedby', icc.verifiedby,
                            'verifiedbranchname', icc.verifiedbranchname,
                            'verifiedbranchcode', icc.verifiedbranchcode,
                            'status', icc.status,
                            'requesteddate', icc.requesteddate,
                            'approvedate', icc.approvedate,
                            'verifieddate', icc.verifieddate
                        )
                    )
                    FROM instantcardcycle icc
                    WHERE icc.requestid = p_requestid
                    -- ADDED: Branch access check
                    AND (v_crossbranch = TRUE OR icc.requestbranchcode = v_branchcode 
                         OR (p_userid IS NULL OR p_userid = 0)) -- Allow if no user ID provided
                );
            ELSE
                -- NORMAL SEARCH: When no requestid provided, use all other filters
                -- ADDED: Apply branch filtering based on user privileges
                v_search_records := (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'requestid', icc.requestid,
                            'scheme', icc.scheme,
                            'cardtype', icc.cardtype,
                            'currency', icc.currency,
                            'totalnumberofcard', icc.totalnumberofcard,
                            'flags', icc.flags,
                            'pintype', icc.pintype,
                            'requestedby', icc.requestedby,
                            'requestedbranchname', icc.requestedbranchname,
                            'requestbranchcode', icc.requestbranchcode,
                            'approvedby', icc.approvedby,
                            'approvedbranchcode', icc.approvedbranchcode,
                            'approvedbranchname', icc.approvedbranchname,
                            'verifiedby', icc.verifiedby,
                            'verifiedbranchname', icc.verifiedbranchname,
                            'verifiedbranchcode', icc.verifiedbranchcode,
                            'status', icc.status,
                            'requesteddate', icc.requesteddate,
                            'approvedate', icc.approvedate,
                            'verifieddate', icc.verifieddate
                        )
                        ORDER BY icc.requesteddate DESC
                    )
                    FROM instantcardcycle icc
                    WHERE 
                        (p_scheme IS NULL OR icc.scheme = p_scheme)
                        AND (p_cardtype IS NULL OR icc.cardtype = p_cardtype)
                        AND (p_requestedby IS NULL OR icc.requestedby = p_requestedby)
                        AND (p_approvedby IS NULL OR icc.approvedby = p_approvedby)
                        AND (p_verifiedby IS NULL OR icc.verifiedby = p_verifiedby)
                        AND (p_requestbranchcode IS NULL OR icc.requestbranchcode = p_requestbranchcode)
                        AND (p_approvedbranchcode IS NULL OR icc.approvedbranchcode = p_approvedbranchcode)
                        AND (p_verifiedbranchcode IS NULL OR icc.verifiedbranchcode = p_verifiedbranchcode)
                        AND (p_status IS NULL OR icc.status = p_status)
                        AND (p_start_date IS NULL OR DATE(icc.requesteddate) >= p_start_date)
                        AND (p_end_date IS NULL OR DATE(icc.requesteddate) <= p_end_date)
                        -- ADDED: Branch access control
                        AND (
                            v_crossbranch = TRUE 
                            OR icc.requestbranchcode = v_branchcode 
                            OR (p_userid IS NULL OR p_userid = 0) -- Allow if no user ID provided
                        )
                );
            END IF;
            
            -- Get filtered count
            IF v_search_records IS NULL THEN
                v_filtered_count := 0;
            ELSE
                v_filtered_count := jsonb_array_length(v_search_records);
            END IF;
            
            -- Prepare result data with access info
            p_result_data := jsonb_build_object(
                'search_criteria', v_search_criteria,
                'search_type', CASE WHEN p_requestid IS NOT NULL THEN 'ID_EXCLUSIVE' ELSE 'NORMAL' END,
                'total_records', v_total_count,
                'filtered_records', v_filtered_count,
                'user_access', jsonb_build_object(
                    'user_id', p_userid,
                    'branch_code', v_branchcode,
                    'crossbranch_access', v_crossbranch,
                    'branch_name', v_branchname
                ),
                'records', COALESCE(v_search_records, '[]'::jsonb)
            );
            
            IF p_requestid IS NOT NULL THEN
                p_result_message := 'SUCCESS: ID exclusive search completed. Found ' || v_filtered_count || ' record(s)';
            ELSE
                p_result_message := 'SUCCESS: Search completed. Found ' || v_filtered_count || ' records';
            END IF;
            
            -- Add access info to message if not cross-branch
            IF v_crossbranch = FALSE AND v_branchcode IS NOT NULL THEN
                p_result_message := p_result_message || ' (Filtered by branch: ' || v_branchcode || ')';
            ELSIF v_crossbranch = TRUE THEN
                p_result_message := p_result_message || ' (Cross-branch access enabled)';
            END IF;
            
            -- Audit log for SEARCH only if search debug flag is enabled
            IF v_search_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    CASE WHEN p_requestid IS NOT NULL THEN 'SEARCH_ID_EXCLUSIVE' ELSE 'SEARCH_SUCCESS' END,
                    'Search performed: ' || v_filtered_count || ' records found',
                    jsonb_build_object(
                        'search_criteria', v_search_criteria,
                        'total_records', v_total_count,
                        'filtered_records', v_filtered_count,
                        'search_type', CASE WHEN p_requestid IS NOT NULL THEN 'ID_EXCLUSIVE' ELSE 'NORMAL' END,
                        'user', v_audit_user,
                        'user_id', p_userid,
                        'branch_access', v_branchcode,
                        'crossbranch', v_crossbranch
                    )
                );
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            p_result_message := 'ERROR: Search failed - ' || SQLERRM;
            p_result_data := '{}'::JSONB;
            
            -- Audit log for SEARCH error only if search debug flag is enabled
            IF v_search_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    'SEARCH_ERROR',
                    'Search failed: ' || SQLERRM,
                    jsonb_build_object(
                        'error', SQLERRM,
                        'search_criteria', v_search_criteria,
                        'user', v_audit_user,
                        'user_id', p_userid
                    )
                );
            END IF;
        END;
        
        -- Return after SEARCH action
        RETURN;
    END IF;
    
    -- ACTION: INSERT (UPDATED with stock availability check)
    IF p_action = 'INSERT' THEN
        BEGIN
            -- Check for NULL required fields
            IF p_scheme IS NULL THEN
                p_result_message := 'ERROR: scheme is required';
                RETURN;
            END IF;
            IF p_cardtype IS NULL THEN
                p_result_message := 'ERROR: cardtype is required';
                RETURN;
            END IF;
            IF p_currency IS NULL THEN
                p_result_message := 'ERROR: currency is required';
                RETURN;
            END IF;
            IF p_totalnumberofcard IS NULL THEN
                p_result_message := 'ERROR: totalnumberofcard is required';
                RETURN;
            END IF;
            IF p_requestedby IS NULL THEN
                p_result_message := 'ERROR: requestedby is required';
                RETURN;
            END IF;
            
            -- ADDED: Use user's branch info if not provided
            IF p_requestedbranchname IS NULL AND v_branchname IS NOT NULL THEN
                p_requestedbranchname := v_branchname;
            END IF;
            
            IF p_requestbranchcode IS NULL THEN
                IF v_branchcode IS NOT NULL THEN
                    p_requestbranchcode := v_branchcode;
                ELSE
                    p_result_message := 'ERROR: requestbranchcode is required';
                    RETURN;
                END IF;
            END IF;
            
            -- ADDED: Validate user can create for this branch if branch code is provided
            IF p_requestbranchcode IS NOT NULL AND v_branchcode IS NOT NULL 
               AND p_requestbranchcode != v_branchcode AND v_crossbranch = FALSE THEN
                p_result_message := 'ERROR: You do not have permission to create records for branch: ' || 
                                   p_requestbranchcode || '. Your branch: ' || v_branchcode;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_ACCESS_DENIED',
                        'Branch access denied for INSERT',
                        jsonb_build_object(
                            'user_branch', v_branchcode,
                            'requested_branch', p_requestbranchcode,
                            'crossbranch', v_crossbranch,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Validate card count
            IF p_totalnumberofcard < 10 THEN
                p_result_message := 'ERROR: Minimum 10 cards required. Provided: ' || p_totalnumberofcard::text;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_VALIDATION_ERROR',
                        'Card count validation failed: ' || p_totalnumberofcard,
                        jsonb_build_object(
                            'provided_cards', p_totalnumberofcard,
                            'minimum_required', 10,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            IF p_totalnumberofcard > 10000 THEN
                p_result_message := 'ERROR: Maximum 10000 cards allowed. Provided: ' || p_totalnumberofcard::text;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_VALIDATION_ERROR',
                        'Card count validation failed: ' || p_totalnumberofcard,
                        jsonb_build_object(
                            'provided_cards', p_totalnumberofcard,
                            'maximum_allowed', 10000,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- NEW LOGIC: Check stock availability for non-head office branches
            v_available_stock := 0;
            v_booked_cards := 0;
            
            -- Variable to store the status we'll insert with
            DECLARE
                v_insert_status VARCHAR(20);
                v_is_greenpin CHAR(1);
            BEGIN
                -- Determine isgreenpin value based on pintype
                IF p_pintype = 'GREEN-PIN' THEN
                    v_is_greenpin := 'Y';
                ELSIF p_pintype = 'PAPER-PIN' THEN
                    v_is_greenpin := 'N';
                ELSE
                    v_is_greenpin := NULL; -- If pintype is null or unknown, don't filter by it
                END IF;
                
                -- Only check stock if branch is NOT head office
                IF p_requestbranchcode IS NOT NULL AND p_requestbranchcode != v_headoffice_branchcode THEN
                    
                    -- Check available stock count
                    SELECT COUNT(*) INTO v_available_stock
                    FROM instantcardstock
                    WHERE status = 'AVAILABLE'
                      --AND allocatedbranch = p_requestbranchcode
                      AND (v_is_greenpin IS NULL OR isgreenpin = v_is_greenpin);
                    
                    RAISE NOTICE 'Available stock for branch % (pintype: %, isgreenpin: %): % cards, Requested: % cards', 
                        p_requestbranchcode, p_pintype, v_is_greenpin, v_available_stock, p_totalnumberofcard;
                    
                    -- Determine status based on stock availability
                    IF v_available_stock >= p_totalnumberofcard THEN
                        v_insert_status := 'BOOKED';
                        v_booked_cards := p_totalnumberofcard; -- All requested cards can be booked
                        RAISE NOTICE 'Sufficient stock. Inserting with status: BOOKED';
                    ELSE
                        v_insert_status := 'PENDING';
                        v_booked_cards := 0; -- No cards booked yet
                        RAISE NOTICE 'Insufficient stock. Inserting with status: PENDING';
                    END IF;
                ELSE
                    -- Head office or branch not specified - default to PENDING
                    v_insert_status := COALESCE(p_status, 'PENDING');
                    v_booked_cards := 0;
                    RAISE NOTICE 'Head office branch or branch not specified. Inserting with status: %', v_insert_status;
                END IF;
                
                -- Insert record with determined status
                INSERT INTO instantcardcycle (
                    scheme, cardtype, currency, totalnumberofcard, 
                    flags, pintype, requestedby, requestedbranchname, 
                    requestbranchcode, status
                ) VALUES (
                    p_scheme,
                    p_cardtype,
                    UPPER(p_currency),
                    p_totalnumberofcard,
                    p_flags,
                    p_pintype,
                    p_requestedby,
                    p_requestedbranchname,
                    p_requestbranchcode,
                    v_insert_status  -- Use the determined status
                )
                RETURNING requestid, jsonb_build_object(
                    'requestid', requestid,
                    'scheme', scheme,
                    'cardtype', cardtype,
                    'currency', currency,
                    'totalnumberofcard', totalnumberofcard,
                    'status', status,
                    'requesteddate', requesteddate,
                    'requestbranchcode', requestbranchcode,
                    'requestedbranchname', requestedbranchname,
                    'cards_available', v_available_stock,
                    'cards_requested', p_totalnumberofcard,
                    'cards_booked', v_booked_cards,
                    'stock_check_performed', CASE WHEN p_requestbranchcode != v_headoffice_branchcode THEN TRUE ELSE FALSE END,
                    'is_head_office', CASE WHEN p_requestbranchcode = v_headoffice_branchcode THEN TRUE ELSE FALSE END
                ) INTO v_new_requestid, p_result_data;
                
                p_result_message := 'SUCCESS: Record inserted for branch: ' || p_requestbranchcode || ' with status: ' || v_insert_status;
                
                -- Add stock info to message if applicable
                IF p_requestbranchcode != v_headoffice_branchcode THEN
                    IF v_insert_status = 'BOOKED' THEN
                        p_result_message := p_result_message || ' - Sufficient stock available';
                    ELSE
                        p_result_message := p_result_message || ' - Insufficient stock (Available: ' || v_available_stock || ' cards)';
                    END IF;
                END IF;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_SUCCESS',
                        'Instant card cycle created: ' || v_new_requestid || ' with status: ' || v_insert_status,
                        jsonb_build_object(
                            'requestid', v_new_requestid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'total_cards', p_totalnumberofcard,
                            'status', v_insert_status,
                            'branch', p_requestbranchcode,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'user_branch', v_branchcode,
                            'crossbranch', v_crossbranch,
                            'stock_available', v_available_stock,
                            'cards_requested', p_totalnumberofcard,
                            'is_head_office', CASE WHEN p_requestbranchcode = v_headoffice_branchcode THEN TRUE ELSE FALSE END
                        )
                    );
                END IF;
            END;
            
        EXCEPTION 
            WHEN not_null_violation THEN
                p_result_message := 'ERROR: Required field is missing';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_CONSTRAINT_ERROR',
                        'Not null constraint violation',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                
            WHEN check_violation THEN
                p_result_message := 'ERROR: Data validation failed';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_CONSTRAINT_ERROR',
                        'Check constraint violation',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                
            WHEN OTHERS THEN
                p_result_message := 'ERROR: ' || SQLERRM;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_ERROR',
                        'Insert failed: ' || SQLERRM,
                        jsonb_build_object(
                            'error', SQLERRM,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'total_cards', p_totalnumberofcard,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
        END;
        
    -- ACTION: UPDATE (UPDATED with branch access control)
    ELSIF p_action = 'UPDATE' THEN
        BEGIN
            IF p_requestid IS NULL THEN
                p_result_message := 'ERROR: requestid is required for UPDATE';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_VALIDATION_ERROR',
                        'Missing requestid for UPDATE',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Get current record
            SELECT * INTO v_current_record 
            FROM instantcardcycle 
            WHERE requestid = p_requestid;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found with requestid: ' || p_requestid;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_NOT_FOUND',
                        'Record not found: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- ADDED: Check if user has access to this record's branch
            IF v_branchcode IS NOT NULL AND v_crossbranch = FALSE 
               AND v_current_record.requestbranchcode != v_branchcode THEN
                p_result_message := 'ERROR: You do not have permission to update this record. ' ||
                                   'Record belongs to branch: ' || v_current_record.requestbranchcode || 
                                   ', Your branch: ' || v_branchcode;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_ACCESS_DENIED',
                        'Branch access denied for UPDATE',
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'record_branch', v_current_record.requestbranchcode,
                            'user_branch', v_branchcode,
                            'crossbranch', v_crossbranch,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Prepare audit data for UPDATE if debug flag is 1
            IF v_debug_flag = 1 THEN
                v_audit_data := jsonb_build_object(
                    'requestid', p_requestid,
                    'old_status', v_current_record.status,
                    'new_status', p_status,
                    'user', v_audit_user,
                    'user_id', p_userid,
                    'user_branch', v_branchcode,
                    'record_branch', v_current_record.requestbranchcode,
                    'crossbranch', v_crossbranch,
                    'old_approvedby', v_current_record.approvedby,
                    'new_approvedby', p_approvedby,
                    'old_verifiedby', v_current_record.verifiedby,
                    'new_verifiedby', p_verifiedby,
                    'old_verifiedbranchcode', v_current_record.verifiedbranchcode,
                    'new_verifiedbranchcode', p_verifiedbranchcode,
                    'changes', jsonb_build_object()
                );
            END IF;
            
            -- Determine update type based on provided parameters
            IF p_scheme IS NOT NULL OR p_cardtype IS NOT NULL OR p_currency IS NOT NULL OR
               p_totalnumberofcard IS NOT NULL OR p_flags IS NOT NULL OR p_pintype IS NOT NULL OR
               p_requestedby IS NOT NULL OR p_requestedbranchname IS NOT NULL OR p_requestbranchcode IS NOT NULL THEN
                -- Type 1: Update all fields (if any non-approval field is provided)
                v_update_type := 'ALL';
                
                -- ADDED: Check if user can change branch if requestbranchcode is being updated
                IF p_requestbranchcode IS NOT NULL AND v_branchcode IS NOT NULL 
                   AND p_requestbranchcode != v_current_record.requestbranchcode 
                   AND v_crossbranch = FALSE THEN
                    p_result_message := 'ERROR: You do not have permission to change record branch. ' ||
                                       'Current branch: ' || v_current_record.requestbranchcode || 
                                       ', New branch: ' || p_requestbranchcode;
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_ACCESS_DENIED',
                            'Branch change denied for UPDATE',
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'old_branch', v_current_record.requestbranchcode,
                                'new_branch', p_requestbranchcode,
                                'user_branch', v_branchcode,
                                'crossbranch', v_crossbranch,
                                'user', v_audit_user,
                                'user_id', p_userid
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
                -- Validate card count if provided
                IF p_totalnumberofcard IS NOT NULL THEN
                    IF p_totalnumberofcard < 10 THEN
                        p_result_message := 'ERROR: Minimum 10 cards required. Provided: ' || p_totalnumberofcard::text;
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Card count validation failed: ' || p_totalnumberofcard,
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'provided_cards', p_totalnumberofcard,
                                    'minimum_required', 10,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_cards', v_current_record.totalnumberofcard
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                    
                    IF p_totalnumberofcard > 10000 THEN
                        p_result_message := 'ERROR: Maximum 10000 cards allowed. Provided: ' || p_totalnumberofcard::text;
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Card count validation failed: ' || p_totalnumberofcard,
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'provided_cards', p_totalnumberofcard,
                                    'maximum_allowed', 10000,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_cards', v_current_record.totalnumberofcard
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                END IF;
                
            ELSIF p_approvedby IS NOT NULL OR p_approvedbranchcode IS NOT NULL OR 
                  p_approvedbranchname IS NOT NULL OR p_verifiedby IS NOT NULL OR
                  p_verifiedbranchname IS NOT NULL OR p_verifiedbranchcode IS NOT NULL OR 
                  p_status IS NOT NULL THEN
                -- Type 2: Update approval/verification fields + status
                v_update_type := 'APPROVAL';
                
                -- Validate status if provided
                IF p_status IS NOT NULL AND p_status NOT IN ('PENDING', 'APPROVED', 'REJECTED', 'PROCESSING', 'COMPLETED', 'VERIFIED') THEN
                    p_result_message := 'ERROR: Invalid status value: ' || p_status;
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_VALIDATION_ERROR',
                            'Invalid status value: ' || p_status,
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'invalid_status', p_status,
                                'user', v_audit_user,
                                'user_id', p_userid,
                                'current_status', v_current_record.status
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
            ELSE
                -- Type 3: No fields to update
                p_result_message := 'ERROR: No fields provided for update';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_VALIDATION_ERROR',
                        'No fields provided for update',
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Validate status transitions
            IF p_status IS NOT NULL THEN
                -- Cannot update COMPLETED records
                IF v_current_record.status = 'COMPLETED' THEN
                    p_result_message := 'ERROR: Cannot update completed cycle';
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_VALIDATION_ERROR',
                            'Attempt to update completed cycle',
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'current_status', v_current_record.status,
                                'requested_status', p_status,
                                'user', v_audit_user,
                                'user_id', p_userid
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
                -- If approving, require approvedby if not already set
                IF p_status = 'APPROVED' AND p_approvedby IS NULL AND v_current_record.approvedby IS NULL THEN
                    p_result_message := 'ERROR: approvedby is required when approving a request';
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_VALIDATION_ERROR',
                            'Missing approver for approval',
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'error', p_result_message,
                                'user', v_audit_user,
                                'user_id', p_userid,
                                'current_status', v_current_record.status
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
                -- If verifying, require verifiedby AND verifiedbranchcode if not already set
                IF p_status = 'VERIFIED' THEN
                    IF p_verifiedby IS NULL AND v_current_record.verifiedby IS NULL THEN
                        p_result_message := 'ERROR: verifiedby is required when verifying a request';
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Missing verifier for verification',
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'error', p_result_message,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_status', v_current_record.status
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                    
                    IF p_verifiedbranchcode IS NULL AND v_current_record.verifiedbranchcode IS NULL THEN
                        p_result_message := 'ERROR: verifiedbranchcode is required when verifying a request';
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Missing verification branch for verification',
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'error', p_result_message,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_status', v_current_record.status
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                END IF;
            END IF;
            
            -- Perform update based on type
            IF v_update_type = 'ALL' THEN
                -- Update all fields
                UPDATE instantcardcycle
                SET 
                    scheme = COALESCE(p_scheme, scheme),
                    cardtype = COALESCE(p_cardtype, cardtype),
                    currency = CASE 
                        WHEN p_currency IS NOT NULL THEN UPPER(p_currency) 
                        ELSE currency 
                    END,
                    totalnumberofcard = COALESCE(p_totalnumberofcard, totalnumberofcard),
                    flags = COALESCE(p_flags, flags),
                    pintype = COALESCE(p_pintype, pintype),
                    requestedby = COALESCE(p_requestedby, requestedby),
                    requestedbranchname = COALESCE(p_requestedbranchname, requestedbranchname),
                    requestbranchcode = COALESCE(p_requestbranchcode, requestbranchcode),
                    approvedby = COALESCE(p_approvedby, approvedby),
                    approvedbranchcode = COALESCE(p_approvedbranchcode, approvedbranchcode),
                    approvedbranchname = COALESCE(p_approvedbranchname, approvedbranchname),
                    verifiedby = COALESCE(p_verifiedby, verifiedby),
                    verifiedbranchname = COALESCE(p_verifiedbranchname, verifiedbranchname),
                    verifiedbranchcode = COALESCE(p_verifiedbranchcode, verifiedbranchcode),
                    status = COALESCE(p_status, status),
                    approvedate = CASE 
                        WHEN p_status IN ('APPROVED', 'REJECTED') AND approvedate IS NULL THEN CURRENT_TIMESTAMP
                        WHEN p_status IN ('APPROVED', 'REJECTED') THEN approvedate
                        ELSE approvedate
                    END,
                    verifieddate = CASE 
                        WHEN p_status = 'VERIFIED' AND verifieddate IS NULL THEN CURRENT_TIMESTAMP
                        WHEN p_status = 'VERIFIED' THEN verifieddate
                        ELSE verifieddate
                    END
                WHERE requestid = p_requestid
                RETURNING jsonb_build_object(
                    'requestid', requestid,
                    'scheme', scheme,
                    'cardtype', cardtype,
                    'currency', currency,
                    'totalnumberofcard', totalnumberofcard,
                    'flags', flags,
                    'pintype', pintype,
                    'status', status,
                    'approvedby', approvedby,
                    'approvedbranchcode', approvedbranchcode,
                    'approvedbranchname', approvedbranchname,
                    'verifiedby', verifiedby,
                    'verifiedbranchname', verifiedbranchname,
                    'verifiedbranchcode', verifiedbranchcode,
                    'approvedate', approvedate,
                    'verifieddate', verifieddate,
                    'requestbranchcode', requestbranchcode,
                    'requestedbranchname', requestedbranchname
                ) INTO p_result_data;
                
                p_result_message := 'SUCCESS: All fields updated';
                
                -- Update audit data with changes for ALL fields update
                IF v_debug_flag = 1 THEN
                    IF p_scheme IS NOT NULL AND p_scheme != v_current_record.scheme THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,scheme}', 
                            jsonb_build_object('from', v_current_record.scheme, 'to', p_scheme));
                    END IF;
                    
                    IF p_totalnumberofcard IS NOT NULL AND p_totalnumberofcard != v_current_record.totalnumberofcard THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,totalnumberofcard}', 
                            jsonb_build_object('from', v_current_record.totalnumberofcard, 'to', p_totalnumberofcard));
                    END IF;
                    
                    IF p_status IS NOT NULL AND p_status != v_current_record.status THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,status}', 
                            jsonb_build_object('from', v_current_record.status, 'to', p_status));
                    END IF;
                    
                    IF p_verifiedby IS NOT NULL AND p_verifiedby != v_current_record.verifiedby THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,verifiedby}', 
                            jsonb_build_object('from', v_current_record.verifiedby, 'to', p_verifiedby));
                    END IF;
                    
                    IF p_verifiedbranchcode IS NOT NULL AND p_verifiedbranchcode != v_current_record.verifiedbranchcode THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,verifiedbranchcode}', 
                            jsonb_build_object('from', v_current_record.verifiedbranchcode, 'to', p_verifiedbranchcode));
                    END IF;
                    
                    IF p_requestbranchcode IS NOT NULL AND p_requestbranchcode != v_current_record.requestbranchcode THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,requestbranchcode}', 
                            jsonb_build_object('from', v_current_record.requestbranchcode, 'to', p_requestbranchcode));
                    END IF;
                    
                    v_audit_description := 'All fields updated for request: ' || p_requestid;
                END IF;
                
            ELSIF v_update_type = 'APPROVAL' THEN
                -- Update only approval/verification fields and status
                UPDATE instantcardcycle
                SET 
                    approvedby = COALESCE(p_approvedby, approvedby),
                    approvedbranchcode = COALESCE(p_approvedbranchcode, approvedbranchcode),
                    approvedbranchname = COALESCE(p_approvedbranchname, approvedbranchname),
                    verifiedby = COALESCE(p_verifiedby, verifiedby),
                    verifiedbranchname = COALESCE(p_verifiedbranchname, verifiedbranchname),
                    verifiedbranchcode = COALESCE(p_verifiedbranchcode, verifiedbranchcode),
                    status = COALESCE(p_status, status),
                    approvedate = CASE 
                        WHEN p_status IN ('APPROVED', 'REJECTED') AND approvedate IS NULL THEN CURRENT_TIMESTAMP
                        WHEN p_status IN ('APPROVED', 'REJECTED') THEN approvedate
                        ELSE approvedate
                    END,
                    verifieddate = CASE 
                        WHEN p_status = 'VERIFIED' AND verifieddate IS NULL THEN CURRENT_TIMESTAMP
                        WHEN p_status = 'VERIFIED' THEN verifieddate
                        ELSE verifieddate
                    END
                WHERE requestid = p_requestid
                RETURNING jsonb_build_object(
                    'requestid', requestid,
                    'status', status,
                    'approvedby', approvedby,
                    'approvedbranchcode', approvedbranchcode,
                    'approvedbranchname', approvedbranchname,
                    'verifiedby', verifiedby,
                    'verifiedbranchname', verifiedbranchname,
                    'verifiedbranchcode', verifiedbranchcode,
                    'approvedate', approvedate,
                    'verifieddate', verifieddate
                ) INTO p_result_data;
                
                p_result_message := 'SUCCESS: Approval/Verification fields updated';
                
                -- Update audit data for APPROVAL/VERIFICATION update
                IF v_debug_flag = 1 THEN
                    IF p_status IS NOT NULL AND p_status != v_current_record.status THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,status}', 
                            jsonb_build_object('from', v_current_record.status, 'to', p_status));
                    END IF;
                    
                    IF p_approvedby IS NOT NULL AND p_approvedby != v_current_record.approvedby THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,approvedby}', 
                            jsonb_build_object('from', v_current_record.approvedby, 'to', p_approvedby));
                    END IF;
                    
                    IF p_verifiedby IS NOT NULL AND p_verifiedby != v_current_record.verifiedby THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,verifiedby}', 
                            jsonb_build_object('from', v_current_record.verifiedby, 'to', p_verifiedby));
                    END IF;
                    
                    IF p_verifiedbranchcode IS NOT NULL AND p_verifiedbranchcode != v_current_record.verifiedbranchcode THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,verifiedbranchcode}', 
                            jsonb_build_object('from', v_current_record.verifiedbranchcode, 'to', p_verifiedbranchcode));
                    END IF;
                    
                    v_audit_description := 'Status updated to ' || COALESCE(p_status, v_current_record.status) || 
                                          ' for request: ' || p_requestid;
                END IF;
                
            END IF;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found';
                p_result_data := '{}'::JSONB;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_ERROR',
                        'Record not found during update: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
            ELSE
                -- ADDED: Include user access info in success message
                IF v_crossbranch = FALSE AND v_branchcode IS NOT NULL THEN
                    p_result_message := p_result_message || ' (User branch: ' || v_branchcode || ')';
                END IF;
                
                IF v_debug_flag = 1 AND v_audit_description IS NOT NULL THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_SUCCESS',
                        v_audit_description,
                        v_audit_data
                    );
                END IF;
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            p_result_message := 'ERROR: ' || SQLERRM;
            p_result_data := '{}'::JSONB;
            
            IF v_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    'UPDATE_ERROR',
                    'Update failed: ' || p_requestid || ' - ' || SQLERRM,
                    jsonb_build_object(
                        'requestid', p_requestid,
                        'error', SQLERRM,
                        'user', v_audit_user,
                        'user_id', p_userid
                    )
                );
            END IF;
        END;
        
    -- ACTION: DELETE (UPDATED with branch access control)
    ELSIF p_action = 'DELETE' THEN
        BEGIN
            IF p_requestid IS NULL THEN
                p_result_message := 'ERROR: requestid is required for DELETE';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_VALIDATION_ERROR',
                        'Missing requestid for DELETE',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Get record before deletion for audit logging
            SELECT * INTO v_current_record 
            FROM instantcardcycle 
            WHERE requestid = p_requestid;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_NOT_FOUND',
                        'Record not found for deletion: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- ADDED: Check if user has access to this record's branch
            IF v_branchcode IS NOT NULL AND v_crossbranch = FALSE 
               AND v_current_record.requestbranchcode != v_branchcode THEN
                p_result_message := 'ERROR: You do not have permission to delete this record. ' ||
                                   'Record belongs to branch: ' || v_current_record.requestbranchcode || 
                                   ', Your branch: ' || v_branchcode;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_ACCESS_DENIED',
                        'Branch access denied for DELETE',
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'record_branch', v_current_record.requestbranchcode,
                            'user_branch', v_branchcode,
                            'crossbranch', v_crossbranch,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Only allow deletion of PENDING or REJECTED records
            IF v_current_record.status NOT IN ('PENDING', 'REJECTED') THEN
                p_result_message := 'ERROR: Cannot delete record with status: ' || v_current_record.status;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_VALIDATION_ERROR',
                        'Delete failed - invalid status: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'status', v_current_record.status,
                            'allowed_statuses', 'PENDING, REJECTED',
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Prepare audit data for DELETE if debug flag is 1
            IF v_debug_flag = 1 THEN
                v_audit_data := jsonb_build_object(
                    'requestid', p_requestid,
                    'scheme', v_current_record.scheme,
                    'cardtype', v_current_record.cardtype,
                    'total_cards', v_current_record.totalnumberofcard,
                    'status', v_current_record.status,
                    'branch', v_current_record.requestbranchcode,
                    'requested_by', v_current_record.requestedby,
                    'approved_by', v_current_record.approvedby,
                    'verified_by', v_current_record.verifiedby,
                    'user', v_audit_user,
                    'user_id', p_userid,
                    'user_branch', v_branchcode,
                    'record_branch', v_current_record.requestbranchcode,
                    'crossbranch', v_crossbranch
                );
            END IF;
            
            -- Delete record
            DELETE FROM instantcardcycle 
            WHERE requestid = p_requestid;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_ERROR',
                        'Record not found during deletion: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
            ELSE
                p_result_message := 'SUCCESS: Record deleted from branch: ' || v_current_record.requestbranchcode;
                p_result_data := jsonb_build_object(
                    'deleted_requestid', p_requestid,
                    'deleted_branch', v_current_record.requestbranchcode,
                    'user_branch', v_branchcode
                );
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_SUCCESS',
                        'Instant card cycle deleted: ' || p_requestid,
                        v_audit_data
                    );
                END IF;
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            p_result_message := 'ERROR: ' || SQLERRM;
            
            IF v_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    'DELETE_ERROR',
                    'Delete failed: ' || p_requestid || ' - ' || SQLERRM,
                    jsonb_build_object(
                        'requestid', p_requestid,
                        'error', SQLERRM,
                        'user', v_audit_user,
                        'user_id', p_userid
                    )
                );
            END IF;
        END;
        
    END IF;
    
END;
$$;


ALTER FUNCTION public.finstantcardcycle_feb112026(p_action character varying, p_requestid character varying, p_scheme character varying, p_cardtype character varying, p_currency character varying, p_totalnumberofcard integer, p_flags character varying, p_pintype character varying, p_requestedby character varying, p_requestedbranchname character varying, p_requestbranchcode character varying, p_approvedby character varying, p_approvedbranchcode character varying, p_approvedbranchname character varying, p_verifiedby character varying, p_verifiedbranchname character varying, p_verifiedbranchcode character varying, p_status character varying, p_start_date date, p_end_date date, p_userid integer, OUT p_result_message character varying, OUT p_result_data jsonb) OWNER TO postgres;

