CREATE FUNCTION public.finstantgetrequestcountbooedapproved(p_branchname character varying) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    -- Return all records as a JSON array
    SELECT jsonb_agg(
        jsonb_build_object(
            'requestid', requestid,
            'totalnumberofcards', totalnumberofcard,
            'bookedcards', booked_cards,
            'approved_cards', approved_cards,
            'bookedcardallocated', bookedcardallocated,
            'approvedcardallocated', approvedcardsallocated,
            'status', status,
            'requestedbranchname', requestedbranchname,
            'requestbranchcode', requestbranchcode,
			'pintype',pintype
        )
    ) INTO v_result
    FROM instantcardcycle
    WHERE requestedbranchname = p_branchname;
    
    -- Check if any records found
    IF v_result IS NULL THEN
        RETURN jsonb_build_array(); -- Return empty array if no records
    END IF;
    
    RETURN v_result;
END;
$$;


