--

CREATE FUNCTION public.finstantgetrequestcountbooedapproved_backfeb16(p_branchname character varying) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result jsonb;
    v_record instantcardcycle%ROWTYPE;
BEGIN
    -- Get the first record for the requested branch name
    SELECT * INTO v_record
    FROM instantcardcycle
    WHERE requestedbranchname = p_branchname
    LIMIT 1;
    
    -- Check if record exists
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'error', 'No record found for branch',
            'branchname', p_branchname
        );
