        'bookedcards', v_record.booked_cards,
        'approved_cards', v_record.approved_cards,
        'bookedcardallocated', v_record.bookedcardallocated,
        'approvedcardallocated', v_record.approvedcardsallocated,
        'status', v_record.status,
        'requestedbranchname', v_record.requestedbranchname,
        'requestbranchcode', v_record.requestbranchcode
    );
    
    RETURN v_result;
END;
$$;


