-- TOC entry 475 (class 1255 OID 19201)
-- Name: foperationlogdump(character varying, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.foperationlogdump(p_function_name character varying, p_additional_info text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_operation_id BIGINT;
BEGIN
    INSERT INTO operation_log (
        function_name,
        start_time,
        execution_status,
        username,
        additional_info
    ) VALUES (
        p_function_name,
        CURRENT_TIMESTAMP,
        'STARTED',
        CURRENT_USER,
        p_additional_info
    ) RETURNING operation_id INTO v_operation_id;
    
    RETURN v_operation_id;
EXCEPTION
    WHEN others THEN
        RAISE NOTICE 'Failed to log operation start: %', SQLERRM;
        RETURN -1; -- Return -1 on failure
END;
$$;


