--
-- TOC entry 386 (class 1255 OID 24201)
-- Name: fproductcrud(character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fproductcrud(p_action character varying, p_productid character varying DEFAULT NULL::character varying, p_productname character varying DEFAULT NULL::character varying, p_productdescription character varying DEFAULT NULL::character varying, p_producttype character varying DEFAULT NULL::character varying, p_schemetype character varying DEFAULT NULL::character varying, p_currency character varying DEFAULT NULL::character varying, p_productbin character varying DEFAULT NULL::character varying, p_status character varying DEFAULT NULL::character varying, p_search_term character varying DEFAULT NULL::character varying, p_page_size integer DEFAULT 10, p_page_number integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_count INT;
    v_total_pages INT;
    v_offset INT;
    v_old_record JSONB;
    v_new_record JSONB;
    v_audit_message TEXT;
    v_deleted_count INT;
BEGIN
    -- Input validation
    IF p_action NOT IN ('INSERT', 'UPDATE', 'DELETE', 'LIST', 'GET') THEN
        RETURN jsonb_build_object(
            'status', 'ERROR',
            'message', 'Invalid action. Use INSERT, UPDATE, DELETE, LIST, or GET.',
            'timestamp', CURRENT_TIMESTAMP
        );
    END IF;

    -- For INSERT, UPDATE, DELETE actions, require basic validation
    IF p_action IN ('INSERT', 'UPDATE') THEN
        IF p_productname IS NULL OR p_productname = '' THEN
            RETURN jsonb_build_object(
                'status', 'ERROR',
                'message', 'Product name is required.',
                'timestamp', CURRENT_TIMESTAMP
            );
        END IF;
        
        IF p_producttype IS NULL OR p_producttype = '' THEN
            RETURN jsonb_build_object(
                'status', 'ERROR',
                'message', 'Product type is required.',
                'timestamp', CURRENT_TIMESTAMP
            );
        END IF;
        
        IF p_schemetype IS NULL OR p_schemetype = '' THEN
            RETURN jsonb_build_object(
                'status', 'ERROR',
                'message', 'Scheme type is required.',
                'timestamp', CURRENT_TIMESTAMP
            );
        END IF;
        
        IF p_currency IS NULL OR p_currency = '' THEN
            RETURN jsonb_build_object(
                'status', 'ERROR',
                'message', 'Currency is required.',
                'timestamp', CURRENT_TIMESTAMP
            );
        END IF;
        
        IF p_status IS NULL THEN
            p_status := 'ACTIVE';
        END IF;
    END IF;

    -- Perform the requested action
    CASE p_action
        WHEN 'INSERT' THEN
            -- Check for duplicate combination (unique constraint)
            BEGIN
                INSERT INTO products (
                    productname,
                    productdescription,
                    producttype,
                    schemetype,
                    currency,
                    productbin,
                    status
                ) VALUES (
                    p_productname,
                    p_productdescription,
                    p_producttype,
                    p_schemetype,
                    p_currency,
                    p_productbin,
                    p_status
                )
                RETURNING productid INTO p_productid;
                
                -- Get the inserted record
                SELECT jsonb_build_object(
                    'productid', productid,
                    'productname', productname,
                    'productdescription', productdescription,
                    'producttype', producttype,
                    'schemetype', schemetype,
                    'currency', currency,
                    'productbin', productbin,
                    'status', status,
                    'createddate', createddate,
                    'updateddate', updateddate
                ) INTO v_result
                FROM products
                WHERE productid = p_productid;
                
                -- Log audit trail
                v_audit_message := 'Product created: ' || p_productname || ' (' || p_productid || ')';
                PERFORM flog_audit_trail('PRODUCT', 'INSERT', v_audit_message, v_result);
                
                v_result := jsonb_build_object(
                    'status', 'SUCCESS',
                    'message', 'Product created successfully.',
                    'data', v_result,
                    'timestamp', CURRENT_TIMESTAMP
                );
                
            EXCEPTION 
                WHEN unique_violation THEN
                    v_result := jsonb_build_object(
                        'status', 'ERROR',
                        'message', 'A product with same type, scheme, currency and BIN already exists.',
                        'timestamp', CURRENT_TIMESTAMP
                    );
                WHEN OTHERS THEN
                    v_result := jsonb_build_object(
                        'status', 'ERROR',
                        'message', SQLERRM,
                        'detail', SQLSTATE,
                        'timestamp', CURRENT_TIMESTAMP
                    );
            END;
            
        WHEN 'UPDATE' THEN
            -- Check if product exists
            IF NOT EXISTS (SELECT 1 FROM products WHERE productid = p_productid) THEN
                RETURN jsonb_build_object(
                    'status', 'ERROR',
                    'message', 'Product not found.',
                    'timestamp', CURRENT_TIMESTAMP
                );
            END IF;
            
            -- Get old record for audit
            SELECT jsonb_build_object(
                'productid', productid,
                'productname', productname,
                'productdescription', productdescription,
                'producttype', producttype,
                'schemetype', schemetype,
                'currency', currency,
                'productbin', productbin,
                'status', status
            ) INTO v_old_record
            FROM products
            WHERE productid = p_productid;
            
            BEGIN
                UPDATE products
                SET 
                    productname = COALESCE(p_productname, productname),
                    productdescription = COALESCE(p_productdescription, productdescription),
                    producttype = COALESCE(p_producttype, producttype),
                    schemetype = COALESCE(p_schemetype, schemetype),
                    currency = COALESCE(p_currency, currency),
                    productbin = COALESCE(p_productbin, productbin),
                    status = COALESCE(p_status, status),
                    updateddate = CURRENT_TIMESTAMP
                WHERE productid = p_productid;
                
                -- Get the updated record
                SELECT jsonb_build_object(
                    'productid', productid,
                    'productname', productname,
                    'productdescription', productdescription,
                    'producttype', producttype,
                    'schemetype', schemetype,
                    'currency', currency,
                    'productbin', productbin,
                    'status', status,
                    'createddate', createddate,
                    'updateddate', updateddate
                ) INTO v_result
                FROM products
                WHERE productid = p_productid;
                
                -- Get new record for audit
                SELECT jsonb_build_object(
                    'productid', productid,
                    'productname', productname,
                    'productdescription', productdescription,
                    'producttype', producttype,
                    'schemetype', schemetype,
                    'currency', currency,
                    'productbin', productbin,
                    'status', status
                ) INTO v_new_record
                FROM products
                WHERE productid = p_productid;
                
                -- Log audit trail with changes
                v_audit_message := 'Product updated: ' || p_productid;
                PERFORM flog_audit_trail('PRODUCT', 'UPDATE', v_audit_message, 
                    jsonb_build_object('old', v_old_record, 'new', v_new_record));
                
                v_result := jsonb_build_object(
                    'status', 'SUCCESS',
                    'message', 'Product updated successfully.',
                    'data', v_result,
                    'timestamp', CURRENT_TIMESTAMP
                );
                
            EXCEPTION 
                WHEN unique_violation THEN
                    v_result := jsonb_build_object(
                        'status', 'ERROR',
                        'message', 'A product with same type, scheme, currency and BIN already exists.',
                        'timestamp', CURRENT_TIMESTAMP
                    );
                WHEN OTHERS THEN
                    v_result := jsonb_build_object(
                        'status', 'ERROR',
                        'message', SQLERRM,
                        'detail', SQLSTATE,
                        'timestamp', CURRENT_TIMESTAMP
                    );
            END;
            
        WHEN 'DELETE' THEN
            -- Check if product exists
            IF NOT EXISTS (SELECT 1 FROM products WHERE productid = p_productid) THEN
                RETURN jsonb_build_object(
                    'status', 'ERROR',
                    'message', 'Product not found.',
                    'timestamp', CURRENT_TIMESTAMP
                );
            END IF;
            
            -- Get record for audit before deletion
            SELECT jsonb_build_object(
                'productid', productid,
                'productname', productname,
                'productdescription', productdescription,
                'producttype', producttype,
                'schemetype', schemetype,
                'currency', currency,
                'productbin', productbin,
                'status', status,
                'createddate', createddate,
                'updateddate', updateddate
            ) INTO v_old_record
            FROM products
            WHERE productid = p_productid;
            
            -- Check dependencies with detailed error messages
            DECLARE
                v_card_count INT;
                v_chargeconfig_count INT;
                v_error_details TEXT;
            BEGIN
                -- Count active cards
                SELECT COUNT(*) INTO v_card_count
                FROM card 
                WHERE productid = p_productid AND status = 'A';
                
                -- Count active charge configurations
                SELECT COUNT(*) INTO v_chargeconfig_count
                FROM chargeconfig 
                WHERE productid = p_productid AND isactive = true;
                
                -- Build detailed error message if dependencies exist
                v_error_details := '';
                IF v_card_count > 0 THEN
                    v_error_details := v_error_details || ' Associated with ' || v_card_count || ' active card(s).';
                END IF;
                IF v_chargeconfig_count > 0 THEN
                    v_error_details := v_error_details || ' Has ' || v_chargeconfig_count || ' active charge configuration(s).';
                END IF;
                
                -- If dependencies exist, return error
                IF v_card_count > 0 OR v_chargeconfig_count > 0 THEN
                    RETURN jsonb_build_object(
                        'status', 'ERROR',
                        'message', 'Cannot delete product due to existing dependencies.' || v_error_details,
                        'dependencies', jsonb_build_object(
                            'active_cards', v_card_count,
                            'active_charge_configs', v_chargeconfig_count
                        ),
                        'timestamp', CURRENT_TIMESTAMP
                    );
                END IF;
                
                -- Perform HARD DELETE
                DELETE FROM products
                WHERE productid = p_productid;
                
                GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
                
                IF v_deleted_count = 0 THEN
                    v_result := jsonb_build_object(
                        'status', 'ERROR',
                        'message', 'Product deletion failed.',
                        'timestamp', CURRENT_TIMESTAMP
                    );
                ELSE
                    -- Log audit trail
                    v_audit_message := 'Product HARD DELETED: ' || p_productid;
                    PERFORM flog_audit_trail('PRODUCT', 'DELETE', v_audit_message, v_old_record);
                    
                    v_result := jsonb_build_object(
                        'status', 'SUCCESS',
                        'message', 'Product permanently deleted successfully.',
                        'deleted_data', v_old_record,
                        'deleted_count', v_deleted_count,
                        'timestamp', CURRENT_TIMESTAMP
                    );
                END IF;
            END;
            
        WHEN 'GET' THEN
            -- Get single product by ID
            IF p_productid IS NULL THEN
                RETURN jsonb_build_object(
                    'status', 'ERROR',
                    'message', 'Product ID is required for GET action.',
                    'timestamp', CURRENT_TIMESTAMP
                );
            END IF;
            
            SELECT jsonb_build_object(
                'productid', productid,
                'productname', productname,
                'productdescription', productdescription,
                'producttype', producttype,
                'schemetype', schemetype,
                'currency', currency,
                'productbin', productbin,
                'status', status,
                'createddate', createddate,
                'updateddate', updateddate
            ) INTO v_result
            FROM products
            WHERE productid = p_productid;
            
            IF v_result IS NULL THEN
                v_result := jsonb_build_object(
                    'status', 'ERROR',
                    'message', 'Product not found.',
                    'timestamp', CURRENT_TIMESTAMP
                );
            ELSE
                v_result := jsonb_build_object(
                    'status', 'SUCCESS',
                    'message', 'Product retrieved successfully.',
                    'data', v_result,
                    'timestamp', CURRENT_TIMESTAMP
                );
            END IF;
            
        WHEN 'LIST' THEN
            -- Calculate pagination
            v_offset := (p_page_number - 1) * p_page_size;
            
            -- Get total count for pagination
            SELECT COUNT(*) INTO v_count
            FROM products
            WHERE 1=1
            AND (
                p_search_term IS NULL OR
                productid ILIKE '%' || p_search_term || '%' OR
                productname ILIKE '%' || p_search_term || '%' OR
                productdescription ILIKE '%' || p_search_term || '%' OR
                producttype ILIKE '%' || p_search_term || '%'
            );
            
            v_total_pages := CEIL(v_count::DECIMAL / p_page_size);
            
            -- Get paginated results
            SELECT jsonb_agg(
                jsonb_build_object(
                    'productid', productid,
                    'productname', productname,
                    'productdescription', productdescription,
                    'producttype', producttype,
                    'schemetype', schemetype,
                    'currency', currency,
                    'productbin', productbin,
                    'status', status,
                    'createddate', createddate,
                    'updateddate', updateddate
                )
            ) INTO v_result
            FROM products
            WHERE 1=1
            AND (
                p_search_term IS NULL OR
                productid ILIKE '%' || p_search_term || '%' OR
                productname ILIKE '%' || p_search_term || '%' OR
                productdescription ILIKE '%' || p_search_term || '%' OR
                producttype ILIKE '%' || p_search_term || '%'
            )
            ORDER BY createddate DESC
            LIMIT p_page_size
            OFFSET v_offset;
            
            -- Handle empty result
            IF v_result IS NULL THEN
                v_result := '[]'::JSONB;
            END IF;
            
            v_result := jsonb_build_object(
                'status', 'SUCCESS',
                'message', 'Products listed successfully.',
                'data', v_result,
                'pagination', jsonb_build_object(
                    'total_records', v_count,
                    'total_pages', v_total_pages,
                    'current_page', p_page_number,
                    'page_size', p_page_size,
                    'has_next', p_page_number < v_total_pages,
                    'has_previous', p_page_number > 1
                ),
                'timestamp', CURRENT_TIMESTAMP
            );
            
    END CASE;
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'status', 'ERROR',
            'message', 'Unexpected error: ' || SQLERRM,
            'detail', SQLSTATE,
            'timestamp', CURRENT_TIMESTAMP
        );
END;
$$;


