--

CREATE FUNCTION public.fruleactionscurd(p_action character varying, p_actionid character varying DEFAULT NULL::character varying, p_ruleid character varying DEFAULT NULL::character varying, p_action_type character varying DEFAULT NULL::character varying, p_action_value jsonb DEFAULT NULL::jsonb, p_user_id character varying DEFAULT NULL::character varying, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_old_record JSONB;
    v_new_record JSONB;
    v_audit_description TEXT;
    v_error_message TEXT;
    v_error_detail TEXT;
    v_error_hint TEXT;
    v_existing_actionid VARCHAR(5);
    v_action_count INTEGER;
    v_rule_count INTEGER;
    v_return_message TEXT;
    v_action_value_text TEXT;
BEGIN
    -- Initialize result
    v_result := '{"success": false, "message": "Unknown error", "data": null}'::JSONB;
    
    -- Trim and validate inputs
    p_action := UPPER(TRIM(p_action));
    p_actionid := TRIM(p_actionid);
    p_ruleid := TRIM(p_ruleid);
    p_action_type := TRIM(p_action_type);
    
    -- Log function call for debugging
    INSERT INTO public.audit_trail (
        entity_type, 
        action_type, 
        description, 
        data, 
        user_id, 
        ip_address, 
        user_agent
    ) VALUES (
        'FUNCTION_CALL',
        'EXECUTE',
        'fruleactionsCURD called with action: ' || p_action,
        jsonb_build_object(
            'actionid', p_actionid,
            'ruleid', p_ruleid,
            'action_type', p_action_type,
            'action', p_action
        ),
        p_user_id,
        p_ip_address,
        p_user_agent
    );
    
    -- Validate action parameter
    IF p_action NOT IN ('INSERT', 'UPDATE', 'DELETE', 'LIST', 'SELECT', 'LIST_BY_RULE') THEN
        RAISE EXCEPTION 'Invalid action. Must be INSERT, UPDATE, DELETE, LIST, SELECT, or LIST_BY_RULE';
    END IF;
    
    -- Validate required parameters based on action
    CASE p_action
        WHEN 'INSERT' THEN
            -- Validate mandatory fields for INSERT
            IF p_ruleid IS NULL OR p_ruleid = '' THEN
                RAISE EXCEPTION 'ruleid is required for INSERT';
            END IF;
            
            IF p_action_type IS NULL OR p_action_type = '' THEN
                RAISE EXCEPTION 'action_type is required for INSERT';
            END IF;
            
            IF p_action_value IS NULL THEN
                RAISE EXCEPTION 'action_value (JSONB) is required for INSERT';
            END IF;
            
            -- Check if parent rule exists
            SELECT COUNT(*) INTO v_rule_count
            FROM public.rulesmaster
            WHERE ruleid = p_ruleid;
            
            IF v_rule_count = 0 THEN
                RAISE EXCEPTION 'Parent rule with ruleid "%" does not exist', p_ruleid;
            END IF;
            
            -- Validate action_value is valid JSONB
            BEGIN
                v_action_value_text := p_action_value::TEXT;
            EXCEPTION WHEN OTHERS THEN
                RAISE EXCEPTION 'Invalid JSONB format for action_value';
            END;
            
        WHEN 'UPDATE' THEN
            -- Validate UPDATE parameters
            IF p_actionid IS NULL OR p_actionid = '' THEN
                RAISE EXCEPTION 'actionid is required for UPDATE';
            END IF;
            
            -- Check if record exists
            SELECT COUNT(*) INTO v_action_count
            FROM public.ruleactions
            WHERE actionid = p_actionid;
            
            IF v_action_count = 0 THEN
                RAISE EXCEPTION 'actionid "%" not found', p_actionid;
            END IF;
            
            -- Get old record for audit
            SELECT row_to_json(ra) INTO v_old_record
            FROM public.ruleactions ra
            WHERE actionid = p_actionid;
            
            -- Check if new ruleid exists (if provided)
            IF p_ruleid IS NOT NULL AND p_ruleid != '' THEN
                SELECT COUNT(*) INTO v_rule_count
                FROM public.rulesmaster
                WHERE ruleid = p_ruleid;
                
                IF v_rule_count = 0 THEN
                    RAISE EXCEPTION 'Parent rule with ruleid "%" does not exist', p_ruleid;
                END IF;
            END IF;
            
            -- Validate action_value if provided
            IF p_action_value IS NOT NULL THEN
                BEGIN
                    v_action_value_text := p_action_value::TEXT;
                EXCEPTION WHEN OTHERS THEN
                    RAISE EXCEPTION 'Invalid JSONB format for action_value';
                END;
            END IF;
            
        WHEN 'DELETE' THEN
            -- Validate DELETE parameters
            IF p_actionid IS NULL OR p_actionid = '' THEN
                RAISE EXCEPTION 'actionid is required for DELETE';
            END IF;
            
            -- Check if record exists
            SELECT COUNT(*) INTO v_action_count
            FROM public.ruleactions
            WHERE actionid = p_actionid;
            
            IF v_action_count = 0 THEN
                RAISE EXCEPTION 'actionid "%" not found', p_actionid;
            END IF;
            
            -- Get record for audit
            SELECT row_to_json(ra) INTO v_old_record
            FROM public.ruleactions ra
            WHERE actionid = p_actionid;
            
        WHEN 'SELECT' THEN
            -- Validate SELECT parameters
            IF p_actionid IS NULL OR p_actionid = '' THEN
                RAISE EXCEPTION 'actionid is required for SELECT';
            END IF;
            
        WHEN 'LIST_BY_RULE' THEN
            -- Validate LIST_BY_RULE parameters
            IF p_ruleid IS NULL OR p_ruleid = '' THEN
                RAISE EXCEPTION 'ruleid is required for LIST_BY_RULE';
            END IF;
            
            -- Check if parent rule exists
            SELECT COUNT(*) INTO v_rule_count
            FROM public.rulesmaster
            WHERE ruleid = p_ruleid;
            
            IF v_rule_count = 0 THEN
                RAISE EXCEPTION 'Parent rule with ruleid "%" does not exist', p_ruleid;
            END IF;
            
    END CASE;
    
    -- Execute the requested action
    CASE p_action
        WHEN 'INSERT' THEN
            -- Insert new rule action
            INSERT INTO public.ruleactions (
                ruleid,
                action_type,
                action_value
            ) VALUES (
                p_ruleid,
                p_action_type,
                p_action_value
            )
            RETURNING actionid INTO v_existing_actionid;
            
            -- Get the newly inserted record
            SELECT jsonb_build_object(
                'actionid', ra.actionid,
                'ruleid', ra.ruleid,
                'action_type', ra.action_type,
                'action_value', ra.action_value,
                'created_at', ra.created_at,
                'updated_at', ra.updated_at
            ) INTO v_new_record
            FROM public.ruleactions ra
            WHERE actionid = v_existing_actionid;
            
            v_return_message := 'Rule action created successfully';
            v_audit_description := 'Created new rule action for rule: ' || p_ruleid;
            
        WHEN 'UPDATE' THEN
            -- Update existing rule action
            UPDATE public.ruleactions
            SET 
                ruleid = COALESCE(NULLIF(p_ruleid, ''), ruleid),
                action_type = COALESCE(NULLIF(p_action_type, ''), action_type),
                action_value = COALESCE(p_action_value, action_value),
                updated_at = CURRENT_TIMESTAMP
            WHERE actionid = p_actionid
            RETURNING actionid INTO v_existing_actionid;
            
            -- Get the updated record
            SELECT jsonb_build_object(
                'actionid', ra.actionid,
                'ruleid', ra.ruleid,
                'action_type', ra.action_type,
                'action_value', ra.action_value,
                'created_at', ra.created_at,
                'updated_at', ra.updated_at
            ) INTO v_new_record
            FROM public.ruleactions ra
            WHERE actionid = p_actionid;
            
            v_return_message := 'Rule action updated successfully';
            v_audit_description := 'Updated rule action: ' || p_actionid;
            
        WHEN 'DELETE' THEN
            -- Delete rule action
            DELETE FROM public.ruleactions
            WHERE actionid = p_actionid;
            
            v_return_message := 'Rule action deleted successfully';
            v_audit_description := 'Deleted rule action: ' || p_actionid;
            v_new_record := NULL;
            
        WHEN 'SELECT' THEN
            -- Select specific rule action
            SELECT jsonb_build_object(
                'actionid', ra.actionid,
                'ruleid', ra.ruleid,
                'action_type', ra.action_type,
                'action_value', ra.action_value,
                'created_at', ra.created_at,
                'updated_at', ra.updated_at
            ) INTO v_new_record
            FROM public.ruleactions ra
            WHERE actionid = p_actionid;
            
            IF v_new_record IS NULL THEN
                RAISE EXCEPTION 'Rule action with ID "%" not found', p_actionid;
            END IF;
            
            v_return_message := 'Rule action retrieved successfully';
            v_audit_description := 'Retrieved rule action: ' || p_actionid;
            v_old_record := NULL;
            
        WHEN 'LIST' THEN
            -- Get all rule actions
            SELECT jsonb_agg(
                jsonb_build_object(
                    'actionid', ra.actionid,
                    'ruleid', ra.ruleid,
                    'action_type', ra.action_type,
                    'action_value', ra.action_value,
                    'created_at', ra.created_at,
                    'updated_at', ra.updated_at
                )
            ) INTO v_new_record
            FROM public.ruleactions ra
            ORDER BY ra.created_at DESC;
            
            IF v_new_record IS NULL THEN
                v_new_record := '[]'::JSONB;
            END IF;
            
            v_return_message := 'Rule actions listed successfully';
            v_audit_description := 'Listed all rule actions';
            v_old_record := NULL;
            
        WHEN 'LIST_BY_RULE' THEN
            -- Get all actions for a specific rule
            SELECT jsonb_agg(
                jsonb_build_object(
                    'actionid', ra.actionid,
                    'ruleid', ra.ruleid,
                    'action_type', ra.action_type,
                    'action_value', ra.action_value,
                    'created_at', ra.created_at,
                    'updated_at', ra.updated_at
                )
            ) INTO v_new_record
            FROM public.ruleactions ra
            WHERE ra.ruleid = p_ruleid
            ORDER BY ra.created_at DESC;
            
            IF v_new_record IS NULL THEN
                v_new_record := '[]'::JSONB;
            END IF;
            
            v_return_message := 'Rule actions listed for rule: ' || p_ruleid;
            v_audit_description := 'Listed actions for rule: ' || p_ruleid;
            v_old_record := NULL;
            
    END CASE;
    
    -- Log the action to audit trail (except for LIST operations)
    IF p_action NOT IN ('LIST', 'LIST_BY_RULE') THEN
        INSERT INTO public.audit_trail (
            entity_type, 
            action_type, 
            description, 
            data, 
            user_id, 
            ip_address, 
            user_agent
        ) VALUES (
            'RULEACTIONS',
            p_action,
            v_audit_description,
            jsonb_build_object(
                'old_record', v_old_record,
                'new_record', v_new_record,
                'actionid', COALESCE(p_actionid, v_existing_actionid),
                'ruleid', p_ruleid
            ),
            p_user_id,
            p_ip_address,
            p_user_agent
        );
    END IF;
    
    -- Build success response
    v_result := jsonb_build_object(
        'success', true,
        'message', v_return_message,
        'data', CASE 
            WHEN p_action IN ('LIST', 'LIST_BY_RULE') THEN v_new_record
            ELSE jsonb_build_object('ruleaction', v_new_record)
        END,
        'actionid', COALESCE(p_actionid, v_existing_actionid),
        'ruleid', CASE 
            WHEN p_action = 'LIST_BY_RULE' THEN p_ruleid
            WHEN p_action IN ('INSERT', 'UPDATE') THEN COALESCE(p_ruleid, 
                (v_new_record->>'ruleid')::VARCHAR)
            ELSE NULL
        END
    );
    
    RETURN v_result;
    
EXCEPTION
    WHEN foreign_key_violation THEN
        v_error_message := 'Foreign key violation. The referenced rule does not exist.';
        v_error_detail := SQLERRM;
        v_error_hint := 'Ensure the ruleid exists in rulesmaster table.';
        
    WHEN invalid_text_representation THEN
        v_error_message := 'Invalid JSONB format for action_value.';
        v_error_detail := SQLERRM;
        v_error_hint := 'Provide valid JSON format for action_value.';
        
    WHEN OTHERS THEN
        -- Get error details
        GET STACKED DIAGNOSTICS 
            v_error_message = MESSAGE_TEXT,
            v_error_detail = PG_EXCEPTION_DETAIL,
            v_error_hint = PG_EXCEPTION_HINT;
        
    -- Log error to audit trail
    INSERT INTO public.audit_trail (
        entity_type, 
        action_type, 
        description, 
        data, 
        user_id, 
        ip_address, 
        user_agent
    ) VALUES (
        'RULEACTIONS',
        'ERROR',
        'Error in fruleactionsCURD: ' || v_error_message,
        jsonb_build_object(
            'action', p_action,
            'error_detail', v_error_detail,
            'error_hint', v_error_hint,
            'actionid', p_actionid,
            'ruleid', p_ruleid
        ),
        p_user_id,
        p_ip_address,
        p_user_agent
    );
    
    -- Build error response
    v_result := jsonb_build_object(
        'success', false,
        'message', 'Operation failed: ' || v_error_message,
        'error_detail', v_error_detail,
        'error_hint', v_error_hint,
        'data', null
    );
    
    RETURN v_result;
END;
$$;


