CREATE FUNCTION public.frulecondtionvalidate_condition_value(p_value text, p_data_type character varying, p_operator character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_validated_value TEXT;
    v_array_values TEXT[];
    v_min_value NUMERIC;
    v_max_value NUMERIC;
BEGIN
    -- Handle empty values
    IF p_value IS NULL OR p_value = '' THEN
        RETURN NULL;
    END IF;
    
    -- Validate based on data_type
    CASE p_data_type
        WHEN 'string' THEN
            -- String validation
            v_validated_value := p_value;
            
        WHEN 'integer' THEN
            -- Integer validation
            BEGIN
                IF p_operator = 'BETWEEN' THEN
                    -- Parse range for BETWEEN operator
                    v_array_values := string_to_array(p_value, ',');
                    IF array_length(v_array_values, 1) = 2 THEN
                        v_min_value := v_array_values[1]::INTEGER;
                        v_max_value := v_array_values[2]::INTEGER;
                        IF v_min_value <= v_max_value THEN
                            v_validated_value := p_value;
                        END IF;
                    END IF;
                ELSIF p_operator = 'IN' THEN
                    -- Parse list for IN operator
                    v_array_values := string_to_array(p_value, ',');
                    FOR i IN 1..array_length(v_array_values, 1) LOOP
                        BEGIN
                            v_array_values[i] := v_array_values[i]::INTEGER::TEXT;
                        EXCEPTION WHEN OTHERS THEN
                            RETURN NULL;
                        END;
                    END LOOP;
                    v_validated_value := array_to_string(v_array_values, ',');
                ELSE
                    -- Single integer value
                    v_validated_value := p_value::INTEGER::TEXT;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                RETURN NULL;
            END;
            
        WHEN 'decimal' THEN
            -- Decimal validation
            BEGIN
                IF p_operator = 'BETWEEN' THEN
                    -- Parse range for BETWEEN operator
                    v_array_values := string_to_array(p_value, ',');
                    IF array_length(v_array_values, 1) = 2 THEN
                        v_min_value := v_array_values[1]::NUMERIC;
                        v_max_value := v_array_values[2]::NUMERIC;
                        IF v_min_value <= v_max_value THEN
                            v_validated_value := p_value;
                        END IF;
                    END IF;
                ELSIF p_operator = 'IN' THEN
                    -- Parse list for IN operator
                    v_array_values := string_to_array(p_value, ',');
                    FOR i IN 1..array_length(v_array_values, 1) LOOP
                        BEGIN
                            v_array_values[i] := v_array_values[i]::NUMERIC::TEXT;
                        EXCEPTION WHEN OTHERS THEN
                            RETURN NULL;
                        END;
                    END LOOP;
                    v_validated_value := array_to_string(v_array_values, ',');
                ELSE
                    -- Single decimal value
                    v_validated_value := p_value::NUMERIC::TEXT;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                RETURN NULL;
            END;
            
        WHEN 'boolean' THEN
            -- Boolean validation
            IF p_value IN ('true', 'false', 'TRUE', 'FALSE', '1', '0') THEN
                v_validated_value := LOWER(p_value);
            ELSE
                RETURN NULL;
            END IF;
            
        WHEN 'date' THEN
            -- Date validation
            BEGIN
                IF p_operator = 'BETWEEN' THEN
                    -- Parse range for BETWEEN operator
                    v_array_values := string_to_array(p_value, ',');
                    IF array_length(v_array_values, 1) = 2 THEN
                        -- Validate both dates
                        v_validated_value := 
                            v_array_values[1]::DATE::TEXT || ',' || 
                            v_array_values[2]::DATE::TEXT;
                    END IF;
                ELSIF p_operator = 'IN' THEN
                    -- Parse list for IN operator
                    v_array_values := string_to_array(p_value, ',');
                    FOR i IN 1..array_length(v_array_values, 1) LOOP
                        BEGIN
                            v_array_values[i] := v_array_values[i]::DATE::TEXT;
                        EXCEPTION WHEN OTHERS THEN
                            RETURN NULL;
                        END;
                    END LOOP;
                    v_validated_value := array_to_string(v_array_values, ',');
                ELSE
                    -- Single date value
                    v_validated_value := p_value::DATE::TEXT;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                RETURN NULL;
            END;
            
        WHEN 'timestamp' THEN
            -- Timestamp validation
            BEGIN
                IF p_operator = 'BETWEEN' THEN
                    -- Parse range for BETWEEN operator
                    v_array_values := string_to_array(p_value, ',');
                    IF array_length(v_array_values, 1) = 2 THEN
                        -- Validate both timestamps
                        v_validated_value := 
                            v_array_values[1]::TIMESTAMP::TEXT || ',' || 
                            v_array_values[2]::TIMESTAMP::TEXT;
                    END IF;
                ELSIF p_operator = 'IN' THEN
                    -- Parse list for IN operator
                    v_array_values := string_to_array(p_value, ',');
                    FOR i IN 1..array_length(v_array_values, 1) LOOP
                        BEGIN
                            v_array_values[i] := v_array_values[i]::TIMESTAMP::TEXT;
                        EXCEPTION WHEN OTHERS THEN
                            RETURN NULL;
                        END;
                    END LOOP;
                    v_validated_value := array_to_string(v_array_values, ',');
                ELSE
                    -- Single timestamp value
                    v_validated_value := p_value::TIMESTAMP::TEXT;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                RETURN NULL;
            END;
            
        ELSE
            RETURN NULL;
    END CASE;
    
    RETURN v_validated_value;
END;
$$;


