CREATE FUNCTION public.frulesmastercurd(p_action character varying, p_ruleid character varying DEFAULT NULL::character varying, p_rulename character varying DEFAULT NULL::character varying, p_ruletype character varying DEFAULT NULL::character varying, p_appliesto character varying DEFAULT NULL::character varying, p_description text DEFAULT NULL::text, p_priority integer DEFAULT NULL::integer, p_isactive boolean DEFAULT NULL::boolean, p_startdate date DEFAULT NULL::date, p_enddate date DEFAULT NULL::date, p_user_id character varying DEFAULT NULL::character varying, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_old_record JSONB;
    v_new_record JSONB;
    v_audit_description TEXT;
    v_error_message TEXT;
    v_error_detail TEXT;
    v_error_hint TEXT;
    v_existing_ruleid VARCHAR(5);
    v_rule_count INTEGER;
    v_return_message TEXT;
    v_allowed_ruletypes TEXT[] := ARRAY['VALIDATION', 'CALCULATION', 'BUSINESS', 'SECURITY', 'WORKFLOW', 'OTHER'];
    v_valid_ruletype BOOLEAN;
BEGIN
    -- Initialize result
    v_result := '{"success": false, "message": "Unknown error", "data": null}'::JSONB;
    
    -- Trim and validate inputs
    p_action := TRIM(p_action);
    p_ruleid := TRIM(p_ruleid);
    p_rulename := TRIM(p_rulename);
    p_ruletype := TRIM(p_ruletype);
    p_appliesto := TRIM(p_appliesto);
    p_description := TRIM(p_description);
    
    -- Log function call for debugging
    INSERT INTO public.audit_trail (
        entity_type, 
        action_type, 
        description, 
        data, 
        user_id, 
        ip_address, 
        user_agent
    ) VALUES (
        'FUNCTION_CALL',
        'EXECUTE',
        'frulesmasterCURD called with action: ' || p_action,
        jsonb_build_object(
            'ruleid', p_ruleid,
            'rulename', p_rulename,
            'ruletype', p_ruletype,
            'action', p_action
        ),
        p_user_id,
        p_ip_address,
        p_user_agent
    );
    
    -- Validate action parameter
    IF p_action NOT IN ('INSERT', 'UPDATE', 'DELETE', 'LIST', 'SELECT') THEN
        RAISE EXCEPTION 'Invalid action. Must be INSERT, UPDATE, DELETE, LIST, or SELECT';
    END IF;
    
    -- Validate required parameters based on action
    CASE p_action
        WHEN 'INSERT' THEN
            -- Validate mandatory fields for INSERT
            IF p_rulename IS NULL OR p_rulename = '' THEN
                RAISE EXCEPTION 'rulename is required for INSERT';
            END IF;
            
            IF p_ruletype IS NULL OR p_ruletype = '' THEN
                RAISE EXCEPTION 'ruletype is required for INSERT';
            END IF;
            
            IF p_appliesto IS NULL OR p_appliesto = '' THEN
                RAISE EXCEPTION 'appliesto is required for INSERT';
            END IF;
            
            IF p_priority IS NULL THEN
                RAISE EXCEPTION 'priority is required for INSERT';
            END IF;
            
            IF p_startdate IS NULL THEN
                RAISE EXCEPTION 'startdate is required for INSERT';
            END IF;
            
            -- Validate ruletype - either in allowed list or pass through
            -- Comment out strict validation if you want to allow any ruletype
            /*
            IF NOT (p_ruletype = ANY(v_allowed_ruletypes)) THEN
                RAISE EXCEPTION 'ruletype must be one of: %, %, %, %, %, or %', 
                    v_allowed_ruletypes[1], v_allowed_ruletypes[2], v_allowed_ruletypes[3],
                    v_allowed_ruletypes[4], v_allowed_ruletypes[5], v_allowed_ruletypes[6];
            END IF;
            */
            
            -- Validate priority range
            IF p_priority < 1 OR p_priority > 999 THEN
                RAISE EXCEPTION 'priority must be between 1 and 999';
            END IF;
            
            -- Validate date range
            IF p_enddate IS NOT NULL AND p_startdate > p_enddate THEN
                RAISE EXCEPTION 'startdate cannot be after enddate';
            END IF;
            
            -- Check for duplicate rulename
            SELECT COUNT(*) INTO v_rule_count
            FROM public.rulesmaster
            WHERE LOWER(rulename) = LOWER(p_rulename);
            
            IF v_rule_count > 0 THEN
                RAISE EXCEPTION 'rulename "%" already exists', p_rulename;
            END IF;
            
        WHEN 'UPDATE' THEN
            -- Validate UPDATE parameters
            IF p_ruleid IS NULL OR p_ruleid = '' THEN
                RAISE EXCEPTION 'ruleid is required for UPDATE';
            END IF;
            
            -- Check if record exists
            SELECT COUNT(*) INTO v_rule_count
            FROM public.rulesmaster
            WHERE ruleid = p_ruleid;
            
            IF v_rule_count = 0 THEN
                RAISE EXCEPTION 'ruleid "%" not found', p_ruleid;
            END IF;
            
            -- Get old record for audit
            SELECT row_to_json(rm) INTO v_old_record
            FROM public.rulesmaster rm
            WHERE ruleid = p_ruleid;
            
            -- Validate ruletype if provided (commented out for flexibility)
            /*
            IF p_ruletype IS NOT NULL AND p_ruletype != '' THEN
                IF NOT (p_ruletype = ANY(v_allowed_ruletypes)) THEN
                    RAISE EXCEPTION 'ruletype must be one of: %, %, %, %, %, or %', 
                        v_allowed_ruletypes[1], v_allowed_ruletypes[2], v_allowed_ruletypes[3],
                        v_allowed_ruletypes[4], v_allowed_ruletypes[5], v_allowed_ruletypes[6];
                END IF;
            END IF;
            */
            
            -- Validate priority range if provided
            IF p_priority IS NOT NULL THEN
                IF p_priority < 1 OR p_priority > 999 THEN
                    RAISE EXCEPTION 'priority must be between 1 and 999';
                END IF;
            END IF;
            
            -- Validate date logic
            IF (p_startdate IS NOT NULL AND p_enddate IS NOT NULL) AND (p_startdate > p_enddate) THEN
                RAISE EXCEPTION 'startdate cannot be after enddate';
            END IF;
            
        WHEN 'DELETE' THEN
            -- Validate DELETE parameters
            IF p_ruleid IS NULL OR p_ruleid = '' THEN
                RAISE EXCEPTION 'ruleid is required for DELETE';
            END IF;
            
            -- Check if record exists
            SELECT COUNT(*) INTO v_rule_count
            FROM public.rulesmaster
            WHERE ruleid = p_ruleid;
            
            IF v_rule_count = 0 THEN
                RAISE EXCEPTION 'ruleid "%" not found', p_ruleid;
            END IF;
            
            -- Get record for audit
            SELECT row_to_json(rm) INTO v_old_record
            FROM public.rulesmaster rm
            WHERE ruleid = p_ruleid;
            
        WHEN 'SELECT' THEN
            -- Validate SELECT parameters
            IF p_ruleid IS NULL OR p_ruleid = '' THEN
                RAISE EXCEPTION 'ruleid is required for SELECT';
            END IF;
            
    END CASE;
    
    -- Execute the requested action
    CASE p_action
        WHEN 'INSERT' THEN
            -- Insert new rule
            INSERT INTO public.rulesmaster (
                rulename,
                ruletype,
                appliesto,
                description,
                priority,
                isactive,
                startdate,
                enddate
            ) VALUES (
                p_rulename,
                p_ruletype,
                p_appliesto,
                p_description,
                p_priority,
                COALESCE(p_isactive, true),
                p_startdate,
                p_enddate
            )
            RETURNING ruleid INTO v_existing_ruleid;
            
            -- Get the newly inserted record
            SELECT jsonb_build_object(
                'ruleid', rm.ruleid,
                'rulename', rm.rulename,
                'ruletype', rm.ruletype,
                'appliesto', rm.appliesto,
                'description', rm.description,
                'priority', rm.priority,
                'isactive', rm.isactive,
                'startdate', rm.startdate,
                'enddate', rm.enddate,
                'created_at', rm.created_at,
                'updated_at', rm.updated_at
            ) INTO v_new_record
            FROM public.rulesmaster rm
            WHERE ruleid = v_existing_ruleid;
            
            v_return_message := 'Rule created successfully';
            v_audit_description := 'Created new rule: ' || p_rulename;
            
        WHEN 'UPDATE' THEN
            -- Update existing rule
            UPDATE public.rulesmaster
            SET 
                rulename = COALESCE(p_rulename, rulename),
                ruletype = COALESCE(NULLIF(p_ruletype, ''), ruletype),
                appliesto = COALESCE(NULLIF(p_appliesto, ''), appliesto),
                description = COALESCE(p_description, description),
                priority = COALESCE(p_priority, priority),
                isactive = COALESCE(p_isactive, isactive),
                startdate = COALESCE(p_startdate, startdate),
                enddate = p_enddate, -- Allow NULL enddate
                updated_at = CURRENT_TIMESTAMP
            WHERE ruleid = p_ruleid
            RETURNING ruleid INTO v_existing_ruleid;
            
            -- Get the updated record
            SELECT jsonb_build_object(
                'ruleid', rm.ruleid,
                'rulename', rm.rulename,
                'ruletype', rm.ruletype,
                'appliesto', rm.appliesto,
                'description', rm.description,
                'priority', rm.priority,
                'isactive', rm.isactive,
                'startdate', rm.startdate,
                'enddate', rm.enddate,
                'created_at', rm.created_at,
                'updated_at', rm.updated_at
            ) INTO v_new_record
            FROM public.rulesmaster rm
            WHERE ruleid = p_ruleid;
            
            v_return_message := 'Rule updated successfully';
            v_audit_description := 'Updated rule: ' || p_ruleid;
            
        WHEN 'DELETE' THEN
            -- Delete rule
            DELETE FROM public.rulesmaster
            WHERE ruleid = p_ruleid;
            
            v_return_message := 'Rule deleted successfully';
            v_audit_description := 'Deleted rule: ' || p_ruleid;
            v_new_record := NULL;
            
        WHEN 'SELECT' THEN
            -- Select specific rule
            SELECT jsonb_build_object(
                'ruleid', rm.ruleid,
                'rulename', rm.rulename,
                'ruletype', rm.ruletype,
                'appliesto', rm.appliesto,
                'description', rm.description,
                'priority', rm.priority,
                'isactive', rm.isactive,
                'startdate', rm.startdate,
                'enddate', rm.enddate,
                'created_at', rm.created_at,
                'updated_at', rm.updated_at
            ) INTO v_new_record
            FROM public.rulesmaster rm
            WHERE ruleid = p_ruleid;
            
            IF v_new_record IS NULL THEN
                RAISE EXCEPTION 'Rule with ID "%" not found', p_ruleid;
            END IF;
            
            v_return_message := 'Rule retrieved successfully';
            v_audit_description := 'Retrieved rule: ' || p_ruleid;
            v_old_record := NULL;
            
        WHEN 'LIST' THEN
            -- Get all rules with optional filtering
            SELECT jsonb_agg(
                jsonb_build_object(
                    'ruleid', rm.ruleid,
                    'rulename', rm.rulename,
                    'ruletype', rm.ruletype,
                    'appliesto', rm.appliesto,
                    'description', rm.description,
                    'priority', rm.priority,
                    'isactive', rm.isactive,
                    'startdate', rm.startdate,
                    'enddate', rm.enddate,
                    'created_at', rm.created_at,
                    'updated_at', rm.updated_at
                )
            ) INTO v_new_record
            FROM public.rulesmaster rm
            WHERE 
                (p_isactive IS NULL OR rm.isactive = p_isactive)
                AND (p_ruletype IS NULL OR rm.ruletype = p_ruletype)
                AND (p_appliesto IS NULL OR rm.appliesto = p_appliesto)
            ORDER BY rm.priority, rm.created_at DESC;
            
            IF v_new_record IS NULL THEN
                v_new_record := '[]'::JSONB;
            END IF;
            
            v_return_message := 'Rules listed successfully';
            v_audit_description := 'Listed rules';
            v_old_record := NULL;
            
    END CASE;
    
    -- Log the action to audit trail (except for LIST which could return many records)
    IF p_action != 'LIST' THEN
        INSERT INTO public.audit_trail (
            entity_type, 
            action_type, 
            description, 
            data, 
            user_id, 
            ip_address, 
            user_agent
        ) VALUES (
            'RULESMASTER',
            p_action,
            v_audit_description,
            jsonb_build_object(
                'old_record', v_old_record,
                'new_record', v_new_record,
                'ruleid', COALESCE(p_ruleid, v_existing_ruleid)
            ),
            p_user_id,
            p_ip_address,
            p_user_agent
        );
    END IF;
    
    -- Build success response
    v_result := jsonb_build_object(
        'success', true,
        'message', v_return_message,
        'data', CASE 
            WHEN p_action = 'LIST' THEN v_new_record
            ELSE jsonb_build_object('rule', v_new_record)
        END,
        'ruleid', COALESCE(p_ruleid, v_existing_ruleid)
    );
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        -- Get error details
        GET STACKED DIAGNOSTICS 
            v_error_message = MESSAGE_TEXT,
            v_error_detail = PG_EXCEPTION_DETAIL,
            v_error_hint = PG_EXCEPTION_HINT;
        
        -- Log error to audit trail
        INSERT INTO public.audit_trail (
            entity_type, 
            action_type, 
            description, 
            data, 
            user_id, 
            ip_address, 
            user_agent
        ) VALUES (
            'RULESMASTER',
            'ERROR',
            'Error in frulesmasterCURD: ' || v_error_message,
            jsonb_build_object(
                'action', p_action,
                'error_detail', v_error_detail,
                'error_hint', v_error_hint,
                'ruleid', p_ruleid
            ),
            p_user_id,
            p_ip_address,
            p_user_agent
        );
        
        -- Build error response
        v_result := jsonb_build_object(
            'success', false,
            'message', 'Operation failed: ' || v_error_message,
            'error_detail', v_error_detail,
            'error_hint', v_error_hint,
            'data', null
        );
        
        RETURN v_result;
END;
$$;


