--
-- TOC entry 453 (class 1255 OID 25495)
-- Name: functionstudent(character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.functionstudent(p_action character varying, p_rollno character varying DEFAULT NULL::character varying, p_name character varying DEFAULT NULL::character varying, p_mobile character varying DEFAULT NULL::character varying, p_subject character varying DEFAULT NULL::character varying, p_college character varying DEFAULT NULL::character varying) RETURNS TABLE(status_code integer, message text, affected_rows integer, action_performed character varying, student_data json)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_affected INT;
    v_student_data JSON;
BEGIN
    -- Initialize student_data as empty JSON
    student_data := '{}'::JSON;
    
    -- INSERT action
    IF p_action = 'INSERT' THEN
        BEGIN
            INSERT INTO student (rollno, name, mobile, subject, college)
            VALUES (p_rollno, p_name, p_mobile, p_subject, p_college)
            RETURNING json_build_object(
                'rollno', rollno,
                'name', name,
                'mobile', mobile,
                'subject', subject,
                'college', college
            ) INTO v_student_data;
            
            status_code := 200;
            message := 'Student inserted successfully';
            affected_rows := 1;
            action_performed := 'INSERT';
            student_data := v_student_data;
            RETURN NEXT;
            
        EXCEPTION 
            WHEN unique_violation THEN
                status_code := 409;
                message := 'Duplicate roll number. Student already exists.';
                affected_rows := 0;
                action_performed := 'INSERT';
                RETURN NEXT;
            WHEN OTHERS THEN
                status_code := 500;
                message := 'Error inserting student: ' || SQLERRM;
                affected_rows := 0;
                action_performed := 'INSERT';
                RETURN NEXT;
        END;
    
    -- UPDATE action
    ELSIF p_action = 'UPDATE' THEN
        UPDATE student 
        SET name = COALESCE(p_name, name),
            mobile = COALESCE(p_mobile, mobile),
            subject = COALESCE(p_subject, subject),
            college = COALESCE(p_college, college)
        WHERE rollno = p_rollno
        RETURNING json_build_object(
            'rollno', rollno,
            'name', name,
            'mobile', mobile,
            'subject', subject,
            'college', college
        ) INTO v_student_data;
        
        GET DIAGNOSTICS v_affected = ROW_COUNT;
        
        IF v_affected = 0 THEN
            status_code := 404;
            message := 'No student found with given roll number';
            affected_rows := 0;
            action_performed := 'UPDATE';
        ELSE
            status_code := 200;
            message := 'Student updated successfully';
            affected_rows := v_affected;
            action_performed := 'UPDATE';
            student_data := v_student_data;
        END IF;
        RETURN NEXT;
    
    -- DELETE action
    ELSIF p_action = 'DELETE' THEN
        -- Get student data before deleting
        SELECT json_build_object(
            'rollno', rollno,
            'name', name,
            'mobile', mobile,
            'subject', subject,
            'college', college
        ) INTO v_student_data
        FROM student 
        WHERE rollno = p_rollno;
        
        DELETE FROM student WHERE rollno = p_rollno;
        
        GET DIAGNOSTICS v_affected = ROW_COUNT;
        
        IF v_affected = 0 THEN
            status_code := 404;
            message := 'No student found with given roll number';
            affected_rows := 0;
            action_performed := 'DELETE';
        ELSE
            status_code := 200;
            message := 'Student deleted successfully';
            affected_rows := v_affected;
            action_performed := 'DELETE';
            student_data := v_student_data;
        END IF;
        RETURN NEXT;
    
    -- GET single student
    ELSIF p_action = 'GET_ONE' THEN
        SELECT json_build_object(
            'rollno', rollno,
            'name', name,
            'mobile', mobile,
            'subject', subject,
            'college', college
        ) INTO v_student_data
        FROM student 
        WHERE rollno = p_rollno;
        
        IF v_student_data IS NOT NULL THEN
            status_code := 200;
            message := 'Student found';
            affected_rows := 1;
            action_performed := 'GET_ONE';
            student_data := v_student_data;
        ELSE
            status_code := 404;
            message := 'No student found with given roll number';
            affected_rows := 0;
            action_performed := 'GET_ONE';
        END IF;
        RETURN NEXT;
    
    -- LIST ALL students
    ELSIF p_action = 'LIST_ALL' THEN
        SELECT json_agg(json_build_object(
            'rollno', rollno,
            'name', name,
            'mobile', mobile,
            'subject', subject,
            'college', college
        )) INTO v_student_data
        FROM student 
        ORDER BY rollno;
        
        IF v_student_data IS NOT NULL THEN
            status_code := 200;
            message := 'Students listed successfully';
            affected_rows := (SELECT COUNT(*) FROM student);
            action_performed := 'LIST_ALL';
            student_data := v_student_data;
        ELSE
            status_code := 200;
            message := 'No students found';
            affected_rows := 0;
            action_performed := 'LIST_ALL';
            student_data := '[]'::JSON;
        END IF;
        RETURN NEXT;
    
    ELSE
        status_code := 400;
        message := 'Invalid action. Use INSERT, UPDATE, DELETE, LIST_ALL, or GET_ONE';
        affected_rows := 0;
        action_performed := 'ERROR';
        RETURN NEXT;
    END IF;
END;
$$;


ALTER FUNCTION public.functionstudent(p_action character varying, p_rollno character varying, p_name character varying, p_mobile character varying, p_subject character varying, p_college character varying) OWNER TO postgres;

--
-- TOC entry 387 (class 1255 OID 19206)
-- Name: get_operation_duration_ms(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_operation_duration_ms(p_operation_id bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_start_time TIMESTAMP;
BEGIN
    SELECT start_time INTO v_start_time 
    FROM operation_log 
    WHERE operation_id = p_operation_id;
    
    IF v_start_time IS NOT NULL THEN
        RETURN EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP - v_start_time)) * 1000;
    ELSE
        RETURN 0;
    END IF;
END;
$$;


ALTER FUNCTION public.get_operation_duration_ms(p_operation_id bigint) OWNER TO postgres;

--
-- TOC entry 367 (class 1255 OID 19354)
-- Name: log_debug_information(bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_debug_information(p_operation_id bigint, p_debug_level integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    debug_rec RECORD;
BEGIN
    RAISE NOTICE '=== INTEGRATED RULES + CHARGE CONFIG APPLICATION ===';
    
    FOR debug_rec IN 
        SELECT 
            rm.rulename,
            cc.chargename,
            cc.charge_type,
            ra.action_value->>'scheme' as rule_scheme,
            ra.action_value->>'card_type' as rule_card_type,
            COUNT(DISTINCT c.cardid) as card_count,
            AVG(
                CASE 
                    WHEN cc.charge_type = 'FLAT' THEN cc.amount
                    WHEN cc.charge_type = 'PER' THEN (cc.percentage / 100.0) * 10000
                    WHEN cc.charge_type = 'BOTH' THEN cc.amount + ((cc.percentage / 100.0) * 10000)
                    ELSE cc.amount
                END
            ) as avg_amount
        FROM card c
        JOIN products p ON c.productid = p.productid
        JOIN cardprofilemapping cpm ON c.cardid = cpm.cardid
        JOIN profilerulemapping prm ON cpm.profileid = prm.profileid
        JOIN rulesmaster rm ON prm.ruleid = rm.ruleid
        JOIN ruleactions ra ON rm.ruleid = ra.ruleid
        JOIN chargeconfig cc ON (
            (cc.productid = p.productid OR cc.productid IS NULL OR cc.applies_to = 'ALL_PRODUCTS')
            AND cc.isactive 
            AND (cc.effectivedate IS NULL OR cc.effectivedate <= CURRENT_DATE)
            AND (cc.expirydate IS NULL OR cc.expirydate >= CURRENT_DATE)
            AND cc.chargename ILIKE '%annual%'
        )
        WHERE prm.is_active 
          AND rm.isactive
          AND ra.action_type = 'apply_annual_fee'
          AND NOT EXISTS (
              SELECT 1 FROM ruleconditions rc 
              WHERE rc.ruleid = rm.ruleid 
                AND rc.is_active
                AND NOT evaluate_card_condition(
                    c.cardid::TEXT, 
                    p.productid::TEXT, 
                    rc.field_name, 
                    rc.operator, 
                    rc.value, 
                    rc.data_type
                )
          )
          AND (ra.action_value->>'scheme' IS NULL OR p.schemetype = ra.action_value->>'scheme')
          AND (ra.action_value->>'card_type' IS NULL OR p.producttype = ra.action_value->>'card_type')
          AND NOT EXISTS (
              SELECT 1 FROM card_charges ch 
              WHERE ch.cardid = c.cardid 
                AND ch.charge_year = EXTRACT(YEAR FROM CURRENT_DATE)
                AND ch.charge_type = 'ANNUAL_FEE'
                AND ch.status != 'CANCELLED'
          )
        GROUP BY rm.rulename, cc.chargename, cc.charge_type, ra.action_value->>'scheme', ra.action_value->>'card_type'
    LOOP
        RAISE NOTICE 'Rule: %, Charge: %, Type: %, Scheme: %, Card Type: %, Cards: %, Avg Amount: %', 
            debug_rec.rulename, 
            debug_rec.chargename,
            debug_rec.charge_type,
            debug_rec.rule_scheme,
            debug_rec.rule_card_type,
            debug_rec.card_count,
            debug_rec.avg_amount;
    END LOOP;
    RAISE NOTICE '=== END DEBUG ===';
END;
$$;


ALTER FUNCTION public.log_debug_information(p_operation_id bigint, p_debug_level integer) OWNER TO postgres;

--
-- TOC entry 435 (class 1255 OID 19728)
-- Name: log_error(bigint, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_error(p_operation_id bigint, p_function_name text, p_error_message text, p_error_detail text, p_sql_state text, p_context text, p_additional_info jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Create error_logs table if it doesn't exist
    CREATE TABLE IF NOT EXISTS error_logs (
        error_id BIGSERIAL PRIMARY KEY,
        operation_id BIGINT,
        function_name TEXT NOT NULL,
        error_message TEXT NOT NULL,
        error_detail TEXT,
        sql_state TEXT,
        context TEXT,
        additional_info JSONB,
        error_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );

    INSERT INTO error_logs (
        operation_id,
        function_name,
        error_message,
        error_detail,
        sql_state,
        context,
        additional_info
    ) VALUES (
        p_operation_id,
        p_function_name,
        p_error_message,
        p_error_detail,
        p_sql_state,
        p_context,
        p_additional_info
    );
END;
$$;


ALTER FUNCTION public.log_error(p_operation_id bigint, p_function_name text, p_error_message text, p_error_detail text, p_sql_state text, p_context text, p_additional_info jsonb) OWNER TO postgres;

--
-- TOC entry 408 (class 1255 OID 19228)
-- Name: log_error(bigint, character varying, text, text, character varying, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_error(p_operation_id bigint, p_function_name character varying, p_error_message text, p_error_detail text DEFAULT NULL::text, p_sql_state character varying DEFAULT NULL::character varying, p_failed_query text DEFAULT NULL::text, p_input_parameters jsonb DEFAULT NULL::jsonb) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_error_id BIGINT;
BEGIN
    -- First ensure error_log table exists
    CREATE TABLE IF NOT EXISTS error_log (
        error_id BIGSERIAL PRIMARY KEY,
        operation_id BIGINT,
        function_name VARCHAR(100) NOT NULL,
        error_timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        error_message TEXT NOT NULL,
        error_detail TEXT,
        sql_state VARCHAR(10),
        failed_query TEXT,
        input_parameters JSONB,
        username VARCHAR(100) DEFAULT CURRENT_USER,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );

    INSERT INTO error_log (
        operation_id,
        function_name,
        error_message,
        error_detail,
        sql_state,
        failed_query,
        input_parameters,
        username
    ) VALUES (
        p_operation_id,
        p_function_name,
        p_error_message,
        p_error_detail,
        p_sql_state,
        p_failed_query,
        p_input_parameters,
        CURRENT_USER
    ) RETURNING error_id INTO v_error_id;
    
    RETURN v_error_id;
EXCEPTION
    WHEN others THEN
        RAISE NOTICE 'Failed to log error: %', SQLERRM;
        RETURN -1;
END;
$$;


ALTER FUNCTION public.log_error(p_operation_id bigint, p_function_name character varying, p_error_message text, p_error_detail text, p_sql_state character varying, p_failed_query text, p_input_parameters jsonb) OWNER TO postgres;

--
-- TOC entry 480 (class 1255 OID 24381)
-- Name: log_operation_completion(bigint, text, integer, integer, numeric, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_operation_completion(p_operation_id bigint, p_status text, p_eligible_count integer DEFAULT 0, p_processed_count integer DEFAULT 0, p_total_amount numeric DEFAULT 0, p_error_message text DEFAULT NULL::text, p_additional_info jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE operation_logs 
    SET 
        end_time = CURRENT_TIMESTAMP,
        status = p_status,
        eligible_count = p_eligible_count,
        processed_count = p_processed_count,
        total_amount = p_total_amount,
        error_message = p_error_message,
        additional_info = COALESCE(additional_info, '{}'::JSONB) || p_additional_info,
        duration_ms = EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP - start_time)) * 1000
    WHERE operation_id = p_operation_id;
END;
$$;


