--
-- TOC entry 371 (class 1255 OID 16624)
-- Name: procinsert_branch(character varying, character varying, character varying, character varying, character varying); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.procinsert_branch(IN p_bankcode character varying, IN p_branchname character varying, IN p_branchid character varying, IN p_managername character varying, IN p_phone character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO kmana_branch (bankcode, branchname, branchid, managername, phone)
    VALUES (p_bankcode, p_branchname, p_branchid, p_managername, p_phone);
EXCEPTION
    WHEN unique_violation THEN
        RAISE NOTICE 'Branch with bankcode % and branchid % already exists.', p_bankcode, p_branchid;
        RAISE; -- Re-raise error so caller sees it
    WHEN others THEN
        RAISE NOTICE 'An error occurred: %', SQLERRM;
        RAISE; -- Re-raise error
END;
$$;


