CREATE FUNCTION public.search_customer_dynamic(p_action character varying DEFAULT NULL::character varying, p_fname character varying DEFAULT NULL::character varying, p_lname character varying DEFAULT NULL::character varying, p_middlename character varying DEFAULT NULL::character varying, p_mobileno character varying DEFAULT NULL::character varying, p_customercode character varying DEFAULT NULL::character varying, p_accountno character varying DEFAULT NULL::character varying, p_cardno character varying DEFAULT NULL::character varying, p_userid integer DEFAULT NULL::integer) RETURNS TABLE(customercode character varying, fname character varying, lname character varying, middlename character varying, mobileno character varying, accountid character varying, accountnumber character varying, accounttype character varying, balance numeric, cardid character varying, cardnumber character varying, cardtype character varying, schemetype character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    dyn_sql TEXT;
    v_branchcode VARCHAR;
    v_institutionid VARCHAR;
    v_crossbranch BOOLEAN;
BEGIN
    -- Get user's branchcode, institutionid, and crossbranch flag
    SELECT lpad(branchid::text, 4, '0'), institutionid, crossbranch
    INTO v_branchcode, v_institutionid, v_crossbranch
    FROM users
    WHERE id = p_userid;

    -- Debug notice
    RAISE NOTICE 'User branchcode=% | institutionid=% | crossbranch=%', v_branchcode, v_institutionid, v_crossbranch;

    -- Base query based on action
    IF p_action = 'CUST' THEN
        dyn_sql := '
            SELECT c.customercode,
                   c.fname,
                   c.lname,
                   c.middlename,
                   c.mobileno,
                   NULL::VARCHAR AS accountid,
                   NULL::VARCHAR AS accountnumber,
                   NULL::VARCHAR AS accounttype,
                   NULL::NUMERIC AS balance,
                   NULL::VARCHAR AS cardid,
                   NULL::VARCHAR AS cardnumber,
                   NULL::VARCHAR AS cardtype,
                   NULL::VARCHAR AS schemetype
            FROM customer c
            WHERE 1=1';

    ELSIF p_action = 'ACC' THEN
        dyn_sql := '
            SELECT c.customercode,
                   c.fname,
                   c.lname,
                   c.middlename,
                   c.mobileno,
                   a.accountid,
                   a.accountnumber,
                   a.accounttype,
                   a.balance,
                   NULL::VARCHAR AS cardid,
                   NULL::VARCHAR AS cardnumber,
                   NULL::VARCHAR AS cardtype,
                   NULL::VARCHAR AS schemetype
            FROM customer c
            JOIN account a ON c.customercode = a.customercode
            WHERE 1=1';

    ELSIF p_action = 'CARD' THEN
        dyn_sql := '
            SELECT c.customercode,
                   c.fname,
                   c.lname,
                   c.middlename,
                   c.mobileno,
                   NULL::VARCHAR AS accountid,
                   NULL::VARCHAR AS accountnumber,
                   NULL::VARCHAR AS accounttype,
                   NULL::NUMERIC AS balance,
                   cd.cardid,
                   cd.cardnumber,
                   cd.cardtype,
                   cd.schemetype
            FROM customer c
            JOIN account a ON c.customercode = a.customercode
            JOIN card cd ON a.accountid = cd.accountid
            WHERE 1=1';

    ELSIF p_action = 'ALL' THEN
        dyn_sql := '
            SELECT c.customercode,
                   c.fname,
                   c.lname,
                   c.middlename,
                   c.mobileno,
                   a.accountid,
                   a.accountnumber,
                   a.accounttype,
                   a.balance,
                   cd.cardid,
                   cd.cardnumber,
                   cd.cardtype,
                   cd.schemetype
            FROM customer c
            LEFT JOIN account a ON c.customercode = a.customercode
            LEFT JOIN card cd ON a.accountid = cd.accountid
            WHERE 1=1';

    ELSE
        RAISE EXCEPTION 'Invalid action: %', p_action;
    END IF;

    -- Apply branch filter if crossbranch is false
    IF NOT v_crossbranch THEN
        dyn_sql := dyn_sql || format(' AND c.branchcode = %L', v_branchcode);
    END IF;

    -- Apply other filters if provided
    IF p_fname IS NOT NULL AND trim(p_fname) <> '' THEN
        dyn_sql := dyn_sql || format(' AND c.fname ILIKE %L', '%' || trim(p_fname) || '%');
    END IF;

    IF p_lname IS NOT NULL AND trim(p_lname) <> '' THEN
        dyn_sql := dyn_sql || format(' AND c.lname ILIKE %L', '%' || trim(p_lname) || '%');
    END IF;

    IF p_middlename IS NOT NULL AND trim(p_middlename) <> '' THEN
        dyn_sql := dyn_sql || format(' AND c.middlename ILIKE %L', '%' || trim(p_middlename) || '%');
    END IF;

    IF p_mobileno IS NOT NULL AND trim(p_mobileno) <> '' THEN
        dyn_sql := dyn_sql || format(' AND c.mobileno = %L', trim(p_mobileno));
    END IF;

    IF p_customercode IS NOT NULL AND trim(p_customercode) <> '' THEN
        dyn_sql := dyn_sql || format(' AND c.customercode = %L', trim(p_customercode));
    END IF;

    IF p_accountno IS NOT NULL AND trim(p_accountno) <> '' AND p_action IN ('ACC','CARD','ALL') THEN
        dyn_sql := dyn_sql || format(' AND a.accountnumber = %L', trim(p_accountno));
    END IF;

    IF p_cardno IS NOT NULL AND trim(p_cardno) <> '' AND p_action IN ('CARD','ALL') THEN
        dyn_sql := dyn_sql || format(' AND cd.cardnumber = %L', trim(p_cardno));
    END IF;

    -- Debug final SQL
    RAISE NOTICE 'Executing SQL: %', dyn_sql;

    -- Execute dynamic query
    RETURN QUERY EXECUTE dyn_sql;
END;
$$;


ALTER FUNCTION public.search_customer_dynamic(p_action character varying, p_fname character varying, p_lname character varying, p_middlename character varying, p_mobileno character varying, p_customercode character varying, p_accountno character varying, p_cardno character varying, p_userid integer) OWNER TO postgres;

--
-- TOC entry 466 (class 1255 OID 24539)
-- Name: simple_apply_charges(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.simple_apply_charges() RETURNS TABLE(status text, records integer, amount numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_records INTEGER := 0;
    v_total DECIMAL(12,2) := 0;
BEGIN
    -- Simple direct insert without all the complex logic
    INSERT INTO card_charges (
        charge_id, cardid, cardnumber, accountid, charge_type, 
        amount, currency, charge_date, charge_year, description,
        card_type, scheme_type, productname, productbin, status
    )
    SELECT 
        fcreatefeesidanual(),  -- Generate charge ID
        c.cardid,
        c.cardnumber,
        c.accountid,
        'ANNUAL_FEE',
        500.00,  -- Fixed amount
        'USD',
        CURRENT_DATE,
        EXTRACT(YEAR FROM CURRENT_DATE),
        'Simple test charge',
        c.cardtype,
        c.schemetype,
        p.productname,
        p.productbin,
        'APPLIED'
    FROM card c
    JOIN products p ON c.productid = p.productid
    WHERE c.cardid IN ('CAR00000012', 'CAR00000013', 'CAR00000055')
    AND c.status = 'A'
    AND NOT EXISTS (
        SELECT 1 FROM card_charges cc 
        WHERE cc.cardid = c.cardid 
        AND cc.charge_year = EXTRACT(YEAR FROM CURRENT_DATE)
        AND cc.charge_type = 'ANNUAL_FEE'
    )
    RETURNING cardid, amount
    INTO v_records, v_total;
    
    status := 'SUCCESS';
    records := v_records;
    amount := v_total;
    
    RETURN NEXT;
    
EXCEPTION WHEN others THEN
    status := 'ERROR: ' || SQLERRM;
    records := 0;
    amount := 0;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION public.simple_apply_charges() OWNER TO postgres;

--
-- TOC entry 459 (class 1255 OID 24563)
-- Name: simple_apply_to_all(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.simple_apply_to_all() RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INTEGER := 0;
BEGIN
    -- Apply charges to ALL active VISA DEBIT cards regardless of profiles
    INSERT INTO card_charges (
        charge_id, cardid, cardnumber, accountid, charge_type, 
        amount, currency, charge_date, charge_year, description,
        card_type, scheme_type, productname, productbin, status
    )
    SELECT 
        fcreatefeesidanual(),
        c.cardid,
        c.cardnumber,
        c.accountid,
        'ANNUAL_FEE',
        500.00,
        'USD',
        CURRENT_DATE,
        EXTRACT(YEAR FROM CURRENT_DATE),
        'Simple annual fee',
        c.cardtype,
        c.schemetype,
        p.productname,
        p.productbin,
        'APPLIED'
    FROM card c
    JOIN products p ON c.productid = p.productid
    WHERE c.status = 'A'
    AND c.cardtype = 'DEBIT'
    AND c.schemetype = 'VISA'
    AND c.cardid IN ('CAR00000012', 'CAR00000013', 'CAR00000055')
    AND NOT EXISTS (
        SELECT 1 FROM card_charges cc 
        WHERE cc.cardid = c.cardid 
        AND cc.charge_year = EXTRACT(YEAR FROM CURRENT_DATE)
        AND cc.charge_type = 'ANNUAL_FEE'
    );
    
    GET DIAGNOSTICS v_count = ROW_COUNT;
    
    RETURN 'Applied charges to ' || v_count || ' cards';
    
EXCEPTION WHEN others THEN
    RETURN 'Error: ' || SQLERRM;
END;
$$;


