    LANGUAGE plpgsql
    AS $$
DECLARE
    next_val BIGINT;
    padded_val TEXT;
BEGIN
    -- Get the next value from the sequence
    next_val := nextval('s_txn_id_seq');

    -- Pad the numeric value to 7 digits with leading zeros and prefix with 'CUST'
    padded_val := 'API' || LPAD(next_val::TEXT, 9, '0');
