CREATE FUNCTION public.generate_quotation_number_direct() RETURNS character varying
    LANGUAGE plpgsql
    AS $$
            DECLARE
                new_number VARCHAR;
                counter INTEGER := 0;
                timestamp_part BIGINT;
            BEGIN
                timestamp_part := EXTRACT(EPOCH FROM NOW())::BIGINT;

                LOOP
                    -- Combine timestamp and random with better distribution
                    new_number := 'QUO' ||
                                 LPAD((timestamp_part % 100000000)::TEXT, 8, '0') ||
                                 LPAD(FLOOR(RANDOM() * 1000)::TEXT, 3, '0');

                    EXIT WHEN NOT EXISTS (SELECT 1 FROM quotations WHERE quotation_number = new_number);

                    counter := counter + 1;
                    -- Increment timestamp slightly for next attempt
                    timestamp_part := timestamp_part + counter;

                    -- Safety break after 5 attempts
                    IF counter >= 5 THEN
                        -- Fallback: use UUID-based approach
                        new_number := 'QUO' ||
                                    LPAD((EXTRACT(EPOCH FROM NOW())::BIGINT % 100000000)::TEXT, 8, '0') ||
                                    LPAD((EXTRACT(MICROSECONDS FROM NOW())::INTEGER % 1000)::TEXT, 3, '0');
                        EXIT;
                    END IF;
                END LOOP;
                RETURN new_number;
            END;
            $$;


