    AS $$
            DECLARE
                new_id VARCHAR;
                counter INTEGER := 0;
                base_part VARCHAR;
            BEGIN
                base_part := TO_CHAR(NOW(), 'YYYY-MM');

                LOOP
                    -- Combine date, random, and microtime for maximum uniqueness
                    new_id := base_part || '-' ||
                             FLOOR(RANDOM() * 9000 + 1000)::TEXT || '-' ||
                             LPAD((EXTRACT(MICROSECONDS FROM NOW())::INTEGER % 1000)::TEXT, 3, '0');

                    EXIT WHEN NOT EXISTS (SELECT 1 FROM quotations WHERE service_id = new_id);

                    counter := counter + 1;
